insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 29, 'വിവാഹാഭ്യർത്ഥന വന്നാൽ സ്ത്രീ നമസ്കരിക്കലും തന്റെ നാഥനോട് നന്മതേടലും', 'بَابٌ: صَلَاةُ الْمَرْأَةِ إِذَا خُطِبَتْ وَاسْتِخَارَتُهَا رَبَّهَا', 62 from books where volume_id=3 and book_no=2 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
