insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ أَبِي أَيُّوبَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَرْبَعٌ مِنْ سُنَنِ الْمُرْسَلِينَ: الْحَيَاءُ، وَالتَّعَطُّرُ، وَالسِّوَاكُ، وَالنِّكَاحُ". حَسَنٌ. (ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ലജ്ജ, സുഗന്ധം ഉപയോഗിക്കൽ, മിസ്വാക് ചെയ്യൽ, വിവാഹം കഴിക്കൽ എന്നിവ ദൈവദൂതരുടെ ചര്യകളിൽപ്പെട്ടതാണ്." (തു)', 'أَبِي أَيُّوبَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 41, 41, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجْنَا مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَنَحْنُ شَبَابٌ لَا نَقْدِرُ عَلَى شَيْءٍ. فَقَالَ: "يَا مَعْشَرَ الشَّبَابِ، عَلَيْكُمْ بِالْبَاءَةِ، فَإِنَّهُ أَغَضُّ لِلْبَصَرِ وَأَحْصَنُ لِلْفَرْجِ، فَمَنْ لَمْ يَسْتَطِعْ مِنْكُمُ الْبَاءَةَ فَعَلَيْهِ بِالصَّوْمِ، فَإِنَّ الصَّوْمَ لَهُ وِجَاءٌ". (ق,ت)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): ഒന്നിനും സാധിക്കാത്ത ഞങ്ങൾ, ചില യുവാക്കൾ റസൂൽ(സ)യോടൊപ്പം പുറപ്പെട്ടു. അന്നേരം അവിടന്ന് പറഞ്ഞു: "യുവസമൂഹമേ, നിങ്ങൾ വിവാഹം കഴിച്ചുകൊള്ളുക. നിശ്ചയമത് കണ്ണിനെ താഴ്ത്തുന്നതും ഗുഹ്യഭാഗത്തെ സംരക്ഷിക്കുന്നതുമാണ്. നിങ്ങളിൽ ആർക്കെങ്കിലും വിവാഹത്തിന് സാധിക്കുന്നില്ലെങ്കിൽ അവൻ നോമ്പനുഷ്ഠിച്ചുകൊള്ളട്ടെ. നിശ്ചയം നോമ്പ് വികാരത്തെ അടക്കി നിർത്തുന്നതാണ്." (ബു,മു,തു)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 41, 41, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ ثَلَاثَةُ رَهْطٍ إِلَى بُيُوتِ أَزْوَاجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَسْأَلُونَ عَنْ عِبَادَةِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا أُخْبِرُوا كَأَنَّهُمْ تَقَالُّوهَا فَقَالُوا: وَأَيْنَ نَحْنُ مِنَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَدْ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ، وَمَا تَأَخَّرَ، فَقَالَ أَحَدُهُمْ: أَمَّا أَنَا فَإِنِّي أُصَلِّي اللَّيْلَ أَبَدًا، وَقَالَ آخَرُ: أَنَا أَصُومُ الدَّهْرَ، وَلَا أُفْطِرُ، وَقَالَ آخَرُ: أَنَا أَعْتَزِلُ النِّسَاءَ فَلَا أَتَزَوَّجُ أَبَدًا، فَجَاءَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَيْهِمْ، فَقَالَ: "أَنْتُمُ الَّذِينَ قُلْتُمْ كَذَا وَكَذَا، أَمَا وَاللهِ إِنِّي لَأَخْشَاكُمْ لِلَّهِ وَأَتْقَاكُمْ لَهُ، لَكِنِّي أَصُومُ وَأُفْطِرُ، وَأُصَلِّي وَأَرْقُدُ، وَأَتَزَوَّجُ النِّسَاءَ، فَمَنْ رَغِبَ عَنْ سُنَّتِي فَلَيْسَ مِنِّي". (خ)', 'അനസുബ്നു മാലിക്(റ): നബി(സ)യുടെ ആരാധനകളെക്കുറിച്ച് ചോദിച്ച് മൂന്നുപേർ നബി(സ)യുടെ ഭാര്യമാരുടെ വീടുകളിലേക്ക് വന്നു. തിരുമേനി(സ)യുടെ ആരാധനയെക്കുറിച്ച് കേട്ടപ്പോൾ അവർക്ക് തങ്ങളുടെ ആരാധന വളരെ കുറവാണെന്ന് തോന്നി. അവർ പറഞ്ഞു: നബി(സ)യോട് ചേർത്തുനോക്കുമ്പോൾ നാമെല്ലാം എവിടെയാണ്, കാരണം അല്ലാഹു അവിടത്തേക്ക് മുൻകഴിഞ്ഞതും വരാനിരിക്കുന്നതുമായ സർവ്വ പാപവും പൊറുത്തു കൊടുത്തിരിക്കുന്നു. അവരിലൊരാൾ പറഞ്ഞു: ഞാൻ എന്നും രാത്രി മുഴുവൻ നമസ്കരിക്കും. മറ്റൊരാൾ പറഞ്ഞു: ഞാൻ എല്ലാദിവസവും നോമ്പനുഷ്ഠിക്കും, ഒരു ദിവസവും നോമ്പ് ഒഴിവാക്കുകയില്ല. മൂന്നാമത്തെയാൾ പറഞ്ഞു: ഞാൻ സ്ത്രീകളിൽ നിന്ന് അകന്നുനിൽക്കും. ഒരിക്കലും വിവാഹം കഴിക്കുകയില്ല. അന്നേരം റസൂൽ(സ) അവരുടെ അടുത്ത് വന്ന് പറഞ്ഞു: "ഈ വിധമെല്ലാം നിങ്ങൾ പറഞ്ഞുവല്ലോ. അല്ലാഹുവാണ, നിങ്ങളെക്കാളെല്ലാം അല്ലാഹുവിനെ ഭയപ്പെടുന്നവനും സൂക്ഷിക്കുന്നവനും ഞാനാണ്. ഞാൻ ചിലപ്പോൾ നോമ്പനുഷ്ഠിക്കുകയും ചിലപ്പോൾ ഉപേക്ഷിക്കുകയും ചെയ്യുന്നു. രാത്രി നമസ്കരിക്കും. ചിലപ്പോൾ ഉറങ്ങും. സ്ത്രീകളെ വിവാഹം കഴിക്കുകയും ചെയ്യും. ആരെങ്കിലും എന്റെ ചര്യയെ വെറുക്കുന്നുവെങ്കിൽ അവൻ എന്നിൽപ്പെട്ടവനല്ല." (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 41, 42, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ عَلْقَمَةَ بْنِ قَيْسٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ مَعَ عَبْدِ اللهِ بْنِ مَسْعُودٍ – رَضِيَ اللهُ عَنْهُ – بِمِنًى، فَخَلَا بِهِ عُثْمَانُ، فَجَلَسْتُ قَرِيبًا مِنْهُ. فَقَالَ لَهُ عُثْمَانُ رَضِيَ اللهُ عَنْهُ: هَلْ لَكَ أَنْ أُزَوِّجَكَ جَارِيَةً بِكْرًا، تُذَكِّرُكَ مِنْ نَفْسِكَ بَعْضَ مَا قَدْ مَضَى؟ فَلَمَّا رَأَى عَبْدُ اللهِ أَنَّهُ لَيْسَ لَهُ حَاجَةٌ سِوَى هَذَا، أَشَارَ إِلَيَّ بِيَدِهِ، فَجِئْتُ وَهُوَ يَقُولُ: لَئِنْ قُلْتَ ذَلِكَ، لَقَدْ قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَا مَعْشَرَ الشَّبَابِ، مَنِ اسْتَطَاعَ مِنْكُمُ الْبَاءَةَ فَلْيَتَزَوَّجْ، فَإِنَّهُ أَغَضُّ لِلْبَصَرِ، وَأَحْصَنُ لِلْفَرْجِ. وَمَنْ لَمْ يَسْتَطِعْ فَعَلَيْهِ بِالصَّوْمِ، فَإِنَّهُ لَهُ وِجَاءٌ". (ق,د,ت,ن,جه)', 'അൽഖമതുബ്നു ഖൈസ്(റ): ഞാൻ അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)വിന്റെ കൂടെ മിനായിൽ നിൽക്കുകയായിരുന്നു. അന്നേരം ഉസ്മാൻ(റ) അവരുമായി ഒഴിഞ്ഞ ഒരിടത്തേക്ക് മാറിയിരുന്നു. ഞാനും അവരുടെ അടുത്തിരുന്നു. ഉസ്മാൻ(റ) അബ്ദുല്ല(റ)വിനോട് ചോദിച്ചു: കന്യകയായ ഒരു സ്ത്രീയെ ഞാൻ നിനക്ക് വിവാഹം കഴിച്ചുതരട്ടെയോ? മുമ്പേ കഴിഞ്ഞുപോയ കാര്യങ്ങൾ നിനക്ക് അത് ഓർമ്മപ്പെടുത്തിത്തരും. ഉസ്മാൻ(റ)വിന് ഇതല്ലാതെ വേറൊന്നും പറയാനില്ലെന്ന് കണ്ടപ്പോൾ അബ്ദുല്ലാ(റ) എന്നെ ആംഗ്യംകാട്ടി വിളിക്കുകയും ഞാൻ അവിടെ ചെല്ലുകയും ചെയ്തു. അബ്ദുല്ല(റ) ഇപ്രകാരം പറയുന്നുണ്ടായിരുന്നു: നിങ്ങൾ ഇപ്രകാരം പറയുന്നുവെങ്കിൽ റസൂൽ(സ) പറഞ്ഞിട്ടുണ്ട്: "യുവസമൂഹമേ, നിങ്ങളിൽ ആർക്കെങ്കിലും വിവാഹം കഴിക്കാൻ സാധിക്കുമെങ്കിൽ വിവാഹം കഴിക്കുക. നിശ്ചയമത് കാഴ്ചയെ താഴ്ത്തുന്നതും ഗുഹ്യഭാഗത്തെ സംരക്ഷിക്കുന്നതുമാണ്. വിവാഹം കഴിക്കാൻ സാധിക്കാത്തവൻ നോമ്പനുഷ്ഠിച്ചുകൊള്ളട്ടെ. നിശ്ചയമത് വികാരത്തെ അടക്കിനിർത്തുന്നതാണ്." (ബു,മു,ദ,തു,ന,ജ)', 'عَلْقَمَةَ بْنِ قَيْسٍ', 'അൽഖമതുബ്നു ഖൈസ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 42, 42, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَمْ نَر – يُر – لِلْمُتَحَابَّيْنِ مِثْلَ النِّكَاحِ". (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "പരസ്പരം സ്നേഹിക്കുന്നവരുടെ ബന്ധം നിലനിർത്താൻ വിവാഹബന്ധത്തെക്കാൾ ഉതകുന്ന മറ്റൊന്നുണ്ടെന്ന് എനിക്ക് തോന്നുന്നില്ല." (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 42, 42, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ نَفَرًا مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سَأَلُوا أَزْوَاجَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ عَمَلِهِ فِي السِّرِّ، فَقَالَ بَعْضُهُمْ: لَا أَتَزَوَّجُ النِّسَاءَ، وَقَالَ بَعْضُهُمْ: لَا آكُلُ اللَّحْمَ، وَقَالَ بَعْضُهُمْ: لَا أَنَامُ عَلَى فِرَاشٍ، فَحَمِدَ اللهَ وَأَثْنَى عَلَيْهِ، فَقَالَ: "مَا بَالُ أَقْوَامٍ قَالُوا كَذَا وَكَذَا؟ لَكِنِّي أُصَلِّي وَأَنَامُ، وَأَصُومُ وَأُفْطِرُ، وَأَتَزَوَّجُ النِّسَاءَ، فَمَنْ رَغِبَ عَنْ سُنَّتِي فَلَيْسَ مِنِّي". (م)', 'അനസ്(റ): നബി(സ)യുടെ അനുചരന്മാരിൽ ചിലർ നബി(സ)യുടെ രഹസ്യആരാധനകളെക്കുറിച്ച് അവിടുത്തെ പത്നിമാരോട് ചോദിച്ചു. എന്നിട്ട് അവരിലൊരാൾ പറഞ്ഞു: ഞാൻ വിവാഹം കഴിക്കുകയില്ല. മറ്റൊരാൾ പറഞ്ഞു: ഞാൻ മാംസം ഭക്ഷിക്കുകയില്ല. മറ്റൊരാൾ പറഞ്ഞു: ഞാൻ വിരിപ്പിൽ കിടന്നുറങ്ങുകയില്ല. അന്നേരം നബി(സ) അല്ലാഹുവിന് ഹംദ് ചൊല്ലി കീർത്തനങ്ങളർപ്പിച്ച ശേഷം പറഞ്ഞു: "ഇന്നിന്ന കാര്യങ്ങളെല്ലാം പറഞ്ഞവരുടെ അവസ്ഥയെന്താണ്? ഞാൻ നമസ്കരിക്കുകയും ഉറങ്ങുകയും നോമ്പനുഷ്ഠിക്കുകയും ഉപേക്ഷിക്കുകയും വിവാഹം കഴിക്കുകയും ചെയ്യുന്നു. ആരെങ്കിലും എന്റെ ചര്യയെ വെറുക്കുന്നുവെങ്കിൽ അവൻ എന്നിൽപ്പെട്ടവനല്ല." (മു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 42, 42, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "ثَلَاثَةٌ حَقٌّ عَلَى اللهِ عَزَّ وَجَلَّ عَوْنُهُمْ: الْمُكَاتَبُ الَّذِي يُرِيدُ الْأَدَاءَ، وَالنَّاكِحُ الَّذِي يُرِيدُ الْعَفَافَ، وَالْمُجَاهِدُ فِي سَبِيلِ اللهِ". (ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "മൂന്ന് കൂട്ടരെ സഹായിക്കൽ അല്ലാഹുവിന്റെ കടമയാണ്. തുക കൊടുത്ത് വീട്ടണമെന്നാഗ്രഹിക്കുന്ന മോചനപത്രം എഴുതപ്പെട്ട അടിമ, സച്ചരിതത്വമാഗ്രഹിച്ച് വിവാഹം കഴിക്കുന്നവൻ, അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ധർമ്മസമരം ചെയ്യുന്നവൻ." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 43, 43, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ عَطَاءٍ رَضِيَ اللهُ عَنْهُ قَالَ: حَضَرْنَا مَعَ ابْنِ عَبَّاسٍ جَنَازَةَ مَيْمُونَةَ رَضِيَ اللهُ عَنْهَا – زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ – بِسَرِفَ، فَقَالَ ابْنُ عَبَّاسٍ: هَذِهِ مَيْمُونَةُ، إِذَا رَفَعْتُمْ جَنَازَتَهَا فَلَا تُزَعْزِعُوهَا وَلَا تُزَلْزِلُوهَا، فَإِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ مَعَهُ تِسْعُ نِسْوَةٍ، فَكَانَ يَقْسِمُ لِثَمَانٍ، وَوَاحِدَةٌ لَمْ يَكُنْ يَقْسِمُ لَهَا. (ن)', 'അത്വാഅ്(റ): സരിഫ് എന്ന സ്ഥലത്ത് വെച്ച് ഞങ്ങൾ ഇബ്നുഅബ്ബാസ്(റ)വിനോടൊന്നിച്ച് നബി(സ)യുടെ ഭാര്യയായ മൈമൂന(റ)യുടെ ജനാസസംസ്കരണത്തിൽ പങ്കെടുത്തു. അന്നേരം ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: ഇത് മൈമൂന(റ)യാണ്. അവരുടെ ജനാസയെടുക്കുമ്പോൾ നിങ്ങൾ ഇളക്കുകയോ കുലുക്കുകയോ ചെയ്യരുത്. നിശ്ചയം റസൂൽ(സ)യുടെ കൂടെ ഒമ്പത് ഭാര്യമാരുണ്ടായിരുന്നു. അവരിൽ എട്ടുപേർക്ക് അവിടന്ന് വിഹിതം വെക്കാറുണ്ടായിരുന്നു. അവരിൽ ഒരു ഭാര്യക്ക് വിഹിതമുണ്ടായിരുന്നില്ല. (ന)', 'عَطَاءٍ', 'അത്വാഅ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 43, 43, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُ قَالَ: تُوُفِّيَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَعِنْدَهُ تِسْعُ نِسْوَةٍ يُصِيبُهُنَّ، إِلَّا سَوْدَةَ، فَإِنَّهَا وَهَبَتْ يَوْمَهَا وَلَيْلَتَهَا لِعَائِشَةَ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ)ക്ക് ഒമ്പത് ഭാര്യമാരുണ്ടായിരിക്കെയാണ് അവിടന്ന് വഫാത്തായത്. അവരിൽ സൗദ(റ) ഒഴികെ ബാക്കി എട്ടുപേരോടും അവിടന്ന് ബന്ധപ്പെടാറുണ്ടായിരുന്നു. സൗദ(റ) തന്റെ ദിനരാത്രികളെ ആഇശ(റ)ക്ക് നൽകിയതായിരുന്നു. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 43, 43, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَطُوفُ عَلَى نِسَائِهِ فِي اللَّيْلَةِ الْوَاحِدَةِ، وَلَهُ يَوْمَئِذٍ تِسْعُ نِسْوَةٍ. (ن)', 'അനസ്(റ): നബി(സ) ഒരു രാത്രി തന്നെ തന്റെ മുഴുവൻ ഭാര്യമാരുടെയും അടുത്ത് ചെല്ലാറുണ്ടായിരുന്നു. അന്ന് നബി(സ)ക്ക് ഒമ്പത് ഭാര്യമാരുണ്ടായിരുന്നു. (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 43, 43, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا أَنَّهَا كَانَتْ تَقُولُ: أَمَا تَسْتَحِي الْمَرْأَةُ أَنْ تَهَبَ نَفْسَهَا لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ حَتَّى أَنْزَلَ اللهُ: {تُرْجِي مَنْ تَشَاءُ مِنْهُنَّ وَتُؤْوِي إِلَيْكَ مَنْ تَشَاءُ} [الأحزاب: ٥١]. قَالَتْ: فَقُلْتُ: إِنَّ رَبَّكَ لَيُسَارِعُ فِي هَوَاكَ. (ق,جه)', 'ആഇശ(റ): അവർ ഇപ്രകാരം പറയാറുണ്ടായിരുന്നു: സ്വന്തത്തെ നബി(സ)ക്ക് സമർപ്പിക്കുന്ന കാര്യത്തിൽ സ്ത്രീകൾക്ക് ലജ്ജയില്ലേ? അങ്ങനെ അല്ലാഹു ഈ സൂക്തമിറക്കി: ''അവരിൽ ഇഷ്ടമുള്ളവരെ അങ്ങേക്ക് അകറ്റുകയും ഇഷ്ടമുള്ളവരെ വിവാഹം കഴിക്കുകയും ചെയ്യാം.'' (അഹ്സാബ്: 51) ആഇശ(റ) പറയുന്നു: അപ്പോൾ നബി(സ)യോട് പറഞ്ഞു: അങ്ങയുടെ രക്ഷിതാവ് വേഗത്തിൽ അങ്ങയുടെ ആഗ്രഹം പൂർത്തീകരിച്ചുതരുന്നു. (ബു,മു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], 'الأحزاب: ٥١', null, 43, 44, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ، وَعِنْدَهُ ابْنَةٌ لَهُ: أَنَسٌ جَاءَتِ امْرَأَةٌ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَعَرَضَتْ نَفْسَهَا عَلَيْهِ، فَقَالَتْ: يَا رَسُولَ اللهِ، هَلْ لَكَ فِيَّ حَاجَةٌ؟ فَقَالَتِ ابْنَتُهُ: مَا أَقَلَّ حَيَاءَهَا. فَقَالَ: هِيَ خَيْرٌ مِنْكِ، رَغِبَتْ فِي رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَعَرَضَتْ نَفْسَهَا عَلَيْهِ. (خ,ن,جه)', 'അനസുബ്നു മാലിക്(റ): തന്റെ മകൾ അരികിലിരിക്കെ അനസ്(റ) പറഞ്ഞു: ഒരു സ്ത്രീ നബി(സ)യുടെ അടുത്തുവന്ന് സ്വന്തത്തെ സമർപ്പിക്കാനുദ്ദേശിച്ചുകൊണ്ട് ചോദിച്ചു: റസൂലേ, അങ്ങേക്ക് എന്നെ ആവശ്യമുണ്ടോ? അപ്പോൾ അനസ്(റ)വിന്റെ മകൾ പറഞ്ഞു: ആ സ്ത്രീക്ക് തീരെ ലജ്ജയില്ലാത്തതെന്താണ്! അനസ്(റ) പറഞ്ഞു: അവൾ നിന്നെക്കാൾ ഉത്തമയാണ്. കാരണമവൾ റസൂൽ(സ)യെ ആഗ്രഹിക്കുകയും സ്വന്തത്തെ റസൂൽ(സ)ക്ക് സമർപ്പിക്കാനാഗ്രഹിക്കുകയും ചെയ്തു. (ബു,ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ','ن','جه']::text[], array['ബു','ന','ജ']::text[], null, null, 44, 44, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كُنْتُ أَغَارُ عَلَى اللَّاتِي وَهَبْنَ أَنْفُسَهُنَّ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَأَقُولُ: [أ]وَتَهَبُ الْمَرْأَةُ نَفْسَهَا؟ فَلَمَّا أَنْزَلَ اللهُ عَزَّ وَجَلَّ: {تُرْجِي مَنْ تَشَاءُ مِنْهُنَّ وَتُؤْوِي إِلَيْكَ مَنْ تَشَاءُ وَمَنِ ابْتَغَيْتَ مِمَّنْ عَزَلْتَ} [الأحزاب: ٥١] قَالَتْ: قُلْتُ: وَاللهِ مَا أَرَى رَبَّكَ إِلَّا يُسَارِعُ لَكَ فِي هَوَاكَ. (م)', 'ആഇശ(റ): റസൂൽ(സ)ക്ക് സ്വന്തത്തെ സമർപ്പിക്കുന്ന സ്ത്രീകളോട് ഞാൻ ദേഷ്യപ്പെടുകയും ഇപ്രകാരം പറയുകയും ചെയ്യാറുണ്ടായിരുന്നു: ഒരു സ്ത്രീ സ്വന്തത്തെ സമർപ്പിക്കുകയോ? ശേഷം, ''അവരിൽ അങ്ങ് ഉദ്ദേശിക്കുന്നവരെ അകറ്റുകയും ഉദ്ദേശിക്കുന്നവരെ വിവാഹം കഴിക്കുകയും ചെയ്യാം. അകറ്റിയവരിൽ നിന്നും വല്ലവരെയും അങ്ങ് ആഗ്രഹിക്കുന്ന പക്ഷം കുറ്റമൊന്നുമില്ല.'' (അഹ്സാബ്: 51) എന്ന സൂക്തം അല്ലാഹു ഇറക്കിയപ്പോൾ ഞാൻ റസൂൽ(സ)യോട് പറഞ്ഞു: അല്ലാഹു തന്നെ സത്യം, അങ്ങയുടെ രക്ഷിതാവ് അങ്ങയുടെ ആഗ്രഹങ്ങൾ വേഗത്തിൽ പൂർത്തീകരിച്ചു തരുന്നതായേ ഞാൻ കാണുന്നുള്ളൂ. (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], 'الأحزاب: ٥١', null, 44, 44, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنْ سَهْلِ بْنِ سَعْدٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَنَا فِي الْقَوْمِ إِذْ قَالَتِ امْرَأَةٌ: إِنِّي قَدْ وَهَبْتُ نَفْسِي لَكَ يَا رَسُولَ اللهِ، فَرَأْ فِيَّ رَأْيَكَ. فَقَامَ رَجُلٌ فَقَالَ: زَوِّجْنِيهَا. فَقَالَ: "اذْهَبْ فَاطْلُبْ وَلَوْ خَاتَمًا مِنْ حَدِيدٍ". فَذَهَبَ فَلَمْ يَجِدْ شَيْئًا وَلَا خَاتَمًا مِنْ حَدِيدٍ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَمَعَكَ مِنْ سُوَرِ الْقُرْآنِ شَيْءٌ". قَالَ: نَعَمْ. قَالَ: فَزَوَّجَهُ بِمَا مَعَهُ مِنْ سُوَرِ الْقُرْآنِ. (ن)', 'സഹ്ലുബ്നു സഅ്ദ്(റ): റസൂലേ, എന്റെ ശരീരത്തെ ഞാൻ അങ്ങേയ്ക്കു നൽകിയിരിക്കുന്നു. അതിനാൽ അങ്ങ് എന്റെ കാര്യത്തിൽ തീരുമാനമെടുക്കുക എന്ന് ഒരു സ്ത്രീ റസൂൽ(സ)യോട് പറഞ്ഞപ്പോൾ ഞാനും ആ സംഘത്തിലുണ്ടായിരുന്നു. അപ്പോൾ ഒരാൾ എഴുന്നേറ്റ് പറഞ്ഞു: അവളെ എനിക്ക് വിവാഹം കഴിച്ചുതരിക. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നീ പോയി ഒരു ഇരുമ്പിന്റെ മോതിരമെങ്കിലും കൊണ്ടുവരിക." അങ്ങനെ ആ മനുഷ്യൻ പോയി അന്വേഷിച്ചെങ്കിലും ഒരു ഇരുമ്പ്മോതിരം പോലും അദ്ദേഹത്തിന് ലഭിച്ചില്ല. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഖുർആനിലെ സൂറത്തുകളിൽ വല്ലതും നിനക്കറിയുമോ?" അദ്ദേഹം പറഞ്ഞു: അതെ. അങ്ങനെ തന്റെയടുത്തുള്ള ഖുർആനിലെ സൂറത്തുകൾക്ക് പകരമായി റസൂൽ(സ) അദ്ദേഹത്തിന് വിവാഹം ചെയ്തുകൊടുത്തു. (ന)', 'سَهْلِ بْنِ سَعْدٍ', 'സഹ്ലുബ്നു സഅ്ദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 44, 44, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ جَاءَهَا حِينَ أَمَرَهُ اللهُ أَنْ يُخَيِّرَ أَزْوَاجَهُ، قَالَتْ عَائِشَةُ: فَبَدَأَ بِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "إِنِّي ذَاكِرٌ لَكِ أَمْرًا، فَلَا عَلَيْكِ أَنْ لَا تُعَجِّلِي حَتَّى تَسْتَأْمِرِي أَبَوَيْكِ". قَالَتْ: وَقَدْ عَلِمَ أَنَّ أَبَوَيَّ لَا يَأْمُرَانِي بِفِرَاقِهِ، ثُمَّ قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: {يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ إِنْ كُنْتُنَّ تُرِدْنَ الْحَيَاةَ الدُّنْيَا وَزِينَتَهَا فَتَعَالَيْنَ أُمَتِّعْكُنَّ} [الأحزاب: ٢٨]. فَقُلْتُ: فِي هَذَا أَسْتَأْمِرُ أَبَوَيَّ، فَإِنِّي أُرِيدُ اللهَ وَرَسُولَهُ وَالدَّارَ الْآخِرَةَ. (ن)', 'ആഇശ(റ): തന്റെ ഭാര്യമാരോട് ഇഷ്ടാനുസരണം പ്രവർത്തിക്കാൻ ആവശ്യപ്പെടുക എന്ന് അല്ലാഹു റസൂൽ(സ)യോട് കൽപ്പിച്ചപ്പോൾ റസൂൽ(സ) എന്റെ അടുത്ത് വന്നു. ആഇശ(റ) പറയുന്നു: മറ്റുള്ളവരുടെ മുമ്പ് എന്നോട് ഇപ്രകാരം പറഞ്ഞു: "ഞാൻ നിന്നോട് ഒരു കാര്യം പറയാൻ പോവുകയാണ്. നിന്റെ മാതാപിതാക്കളോട് കൂടിയാലോചിക്കും മുമ്പ് വേഗത്തിൽ നീ അതിൽ തീരുമാനമെടുക്കരുത്." മഹതി പറയുന്നു: എന്റെ മാതാപിതാക്കൾ റസൂൽ(സ)യെ പിരിയാൻ എന്നോട് കൽപ്പിക്കുകയില്ലെന്ന് റസൂൽ(സ)ക്ക് അറിയാമായിരുന്നു. ശേഷം അവിടന്ന് (അല്ലാഹു പറഞ്ഞതായി) എന്നോട് പറഞ്ഞു: ''നബിയേ, അങ്ങ് അവിടത്തെ പത്നിമാരോട് ഇപ്രകാരം പറയുക: ഐഹികലോകത്തെ ആഗ്രഹിക്കുന്നുവെങ്കിൽ നിങ്ങൾ വരിക, ഞാൻ നിങ്ങളെ സുഖിപ്പിക്കാം.'' അപ്പോൾ ഞാൻ പറഞ്ഞു: ഈ കാര്യത്തിലാണോ ഞാൻ എന്റെ മാതാപിതാക്കളോട് കൂടിയാലോചന നടത്തേണ്ടത്, നിശ്ചയം ഞാൻ അല്ലാഹുവിനെയും അവന്റെ റസൂലിനെയും പാരത്രികലോകത്തെയുമാണ് ആഗ്രഹിക്കുന്നത്. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], 'الأحزاب: ٢٨', null, 45, 45, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَدْ خَيَّرَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نِسَاءَهُ، أَوْ كَانَ طَلَاقًا. وفي رواية قَالَتْ: خَيَّرَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَاخْتَرْنَاهُ، فَلَمْ يَكُنْ طَلَاقًا. (ن)', 'ആഇശ(റ): റസൂൽ(സ) തന്റെ ഭാര്യമാർക്ക് ഇഷ്ടാനുസരണം ചെയ്യാനുള്ള അവസരം നൽകി, അല്ലെങ്കിൽ വിവാഹമോചനം നടക്കുമായിരുന്നു. മറ്റൊരു നിവേദനം: മഹതി പറയുന്നു: റസൂൽ(സ) ഞങ്ങൾക്ക് ഇഷ്ടാനുസരണം പ്രവർത്തിക്കാനുള്ള അവസരം നൽകി, അങ്ങനെ ഞങ്ങൾ റസൂൽ(സ)യെ തെരഞ്ഞെടുത്തു. അതിനാൽ വിവാഹമോചനം സംഭവിച്ചില്ല. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 45, 45, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=2 and h.hadith_no=16), 1, 'وَفِي رِوَايَةٍ قَالَتْ: خَيَّرَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَاخْتَرْنَاهُ، فَلَمْ يَكُنْ طَلَاقًا. (ن)', 'മറ്റൊരു നിവേദനം: മഹതി പറയുന്നു: റസൂൽ(സ) ഞങ്ങൾക്ക് ഇഷ്ടാനുസരണം പ്രവർത്തിക്കാനുള്ള അവസരം നൽകി, അങ്ങനെ ഞങ്ങൾ റസൂൽ(സ)യെ തെരഞ്ഞെടുത്തു. അതിനാൽ വിവാഹമോചനം സംഭവിച്ചില്ല. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: مَا مَاتَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَتَّى أُحِلَّ لَهُ النِّسَاءُ، وفي رواية قَالَتْ: مَا تُوُفِّيَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَتَّى أَحَلَّ اللهُ لَهُ أَنْ يَتَزَوَّجَ مِنَ النِّسَاءِ مَا شَاءَ. (ن)', 'ആഇശ(റ): സ്ത്രീകൾ തനിക്ക് അനുവദിക്കപ്പെട്ട ശേഷമാണ് റസൂൽ(സ) വഫാത്തായത്. മറ്റൊരു നിവേദനത്തിൽ: സ്ത്രീകളിൽ ഉദ്ദേശിച്ചവരെ വിവാഹം കഴിക്കൽ തനിക്ക് അനുവദിക്കപ്പെട്ടതിന് ശേഷം മാത്രമാണ് റസൂൽ(സ) വഫാത്തായത്. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 45, 45, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=2 and h.hadith_no=17), 1, 'وَفِي رِوَايَةٍ قَالَتْ: مَا تُوُفِّيَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَتَّى أَحَلَّ اللهُ لَهُ أَنْ يَتَزَوَّجَ مِنَ النِّسَاءِ مَا شَاءَ. (ن)', 'മറ്റൊരു നിവേദനത്തിൽ: സ്ത്രീകളിൽ ഉദ്ദേശിച്ചവരെ വിവാഹം കഴിക്കൽ തനിക്ക് അനുവദിക്കപ്പെട്ടതിന് ശേഷം മാത്രമാണ് റസൂൽ(സ) വഫാത്തായത്. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ سَعْدِ بْنِ هِشَامٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ دَخَلَ عَلَى أُمِّ الْمُؤْمِنِينَ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَ: قُلْتُ: إِنِّي أُرِيدُ أَنْ أَسْأَلَكِ عَنِ التَّبَتُّلِ، فَمَا تَرَيْنَ فِيهِ؟ قَالَتْ: فَلَا تَفْعَلْ، أَمَا سَمِعْتَ اللهَ عَزَّ وَجَلَّ يَقُولُ: {وَلَقَدْ أَرْسَلْنَا رُسُلًا مِنْ قَبْلِكَ وَجَعَلْنَا لَهُمْ أَزْوَاجًا وَذُرِّيَّةً} [الرعد: ٣٨] فَلَا تَتَبَتَّلْ. (ن)', 'സഅ്ദുബ്നു ഹിശാം(റ): ഞാൻ മുഅ്മിനീങ്ങളുടെ മാതാവായ ആഇശ(റ)യുടെ അടുത്തുചെന്ന് പറഞ്ഞു: വിവാഹം ഉപേക്ഷിക്കുന്നതിനെക്കുറിച്ച് ഞാൻ അങ്ങയോട് ചോദിക്കാനാഗ്രഹിക്കുന്നു. അതിൽ അങ്ങയുടെ അഭിപ്രായമെന്താണ്? അവർ പറഞ്ഞു: നീയത് ചെയ്യരുത്. ''അങ്ങയുടെ മുമ്പും നാം പ്രവാചകന്മാരെ അയക്കുകയും അവർക്ക് ഭാര്യസന്താനങ്ങളെ നൽകുകയും ചെയ്തിട്ടുണ്ട്.'' (റഅ്ദ്: 38) എന്ന് അല്ലാഹു പറയുന്നത് നീ കേട്ടിട്ടില്ലേ. അതിനാൽ നീ വിവാഹം ഉപേക്ഷിക്കരുത്. (ന)', 'سَعْدِ بْنِ هِشَامٍ', 'സഅ്ദുബ്നു ഹിശാം(റ)', null, null, array['ن']::text[], array['ന']::text[], 'الرعد: ٣٨', null, 46, 46, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللهِ، إِنِّي رَجُلٌ شَابٌّ، قَدْ خَشِيتُ عَلَى نَفْسِيَ الْعَنَتَ، وَلَا أَجِدُ طَوْلًا أَتَزَوَّجُ النِّسَاءَ، أَفَأَخْتَصِي؟ فَأَعْرَضَ عَنْهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَتَّى قَالَ ثَلَاثًا، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَا أَبَا هُرَيْرَةَ، جَفَّ الْقَلَمُ بِمَا أَنْتَ لَاقٍ، فَاخْتَصِ عَلَى ذَلِكَ أَوْ دَعْ". (ن)', 'അബൂഹുറൈറ(റ): ഞാൻ ചോദിച്ചു: റസൂലേ, ഞാൻ ഒരു യുവാവാണ്, ഞാൻ നാശത്തിൽ അകപ്പെടുമോ എന്ന് ഭയപ്പെടുന്നു. വിവാഹം കഴിക്കാനുള്ള മുതൽ എനിക്ക് ലഭിക്കാനുമില്ല. അതുകൊണ്ട് ഞാൻ ഷണ്ഡനാവട്ടെയോ? അപ്പോൾ നബി(സ) തിരിഞ്ഞുകളഞ്ഞു. അബൂഹുറൈറ(റ) അത് മൂന്നുപ്രാവശ്യം ചോദിച്ചു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അബൂഹുറൈറാ, നീ എന്തുചെയ്യാൻ പോകുന്നുവെന്ന് പേന എഴുതിവെച്ചിരിക്കുന്നു. അതനുസരിച്ച് നീ ഷണ്ഡീകരണം നടത്തുകയോ ഉപേക്ഷിക്കുകയോ ചെയ്യുക." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 46, 46, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَرَادَ عُثْمَانُ بْنُ مَظْعُونٍ رَضِيَ اللهُ عَنْهُ أَنْ يَتَبَتَّلَ، فَنَهَاهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَلَوْ أَجَازَ لَهُ ذَلِكَ لَاخْتَصَيْنَا. (م)', 'സഅ്ദുബ്നു അബീവഖാസ്(റ): ഉസ്മാനുബ്നു മള്ഊൻ(റ) ഭാര്യമാരെ വെടിഞ്ഞ് ആരാധനകളിൽ മുഴുകാൻ തീരുമാനിച്ചു. അന്നേരം റസൂൽ(സ) അദ്ദേഹത്തെ വിലക്കി. റസൂൽ(സ) അത് അനുവദിച്ചിരുന്നെങ്കിൽ ഞങ്ങളും വികാരശമനോപാധി തേടുമായിരുന്നു. (മു)', 'سَعْدِ بْنِ أَبِي وَقَّاصٍ', 'സഅ്ദുബ്നു അബീവഖാസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 46, 46, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "تُنْكَحُ الْمَرْأَةُ لِأَرْبَعٍ: لِمَالِهَا، وَلِحَسَبِهَا، وَلِجَمَالِهَا، وَلِدِينِهَا. فَاظْفَرْ بِذَاتِ الدِّينِ، تَرِبَتْ يَدَاكَ". (ق,د,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നാല് കാര്യങ്ങളുടെ പേരിലാണ് സ്ത്രീകൾ വിവാഹം കഴിക്കപ്പെടുക: അവളുടെ മുതൽ, കുടുംബം, ഭംഗി, മതചിട്ട എന്നിവയുടെ പേരിൽ. അതിനാൽ മതചിട്ടയുള്ള സ്ത്രീയെ നീ വിവാഹം കഴിക്കുക. എങ്കിൽ നിനക്ക് വിജയിക്കാം." (ബു,മു,ദ,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 46, 46, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَزَوَّجُوا النِّسَاءَ لِحُسْنِهِنَّ، فَعَسَى حُسْنُهُنَّ أَنْ يُرْدِيَهُنَّ. وَلَا تَزَوَّجُوهُنَّ لِأَمْوَالِهِنَّ، فَعَسَى أَمْوَالُهُنَّ أَنْ تُطْغِيَهُنَّ. وَلَكِنْ تَزَوَّجُوهُنَّ عَلَى الدِّينِ، وَلَأَمَةٌ خَرْمَاءُ سَوْدَاءُ ذَاتُ دِينٍ أَفْضَلُ". [ز: في سنده ضعيف] (جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഭംഗിയുടെ പേരിൽ നിങ്ങൾ സ്ത്രീകളെ വിവാഹം കഴിക്കരുത്. അവരുടെ ഭംഗി ഒരുപക്ഷേ അവരെ നശിപ്പിച്ചേക്കാം. മുതലിന്റെ പേരിലും വിവാഹം കഴിക്കരുത്. അവരുടെ മുതൽ അവരെ ഒരുപക്ഷേ പിഴപ്പിച്ചേക്കാം. മതചിട്ടയുടെ പേരിൽ മാത്രം നിങ്ങളവരെ വിവാഹം കഴിക്കുക. മതചിട്ടയുള്ളവളും മൂക്കുകുത്തിയവളുമായി കറുത്ത അടിമസ്ത്രീയാണ് ഏറ്റവും ഉത്തമം." (ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيف', null, 46, 47, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنْ أَبِي حَاتِمٍ الْمُزَنِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا جَاءَكُمْ مَنْ تَرْضَوْنَ دِينَهُ وَخُلُقَهُ فَأَنْكِحُوهُ، إِلَّا تَفْعَلُوا تَكُنْ فِتْنَةٌ فِي الْأَرْضِ وَفَسَادٌ". قَالُوا: يَا رَسُولَ اللهِ، وَإِنْ كَانَ فِيهِ؟ قَالَ: "إِذَا جَاءَكُمْ مَنْ تَرْضَوْنَ دِينَهُ وَخُلُقَهُ، فَأَنْكِحُوهُ". ثَلَاثَ مَرَّاتٍ. حَسَنٌ. (ت)', 'അബൂഹാതിമുൽ മുസ്നി(റ): റസൂൽ(സ) പറഞ്ഞു: "മതത്തിന്റെയും സ്വഭാവത്തിന്റെയും പേരിൽ നിങ്ങൾ തൃപ്തിപ്പെടുന്നവർ നിങ്ങളുടെ അടുത്തുവന്നാൽ നിങ്ങൾ അവന് വിവാഹം ചെയ്തുകൊടുക്കുക. നിങ്ങൾ അപ്രകാരം ചെയ്യുന്നില്ലെങ്കിൽ ഭൂമിയിൽ അക്രമവും അനാചാരവുമുണ്ടാകും." അവർ ചോദിച്ചു: റസൂലേ, അവനിൽ വല്ല കുറവുമുണ്ടെങ്കിലോ? റസൂൽ(സ) പറഞ്ഞു: "മതത്തിന്റെയും സ്വഭാവത്തിന്റെയും പേരിൽ നിങ്ങൾ തൃപ്തിപ്പെടുന്ന ഒരുത്തൻ വന്നാൽ നിങ്ങൾ അവന് വിവാഹം ചെയ്തുകൊടുക്കുക." തിരുമേനി(സ) ഇത് മൂന്ന് പ്രാവശ്യം പറഞ്ഞു. (തു)', 'أَبِي حَاتِمٍ الْمُزَنِيِّ', 'അബൂഹാതിമുൽ മുസ്നി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 47, 47, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ الْمَرْأَةَ تُنْكَحُ عَلَى دِينِهَا وَمَالِهَا وَجَمَالِهَا، فَعَلَيْكَ بِذَاتِ الدِّينِ، تَرِبَتْ يَدَاكَ". حَسَنٌ صَحِيحٌ. (م,ت)', 'ജാബിർ(റ): നബി(സ) പറഞ്ഞു: "നിശ്ചയം സ്ത്രീയുടെ ഭംഗിയും മുതലും മതചിട്ടയും അടിസ്ഥാനപ്പെടുത്തിയാണ് അവൾ വിവാഹം കഴിക്കപ്പെടുക. അതുകൊണ്ട് മതചിട്ടയുള്ളവളെ വിവാഹം കഴിക്കുക. എങ്കിൽ നീ വിജയിച്ചു." (മു,തു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 47, 47, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ أَحْسَابَ أَهْلِ الدُّنْيَا الَّذِي يَذْهَبُونَ إِلَيْهِ الْمَالُ". (ن)', 'ബുറൈദ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഐഹികലോകത്തെ കാംക്ഷിക്കുന്നവർ ആഗ്രഹിക്കുന്ന ശ്രേഷ്ഠത മുതലാണ്." (ന)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 47, 47, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قِيلَ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَيُّ النِّسَاءِ خَيْرٌ؟ قَالَ: "الَّتِي تَسُرُّهُ إِذَا نَظَرَ، وَتُطِيعُهُ إِذَا أَمَرَ، وَلَا تُخَالِفُهُ فِي نَفْسِهَا وَمَالِهَا بِمَا يَكْرَهُ". (ن)', 'അബൂഹുറൈറ(റ): ഏത് സ്ത്രീയാണ് ഉത്തമ? എന്ന് നബി(സ)യോട് ചോദിക്കപ്പെട്ടപ്പോൾ അവിടന്ന് പറഞ്ഞു: "കണ്ടാൽ ഭർത്താവിന് സന്തോഷമുണ്ടാക്കുകയും കൽപ്പിച്ചാൽ അവനെ അനുസരിക്കുകയും തന്റെ ശരീരത്തിലും മുതലിലും ഭർത്താവ് വെറുക്കും വിധം ഭർത്താവിന് എതിര് ചെയ്യാതിരിക്കുകയും ചെയ്യുന്നവളാണ് ഉത്തമ." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 47, 47, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ كَانَ يَقُولُ: "مَا اسْتَفَادَ الْمُؤْمِنُ – بَعْدَ تَقْوَى اللهِ – خَيْرًا لَهُ مِنْ زَوْجَةٍ صَالِحَةٍ: إِنْ أَمَرَهَا أَطَاعَتْهُ: وَإِنْ نَظَرَ إِلَيْهَا سَرَّتْهُ، وَإِنْ أَقْسَمَ عَلَيْهَا أَبَرَّتْهُ، وَإِنْ غَابَ عَنْهَا نَصَحَتْهُ فِي نَفْسِهَا وَمَالِهِ". [ز: في سنده ضعيف، وله شاهد] (جه)', 'അബൂഉമാമ(റ): നബി(സ) ഇപ്രകാരം പറയാറുണ്ടായിരുന്നു: "അല്ലാഹുവിന്റെ ഭക്തിക്കു ശേഷം താൻ പറഞ്ഞാലനുസരിക്കുന്ന തന്നോട് സത്യം ചെയ്ത് പറഞ്ഞാൽ അത് പൂർത്തിയാക്കുന്ന താൻ അപ്രത്യക്ഷനാകുമ്പോൾ തന്റെ മുതലിലും അവളുടെ ശരീരത്തിലും ഗുണം കാംക്ഷിക്കുന്നവളുമായ സൽഗുണയായ ഭാര്യയെക്കാൾ ഉത്തമമായ ഒരു നന്മയെയും സത്യവിശ്വാസി നേടിയിട്ടില്ല." (ജ)', 'أَبِي أُمَامَةَ', 'അബൂഉമാമ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيف، وله شاهد', null, 47, 48, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّمَا الدُّنْيَا مَتَاعٌ، وَلَيْسَ مِنْ مَتَاعِ الدُّنْيَا شَيْءٌ أَفْضَلَ مِنَ الْمَرْأَةِ الصَّالِحَةِ". (م,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം ഐഹികലോകം നിറയെ വിഭവങ്ങളാണ്. ഐഹികലോകത്തെ വിഭവങ്ങളിൽ സൽഗുണയായ സ്ത്രീയെക്കാൾ ഉത്തമമായ ഒരു വിഭവവുമില്ല." (മു,ന,ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['م','ن','جه']::text[], array['മു','ന','ജ']::text[], null, null, 48, 48, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنْ ثَوْبَانَ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا نَزَلَ فِي الْفِضَّةِ وَالذَّهَبِ مَا نَزَلَ قَالُوا: فَأَيَّ الْمَالِ نَتَّخِذُ؟ قَالَ عُمَرُ رَضِيَ اللهُ عَنْهُ: فَأَنَا أَعْلَمُ لَكُمْ ذَلِكَ. فَأَوْضَعَ عَلَى بَعِيرِهِ، فَأَدْرَكَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَنَا فِي أَثَرِهِ، فَقَالَ: يَا رَسُولَ اللهِ، أَيَّ الْمَالِ نَتَّخِذُ؟ فَقَالَ: "لِيَتَّخِذْ أَحَدُكُمْ قَلْبًا شَاكِرًا، وَلِسَانًا ذَاكِرًا، وَزَوْجَةً مُؤْمِنَةً، تُعِينُ أَحَدَكُمْ عَلَى أَمْرِ الْآخِرَةِ". (ت,جه)', 'സൗബാൻ(റ): സ്വർണ്ണത്തിന്റെയും വെള്ളിയുടെയും കാര്യത്തിൽ പ്രത്യേക വിധിവിലക്കുകൾ അവതരിച്ചപ്പോൾ ചിലർ ചോദിച്ചു: ഇനി ഏത് മുതലാണ് നാം ഉപയോഗിക്കുക. ഉമർ(റ) പറഞ്ഞു: അതിനെക്കുറിച്ച് ഞാൻ നിങ്ങൾക്ക് പഠിപ്പിച്ചുതരാം. ശേഷം ഉമർ(റ) തന്റെ ഒട്ടകപ്പുറത്ത് ധൃതിയിൽ പുറപ്പെട്ടു. അങ്ങനെ ഉമർ(റ) നബി(സ)യുടെ അടുത്തെത്തി, ഞാൻ അവരുടെ പിറകിലുണ്ടായിരുന്നു. അദ്ദേഹം ചോദിച്ചു: റസൂലേ, ഏത് മുതലാണ് ഞങ്ങൾ ഉപയോഗിക്കേണ്ടത്? റസൂൽ(സ) പറഞ്ഞു: "നന്ദിചെയ്യുന്ന ഹൃദയത്തെയും ദിക്ർ ചൊല്ലുന്ന നാവിനെയും പാരത്രിക കാര്യത്തിൽതന്നെ സഹായിക്കുന്ന മുഅ്മിനായ ഭാര്യയെയും നിങ്ങളിലോരോരുത്തരും നേടുക." (തു,ജ)', 'ثَوْبَانَ', 'സൗബാൻ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 48, 48, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ أَرَادَ أَنْ يَلْقَى اللهَ طَاهِرًا مُطَهَّرًا فَلْيَتَزَوَّجِ الْحَرَائِرَ". [ز: في سنده راويان ضعيفان] (جه)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) ഇപ്രകാരം പറയുന്നത് ഞാൻ കേട്ടു: "ശുദ്ധനും പരിശുദ്ധനുമായി അല്ലാഹുവിനെ കണ്ടുമുട്ടണമെന്ന് ആരെങ്കിലും കൊതിക്കുന്നുവെങ്കിൽ സ്വതന്ത്രകളെ അവൻ വിവാഹം കഴിക്കട്ടെ." (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده راويان ضعيفان', null, 48, 48, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "النِّكَاحُ مِنْ سُنَّتِي، فَمَنْ لَمْ يَعْمَلْ بِسُنَّتِي فَلَيْسَ مِنِّي. وَتَزَوَّجُوا، فَإِنِّي مُكَاثِرٌ بِكُمُ الْأُمَمَ. وَمَنْ كَانَ ذَا طَوْلٍ فَلْيَنْكِحْ، وَمَنْ لَمْ يَجِدْ فَعَلَيْهِ بِالصِّيَامِ، فَإِنَّ الصَّوْمَ لَهُ وِجَاءٌ". [في سنده راو متفق على ضعفه، لكن له شاهد صحيح] (جه)', 'ആഇശ(റ): റസൂൽ(സ) പറഞ്ഞു: "വിവാഹം എന്റെ ചര്യയിൽപ്പെട്ടതാണ്. എന്റെ ചര്യയനുസരിച്ച് പ്രവർത്തിക്കാത്തവൻ എന്നിൽപ്പെട്ടവനല്ല. നിങ്ങൾ വിവാഹം കഴിക്കുക. നിങ്ങളുടെ ആധിക്യം കൊണ്ട് ഞാൻ മറ്റുസമുദായക്കാരോട് അഭിമാനം പറയും. ഐശ്വര്യമുള്ളവൻ വിവാഹം കഴിക്കുക. അതിന് സാധിക്കാത്തവൻ നോമ്പനുഷ്ഠിക്കുക. നിശ്ചയം നോമ്പ് വികാരത്തെ അടക്കിനിർത്തുന്നതാണ്." (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'في سنده راو متفق على ضعفه، لكن له شاهد صحيح', null, 49, 49, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ عَبْدَ اللهِ هَلَكَ وَتَرَكَ تِسْعَ بَنَاتٍ – أَوْ قَالَ: سَبْعَ [بَنَاتٍ] – فَتَزَوَّجْتُ امْرَأَةً ثَيِّبًا، فَقَالَ لِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَا جَابِرُ تَزَوَّجْتَ". قَالَ: قُلْتُ: نَعَمْ. قَالَ: "فَبِكْرٌ أَمْ ثَيِّبٌ". قَالَ: قُلْتُ: بَلْ ثَيِّبٌ يَا رَسُولَ اللهِ، قَالَ: "فَهَلَّا جَارِيَةً تُلَاعِبُهَا وَتُلَاعِبُكَ، أَوْ قَالَ: تُضَاحِكُهَا وَتُضَاحِكُكَ". قَالَ: قُلْتُ لَهُ: إِنَّ عَبْدَ اللهِ هَلَكَ وَتَرَكَ تِسْعَ بَنَاتٍ – أَوْ: سَبْعَ [بَنَاتٍ] – وَإِنِّي كَرِهْتُ أَنْ آتِيَهُنَّ – أَوْ: أَجِيئَهُنَّ – بِمِثْلِهِنَّ، فَأَحْبَبْتُ أَنْ أَجِيءَ بِامْرَأَةٍ تَقُومُ عَلَيْهِنَّ وَتُصْلِحُهُنَّ. قَالَ: "فَبَارَكَ اللهُ لَكَ". أَوْ: قَالَ لِي خَيْرًا. (م)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): ഏഴ് പെൺമക്കളെ അല്ലെങ്കിൽ ഒമ്പത് പെൺമക്കളെ ഒഴിവാക്കിയിട്ടാണ് അബ്ദുല്ല(റ) - എന്റെ പിതാവ് - വഫാത്തായത്. ശേഷം ഞാൻ ഒരു വിധവയെ വിവാഹം കഴിച്ചു. റസൂൽ(സ) എന്നോട് ചോദിച്ചു: "ജാബിറേ, നീ വിവാഹം കഴിച്ചുവോ?" ഞാൻ പറഞ്ഞു: അതെ. റസൂൽ(സ) ചോദിച്ചു: "കന്യകയോ വിധവയോ?" ഞാൻ പറഞ്ഞു: റസൂലേ, വിധവയെയാണ് ഞാൻ വിവാഹം കഴിച്ചത്. റസൂൽ(സ) ചോദിച്ചു: "ഒരു ബാലികയെ വേൾക്കാമായിരുന്നില്ലേ? എങ്കിൽ നിനക്കവളെയും അവൾക്ക് നിന്നെയും കളിപ്പിക്കാം. അല്ലെങ്കിൽ നിനക്കവളെയും അവൾക്ക് നിന്നെയും ചിരിപ്പിക്കാം." ഞാൻ പറഞ്ഞു: ഒമ്പതോ ഏഴോ പെൺകുട്ടികളെ ഉപേക്ഷിച്ചുകൊണ്ടാണ് അബ്ദുല്ല(റ) വഫാത്തായത്. ആ പെൺകുട്ടികളെപ്പോലെയുള്ള ഒരു സ്ത്രീയെ അവരിലേക്ക് കൊണ്ടുവരുന്നതിനെ ഞാൻ വെറുക്കുകയും അവരുടെ കാര്യങ്ങൾ നോക്കിനടത്തുകയും അവരെ പരിചരിക്കുകയും ചെയ്യുന്ന ഒരുത്തിയെ കൊണ്ടുവരണമെന്ന് ഞാൻ ആഗ്രഹിക്കുകയും ചെയ്തു. റസൂൽ(സ) പറഞ്ഞു: "എങ്കിൽ അല്ലാഹു നിനക്ക് അനുഗ്രഹം ചെയ്യട്ടെ." അല്ലെങ്കിൽ എനിക്ക് നല്ലത് വരട്ടെ എന്ന് അവിടന്ന് പറഞ്ഞു. (മു)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['م']::text[], array['മു']::text[], 'بَنَاتٍ', null, 49, 49, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: تَزَوَّجْتُ امْرَأَةً عَلَى عَهْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَلَقِيتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "أَتَزَوَّجْتَ يَا جَابِرُ". قُلْتُ: نَعَمْ. قَالَ: "أَبِكْرًا أَوْ ثَيِّبًا". قُلْتُ ثَيِّبًا. قَالَ: "فَهَلَّا بِكْرًا تُلَاعِبُهَا". قُلْتُ: كُنَّ لِي أَخَوَاتٌ، فَخَشِيتُ أَنْ تَدْخُلَ بَيْنِي وَبَيْنَهُنَّ. قَالَ: "فَذَاكَ إِذَنْ". (ق,ن,جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ)യുടെ കാലത്ത് ഞാനൊരു സ്ത്രീയെ വിവാഹം ചെയ്തു. ശേഷം ഞാൻ റസൂൽ(സ)യെ കണ്ടുമുട്ടി. അപ്പോൾ അവിടന്ന് ചോദിച്ചു: "ജാബിറേ, നീ വിവാഹം കഴിച്ചുവോ?" ഞാൻ പറഞ്ഞു: അതെ. റസൂൽ(സ) ചോദിച്ചു: "കന്യകയെയോ അതോ വിധവയെയോ". ഞാൻ പറഞ്ഞു: വിധവയെ. റസൂൽ(സ) ചോദിച്ചു: "കന്യകയെ വിവാഹം കഴിക്കാമായിരുന്നില്ലേ, എങ്കിൽ നിനകക്ക് അവളെ കളിപ്പിക്കാമായിരുന്നു." ഞാൻ പറഞ്ഞു: എനിക്ക് കുറെ സഹോദരിമാരുണ്ടായിരുന്നു. അതിനാൽ അവൾ എന്റെയും അവരുടെയും ഇടയിൽ ഇടപെടുമോ എന്ന് ഞാൻ ഭയപ്പെട്ടു. റസൂൽ(സ) പറഞ്ഞു: "എങ്കിൽ അവൾ തന്നെ മതി." (ബു,മു,ന,ജ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['ق','ن','جه']::text[], array['ബു','മു','ന','ജ']::text[], null, null, 49, 50, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنْ عُوَيْمِ بْنِ سَاعِدَةَ الْأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُ عَنْ جَدِّهِ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "عَلَيْكُمْ بِالْأَبْكَارِ، فَإِنَّهُنَّ أَعْذَبُ أَفْوَاهًا، وَأَنْتَقُ أَرْحَامًا، وَأَرْضَى بِالْيَسِيرِ". [ز: في سنده راو مختلف فيه] (جه)', 'ഉവൈമുബ്നു സാഇദ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ കന്യകകളെ വിവാഹം കഴിക്കുക. നിശ്ചയമവർ ശുദ്ധമായ വായയുള്ളവരും കൂടുതൽ പ്രസവിക്കുന്നവരും ചുരുങ്ങിയവ കൊണ്ട് തൃപ്തിപ്പെടുന്നവരുമാണ്." (ജ)', 'عُوَيْمِ بْنِ سَاعِدَةَ الْأَنْصَارِيِّ', 'ഉവൈമുബ്നു സാഇദ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده راو مختلف فيه', null, 50, 50, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قُلْتُ: يَا رَسُولَ اللهِ أَرَأَيْتَ لَوْ نَزَلْتَ وَادِيًا وَفِيهِ شَجَرَةٌ قَدْ أُكِلَ مِنْهَا، وَوَجَدْتَ شَجَرًا لَمْ يُؤْكَلْ مِنْهَا، فِي أَيِّهَا كُنْتَ تُرْتِعُ بَعِيرَكَ؟ قَالَ: "فِي الَّذِي لَمْ يُرْتَعْ مِنْهَا". تَعْنِي أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَمْ يَتَزَوَّجْ بِكْرًا غَيْرَهَا. (خ)', 'ആഇശ(റ): ഞാൻ റസൂൽ(സ)യോട് ചോദിച്ചു: റസൂലേ, മുമ്പ് ആരോ ഭക്ഷിച്ച ഒരു മരമുള്ള താഴ്വരയിൽ അങ്ങ് ഇറങ്ങുകയും മുമ്പ് ആരും ഭക്ഷിച്ചിട്ടില്ലാത്ത ഒരു മരത്തെ നിങ്ങൾ അതിൽ കാണുകയും ചെയ്താൽ അവയിൽ ഏതിലാണ് അങ്ങയുടെ ഒട്ടകത്തെ അങ്ങ് മേയ്ക്കുക എന്ന് പറഞ്ഞുതരിക. നബി(സ) പറഞ്ഞു: "ആരും മേയ്ച്ചിട്ടില്ലാത്തതിൽ നിന്ന്." താനൊഴികെ മറ്റൊരു കന്യകയെയും റസൂൽ(സ) വിവാഹം കഴിച്ചിട്ടില്ലെന്നാണ് ആഇശ(റ) ഉദ്ദേശിച്ചത്. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 50, 50, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "تَخَيَّرُوا لِنُطَفِكُمْ، وَانْكِحُوا الْأَكْفَاءَ وَأَنْكِحُوا إِلَيْهِمْ". [ز: في سنده ضعيف] (جه)', 'ആഇശ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളുടെ ഇന്ദ്രിയങ്ങൾക്ക് (യോജിച്ചവരെ) നിങ്ങൾ തെരഞ്ഞെടുക്കുക. കുഫ്വ് ഒത്തവരെ നിങ്ങൾ വിവാഹം കഴിക്കുകയും കുഫ്വ് ഒത്തവർക്ക് വിവാഹം ചെയ്ത് കൊടുക്കുകയും ചെയ്യുക." (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيف', null, 50, 50, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ أَبَا هِنْدٍ حَجَمَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الْيَافُوخِ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَا بَنِي بَيَاضَةَ، أَنْكِحُوا أَبَا هِنْدٍ، وَأَنْكِحُوا إِلَيْهِ". قَالَ: "وَإِنْ كَانَ فِي شَيْءٍ مِمَّا تَدَاوُونَ بِهِ خَيْرٌ فَالْحِجَامَةُ". (د)', 'അബൂഹുറൈറ(റ): നബി(സ)യുടെ മൂർദ്ധാവിൽ അബൂഹിന്ദ്(റ) കൊമ്പ് വെച്ചു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ബയാളയുടെ സന്തതികളേ! നിങ്ങൾ അബൂഹിന്ദിന് നിങ്ങളുടെ പെൺമക്കളെ വിവാഹം ചെയ്ത് കൊടുക്കുകയും അദ്ദേഹത്തിന്റെ മക്കളെ നിങ്ങൾ വിവാഹം കഴിക്കുകയും ചെയ്യുക." ശേഷം അവിടന്ന് പറഞ്ഞു: "നിങ്ങൾ ചികിത്സിച്ച് കൊണ്ടിരിക്കുന്ന വല്ല കാര്യത്തിലും വല്ല നന്മയുമുണ്ടെങ്കിൽ അത് കൊമ്പ്‌വെക്കൽ മാത്രമാണ്." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 50, 50, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا أَنَّ أَبَا حُذَيْفَةَ بْنَ عُتْبَةَ بْنِ رَبِيعَةَ بْنِ عَبْدِ شَمْسٍ، وَكَانَ مِمَّنْ شَهِدَ بَدْرًا مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَبَنَّى سَالِمًا وَأَنْكَحَهُ بِنْتَ أَخِيهِ هِنْدَ بِنْتَ الْوَلِيدِ بْنِ عُتْبَةَ بْنِ رَبِيعَةَ، وَهُوَ مَوْلًى لِامْرَأَةٍ مِنَ الْأَنْصَارِ، كَمَا تَبَنَّى النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ زَيْدًا، وَكَانَ مَنْ تَبَنَّى رَجُلًا فِي الْجَاهِلِيَّةِ، دَعَاهُ النَّاسُ إِلَيْهِ، وَوَرِثَ مِنْ مِيرَاثِهِ، حَتَّى أَنْزَلَ اللهُ: {ادْعُوهُمْ لِآبَائِهِمْ} إِلَى قَوْلِهِ {وَمَوَالِيكُمْ} فَرُدُّوا إِلَى آبَائِهِمْ، فَمَنْ لَمْ يُعْلَمْ لَهُ أَبٌ كَانَ مَوْلًى وَأَخًا فِي الدِّينِ، فَجَاءَتْ سَهْلَةُ بِنْتُ سُهَيْلِ بْنِ عَمْرٍو الْقُرَشِيِّ، ثُمَّ الْعَامِرِيِّ، وَهِيَ امْرَأَةُ أَبِي حُذَيْفَةَ بْنِ عُتْبَةَ، النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللهِ إِنَّا كُنَّا نَرَى سَالِمًا وَلَدًا، وَقَدْ أَنْزَلَ اللهُ فِيهِ مَا قَدْ عَلِمْتَ، فَذَكَرَ الْحَدِيثَ. (خ,ن)', 'ആഇശ(റ): തിരുമേനി(സ)യുടെ കൂടെ ബദർ യുദ്ധത്തിൽ പങ്കെടുത്ത അബൂഹുദൈഫതുബ്നു ഉത്ബ(റ), സാലിം(റ)വിനെ ദത്തെടുക്കുകയും തന്റെ സഹോദരപുത്രി ഹിന്ദ് ബിൻതു വലീദിനെ അദ്ദേഹത്തിന് വിവാഹം കഴിച്ച് കൊടുക്കുകയും ചെയ്തു. സാലിം(റ) മുമ്പ് ഒരു അൻസാരി സ്ത്രീയുടെ അടിമയായിരുന്നു. റസൂൽ(സ) സൈദ്(റ)വിനെ ദത്തെടുത്തതുപോലെയായിരുന്നു ഈ സംഭവം. ജാഹിലിയ്യാ കാലത്ത് ഒരാളെ ദത്തെടുത്താൽ അയാളെ ആ ദത്തെടുത്തവന്റെ കുടുംബമായി ഗണിക്കുകയും ദത്തുപുത്രന് അനന്തരാവകാശം ലഭിക്കുകയും ചെയ്യാറുണ്ടായിരുന്നു. അവസാനം ''അവരെ യഥാർത്ഥ പിതാക്കളോട് ചേർത്തുവിളിക്കുക''യെന്ന ഖുർആൻ വാക്യം അവതരിച്ചു. അതോടെ അവരെയെല്ലാം സ്വന്തം പിതാക്കളോട് ചേർത്തു വിളിക്കാൻ തുടങ്ങി. പിതാവ് ആരെന്ന് അറിയപ്പെടാത്തവർ സേവകരും ദീനിലെ സഹോദരൻമാരുമായി പരിഗണിക്കപ്പെട്ടു. അങ്ങനെയിരിക്കെ സഹ്‌ലതു ബിൻത് അംറ്(റ) - അവർ അബൂഹുദൈഫ(റ)വിന്റെ ഭാര്യയായിരുന്നു - വന്ന് നബി(സ)യോട് പറഞ്ഞു: "റസൂലേ, സാലിമിനെ സ്വന്തം പുത്രനായിട്ടാണ് ഞങ്ങൾ ഗണിച്ചിരുന്നത്. ഇപ്പോഴിതാ അങ്ങറിഞ്ഞ പോലെ അല്ലാഹു ഈ വിധി അവതരിപ്പിച്ചിരിക്കുന്നു. തുടർന്ന് ഹദീസിന്റെ ബാക്കിഭാഗം വിവരിച്ചു. (ബു,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 50, 51, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: دَخَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى ضُبَاعَةَ بِنْتِ الزُّبَيْرِ، فَقَالَ لَهَا: "لَعَلَّكِ أَرَدْتِ الْحَجَّ؟" قَالَتْ: وَاللهِ لَا أَجِدُنِي إِلَّا وَجِعَةً، فَقَالَ لَهَا: "حُجِّي وَاشْتَرِطِي وَقُولِي: اللَّهُمَّ مَحِلِّي حَيْثُ حَبَسْتَنِي". وَكَانَتْ تَحْتَ الْمِقْدَادِ بْنِ الْأَسْوَدِ. (خ)', 'ആഇശ(റ): നബി(സ) ളുബാഅതുബിൻത് സുബൈർ(റ)വിന്റെ അടുത്ത് ചെന്ന് അവരോട് ചോദിച്ചു: "നീ ഹജ്ജ് ചെയ്യണമെന്ന് ആഗ്രഹിക്കുന്നുണ്ടോ?". അവർ പറഞ്ഞു: അല്ലാഹുവാണെ, ഒരു രോഗമല്ലാതെ എനിക്കൊരു തടസ്സവുമില്ല. നബി(സ) പറഞ്ഞു: "നീ ഹജ്ജ് ചെയ്ത്കൊള്ളുക, ഇങ്ങനെയൊരു നിബന്ധനയും വെച്ചകൊള്ളുക: എന്റെ രോഗം എവിടെവെച്ച് എന്നെ തടസ്സപ്പെടുത്തുന്നുവോ അവിടെ വെച്ച് ഹജ്ജിന്റെ നിശ്ചയത്തിൽ നിന്ന് ഞാൻ ഒഴിവാകും." അവർ മിക്ദാദ്(റ)വിന്റെ ഭാര്യയായിരുന്നു. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 51, 51, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنْ سَهْلٍ رَضِيَ اللهُ عَنْهُ قَالَ: مَرَّ رَجُلٌ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "مَا تَقُولُونَ فِي هَذَا؟" قَالُوا: حَرِيٌّ إِنْ خَطَبَ أَنْ يُنْكَحَ، وَإِنْ شَفَعَ أَنْ يُشَفَّعَ، وَإِنْ قَالَ أَنْ يُسْتَمَعَ، قَالَ: ثُمَّ سَكَتَ، فَمَرَّ رَجُلٌ مِنْ فُقَرَاءِ الْمُسْلِمِينَ، فَقَالَ: "مَا تَقُولُونَ فِي هَذَا؟" قَالُوا: حَرِيٌّ إِنْ خَطَبَ أَنْ لَا يُنْكَحَ، وَإِنْ شَفَعَ أَنْ لَا يُشَفَّعَ، وَإِنْ قَالَ أَنْ لَا يُسْمَعَ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "هَذَا خَيْرٌ مِنْ مِلْءِ الْأَرْضِ مِثْلَ هَذَا". [يَقْصُدُ الْأَوَّلَ]. (خ)', 'സഹ്ൽ(റ): ഒരു മനുഷ്യൻ നബി(സ)യുടെ അടുത്ത്കൂടെ നടന്നുപോയി. അവിടന്ന് ചോദിച്ചു: "ഈ മനുഷ്യനെപ്പറ്റി നിങ്ങളുടെ അഭിപ്രായമെന്ത്?" അവർ പറഞ്ഞു: അദ്ദേഹം ഒരു തറവാട്ടിൽ വിവാഹാലോചന നടത്തിയാൽ അദ്ദേഹത്തിന് വിവാഹം ചെയ്ത് കൊടുക്കും, വല്ല ശുപാർശയും ചെയ്താൽ അത് സ്വീകരിക്കപ്പെടും, വല്ലതും സംസാരിച്ചാൽ മറ്റുള്ളവരെല്ലാം അനുസരിക്കും. അൽപസമയം നബി(സ) മൗനമവലംബിച്ചു. അപ്പോൾ ഒരു മുസ്ലിം ദരിദ്രൻ അതിലൂടെ കടന്നുപോയി. തിരുമേനി(സ) ചോദിച്ചു: "ഇദ്ദേഹത്തെപ്പറ്റി നിങ്ങളുടെ അഭിപ്രായമെന്ത്?." അവർ പറഞ്ഞു: അദ്ദേഹം വിവാഹാലോചന നടത്തിയാൽ ആരും വിവാഹം ചെയ്തുകൊടുക്കുകയില്ല. ശിപാർശ ചെയ്താൽ ആരും സ്വീകരിക്കുകയില്ല. എന്തെങ്കിലും പറഞ്ഞാൽ ആരും ശ്രദ്ധിക്കുകയുമില്ല. നബി(സ) പറഞ്ഞു: "ആദ്യത്തെയാളെപ്പോലുള്ളവർ ഭൂമിനിറയെ ഉണ്ടായാലും അവരേക്കാളും ഉത്തമൻ ഇദ്ദേഹമാണ്." (ബു)', 'سَهْلٍ', 'സഹ്ൽ(റ)', null, null, array['خ']::text[], array['ബു']::text[], 'يَقْصُدُ الْأَوَّلَ', null, 51, 52, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنْ مَعْقِلِ بْنِ يَسَارٍ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنِّي أَصَبْتُ امْرَأَةً ذَاتَ حَسَبٍ وَمَنْصِبٍ، إِلَّا أَنَّهَا لَا تَلِدُ، أَفَأَتَزَوَّجُهَا؟ فَنَهَاهُ، ثُمَّ أَتَاهُ الثَّانِيَةَ فَنَهَاهُ، ثُمَّ أَتَاهُ الثَّالِثَةَ فَنَهَاهُ، فَقَالَ: "تَزَوَّجُوا الْوَلُودَ الْوَدُودَ، فَإِنِّي مُكَاثِرٌ بِكُمْ". (ن)', 'മഅ്ഖലുബ്നു യസാർ(റ): ഒരാള് റസൂൽ(സ)യുടെ അടുത്ത് വന്ന് ചോദിച്ചു: കുടുംബമഹിമയും സ്ഥാനവുമുള്ള ഒരു സ്ത്രീയെ ഞാൻ കണ്ടുവെച്ചിട്ടുണ്ട്. പക്ഷേ, അവൾ പ്രസവിക്കുകയില്ല. ഞാനവളെ വിവാഹം കഴിക്കട്ടെയോ? നബി(സ) അദ്ദേഹത്തെ വിലക്കി. രണ്ടാം പ്രാവശ്യവും അദ്ദേഹം വന്ന് ചോദിച്ചു, അപ്പോഴും നബി(സ) അദ്ദേഹത്തെ വിലക്കി. പിന്നെ മൂന്നാം പ്രാവശ്യം വന്നപ്പോഴും നബി(സ) അദ്ദേഹത്തെ വിലക്കി, എന്നിട്ട് പറഞ്ഞു: "സ്നേഹസമ്പന്നരായ കൂടുതൽ പ്രസവിക്കുന്ന സ്ത്രീകളെ നിങ്ങൾ വിവാഹം കഴിക്കുക, നിശ്ചയം ഞാൻ നിങ്ങളുടെ ആധിക്യം കൊണ്ട് അഭിമാനിക്കുന്നവനാണ്." (ന)', 'مَعْقِلِ بْنِ يَسَارٍ', 'മഅ്ഖലുബ്നു യസാർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 52, 52, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنَّ امْرَأَتِي لَا تَمْنَعُ يَدَ لَامِسٍ. قَالَ: "غَرِّبْهَا". قَالَ: أَخَافُ أَنْ تَتْبَعَهَا نَفْسِي، قَالَ: "فَاسْتَمْتِعْ بِهَا". (د,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ഒരാൾ നബി(സ)യുടെ അടുത്ത് വന്ന് പറഞ്ഞു: എന്റെ ഭാര്യ തന്നെ സ്പർശിക്കുന്നവരുടെ കൈ തടയുകയില്ല. നബി(സ) പറഞ്ഞു: "നീയവളെ ഒഴിവാക്കുക." അദ്ദേഹം പറഞ്ഞു: ഞാൻ അവളെ ആഗ്രഹിച്ച് പോകുമോ എന്ന് ഭയപ്പെടുന്നു. നബി(സ) പറഞ്ഞു: "എങ്കിൽ നീയവളുമായി സുഖിക്കുക." (ദ,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 52, 52, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنْ مَيْمُونَةَ بِنْتِ كَرْدَمٍ رَضِيَ اللهُ عَنْهَا قَالَتْ: خَرَجْتُ مَعَ أَبِي فِي حَجَّةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَرَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَدَنَا إِلَيْهِ أَبِي وَهُوَ عَلَى نَاقَةٍ لَهُ، فَوَقَفَ لَهُ وَاسْتَمَعَ مِنْهُ، وَمَعَهُ دِرَّةٌ كَدِرَّةِ الْكُتَّابِ، فَسَمِعْتُ الْأَعْرَابَ وَالنَّاسَ وَهُمْ يَقُولُونَ: الطَّبْطَبِيَّةَ الطَّبْطَبِيَّةَ الطِّبْطِبِيَّةَ، فَدَنَا إِلَيْهِ أَبِي، فَأَخَذَ بِقَدَمِهِ، فَأَقَرَّ لَهُ، وَوَقَفَ عَلَيْهِ، وَاسْتَمَعَ مِنْهُ، فَقَالَ: إِنِّي حَضَرْتُ جَيْشَ عِشْرَانَ، فَقَالَ طَارِقُ بْنُ الْمُرَقَّعِ: مَنْ يُعْطِينِي رُمْحًا بِثَوَابِهِ قُلْتُ: وَمَا ثَوَابُهُ؟ قَالَ: أُزَوِّجُهُ أَوَّلَ بِنْتٍ تَكُونُ لِي. فَأَعْطَيْتُهُ رُمْحِي، ثُمَّ غِبْتُ عَنْهُ، حَتَّى عَلِمْتُ أَنَّهُ قَدْ وُلِدَ لَهُ جَارِيَةٌ وَبَلَغَتْ، ثُمَّ جِئْتُهُ فَقُلْتُ لَهُ: أَهْلِي جَهِّزْهُنَّ إِلَيَّ، فَحَلَفَ أَنْ لَا يَفْعَلَ حَتَّى أُصْدِقَهُ صَدَاقًا جَدِيدًا غَيْرَ الَّذِي كَانَ بَيْنِي وَبَيْنَهُ، وَحَلَفْتُ لَا أُصْدِقُ غَيْرَ الَّذِي أَعْطَيْتُهُ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "وَبِقَرْنِ أَيِّ النِّسَاءِ هِيَ الْيَوْمَ". قَالَ: قَدْ رَأَتِ الْقَتِيرَ قَالَ: "أَرَى أَنْ تَتْرُكَهَا". قَالَ: فَرَاعَنِي ذَلِكَ، وَنَظَرْتُ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا رَأَى ذَلِكَ مِنِّي قَالَ: "لَا تَأْثَمْ، وَلَا يَأْثَمُ صَاحِبُكَ". (د)', 'മൈമൂന ബിൻത് കർദം(റ): റസൂൽ(സ)യുടെ ഹജ്ജിൽ എന്റെ പിതാവിന്റെ കൂടെ ഞാനും പുറപ്പെട്ടു. ഞാൻ റസൂൽ(സ)യെ കണ്ടു. അവിടന്ന് ഒരു ഒട്ടകപ്പുറത്തായിരുന്നു. എന്റെ പിതാവ് റസൂൽ(സ)യുടെ അടുത്തെത്തി. അവിടെച്ചെന്ന് നിൽക്കുകയും റസൂൽ(സ) പറയുന്നത് ശ്രദ്ധിച്ച് കേൾക്കുകയും ചെയ്തു. നബി(സ)യുടെ അടുത്ത് അധ്യാപകരുടെ വടിപോലുള്ള ഒരു വടിയുണ്ടായിരുന്നു. അഅ്റാബികളും ജനങ്ങളും ഇപ്രകാരം പറയുന്നത് ഞാൻ കേട്ടു: വടിയെ സൂക്ഷിക്കുക, വടിയെ സൂക്ഷിക്കുക, വടിയെ സൂക്ഷിക്കുക. എന്റെ പിതാവ് നബി(സ)യുടെ അടുത്ത് ചെന്നു. അവിടത്തെ പാദം പിടിച്ചു, അവിടത്തെ അംഗീകരിക്കുകയും, അവിടെ നിൽക്കുകയും പറയുന്നത് ശ്രദ്ധിച്ച് കേൾക്കുകയും ചെയ്തു. എന്നിട്ട് പറഞ്ഞു: ഇസ്റാൻ യുദ്ധത്തിൽ ഞാൻ പങ്കെടുത്തു. അപ്പോൾ ത്വാരിഖുബ്നുൽ മുറഖഅ് പറഞ്ഞു: പ്രതിഫലത്തനു പകരമായി ആരാണെനിക്കൊരു കുന്തം തരിക? ഞാൻ ചോദിച്ചു: എന്താണ് പ്രതിഫലം? ത്വാരിഖ് പറഞ്ഞു: എനിക്കുണ്ടാകുന്ന ആദ്യപെൺകുട്ടിയെ ഞാനവന് വിവാഹം ചെയ്ത് കൊടുക്കും. അങ്ങനെ ഞാനവന് എന്റെ കുന്തം നൽകി. ശേഷം ഞാനവനിൽ നിന്ന് അപ്രത്യക്ഷനാവുകയും ശേഷം അവനൊരു പെൺകുട്ടി ജനിച്ചിട്ടുണ്ടെന്നും അവൾക്ക് പ്രായമായിട്ടുണ്ടെന്നുമുള്ള വിവരം ഞാനറിയുകയും ചെയ്തു. ഞാനവന്റെ അടുത്ത് ചെന്ന് പറഞ്ഞു: എന്റെ ഭാര്യയെ എനിക്ക് ഒരുക്കിത്തരിക. ഞാനും ത്വാരിഖും മുന്നെ ചെയ്ത കരാറിന് പുറമെ പുതിയ മഹ്റ് നൽകാതെ അപ്രകാരം ചെയ്യില്ലെന്ന് ത്വാരിഖ് സത്യം ചെയ്തു. ഞാൻ മുന്നെ നൽകിയ മഹ്റല്ലാതെ മറ്റൊന്നും നൽകില്ലെന്ന് ഞാനും സത്യം ചെയ്തു. ഇത് കേട്ട് റസൂൽ(സ) ചോദിച്ചു: "ഇന്ന് അവൾക്ക് എത്രവയസ്സാണ്?". എന്റെ പിതാവ് പറഞ്ഞു: അവൾക്ക് നര ബാധിച്ചിട്ടുണ്ട്. റസൂൽ(സ) പറഞ്ഞു: "നീയവളെ ഉപേക്ഷിക്കണമെന്നാണെന്റെ അഭിപ്രായം." എന്റെ പിതാവ് പറഞ്ഞു: ആ കാര്യം എന്നെ അസ്വസ്ഥനാക്കി. ഞാൻ റസൂൽ(സ)യെ നോക്കി. എന്റെ മനസ്ഥിതി മനസ്സിലാക്കിയപ്പോൾ അവിടന്ന് പറഞ്ഞു: "നീയോ നിന്റെ എതിർ കക്ഷിയോ തെറ്റുകാരാവുകയില്ല." (ദ)', 'مَيْمُونَةَ بِنْتِ كَرْدَمٍ', 'മൈമൂന ബിൻത് കർദം(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 52, 53, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنْ إِبْرَاهِيمَ بْنِ مَيْسَرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ خَالَتَهُ أَخْبَرَتْهُ عَنِ امْرَأَةٍ – قَالَتْ: هِيَ مُصَدَّقَةٌ، امْرَأَةُ صِدْقٍ – قَالَتْ: بَيْنَا أَبِي فِي غَزَاةٍ فِي الْجَاهِلِيَّةِ إِذْ رَمِضُوا، فَقَالَ رَجُلٌ: مَنْ يُعْطِينِي نَعْلَيْهِ وَأُنْكِحُهُ أَوَّلَ بِنْتٍ تُولَدُ لِي؟ فَخَلَعَ أَبِي نَعْلَيْهِ فَأَلْقَاهُمَا إِلَيْهِ، فَوُلِدَتْ لَهُ جَارِيَةٌ، فَبَلَغَتْ..، وَذَكَرَ نَحْوَهُ، لَمْ يَذْكُرْ قِصَّةَ الْقَتِيرِ. (د)', 'ഇബ്റാഹീമുബ്നു മയ്സറ(റ): തന്റെ മാതൃസഹോദരി ഒരു സ്ത്രീയെക്കുറിച്ച് അദ്ദേഹത്തിന് പറഞ്ഞുകൊടുത്തു - ആ സ്ത്രീ സത്യസന്ധയായിരുന്നു - അവർ പറഞ്ഞു: എന്റെ പിതാവ് ജാഹിലിയ്യാ കാലത്തെ ഒരു യുദ്ധത്തിൽ പങ്കെടുത്തു കൊണ്ടിരിക്കെ അവർക്ക് തങ്ങളുടെ കാലുകളിൽ (വെയിൽ കാരണം) ശക്തമായ ചൂട് അനുഭവപ്പെട്ടു. അപ്പോൾ ഒരാൾ ചോദിച്ചു: ആരാണ് എനിക്ക് തന്റെ രണ്ട് ചെരിപ്പുകൾ നൽകുക. അതിനു പകരം എനിക്ക് ആദ്യം ജനിക്കുന്ന പെൺകുട്ടിയെ ഞാനവന് വിവാഹം ചെയ്തുകൊടുക്കും. അന്നേരം എന്റെ പിതാവ് തന്റെ രണ്ട് ചെരിപ്പുകൾ ഊരി അവന് ഇട്ടുകൊടുത്തു. ശേഷം ആ മനുഷ്യന് ഒരു പെൺകുട്ടി ജനിച്ചു. ശേഷം മുമ്പ് പറഞ്ഞതു പോലെയുള്ള ഹദീസ് പറഞ്ഞു. അവിടെ നെരയുടെ കാര്യം പറഞ്ഞിട്ടില്ല. (ദ)', 'إِبْرَاهِيمَ بْنِ مَيْسَرَةَ', 'ഇബ്റാഹീമുബ്നു മയ്സറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 53, 53, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنِ الْبَرَاءِ رَضِيَ اللهُ عَنْهُ قَالَ: أَصَبْتُ عَمِّي وَمَعَهُ رَايَةٌ، فَقُلْتُ: أَيْنَ تُرِيدُ؟ فَقَالَ: بَعَثَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَى رَجُلٍ نَكَحَ امْرَأَةَ أَبِيهِ، فَأَمَرَنِي أَنْ أَضْرِبَ عُنُقَهُ وَآخُذَ مَالَهُ. (ن)', 'ബറാഅ്(റ): എന്റെ പിതൃസഹോദരൻ ഒരു കൊടിപിടിച്ച് പോകുന്നത് ഞാൻ കണ്ടു. ഞാൻ ചോദിച്ചു: എവിടേക്കാണ് പോകുന്നത്? അദ്ദേഹം പറഞ്ഞു: തന്റെ പിതാവ് മരിച്ച ശേഷം പിതാവിന്റെ ഭാര്യയെ വിവാഹം ചെയ്ത ഒരുത്തന്റെയടുത്തേക്ക് റസൂൽ(സ) എന്നെ പറഞ്ഞയക്കുകയും അവന്റെ കഴുത്തുവെട്ടി മുതൽ കണ്ടുകെട്ടാൻ എന്നോട് കൽപിക്കുകയും ചെയ്തു. (ന)', 'الْبَرَاءِ', 'ബറാഅ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 53, 54, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ نَبِيَّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَعَثَ جَيْشًا إِلَى أَوْطَاسٍ فَلَقُوا عَدُوًّا، فَقَاتَلُوهُمْ وَظَهَرُوا عَلَيْهِمْ، فَأَصَابُوا لَهُمْ سَبَايَا لَهُنَّ أَزْوَاجٌ فِي الْمُشْرِكِينَ، فَكَانَ الْمُسْلِمُونَ تَحَرَّجُوا مِنْ غِشْيَانِهِنَّ، فَأَنْزَلَ اللهُ عَزَّ وَجَلَّ: {وَالْمُحْصَنَاتُ مِنَ النِّسَاءِ إِلَّا مَا مَلَكَتْ أَيْمَانُكُمْ} [النساء: ٢٤] أَيْ هَذَا لَكُمْ حَلَالٌ إِذَا انْقَضَتْ عِدَّتُهُنَّ. (ن)', 'അബൂസഈദിൽ ഖുദ്രി(റ): നബി(സ) ഔത്വാസ് എന്ന സ്ഥലത്തേക്ക് ഒരു സൈന്യത്തെ അയച്ചു. അവർ തങ്ങളുടെ ശത്രുക്കളോട് ഏറ്റുമുട്ടുകയും വിജയിക്കുകയും അവിശ്വാസികളായ ഭർത്താക്കളുള്ള കുറേ സ്ത്രീകളെ ബന്ധികളായി പിടിക്കുകയും ചെയ്തു. ആ സ്ത്രീകളുമായി ബന്ധപ്പെടാൻ മുസ്ലിംകൾക്ക് വൈമനസ്യമുണ്ടായി. അപ്പോൾ അല്ലാഹു ''നിങ്ങളുടെ ഉടമസ്ഥതയിലുള്ളതല്ലാത്ത സച്ചരിതയായ സ്ത്രീകളും'' (നിസാഅ്:24) എന്ന സൂക്തമിറക്കി. ഈ സ്ത്രീകളുടെ ഇദ്ദ കഴിഞ്ഞാൽ അവർ നിങ്ങൾക്ക് അനുവദനീയമാണ് എന്നർത്ഥം. (ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['ن']::text[], array['ന']::text[], 'النساء: ٢٤', null, 54, 54, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ قَالَ: خَطَبَ أَبُو بَكْرٍ وَعُمَرُ رَضِيَ اللهُ عَنْهُمَا فَاطِمَةَ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّهَا صَغِيرَةٌ". فَخَطَبَهَا عَلِيٌّ فَزَوَّجَهَا مِنْهُ. (ن)', 'ബുറൈദ(റ): അബൂബക്കർ(റ)വും ഉമർ(റ)വും ഫാത്വിമ(റ)യെ വിവാഹാലോചന നടത്തി. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അവൾ പ്രായം കുറഞ്ഞവളാണ്." ശേഷം അലി(റ) വിവാഹാലോചന നടത്തുകയും ഫാത്വിമ(റ)യെ അലി(റ)വിന് വിവാഹം ചെയ്ത് കൊടുക്കുകയും ചെയ്തു. (ന)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 54, 54, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنْ عَائِشَةَ زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَضِيَ اللهُ عَنْهُمَا أَنَّ أَبَا حُذَيْفَةَ بْنَ عُتْبَةَ – وَكَانَ مِمَّنْ شَهِدَ بَدْرًا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ – تَبَنَّى سَالِمًا، وَهُوَ مَوْلًى لِامْرَأَةٍ مِنَ الْأَنْصَارِ، كَمَا تَبَنَّى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ زَيْدَ بْنَ حَارِثَةَ، وَأَنْكَحَ أَبُو حُذَيْفَةَ بْنُ عُتْبَةَ سَالِمًا ابْنَةَ أَخِيهِ هِنْدَ ابْنَةَ الْوَلِيدِ بْنِ عُتْبَةَ بْنِ رَبِيعَةَ، وَكَانَتْ هِنْدُ بِنْتُ الْوَلِيدِ بْنِ عُتْبَةَ مِنَ الْمُهَاجِرَاتِ الْأُوَلِ، وَهِيَ يَوْمَئِذٍ مِنْ أَفْضَلِ أَيَامَى قُرَيْشٍ، فَلَمَّا أَنْزَلَ اللهُ عَزَّ وَجَلَّ فِي زَيْدِ بْنِ حَارِثَةَ: {ادْعُوهُمْ لِآبَائِهِمْ هُوَ أَقْسَطُ عِنْدَ اللهِ} رُدَّ كُلُّ أَحَدٍ يَنْتَمِي مِنْ أُولَئِكَ إِلَى أَبِيهِ، فَإِنْ لَمْ يَكُنْ يُعْلَمُ أَبُوهُ رُدَّ إِلَى مَوَالِيهِ. (ن)', 'ആഇശ(റ), ഉമ്മുസലമ(റ): റസൂൽ(സ)യോടൊപ്പം ബദ്ർയുദ്ധത്തിൽ പങ്കെടുത്ത അബൂ ഹുദൈഫതുബ്നു ഉത്ബ(റ) സാലിം(റ)വിനെ ദത്തെടുത്തിരുന്നു. സാലിം(റ) ഒരു അൻസാരി സ്ത്രീയുടെ അടിമയായിരുന്നു. റസൂൽ(സ) സൈദുബ്നു ഹാരിസ(റ)വിനെ ദത്തെടുത്തതു പോലെയായിരുന്നു ഈ സംഭവം. തന്റെ സഹോദര പുത്രി ഹിന്ദ് ബിൻതു വലീദിനെ അബൂ ഹുദൈഫ(റ) സാലിം(റ)വിന് വിവാഹം ചെയ്തു കൊടുത്തിരുന്നു. ഹിന്ദ് ബിൻത് വലീദ്(റ) ആദ്യമായി പാലായനം ചെയ്തവരുടെ കൂട്ടത്തിൽ പെട്ടവരായിരുന്നു. അന്ന് ഖുറൈഷികളിലെ ഏറ്റവും ശ്രേഷ്ഠരായ വിധവകളിൽ പെട്ടവരായിരുന്നു അവർ. സൈദുബ്നു ഹാരിസ(റ)വിന്റെ കാര്യത്തിൽ ''അവരെ തങ്ങളുടെ യഥാർത്ഥ പിതാക്കളിലേക്ക് ചേർത്തുവിളിക്കുക, അതാണ് അല്ലാഹുവിങ്കൽ കൂടുതൽ നീതിയുക്തം'' എന്ന സൂക്തമവതരിച്ചപ്പോൾ വളർത്തുപുത്രന്മാർ തങ്ങളുടെ യഥാർത്ഥപിതാക്കളിലേക്ക് ചേർക്കപ്പെടാൻ തുടങ്ങി. പിതാക്കൾ അറിയപ്പെടാത്തവർ തങ്ങളുടെ ഉടമസ്ഥന്മാരുടെ സേവകന്മാരായി അറിയപ്പെട്ടു. (ന)', 'عَائِشَةَ زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 54, 55, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: تَزَوَّجَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَنَا بِنْتُ سِتِّ سِنِينَ، فَقَدِمْنَا الْمَدِينَةَ، فَنَزَلْنَا فِي بَنِي الْحَارِثِ بْنِ الْخَزْرَجِ، فَوُعِكْتُ، فَتَمَرَّقَ شَعَرِي حَتَّى وَفَى لَهُ جُمَيْمَةٌ، فَأَتَتْنِي أُمِّي أُمُّ رُومَانَ – وَإِنِّي لَفِي أُرْجُوحَةٍ وَمَعِي صَوَاحِبَاتٌ لِي – فَصَرَخَتْ بِي، فَأَتَيْتُهَا وَمَا أَدْرِي مَا تُرِيدُ، فَأَخَذَتْ بِيَدِي فَأَوْقَفَتْنِي عَلَى بَابِ الدَّارِ، وَإِنِّي لَأَنْهَجُ، حَتَّى سَكَنَ بَعْضُ نَفْسِي، ثُمَّ أَخَذَتْ شَيْئًا مِنْ مَاءٍ فَمَسَحَتْ بِهِ عَلَى وَجْهِي وَرَأْسِي، ثُمَّ أَدْخَلَتْنِي الدَّارَ، فَإِذَا نِسْوَةٌ مِنَ الْأَنْصَارِ فِي بَيْتٍ، فَقُلْنَ: عَلَى الْخَيْرِ وَالْبَرَكَةِ، وَعَلَى خَيْرِ طَائِرٍ. فَأَسْلَمَتْنِي إِلَيْهِنَّ، فَأَصْلَحْنَ مِنْ شَأْنِي، فَلَمْ يَرُعْنِي إِلَّا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ضُحًى، فَأَسْلَمَتْنِي إِلَيْهِ، وَأَنَا يَوْمَئِذٍ بِنْتُ تِسْعِ سِنِينَ. (ق,جه)', 'ആഇശ(റ): എനിക്ക് ആറ് വയസ്സുള്ളപ്പോഴാണ് റസൂൽ(സ) എന്നെ വിവാഹം ചെയ്തത്. അങ്ങനെ ഞങ്ങൾ മദീനയിലേക്ക് പോവുകയും ബനുൽഹാരിസുബ്നുൽ ഖസ്റജിന്റെ താമസസ്ഥലങ്ങളിൽ ഇറങ്ങുകയും ചെയ്തു. അവിടെവെച്ച് എനിക്ക് പനിപിടിച്ചു. തന്നിമിത്തം തലമുടിയെല്ലാം ചെവിയുടെ ഭാഗങ്ങളിലേക്ക നീണ്ടിറങ്ങി. അങ്ങനെയിരിക്കെ ഒരു ദിവസം എന്റെ കൂട്ടുകാരികളുമൊത്ത് ഊഞ്ഞാലിൽ ആടിക്കളിച്ച് കൊണ്ടിരിക്കുമ്പോൾ ഉമ്മുറൂമാൻ(റ) (എന്റെ മാതാവ്) എന്റെയടുത്ത് വന്ന് എന്നെ ഉച്ചത്തിൽ വിളിച്ചു. ഉടനെ ഞാൻ അവരുടെയടുത്ത് ചെന്നു. എന്തിനാണ് എന്നെ വിളിക്കുന്നതെന്ന് എനിക്ക് അറിയുമായിരുന്നില്ല. അവർ (മാതാവ്) എന്റെ കൈപിടിക്കുകയും എന്നെ വാതിലിന്റെ അടുക്കൽ നിറുത്തുകയും ചെയ്തു. എന്റെ ശ്വാസം നേരെയാകുന്നത് വരെ ഞാൻ കിതക്കുന്നുണ്ടായിരുന്നു. ശേഷം അവർ കുറച്ച് വെള്ളം എടുത്ത് എന്റെ മുഖവും തലയും കഴുകി. എന്നിട്ട് എന്നെ അവിടെയുള്ള ഒരു വീട്ടിൽ പ്രവേശിപ്പിച്ചു. അവിടെ കുറെ അൻസാരിസ്ത്രീകളുണ്ടായിരുന്നു. അവർ ഇപ്രകാരം പറഞ്ഞു: സർവ്വ വിധ നന്മയും അനുഗ്രഹവും സൗഭാഗ്യവും നിനക്ക് ലഭിക്കുമാറാകട്ടെ. എന്റെ മാതാവ് എന്നെ അവരിലേക്ക് ഏൽപ്പിച്ചു. അവർ എന്നെ ഭംഗിയാക്കി നിർത്തി. അങ്ങനെ ളുഹാ സമയത്ത് പെട്ടെന്ന് റസൂൽ(സ) വരികയും ഉടനെ ആ വനിതകൾ എന്നെ നബി(സ)ക്ക് ഏൽപ്പിക്കുകയും ചെയ്തു. അന്നെനിക്ക് ഒമ്പത് വയസ്സായിരുന്നു. (ബു,മു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 55, 55, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنْ عُمَرَ بْنِ أَبِي سَلَمَةَ رَضِيَ اللهُ عَنْهُ، عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا: لَمَّا انْقَضَتْ عِدَّتُهَا بَعَثَ إِلَيْهَا أَبُو بَكْرٍ يَخْطُبُهَا عَلَيْهِ، فَلَمْ تَزَوَّجْهُ، فَبَعَثَ إِلَيْهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عُمَرَ بْنَ الْخَطَّابِ يَخْطُبُهَا عَلَيْهِ، فَقَالَتْ: أَخْبِرْ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنِّي امْرَأَةٌ غَيْرَى، وَأَنِّي امْرَأَةٌ مُصْبِيَةٌ، وَلَيْسَ أَحَدٌ مِنْ أَوْلِيَائِي شَاهِدٌ. فَأَتَى رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَ ذَلِكَ لَهُ، فَقَالَ: "ارْجِعْ إِلَيْهَا فَقُلْ لَهَا: أَمَّا قَوْلُكِ إِنِّي امْرَأَةٌ غَيْرَى، فَسَأَدْعُو اللهَ لَكِ فَيُذْهِبُ غَيْرَتَكِ. وَأَمَّا قَوْلُكِ: إِنِّي امْرَأَةٌ مُصْبِيَةٌ، فَسَتُكْفَيْنَ صِبْيَانَكِ. وَأَمَّا قَوْلُكِ: أَنْ لَيْسَ أَحَدٌ مِنْ أَوْلِيَائِي شَاهِدٌ، فَلَيْسَ أَحَدٌ مِنْ أَوْلِيَائِكِ شَاهِدٌ وَلَا غَائِبٌ يَكْرَهُ ذَلِكَ". فَقَالَتْ لِابْنِهَا: يَا عُمَرُ، قُمْ فَزَوِّجْ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَزَوَّجَهُ". (ن)', 'ഉമ്മുസലമ(റ)വിൽ നിന്ന് ഉമറുബ്നു അബീസലമ(റ): മഹതിയുടെ ഇദ്ദയുടെ സമയം കഴിഞ്ഞപ്പോൾ വിവാഹാലോചനയുമായി അബൂബക്കർ(റ) ആളെ അയച്ചു. പക്ഷേ, മഹതി അബൂബക്കർ(റ)വിനെ വിവാഹം കഴിച്ചില്ല. ശേഷം തന്റെ വിവാഹാഭ്യർത്ഥനയുമായി റസൂൽ(സ) അവരിലേക്ക് ഉമറുബ്നുൽ ഖത്തബ്(റ)വിനെ പറഞ്ഞയച്ചു. അന്നേരം മഹതി പറഞ്ഞു: ഞാൻ ദേഷ്യം കൂടിയ, കുട്ടികളുള്ള സ്ത്രീയാണെന്നും എന്റെ കൈകാര്യകർത്താക്കളിൽ ആരും നാട്ടിലില്ലെന്നും നീ റസൂൽ(സ)യോട് പറയുക. ഉമർ(റ) റസൂൽ(സ)യുടെ അടുത്തുവന്ന് വിവരം പറഞ്ഞു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നീ അവരുടെ അടുത്തുചെന്ന് ഇപ്രകാരം പറയുക: ഞാൻ ദേഷ്യം കൂടിയ സ്ത്രീയാണെന്ന് നീ പറഞ്ഞുവല്ലോ? നിനക്കു വേണ്ടി ഞാൻ അല്ലാഹുവിനോട് പ്രാർത്ഥിക്കും. അവൻ നിന്റെ ദേഷ്യത്തെ ഇല്ലാതാക്കും. ഞാൻ കുട്ടികളുള്ള സ്ത്രീയാണെന്ന് നീ പറഞ്ഞുവല്ലോ? നിന്റെ കുട്ടികളുടെ കാര്യത്തിൽ നീ സന്തോഷവതിയാകും. എന്റെ കൈകാര്യകർത്താക്കളിൽ ആരും നാട്ടിലില്ലെന്ന് നീ പറഞ്ഞുവല്ലോ? നാട്ടിലുള്ളവരോ ഇല്ലാത്തവരോ ആയ നിന്റെ കൈകാര്യകർത്താക്കളിൽ ആരും തന്നെ ഈ കാര്യത്തെ വെറുക്കുന്നില്ല." ഇതു കേട്ടപ്പോൾ മഹതി തന്റെ മകനോട് പറഞ്ഞു: ഉമറേ, നീ ചെന്ന് എന്നെ റസൂൽ(സ)ക്ക് വിവാഹം കഴിച്ചുകൊടുക്കുക. അങ്ങനെ (മഹതിയുടെ മകൻ) ഉമർ(റ) അവരെ വിവാഹം കഴിച്ചുകൊടുത്തു. (ന)', 'عُمَرَ بْنِ أَبِي سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 55, 56, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَزَوَّجَهَا وَهِيَ بِنْتُ سِتٍّ، وَبَنَى بِهَا وَهِيَ بِنْتُ تِسْعٍ. وفي رواية قَالَتْ: تَزَوَّجَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِسَبْعِ سِنِينَ، وَدَخَلَ عَلَيَّ لِتِسْعِ سِنِينَ. وفي رواية قَالَتْ: تَزَوَّجَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِتِسْعِ سِنِينَ، وَصَحِبْتُهُ تِسْعًا. وفي رواية: تَزَوَّجَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهِيَ بِنْتُ تِسْعٍ، وَمَاتَ عَنْهَا وَهِيَ بِنْتُ ثَمَانِي عَشْرَةَ. (ن)', 'ആഇശ(റ): മഹതിക്ക് ആറ് വയസ്സുള്ളപ്പോഴാണ് റസൂൽ(സ) മഹതിയെ വിവാഹം ചെയ്തത്. ഒമ്പത് വയസ്സുള്ളപ്പോഴാണ് മഹതിയുമായി വീട് കൂടിയത്. മറ്റൊരു നിവേദനത്തിൽ: മഹതി പറയുന്നു: എന്നെ റസൂൽ(സ) വിവാഹം ചെയ്തത് എനിക്ക് ഏഴ് വയസ്സുള്ളപ്പോഴാണ്. ഒമ്പതാം വയസ്സിലാണ് ഞാനുമായി ആദ്യരാത്രി കൂടിയത്. മറ്റൊരു നിവേദനം: മഹതി പറഞ്ഞു: ഒമ്പതാം വയസ്സിൽ റസൂൽ(സ) എന്നെ വിവാഹം കഴിക്കുകയും ഒമ്പതാം വയസ്സിൽ തന്നെ ഞാനവരോടൊപ്പം കൂടുകയും ചെയ്തു. മറ്റൊരു നിവേദനം: ഒമ്പതാം വയസ്സിൽ റസൂൽ(സ) മഹതിയെ വിവാഹം ചെയ്തു. മഹതിക്ക് പതിനെട്ട് വയസ്സുള്ളപ്പോഴാണ് റസൂൽ(സ) വഫാത്തായത്. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 56, 56, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=2 and h.hadith_no=51), 1, 'وَفِي رِوَايَةٍ قَالَتْ: تَزَوَّجَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِسَبْعِ سِنِينَ، وَدَخَلَ عَلَيَّ لِتِسْعِ سِنِينَ.', 'മറ്റൊരു നിവേദനത്തിൽ: മഹതി പറയുന്നു: എന്നെ റസൂൽ(സ) വിവാഹം ചെയ്തത് എനിക്ക് ഏഴ് വയസ്സുള്ളപ്പോഴാണ്. ഒമ്പതാം വയസ്സിലാണ് ഞാനുമായി ആദ്യരാത്രി കൂടിയത്.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=2 and h.hadith_no=51), 2, 'وَفِي رِوَايَةٍ قَالَتْ: تَزَوَّجَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِتِسْعِ سِنِينَ، وَصَحِبْتُهُ تِسْعًا.', 'മറ്റൊരു നിവേദനം: മഹതി പറഞ്ഞു: ഒമ്പതാം വയസ്സിൽ റസൂൽ(സ) എന്നെ വിവാഹം കഴിക്കുകയും ഒമ്പതാം വയസ്സിൽ തന്നെ ഞാനവരോടൊപ്പം കൂടുകയും ചെയ്തു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=2 and h.hadith_no=51), 3, 'وَفِي رِوَايَةٍ: تَزَوَّجَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهِيَ بِنْتُ تِسْعٍ، وَمَاتَ عَنْهَا وَهِيَ بِنْتُ ثَمَانِي عَشْرَةَ. (ن)', 'മറ്റൊരു നിവേദനം: ഒമ്പതാം വയസ്സിൽ റസൂൽ(സ) മഹതിയെ വിവാഹം ചെയ്തു. മഹതിക്ക് പതിനെട്ട് വയസ്സുള്ളപ്പോഴാണ് റസൂൽ(സ) വഫാത്തായത്. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنْ عُرْوَةَ رَضِيَ اللهُ عَنْهَا أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَطَبَ عَائِشَةَ إِلَى أَبِي بَكْرٍ، فَقَالَ لَهُ أَبُو بَكْرٍ رَضِيَ اللهُ عَنْهُ: إِنَّمَا أَنَا أَخُوكَ، فَقَالَ: "أَنْتَ أَخِي فِي دِينِ اللهِ وَكِتَابِهِ، وَهِيَ لِي حَلَالٌ". (خ)', 'ഉർവ(റ): നബി(സ) ആഇശ(റ)യുടെ കാര്യത്തിൽ അബൂബക്കർ(റ)വിനോട് വിവാഹാഭ്യർത്ഥന നടത്തി. അപ്പോൾ അബൂബക്കർ(റ) പറഞ്ഞു: നിശ്ചയം ഞാൻ അങ്ങയുടെ സഹോദരനാണ്. അപ്പോൾ അവിടന്ന് പ്രതിവചിച്ചു: "അല്ലാഹുവിന്റെ ദീനിലും ഗ്രന്ഥത്തിലും നിങ്ങൾ എനിക്ക് സഹോദരനാണ്. അവൾ എനിക്ക് അനുവദനീയമാണ്." (ബു)', 'عُرْوَةَ', 'ഉർവ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 56, 57, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ حِينَ هَلَكَ عُثْمَانُ بْنُ مَظْعُونٍ تَرَكَ ابْنَةً لَهُ، قَالَ ابْنُ عُمَرَ: فَزَوَّجَنِيهَا خَالِي قُدَامَةُ – وَهُوَ عَمُّهَا – وَلَمْ يُشَاوِرْهَا، وَذَلِكَ بَعْدَ مَا هَلَكَ أَبُوهَا، فَكَرِهَتْ نِكَاحَهُ، وَأَحَبَّتِ الْجَارِيَةُ أَنْ يُزَوِّجَهَا الْمُغِيرَةَ بْنَ شُعْبَةَ، فَزَوَّجَهَا إِيَّاهُ. [ز: في سنده ضعيف] (جه)', 'ഇബ്നുഉമർ(റ): ഉസ്മാനുബ്നു മള്ഊൻ(റ) വഫാത്താകുമ്പോൾ അവർക്ക് ഒരു പെൺകുട്ടിയുണ്ടായരുന്നു. ഇബ്നുഉമർ(റ) പറഞ്ഞു: എന്റെ അമ്മാവനും അവളുടെ പിതൃവ്യനുമായ ഖുദാമ(റ) അവളോട് അഭിപ്രായം ചോദിക്കാതെ അവളെ എനിക്ക് വിവാഹം ചെയ്ത് തന്നു. അവളുടെ പിതാവ് (ഉസ്മാൻ(റ)) വഫാതായ ശേഷമായിരുന്നു ഈ സംഭവം. അവൾ ആ വിവാഹത്തെ വെറുക്കുകയും മുഗീറതുബ്നു ശുഅ്ബ(റ)വുമായി വിവാഹബന്ധത്തിലേർപ്പെടണമെന്ന് ആഗ്രഹിക്കുകയും ചെയ്തു. അങ്ങന ഖുദാമ(റ) അവരെ മുഗീറതുബ്നു ശുഅ്ബ(റ)വിന് വിവാഹം ചെയ്ത് കൊടുത്തു. (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيف', null, 57, 57, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ عُمَرَ بْنَ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ حَدَّثَنَا قَالَ: تَأَيَّمَتْ حَفْصَةُ بِنْتُ عُمَرَ مِنْ خُنَيْسِ بْنِ حُذَافَةَ السَّهْمِيِّ، وَكَانَ مِنْ أَصْحَابِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَتُوُفِّيَ بِالْمَدِينَةِ، قَالَ عُمَرُ: فَأَتَيْتُ عُثْمَانَ بْنَ عَفَّانَ رَضِيَ اللهُ عَنْهُ فَعَرَضْتُ عَلَيْهِ حَفْصَةَ بِنْتَ عُمَرَ، قَالَ: قُلْتُ: إِنْ شِئْتَ أَنْكَحْتُكَ حَفْصَةَ. قَالَ: سَأَنْظُرُ فِي أَمْرِي. فَلَبِثْتُ لَيَالِيَ ثُمَّ لَقِيَنِي فَقَالَ: قَدْ بَدَا لِي أَنْ لَا أَتَزَوَّجَ يَوْمِي هَذَا. قَالَ عُمَرُ: فَلَقِيتُ أَبَا بَكْرٍ الصِّدِّيقَ رَضِيَ اللهُ عَنْهُ فَقُلْتُ: إِنْ شِئْتَ زَوَّجْتُكَ حَفْصَةَ بِنْتَ عُمَرَ. فَصَمَتَ أَبُو بَكْرٍ فَلَمْ يَرْجِعْ إِلَيَّ شَيْئًا، فَكُنْتُ عَلَيْهِ أَوْجَدَ مِنِّي عَلَى عُثْمَانَ، فَلَبِثْتُ لَيَالِيَ، ثُمَّ خَطَبَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَنْكَحْتُهَا إِيَّاهُ، فَلَقِيَنِي أَبُو بَكْرٍ فَقَالَ: لَعَلَّكَ وَجَدْتَ عَلَيَّ حِينَ عَرَضْتَ عَلَيَّ حَفْصَةَ فَلَمْ أَرْجِعْ إِلَيْكَ شَيْئًا؟ قَالَ عُمَرُ: قُلْتُ: نَعَمْ. قَالَ: فَإِنَّهُ لَمْ يَمْنَعْنِي أَنْ أَرْجِعَ إِلَيْكَ شَيْئًا فِيمَا عَرَضْتَ عَلَيَّ إِلَّا أَنِّي قَدْ كُنْتُ عَلِمْتُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَدْ ذَكَرَهَا، وَلَمْ أَكُنْ لِأُفْشِيَ سِرَّ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَلَوْ تَرَكَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَبِلْتُهَا. (ن)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): ഉമറുബ്നുൽ ഖത്താബ്(റ) പറഞ്ഞു: ഖുനൈസുബ്നു ഹുദാഫത്തുസ്സഹ്മി(റ) വഫാത്തായപ്പോൾ ഹഫ്സതു ബിൻത് ഉമർ(റ) വിധവയായി. ഖുനൈസ്(റ) റസൂൽ(സ)യുടെ അനുചരനായിരുന്നു. മദീനയിൽ വെച്ചാണവർ വഫാത്തായത്. ഉമർ(റ) പറഞ്ഞു: ശേഷം ഞാൻ ഉസ്മാനുബ്നു അഫ്ഫാൻ(റ)വിന്റെ അടുത്ത് ചൊല്ലുകയും ഹഫ്സ(റ)യെക്കുറിച്ച് പറയുകയും ചെയ്തു. ഞാൻ പറഞ്ഞു: നിങ്ങൾക്ക് വേണമെങ്കിൽ ഞാൻ ഹഫ്സ(റ)യെ വിവാഹം ചെയ്തുതരാം. ഉസ്മാൻ(റ) പറഞ്ഞു: ഞാൻ ഒന്നു ചിന്തിക്കട്ടെ. അൽപ ദിവസങ്ങൾക്ക് ശേഷം ഉസ്മാൻ(റ) എന്നെ കണ്ടുമുട്ടി. എന്നിട്ട് പറഞ്ഞു: ഇപ്പോൾ ഹഫ്സ(റ)യെ വിവാഹം ചെയ്യേണ്ട എന്നാണ് എനിക്ക് തോന്നുന്നത്. ഉമർ(റ) പറഞ്ഞു: ശേഷം ഞാൻ അബൂബക്കർ(റ)വിന്റെ അടുത്ത് ചെന്നു പറഞ്ഞു: നിങ്ങൾക്കു വേണമെങ്കിൽ ഞാൻ ഹഫ്സ(റ)യെ വിവാഹം ചെയ്ത് തരാം. അബൂബക്കർ(റ) മൗനവലംബിച്ചു, ഒന്നും തന്നെ ഉരിയാടിയില്ല. അബൂബക്കർ(റ)വിന്റെ കാര്യത്തിൽ ഉസ്മാൻ(റ)വിന്റെ കാര്യത്തിലുള്ളതിനേക്കാൾ വിശമം എനിക്ക് അനുഭവപ്പെട്ടു. വീണ്ടും അൽപദിവസം കഴിഞ്ഞു. ശേഷം റസൂൽ(സ) ഹഫ്സ(സ)യുടെ കാര്യത്തിൽ വിവാഹാഭ്യർത്ഥന നടത്തുകയും ഞാനവളെ റസൂൽ(സ)ക്ക് വിവാഹം ചെയ്ത് കൊടുക്കുകയും ചെയ്തു. ശേഷം അബൂബക്കർ(റ) എന്നെ കണ്ടുമുട്ടിയപ്പോൾ ചോദിച്ചു: നിങ്ങൾ എന്നോട് ഹഫ്സ(റ)യുടെ കാര്യം പറഞ്ഞപ്പോൾ ഞാൻ ഒന്നും പ്രതികരിക്കാത്തതിൽ നിങ്ങൾക്ക് വിശമമുണ്ടാകും? ഞാൻ പറഞ്ഞു: അതെ. അബൂബക്കർ(റ) പറഞ്ഞു: റസൂൽ(സ) ഹഫ്സ(റ)യുടെ വിവാഹ കാര്യം ചിന്തിച്ചിട്ടുണ്ടെന്ന് ഞാൻ അറിഞ്ഞതിനാലും റസൂൽ(സ)യുടെ രഹസ്യം പുറത്ത് പറയേണ്ട എന്ന് വിചാരിച്ചതിനാലുമാണ് നിങ്ങളവളുടെ കാര്യം എന്നോട് പറഞ്ഞപ്പോൾ ഞാൻ ഒന്നും പ്രതികരിക്കാതിരുന്നത്. റസൂൽ(സ) അവളെ ഉപേക്ഷിക്കാനാണ് തീരുമാനിച്ചതെങ്കിൽ ഞാൻ അവളെ സ്വീകരിക്കുമായിരുന്നു. (ന)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 57, 58, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: أَنَّ مَرْثَدَ بْنَ أَبِي مَرْثَدٍ الْغَنَوِيَّ – وَكَانَ رَجُلًا شَدِيدًا، وَكَانَ يَحْمِلُ الْأَسَارَى مِنْ مَكَّةَ إِلَى الْمَدِينَةِ – قَالَ: فَدَعَوْتُ رَجُلًا لِأَحْمِلَهُ، وَكَانَ بِمَكَّةَ بَغِيٌّ يُقَالُ لَهَا عَنَاقُ، وَكَانَتْ صَدِيقَتَهُ، خَرَجَتْ فَرَأَتْ سَوَادِي فِي ظِلِّ الْحَائِطِ، فَقَالَتْ: مَنْ هَذَا؟ مَرْثَدٌ، مَرْحَبًا وَأَهْلًا يَا مَرْثَدُ، انْطَلِقِ اللَّيْلَةَ فَبِتْ عِنْدَنَا فِي الرَّحْلِ. قُلْتُ: يَا عَنَاقُ، إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَرَّمَ الزِّنَا، قَالَتْ: يَا أَهْلَ الْخِيَامِ، هَذَا الدُّلْدُلُ، هَذَا الَّذِي يَحْمِلُ أُسَرَاءَكُمْ مِنْ مَكَّةَ إِلَى الْمَدِينَةِ. فَسَلَكْتُ الْخَنْدَمَةَ، فَطَلَبَنِي ثَمَانِيَةٌ، فَجَاءُوا حَتَّى قَامُوا عَلَى رَأْسِي فَبَالُوا، فَطَارَ بَوْلُهُمْ عَلَيَّ، وَأَعْمَاهُمُ اللهُ عَنِّي، فَجِئْتُ إِلَى صَاحِبِي فَحَمَلْتُهُ، فَلَمَّا انْتَهَيْتُ بِهِ إِلَى الْأَرَاكِ فَكَكْتُ عَنْهُ كَبْلَهُ، فَجِئْتُ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: يَا رَسُولَ اللهِ، أَنْكِحُ عَنَاقَ؟ فَسَكَتَ عَنِّي، فَنَزَلَتْ: {الزَّانِيَةُ لَا يَنْكِحُهَا إِلَّا زَانٍ أَوْ مُشْرِكٌ} [النور: ٣] فَدَعَانِي فَقَرَأَهَا عَلَيَّ وَقَالَ: "لَا تَنْكِحْهَا". (ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): മർസദുബ്നു അബീ മർസദുൽ ഗൻവീ(റ) - അദ്ദേഹം ശക്തനായിരുന്നു, മക്കയിൽ നിന്ന് മദീനയിലേക്ക് ബന്ധികളെ കൊണ്ടുവരുന്നയാളായിരുന്നു അദ്ദേഹം - പറഞ്ഞു: മദീനയിലേക്ക് കൊണ്ടുപോകാൻ വേണ്ടി ബന്ധികളിൽ പെട്ട ഒരുത്തനെ ഞാൻ വിളിച്ചു. മക്കയിൽ അനാഖ് എന്ന് പേരുള്ള ഒരു അഭിസാരികയുണ്ടായിരുന്നു. അവൾ അയാളുടെ കൂട്ടുകാരിയായിരുന്നു. ഞാൻ അവിടെയെത്തിയപ്പോൾ മതിലിന് മറവിൽ അവൾ എന്റെ രൂപത്തെ കണ്ടു. അവൾ പറഞ്ഞു: ആരാണിത്? മർസദോ, നിനക്ക് സ്വാഗതം, നീ ഇന്ന് രാത്രി നമ്മുടെ ടെന്റിൽ നമ്മോടൊപ്പം അന്തിയുറങ്ങുക. ഞാൻ പറഞ്ഞു: അനാഖേ, റസൂൽ(സ) വ്യഭിചാരം ഹറാമാക്കിയിരിക്കുന്നു. അവൾ വിളിച്ചു പറഞ്ഞു: ടെന്റുകളിൽ താമസിക്കുന്നവരേ, ഇതാ ഒരു മുള്ളൻ പന്നി, ഇവനാണ് നിങ്ങളുടെ ബന്ധികളെ മക്കയിൽ നിന്ന് മദീനയിലേക്ക് കൊണ്ടുപോകുന്നത്. അത് കേട്ടപ്പോൾ ഞാൻ ഖൻദമ എന്ന മലയിൽ ഒളിഞ്ഞിരുന്നു. എട്ട് പേർ എന്നെ അന്വേഷിച്ചിറങ്ങി. അങ്ങനെ അവർ വരികയും എന്റെ തലഭാഗത്ത് വരെ അവർ നിൽക്കുകയും മൂത്രമൊഴിക്കുകയും ചെയ്തു. അവരുടെ മൂത്രം എന്റെ ശരീരത്തിലേക്കും തെറിച്ചു. പക്ഷേ, അല്ലാഹു അവരിൽ നിന്ന് എന്നെ മറച്ചുവെച്ചു. ശേഷം ഞാൻ എന്റെ ആളുടെ അടുത്ത് ചെന്ന് അവനെ കൊണ്ടുപോയി. അവനുമായി ഞാൻ അറാക് എന്ന സ്ഥലത്തെത്തിയപ്പോൾ അവന്റെ മേലുണ്ടായിരുന്ന ബന്ധനങ്ങളെ ഞാൻ അഴിച്ചുമാറ്റി. ശേഷം ഞാൻ റസൂൽ(സ)യുടെ അടുത്ത് ചെന്ന് ചോദിച്ചു: റസൂലേ, ഞാൻ അനാഖിനെ വിവാഹം കഴിക്കട്ടെയോ? റസൂൽ(സ) എന്നോട് ഒന്നും പറഞ്ഞില്ല. ശേഷം ''വ്യഭിചാരിയായ സ്ത്രീയെ വ്യഭിചാരിയോ ബഹുദൈവാരാധകനോ മാത്രമാണ് വിവാഹം കഴിക്കുക'' (നൂർ:3) എന്ന സൂക്തമിറങ്ങി. അപ്പോൾ റസൂൽ(സ) എന്നെ വിളിക്കുകയും അത് എനിക്ക് ഓതിത്തരികയും ചെയ്തു. എന്നിട്ട് പറഞ്ഞു: "നീയവളെ വിവാഹം കഴിക്കരുത്." (ന)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], 'النور: ٣', null, 58, 59, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا يَنْكِحُ الزَّانِي الْمَجْلُودُ إِلَّا مِثْلَهُ". (د)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "വ്യഭിചാരത്തിന്റെ പേരിൽ ശിക്ഷിക്കപ്പെട്ട അഭിസാരികയെ അവളെപ്പോലെയുള്ളവർ മാത്രമേ വിവാഹം കഴിക്കുകയുള്ളൂ." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 59, 59, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنهُ قَالَ: قَالُوا: يَا رَسُولَ اللهِ، أَلَا تَتَزَوَّجُ مِنْ نِسَاءِ الأَنْصَارِ؟ قَالَ: "إِنَّ فِيهِمْ لَغَيْرَةً شَدِيدَةً". (ن)', 'അനസ്(റ): അവർ ചോദിച്ചു: റസൂലേ, അവിടന്ന് അൻസാരി സ്ത്രീകളെ വിവാഹം കഴിക്കുന്നില്ലേ? റസൂൽ(സ) പറഞ്ഞു: "അവർ കൂടുതൽ ദേഷ്യമുള്ളവരാണ്." (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 59, 59, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ فِي خُطْبَةِ الْحَاجَةِ فِي النِّكَاحِ وَغَيْرِهِ قَالَ: عَلَّمَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خُطْبَةَ الْحَاجَةِ: "أَنِ الْحَمْدُ لِلَّهِ، نَسْتَعِينُهُ وَنَسْتَغْفِرُهُ، وَنَعُوذُ بِهِ مِنْ شُرُورِ أَنْفُسِنَا، مَنْ يَهْدِ اللهُ فَلَا مُضِلَّ لَهُ، وَمَنْ يُضْلِلْ فَلَا هَادِيَ لَهُ، وَأَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ. {يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمُ الَّذِي خَلَقَكُمْ مِنْ نَفْسٍ وَاحِدَةٍ وَخَلَقَ مِنْهَا زَوْجَهَا وَبَثَّ مِنْهُمَا رِجَالاً كَثِيرًا وَنِسَاءً وَاتَّقُوا اللَّهَ الَّذِي تَسَاءَلُونَ بِهِ وَالْأَرْحَامَ إِنَّ اللَّهَ كَانَ عَلَيْكُمْ رَقِيبًا} [النساء: ١] {يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ حَقَّ تُقَاتِهِ وَلَا تَمُوتُنَّ إِلَّا وَأَنْتُمْ مُسْلِمُونَ} [آل عمران: ١٠٢]. {يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَقُولُوا قَوْلًا سَدِيدًا. يُصْلِحْ لَكُمْ أَعْمَالَكُمْ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ وَمَنْ يُطِعِ اللَّهَ وَرَسُولَهُ فَقَدْ فَازَ فَوْزًا عَظِيمًا} [الأحزاب: ٧٠,٧١] وفي رواية: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا تَشَهَّدَ، ذَكَرَ نَحْوَهُ، وَقَالَ: بَعْدَ قَوْلِهِ "وَرَسُولُهُ": "أَرْسَلَهُ بِالْحَقِّ بَشِيرًا وَنَذِيرًا بَيْنَ يَدَيِ السَّاعَةِ، مَنْ يُطِعِ اللهَ وَرَسُولَهُ فَقَدْ رَشَدَ، وَمَنْ يَعْصِهِمَا فَإِنَّهُ لَا يَضُرُّ إِلَّا نَفْسَهُ، وَلَا يَضُرُّ اللهَ شَيْئًا". (د,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): വിവാഹത്തിനും മറ്റുമുള്ള ഹാജതിന്റെ (ആവശ്യങ്ങൾക്കുള്ള) ഖുത്ബയെക്കുറിച്ച് അവർ പറഞ്ഞു: റസൂൽ(സ) ഹാജതിന്റെ ഖുത്ബ ഇപ്രകാരമാണെന്ന് ഞങ്ങൾക്ക് പഠിപ്പിച്ച് തന്നു: "അല്ലാഹുവിനാണ് സർവ്വസ്തുതിയും, അവനോട് ഞങ്ങൾ സഹായം ചോദിക്കുകയും പൊറുക്കലിനെ തേടുകയും ചെയ്യുന്നു. ഞങ്ങളുടെ ശരീരങ്ങളുടെ തിന്മകളിൽ നിന്ന് അല്ലാഹുവിനോട് കാവൽ ചോദിക്കുന്നു. ആരെയെങ്കിലും അല്ലാഹു സന്മാർഗ്ഗത്തിലാക്കുന്നുവെങ്കിൽ അവനെ വഴികേടിലാക്കാൻ മറ്റാരുമില്ല. ആരെയെങ്കിലുമവൻ വഴികേടിലാക്കുന്നുവെങ്കിൽ അവനെ സന്മാർഗ്ഗത്തിലാക്കാൻ മറ്റാരുമില്ല. അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ലെന്നും മുഹമ്മദ് നബി(സ) അവന്റെ അടിമയും റസൂലുമാണെന്നും ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു. ''ജനങ്ങളേ, നിങ്ങളെ ഒരു ശരീരത്തിൽ നിന്ന് സൃഷ്ടിക്കുകയും ആ ശരീരത്തിൽ നിന്ന് അതിന്റെ ഇണയെ സൃഷ്ടിക്കുകയും അവ രണ്ടിൽ നിന്നുമായി ധാരാളം സ്ത്രീപുരഷന്മാരെ വ്യാപിപ്പിക്കുകയും ചെയ്ത നിങ്ങളുടെ രക്ഷിതാവിനെ നിങ്ങൾ ഭയപ്പെടുക, നിങ്ങൾ മുൻനിർത്തി ചോദിക്കുന്ന അല്ലാഹുവിനെയും നിങ്ങളുടെ കുടുംബ ബന്ധങ്ങളെയും നിങ്ങൾ സൂക്ഷിക്കുക. നിശ്ചയം അല്ലാഹു നിങ്ങളെ നിരീക്ഷിക്കുന്നവനാണ്.'' (നിസാഅ്: 1) ''സത്യവിശ്വാസികളേ, നിങ്ങൾ വേണ്ടവിധം അല്ലാഹുവിനെ സൂക്ഷിക്കുക. മുസ്ലിംകളായിട്ടല്ലാതെ നിങ്ങൾ മരിക്കരുത്.'' (ആലുഇംറാൻ: 102) ''സത്യവിശ്വാസികളേ, നിങ്ങൾ അല്ലാഹുവിനെ സൂക്ഷിക്കുക, നേരായ വാക്ക് മൊഴിയുക. എങ്കിൽ അവൻ നിങ്ങളുടെ പ്രവർത്തനങ്ങൾ നന്നാക്കുകയും നിങ്ങളുടെ ദോഷങ്ങൾ പൊറുത്ത് തരികയും ചെയ്യും. ആരെങ്കിലും അല്ലാഹുവിനെയും അവന്റെ റസൂലിനെയും അനുസരിക്കുന്നുവെങ്കിൽ അവൻ മഹത്തായ വിജയം വിജയിച്ചിരിക്കുന്നു.'' (അഹ്സാബ്: 70, 71)
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=2 and h.hadith_no=58), 1, 'وَفِي رِوَايَةٍ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا تَشَهَّدَ، ذَكَرَ نَحْوَهُ، وَقَالَ: بَعْدَ قَوْلِهِ "وَرَسُولُهُ": "أَرْسَلَهُ بِالْحَقِّ بَشِيرًا وَنَذِيرًا بَيْنَ يَدَيِ السَّاعَةِ، مَنْ يُطِعِ اللهَ وَرَسُولَهُ فَقَدْ رَشَدَ، وَمَنْ يَعْصِهِمَا فَإِنَّهُ لَا يَضُرُّ إِلَّا نَفْسَهُ، وَلَا يَضُرُّ اللهَ شَيْئًا". (د,ت,ن,جه)', 'മറ്റൊരു നിവേദനത്തിൽ ഇപ്രകാരമുണ്ട്: റസൂൽ(സ) ഖുത്ബയോതുമ്പോൾ ഇതുപോലോത്തത് പറയുമായിരുന്നു. അതിൽ "അല്ലാഹുവിന്റെ റസൂലുമാണ്" എന്ന വാക്കിന് ശേഷം അവിടന്ന് ഇപ്രകാരം പറയാറുണ്ടായിരുന്നു: "അന്ത്യനാളോടടുത്ത് സത്യവുമായി സന്തോഷവാർത്തയറിയിക്കുന്നവരായും മുന്നറിയിപ്പുകാരനായും അവരെ അല്ലാഹു അയച്ചു. ആരെങ്കിലും അല്ലാഹുവിനെയും അവന്റെ റസൂലിനെയും അനുസരിക്കുന്നുവെങ്കിൽ അവൻ സന്മാർഗ്ഗിയായി, ആരെങ്കിലും അവരെ ധിക്കരിക്കുന്നുവെങ്കിൽ അവൻ സ്വന്തത്തെ തന്നെയാണ് ഉപദ്രവിക്കുന്നത്. അല്ലാഹുവിന് അത് ഒരു കുറവും വരുത്തുകയില്ല." (ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنْ رَجُلٍ مِنْ بَنِي سُلَيْمٍ قَالَ: خَطَبْتُ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أُمَامَةَ بِنْتَ عَبْدِ الْمُطَّلِبِ، فَأَنْكَحَنِي مِنْ غَيْرِ أَنْ يَتَشَهَّدَ. (د)', 'ബനൂ സുലൈം ഗോത്രത്തിൽ പെട്ട ഒരാൾ പറഞ്ഞു: ഉമാമതുബിൻത് അബ്ദുൽ മുത്വലിബ്(റ)ന്റെ വിഷയത്തിൽ ഞാൻ റസൂൽ(സ)യോട് വിവാഹാഭ്യർത്ഥന നടത്തി. അപ്പോൾ വിവാഹ ഖുത്ബയില്ലാതെ തന്നെ നബി(സ) എനിക്കവളെ വിവാഹം ചെയ്ത് തന്നു. (ദ)', 'رَجُلٍ مِنْ بَنِي سُلَيْمٍ قَالَ', 'ബനൂ സുലൈം ഗോത്രത്തിൽ പെട്ട ഒരാൾ പറഞ്ഞു', null, null, array['د']::text[], array['ദ']::text[], null, null, 60, 60, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: أُوتِيَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ جَوَامِعَ الْخَيْرِ وَخَوَاتِمَهُ، أَوْ قَالَ: فَوَاتِحَ الْخَيْرِ، فَعَلَّمَنَا خُطْبَةَ الصَّلَاةِ وَخُطْبَةَ الْحَاجَةِ. خُطْبَةُ الصَّلَاةِ: "التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ. أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ". وَخُطْبَةُ الْحَاجَةِ أَنِ: "الْحَمْدُ لِلَّهِ نَحْمَدُهُ وَنَسْتَعِينُهُ وَنَسْتَغْفِرُهُ، وَنَعُوذُ بِاللَّهِ مِنْ شُرُورِ أَنْفُسِنَا وَمِنْ سَيِّئَاتِ أَعْمَالِنَا، مَنْ يَهْدِهِ اللَّهُ فَلَا مُضِلَّ لَهُ، وَمَنْ يُضْلِلْ فَلَا هَادِيَ لَهُ. وَأَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ". ثُمَّ تَصِلُ خُطْبَتَكَ بِثَلَاثِ آيَاتٍ مِنْ كِتَابِ اللَّهِ: {يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ حَقَّ تُقَاتِهِ وَلَا تَمُوتُنَّ إِلَّا وَأَنْتُمْ مُسْلِمُونَ}. {وَاتَّقُوا اللَّهَ الَّذِي تَسَاءَلُونَ بِهِ وَالْأَرْحَامَ إِنَّ اللَّهَ كَانَ عَلَيْكُمْ رَقِيبًا} {اتَّقُوا اللَّهَ وَقُولُوا قَوْلًا سَدِيدًا يُصْلِحْ لَكُمْ أَعْمَالَكُمْ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ وَمَنْ يُطِعِ اللَّهَ وَرَسُولَهُ فَقَدْ فَازَ فَوْزًا عَظِيمًا} (د,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): റസൂൽ(സ)ക്ക് സർവ്വ നന്മകളും അവയുടെ അന്ത്യവും (പൂർണ്ണതയും) നൽകപ്പെട്ടിരുന്നു. റസൂൽ(സ) ഞങ്ങൾക്ക് നിസ്കാരത്തിലുള്ള ഖുത്ബയും ഹാജതിനുള്ള ഖുത്ബയും പഠിപ്പിച്ചുതന്നു. "എല്ലാ നന്മകളും തിരുമുൾകാഴ്ചകളും പ്രാർത്ഥനകളും അല്ലാഹുവിനുള്ളതാണ്. പ്രവാചകരേ, അങ്ങയുടെ മേൽ രക്ഷയും അല്ലാഹുവിന്റെ കരുണയും അനുഗ്രഹവും വർഷിക്കട്ടെ. നമ്മുടെ മേലിലും അല്ലാഹുവിന്റെ സജ്ജനങ്ങളായ അടിമകളുടെ മേലിലും രക്ഷയുണ്ടാവട്ടെ. അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ലെന്നും മുഹമ്മദ് നബി(സ) അവന്റെ അടിമയും റസൂലുമാണെന്നും ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു." എന്നതാണ് നിസ്കാരത്തിന്റെ ഖുത്ബ. എന്നാൽ ഹാജതിന്റെ ഖുത്ബ ഇപ്രകാരമാണ്: "അല്ലാഹുവിനാണ് സർവ്വ സ്തുതിയും, അവനെ ഞങ്ങൾ സ്തുതിക്കുകയും അവനോട് സഹായം തേടുകയും പൊറുക്കലിനെ ചോദിക്കുകയും ചെയ്യുന്നു. ഞങ്ങളുടെ ശരീരങ്ങളുടെ തിന്മകളിൽ നിന്നും പ്രവർത്തനങ്ങളുടെ മോശത്തരങ്ങളിൽ നിന്നും ഞങ്ങൾ അല്ലാഹുവിനോട് കാവൽ ചോദിക്കുന്നു. ആരെയെങ്കിലും അല്ലാഹു നേർമാർഗ്ഗിത്തിലാക്കുന്നുവെങ്കിൽ അവനെ വഴികേടിലാക്കുവാൻ മറ്റാരുമില്ല. ആരെയെങ്കിലുമവൻ വഴികേടിലാക്കുന്നുവെങ്കിൽ അവനെ നേർമാർഗ്ഗത്തിലാക്കാൻ ഒരാളുമില്ല. അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ലെന്നും അവന് പങ്കുകാരില്ലെന്നും മുഹമ്മദ് നബി(സ) അവന്റെ അടിമയും റസൂലുമാണെന്നും ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു." ശേഷം നിന്റെ ഖുത്ബയെ ഖുർആനിലെ മൂന്ന് ആയത്തുകളുമായി ബന്ധിപ്പിക്കണം. ''സത്യവിശ്വാസികളേ, അല്ലാഹുവിനെ സൂക്ഷിക്കേണ്ട വിധം നിങ്ങൾ സൂക്ഷിക്കുക. നിങ്ങൾ മുസ്ലിംകളായിട്ടല്ലാതെ മരിക്കരുത്.'' ''നിങ്ങൾ മുൻനിർത്തി ചോദിക്കുന്ന അല്ലാഹുവിനെയും കുടുംബബന്ധങ്ങളെയും നിങ്ങൾ സൂക്ഷിക്കുക, തീർച്ചയായും അല്ലാഹു നിങ്ങളെ നിരീക്ഷിക്കുന്നവനാണ്.'' ''നിങ്ങൾ അല്ലാഹുവിനെ സൂക്ഷിക്കുകയും നേരായ വാക്ക് സംസാരിക്കുകയും ചെയ്യുക, എങ്കിൽ അവൻ നിങ്ങളുടെ പ്രവർത്തനങ്ങളെ നന്നാക്കിത്തരികയും പാപങ്ങളെ പൊറുത്ത് തരികയും ചെയ്യും. ആരെങ്കിലും അല്ലാഹുവിനെയും അവന്റെ റസൂലിനെയും അനുസരിക്കുന്നുവെങ്കിൽ അവൻ മഹത്തായ വിജയം വിജയിച്ചിരിക്കുന്നു.'' എന്നീ സൂക്തങ്ങളാണവ. (ദ,തു,ന,ജ)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 60, 61, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 61, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْحَمْدُ لِلَّهِ نَحْمَدُهُ وَنَسْتَعِينُهُ، وَنَعُوذُ بِاللَّهِ مِنْ شُرُورِ أَنْفُسِنَا وَمِنْ سَيِّئَاتِ أَعْمَالِنَا، مَنْ يَهْدِهِ اللَّهُ فَلَا مُضِلَّ لَهُ، وَمَنْ يُضْلِلْ فَلَا هَادِيَ لَهُ، وَأَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ. أَمَّا بَعْدُ". (م,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിനാണ് സർവ്വസ്തുതിയും, ഞങ്ങൾ അവനെ സ്തുതിക്കുകയും അവനോട് സഹായം തേടുകയും ചെയ്യുന്നു. ഞങ്ങളുടെ ശരീരങ്ങളുടെ തിന്മകളിൽ നിന്നും മോശമായ പ്രവർത്തനങ്ങളിൽ നിന്നും ഞങ്ങൾ അല്ലാഹുവിനോട് കാവൽ ചോദിക്കുന്നു. ആരെയെങ്കിലും അല്ലാഹു സന്മാർഗ്ഗത്തിലാക്കിയാൽ അവനെ വഴികേടിലാക്കാൻ മറ്റാരുമില്ല, ആരെയെങ്കിലുമവൻ വഴികേടിലാക്കിയാൽ അവനെ സന്മാർഗ്ഗത്തിലാക്കാൻ മറ്റാരുമില്ല. അല്ലാഹുവില്ലാതെ ആരാധ്യനില്ല, അവന് പങ്കാളിയില്ല എന്നും മുഹമ്മദ് നബി(സ) അവന്റെ അടിമയും റസൂലുമാണെന്നും ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു, ആമുഖത്തിനു ശേഷം." (മു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م','ن','جه']::text[], array['മു','ന','ജ']::text[], null, null, 61, 61, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 62, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "كُلُّ أَمْرٍ ذِي بَالٍ لَا يُبْدَأُ فِيهِ بِالْحَمْدِ أَقْطَعُ". (د,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിനെ സ്തുതിക്കാതെ തുടങ്ങുന്ന പരിഗണനീയമായ സർവ്വ കാര്യങ്ങളും അനുഗ്രഹത്തെ തൊട്ട് വിദൂരത്താണ്." (ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 61, 61, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 63, 'عَنْ فَاطِمَةَ بِنْتِ قَيْسٍ رَضِيَ اللهُ عَنْهَا – وَكَانَتْ مِنَ الْمُهَاجِرَاتِ الْأُوَلِ – قَالَتْ: خَطَبَنِي عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ فِي نَفَرٍ مِنْ أَصْحَابِ مُحَمَّدٍ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَخَطَبَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى مَوْلَاهُ أُسَامَةَ بْنِ زَيْدٍ، وَقَدْ كُنْتُ حُدِّثْتُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ أَحَبَّنِي فَلْيُحِبَّ أُسَامَةَ". فَلَمَّا كَلَّمَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قُلْتُ: أَمْرِي بِيَدِكَ، فَأَنْكِحْنِي مَنْ شِئْتَ. فَقَالَ: "انْطَلِقِي إِلَى أُمِّ شَرِيكٍ". وَأُمُّ شَرِيكٍ امْرَأَةٌ غَنِيَّةٌ مِنَ الْأَنْصَارِ، عَظِيمَةُ النَّفَقَةِ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ، يَنْزِلُ عَلَيْهَا الضِّيفَانُ، فَقُلْتُ: سَأَفْعَلُ. قَالَ: "لَا تَفْعَلِي، فَإِنَّ أُمَّ شَرِيكٍ كَثِيرَةُ الضِّيفَانِ، فَإِنِّي أَكْرَهُ أَنْ يَسْقُطَ عَنْكِ خِمَارُكِ، أَوْ يَنْكَشِفَ الثَّوْبُ عَنْ سَاقَيْكِ، فَيَرَى الْقَوْمُ مِنْكِ بَعْضَ مَا تَكْرَهِينَ. وَلَكِنِ انْتَقِلِي إِلَى ابْنِ عَمِّكِ عَبْدِ اللَّهِ بْنِ عَمْرٍو ابْنِ أُمِّ مَكْتُومٍ". فَانْتَقَلْتُ إِلَيْهِ. (ن)', 'ഫാത്വിമതുബിൻതു ഖൈസ്(റ): മഹതി ആദ്യം ഹിജ്റ പോയവരിൽ പെട്ടവരായിരുന്നു. - അവർ പറഞ്ഞു: നബി(സ)യുടെ സ്വഹാബികളിൽ ചിലരോടൊപ്പം അബ്ദുർറഹ്മാനുബ്നു ഔഫ്(റ)വും എന്നോട് വിവാഹാലോചന നടത്തി. തന്റെ മൗലയായ ഉസാമതുബ്നു സൈദ്(റ)വിന് വേണ്ടി റസൂൽ(സ)യും എന്നോട് വിവാഹാഭ്യർത്ഥന നടത്തി. "ആരെങ്കിലും എന്നെ സ്നേഹിക്കുന്നുവെങ്കിൽ അവൻ ഉസാമ(റ)വിനെയും സ്നേഹിച്ച് കൊള്ളട്ടെ." എന്ന് റസൂൽ(സ) പറഞ്ഞതായി ഞാൻ അറിഞ്ഞിരുന്നു. റസൂൽ(സ) എന്നോട് സംസാരിച്ചപ്പോൾ ഞാൻ പറഞ്ഞു: എന്റെ കാര്യം അങ്ങയുടെ കരങ്ങളിലാണ്. അങ്ങ് ഉദ്ദേശിക്കുന്നവർക്ക് എന്നെ വിവാഹം ചെയ്ത് കൊടുക്കുക. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നീ ഉമ്മുശരീക്(റ)യുടെ അടുത്തേക്ക് പോവുക." അൻസാരികളിൽ പെട്ട ധനികയായ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ കൂടുതൽ ചെലവഴിക്കുന്ന സ്ത്രീയായിരുന്നു ഉമ്മു ശരീക്(റ). അവരുടെ അടുത്ത് അതിഥികൾ വരാറുണ്ടായിരുന്നു. ഞാൻ പറഞ്ഞു: ഞാൻ അപ്രകാരം ചെയ്യാം. നബി(സ) പറഞ്ഞു: "നീ അപ്രകാരം ചെയ്യരുത്, കാരണം ഉമ്മുശരീക്(റ)യുടെ അടുത്ത് കൂടുതൽ അതിഥികൾ വരാറുണ്ട്. നിന്റെ മുഖാവരണം വീഴുന്നതും അല്ലെങ്കിൽ വസ്ത്രം നീങ്ങി കണംകാൽ വെളിവാകുന്നതും ഞാൻ വെറുക്കുന്നു, അപ്പോൾ നീ ഇഷ്ടപ്പെടാത്തത് ജനങ്ങൾ കാണാനിടയാകും. നീ നിന്റെ പിതൃവ്യ പുത്രനായ അബ്ദുല്ലാഹിബ്നു അംറുബ്നു ഉമ്മിമക്തൂം(റ)വിന്റെ അടുത്തേക്ക് പോവുക. അങ്ങനെ ഞാൻ അദ്ദേഹത്തിന്റെ അടുത്തേക്ക് പോയി. (ന)', 'فَاطِمَةَ بِنْتِ قَيْسٍ', 'ഫാത്വിമതുബിൻതു ഖൈസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 61, 62, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 64, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "كُلُّ خُطْبَةٍ لَيْسَ فِيهَا تَشَهُّدٌ فَهِيَ كَالْيَدِ الْجَذْمَاءِ". حَسَنٌ صَحِيحٌ. (د,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "തശഹ്ഹുദ് (സാക്ഷ്യവാക്യം) ഇല്ലാത്ത എല്ലാ ഖുത്ബയും മുറിഞ്ഞ കരം പോലെയാണ്." (ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 62, 62, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 65, 'عَنْ عَدِيِّ بْنِ حَاتِمٍ رَضِيَ اللهُ عَنْهُ قَالَ: تَشَهَّدَ رَجُلَانِ عِنْدَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ أَحَدُهُمَا: مَنْ يُطِعِ اللَّهَ وَرَسُولَهُ فَقَدْ رَشِدَ، وَمَنْ يَعْصِهِمَا فَقَدْ غَوَى. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "بِئْسَ الْخَطِيبُ أَنْتَ". (ن)', 'അദിയ്യുബ്നു ഹാതിം(റ): രണ്ട്പേർ നബി(സ)യുടെ അടുത്ത് വെച്ച് തശഹ്ഹുദ് ചൊല്ലി. അവരിലൊരാൾ ഇപ്രകാരം ചൊല്ലി: ആരെങ്കിലും അല്ലാഹുവിനെയും അവന്റെ റസൂലിനെയും അനുസരിച്ചാൽ അവൻ സൻമാർഗ്ഗത്തിലായി. അവരെ ആരെങ്കിലും  ധിക്കരിച്ചാൽ അവൻ വഴികേടിലായി. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നീ വളരെ മോശമായ ഖുത്ബക്കാരനാണ്." (ന)', 'عَدِيِّ بْنِ حَاتِمٍ', 'അദിയ്യുബ്നു ഹാതിം(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 62, 62, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 66, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا انْقَضَتْ عِدَّةُ زَيْنَبَ قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِزَيْدٍ: "اذْكُرْهَا عَلَيَّ". قَالَ زَيْدٌ: فَانْطَلَقْتُ فَقُلْتُ: يَا زَيْنَبُ، أَبْشِرِي، أَرْسَلَنِي إِلَيْكِ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَذْكُرُكِ. فَقَالَتْ: مَا أَنَا بِصَانِعَةٍ شَيْئًا حَتَّى أَسْتَأْمِرَ رَبِّي. فَقَامَتْ إِلَى مَسْجِدِهَا، وَنَزَلَ الْقُرْآنُ وَجَاءَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَدَخَلَ بِغَيْرِ أَمْرٍ. (ن)', 'അനസ്(റ): സൈനബ്(റ)വിന്റെ ഇദ്ദയുടെ സമയം കഴിഞ്ഞപ്പോൾ റസൂൽ(സ) സൈദ്(റ)വിനോട് പറഞ്ഞു: "എനിക്ക് വേണ്ടി നീയവളോട് വിവാഹാഭ്യർത്ഥന നടത്തുക." സൈദ്(റ) പറയുന്നു: അപ്പോൾ ഞാൻ പോയി സൈനബ്(റ)യോട് പറഞ്ഞു: ഓ, സൈനബ്, നീ സന്തോഷിക്കുക. നിന്നോട് വിവാഹാഭ്യർത്ഥന നടത്താൻ റസൂൽ(സ) എന്നെ നിന്റെയടുത്തേക്ക് പറഞ്ഞയച്ചിരിക്കുന്നു. സൈനബ്(റ) പറഞ്ഞു: എന്റെ റബ്ബിനോട് ചോദിക്കും വരെ ഞാനൊരു കാര്യവും ചെയ്യില്ല. ശേഷം മഹതി തന്റെ നമസ്കാരസ്ഥലത്തേക്ക് പോയി. ശേഷം ഈ വിഷയത്തിൽ ഖുർആൻ അവതരിക്കുകയും റസൂൽ(സ) വന്ന് കൽപനയില്ലാതെ തന്നെ പ്രവേശിക്കുകയും ചെയ്തു. (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 62, 63, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 67, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَتْ زَيْنَبُ بِنْتُ جَحْشٍ تَفْخَرُ عَلَى نِسَاءِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَتَقُولُ: إِنَّ اللهَ عَزَّ وَجَلَّ أَنْكَحَنِي مِنَ السَّمَاءِ، وَفِيهَا نَزَلَتْ آيَةُ الْحِجَابِ. (ن)', 'അനസുബ്നു മാലിക്(റ): ആകാശത്തുനിന്നുള്ള ദൈവസന്ദേശമനുസരിച്ചാണ് അല്ലാഹു എന്നെ വിവാഹം ചെയ്ത് കൊടുത്തത് എന്ന് പറഞ്ഞുകൊണ്ട് സൈനബ് ബിൻത് ജഹ്ശ്(റ) നബി(സ)യുടെ മറ്റു ഭാര്യമാരുടെ ഇടയിൽ അഭിമാനിക്കാറുണ്ടായിരുന്നു. സൈനബ്(റ)യുടെ കാര്യത്തിലാണ് ഹിജാബി(മറ സ്വീകരിക്കൽ)ന്റെ സൂക്തമവതരിച്ചത്. (ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 63, 63, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 68, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَخْطُبُ أَحَدُكُمْ عَلَى خِطْبَةِ بَعْضٍ". (ن)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിലാരും തന്റെ സഹോദരൻ വിവാഹാലോചന നടത്തിക്കൊണ്ടിരിക്കുന്ന സ്ത്രീയെ വിവാഹാലോചന നടത്തരുത്." (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 63, 63, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 69, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ شِمَاسَةَ: أَنَّهُ سَمِعَ عُقْبَةَ بْنَ عَامِرٍ رَضِيَ اللهُ عَلَى الْمِنْبَرِ يَقُولُ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْمُؤْمِنُ أَخُ الْمُؤْمِنِ، فَلَا يَحِلُّ لِلْمُؤْمِنِ أَنْ يَبْتَاعَ عَلَى بَيْعِ أَخِيهِ، وَلَا يَخْطُبَ عَلَى خِطْبَةِ أَخِيهِ حَتَّى يَذَرَ". (ق,ن)', 'അബ്ദുർറഹ്മാനുബ്നു ശിമാസ(റ): ഉഖ്ബതുബ്നു ആമിർ(റ) മിമ്പറിൽ കയറി ഇപ്രകാരം പറയുന്നത് അവർ കേട്ടു: റസൂൽ(സ) പറഞ്ഞിരിക്കുന്നു: "ഒരു സത്യവിശ്വാസി മറ്റൊരു സത്യവിശ്വാസിയുടെ സഹോദരനാണ്. അതിനാൽ ഒരു സത്യവിശ്വാസിക്ക് തന്റെ സഹോദരൻ വാങ്ങിക്കൊണ്ടിരിക്കുന്ന സാധനം വാങ്ങാൻ പാടില്ല. അതുപോലെ തന്റെ സഹോദരൻ വിവാഹാലോചന നടത്തിക്കൊണ്ടിരിക്കുന്ന സ്ത്രീയെ അവൻ ഒഴിവാക്കുന്നത് വരെ വിവാഹോലോചന നടത്താനും പാടില്ല." (ബു,മു,ന)', 'عَبْدِ الرَّحْمَنِ بْنِ شِمَاسَةَ', 'അബ്ദുർറഹ്മാനുബ്നു ശിമാസ(റ)', null, null, array['ق','ن']::text[], array['ബു','മു','ന']::text[], null, null, 63, 63, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 70, 'عَنْ فَاطِمَةَ بِنْتِ قَيْسٍ رَضِيَ اللهُ عَنْهَا: أَنَّ زَوْجَهَا طَلَّقَهَا ثَلَاثًا، وَلَمْ يَجْعَلْ لَهَا سُكْنَى وَلَا نَفَقَةً. قَالَتْ: وَوَضَعَ لِي عَشَرَةَ أَقْفِزَةٍ عِنْدَ ابْنِ عَمٍّ لَهُ: خَمْسَةَ شَعِيرًا وَخَمْسَةَ بُرًّا. قَالَتْ: فَأَتَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَذَكَرْتُ ذَلِكَ لَهُ، قَالَتْ: فَقَالَ: "صَدَقَ". قَالَتْ: فَأَمَرَنِي أَنْ أَعْتَدَّ فِي بَيْتِ أُمِّ شَرِيكٍ، ثُمَّ قَالَ لِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ بَيْتَ أُمِّ شَرِيكٍ بَيْتٌ يَغْشَاهُ الْمُهَاجِرُونَ، وَلَكِنِ اعْتَدِّي فِي بَيْتِ ابْنِ أُمِّ مَكْتُومٍ، فَعَسَى أَنْ تُلْقِي ثِيَابَكِ وَلَا يَرَاكِ، فَإِذَا انْقَضَتْ عِدَّتُكِ فَجَاءَ أَحَدٌ يَخْطُبُكِ، فَآذِنِينِي". فَلَمَّا انْقَضَتْ عِدَّتِي خَطَبَنِي أَبُو جَهْمٍ وَمُعَاوِيَةُ، قَالَتْ: فَأَتَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَذَكَرْتُ ذَلِكَ لَهُ، فَقَالَ: "أَمَّا مُعَاوِيَةُ فَرَجُلٌ لَا مَالَ لَهُ، وَأَمَّا أَبُو جَهْمٍ فَرَجُلٌ شَدِيدٌ عَلَى النِّسَاءِ". قَالَتْ: فَخَطَبَنِي أُسَامَةُ بْنُ زَيْدٍ، فَتَزَوَّجَنِي، فَبَارَكَ اللهُ لِي فِي أُسَامَةَ. حَسَنٌ صَحِيحٌ. (م,د,ت)', 'ഫാത്വിമതുബിൻതു ഖൈസ്(റ): മഹതിയുടെ ഭർത്താവ് അവരെ മൂന്ന് ത്വലാഖും (വിവാഹമോചനം) ചൊല്ലി. അദ്ദേഹം മഹതിക്ക് താമസസ്ഥലമോ ചെലവോ നിശ്ചയിച്ചുകൊടുത്തില്ല. മഹതി പറഞ്ഞു: അദ്ദേഹം എനിക്ക് വേണ്ടി അഞ്ച് കഫീസ് ബാർലിയും അഞ്ച് കഫീസ് ഗോതമ്പും അടക്കം പത്ത് കഫീസ് അദ്ദേഹത്തിന്റെ പിതൃവ്യപുത്രന്റെയടുത്ത് ഏൽപിച്ചു. അങ്ങനെ ഞാൻ റസൂൽ(സ)യുടെ അടുത്ത് ചെല്ലുകയും ആ വിവരം പറയുകയും ചെയ്തു. റസൂൽ(സ) പറഞ്ഞു: "അവൻ ചെയ്തത് ശരിയാണ്." മഹതി പറയുന്നു: ശേഷം എന്നോട് ഉമ്മുശരീക്(റ)യുടെ വീട്ടിൽ പോയി ''ഇദ്ദ'' ഇരിക്കാൻ കൽപ്പിച്ച ശേഷം റസൂൽ(സ) എന്നോട് പറഞ്ഞു: "മുഹാജിറുകൾ അധികമായി വരുന്ന വീടാണ് ഉമ്മുശരീക്(റ)യുടെ വീട്, നീ ഇബ്നു ഉമ്മിമക്തൂം(റ)വിന്റെ വീട്ടിൽ ഇദ്ദ ഇരിക്കുക. കാരണം ഒരു പക്ഷേ, നിന്റെ വസ്ത്രം അഴിയാം, ഇബ്നു ഉമ്മിമക്തൂം(റ) അത് കാണുകയില്ല. നിന്റെ ഇദ്ദ കഴിയുകയും ആരെങ്കിലും നിന്നോട് വിവാഹാഭ്യർത്ഥന നടത്തുകയും ചെയ്താൽ നീ എന്നോട് സമ്മതം ചോദിക്കുക." എന്റെ ഇദ്ദ കഴിഞ്ഞപ്പോൾ അബൂ ജഹം(റ)വും മുആവിയ()വും എന്നോട് വിവാഹാഭ്യർത്ഥന നടത്തി. ഞാൻ റസൂൽ(സ)യുടെ അടുത്ത് ചെല്ലുകയും ആ വിവരം റസൂൽ(സ)യോട് പറയുകയും ചെയ്തു. അപ്പോൾ അവിടന്ന് എന്നോട് പറഞ്ഞു: "മുആവിയ സമ്പത്തില്ലാത്തയാളാണ്, അബൂ ജഹം(റ) സ്ത്രീകളോട് പരുഷമായി പെരുമാറുന്നവനാണ്." ശേഷം ഉസാമതുബ്നു സൈദ്(റ) എന്നോട് വിവാഹാഭ്യർത്ഥന നടത്തുകയും എന്നെ വിവാഹം കഴിക്കുകയും ചെയ്തു. അങ്ങനെ ഉസാമ(റ)വിൽ അല്ലാഹു എനിക്ക് അനുഗ്രഹം ചെയ്തു. (മു,ദ,തു)', 'فَاطِمَةَ بِنْتِ قَيْسٍ', 'ഫാത്വിമതുബിൻതു ഖൈസ്(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 63, 64, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 71, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يَخْطُبُ أَحَدُكُمْ عَلَى خِطْبَةِ أَخِيهِ وَلَا يَبِعْ عَلَى بَيْعِ أَخِيهِ إِلَّا بِإِذْنِهِ". (م,د,جه)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിലാരും തന്റെ സഹോദരന്റെ സമ്മതം കൂടാതെ അവന്റെ വിവാഹാഭ്യർത്ഥന നിലനിൽക്കെ മേൽ വിവാഹാഭ്യർത്ഥന നടത്തുകയോ അവന്റെ കച്ചവടത്തിനുമേൽ കച്ചവടം ചെയ്യുകയോ അരുത്." (മു,ദ,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 64, 64, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 72, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَنَاجَشُوا، وَلَا يَبِعْ حَاضِرٌ لِبَادٍ، وَلَا يَبِعِ الرَّجُلُ عَلَى بَيْعِ أَخِيهِ، وَلَا يَخْطُبْ عَلَى خِطْبَةِ أَخِيهِ، وَلَا تَسْأَلِ الْمَرْأَةُ طَلَاقَ أُخْتِهَا لِتَكْتَفِئَ مَا فِي إِنَائِهَا". (م,ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ഏറ്റക്കച്ചവടം നടത്തരുത്. പരിഷ്കൃതർ അപരിഷ്കൃതരുമായി കച്ചവടം നടത്തരുത്. ആരും തന്റെ സഹോദരൻ കച്ചവടം ചെയ്തതിനുമേൽ കച്ചവടം ചെയ്യുകയോ അവൻ വിവാഹാഭ്യർത്ഥന നടത്തിക്കൊണ്ടിരിക്കുന്ന സ്ത്രീയെ വിവാഹാഭ്യർത്ഥന നടത്തുകയോ ചെയ്യരുത്. തന്റെ സഹോദരിക്ക് ലഭിക്കുന്നത് മുഴുവൻ തനിക്കു ലഭിക്കാൻ വേണ്ടി ഒരു സ്ത്രീയും തന്റെ സഹോദരിയെ വിവാഹമോചനം ചെയ്യാൻ ആവശ്യപ്പെടരുത്." (മു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 64, 64, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 73, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَخْطُبُ أَحَدُكُمْ عَلَى خِطْبَةِ أَخِيهِ، حَتَّى يَنْكِحَ أَوْ يَتْرُكَ". (ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "വിവാഹം കഴിക്കുകയോ ഉപേക്ഷിക്കുകയോ ചെയ്യുന്നത് വരെ നിങ്ങളിലാരും തന്റെ സഹോദരന്റെ വിവാഹാഭ്യർത്ഥനക്കുമേൽ വിവാഹാഭ്യർത്ഥന നടത്തരുത്." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 64, 65, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 74, 'عَنْ فَاطِمَةَ بِنْتِ قَيْسٍ رَضِيَ اللهُ عَنْهَا: أَنَّهَا كَانَتْ تَحْتَ أَبِي عَمْرِو بْنِ حَفْصٍ فَلَمَّا أَمَّرَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلِيَّ بْنَ أَبِي طَالِبٍ عَلَى الْيَمَنِ خَرَجَ مَعَهُ، وَأَرْسَلَ إِلَيْهَا بِتَطْلِيقَةٍ هِيَ بَقِيَّةُ طَلَاقِهَا، وَأَمَرَ لَهَا الْحَارِثَ بْنَ هِشَامٍ وَعَيَّاشَ بْنَ أَبِي رَبِيعَةَ بِنَفَقَتِهَا، فَأَرْسَلَتْ – زَعَمَتْ – إِلَى الْحَارِثِ وَعَيَّاشٍ تَسْأَلُهُمَا الَّذِي أَمَرَ لَهَا بِهِ زَوْجُهَا، فَقَالَا: وَاللهِ مَا لَهَا عِنْدَنَا نَفَقَةٌ إِلَّا أَنْ تَكُونَ حَامِلًا، وَمَا لَهَا أَنْ تَكُونَ فِي مَسْكَنِنَا إِلَّا بِإِذْنِنَا. فَزَعَمَتْ أَنَّهَا أَتَتْ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَتْ ذَلِكَ لَهُ، فَصَدَّقَهُمَا. قَالَتْ فَاطِمَةُ: فَأَيْنَ أَنْتَقِلُ يَا رَسُولَ اللهِ؟ قَالَ: "انْتَقِلِي عِنْدَ ابْنِ أُمِّ مَكْتُومٍ الْأَعْمَى الَّذِي سَمَّاهُ اللهُ عَزَّ وَجَلَّ فِي كِتَابِهِ". قَالَتْ فَاطِمَةُ: فَاعْتَدَدْتُ عِنْدَهُ، وَكَانَ رَجُلًا قَدْ ذَهَبَ بَصَرُهُ، فَكُنْتُ أَضَعُ ثِيَابِي عِنْدَهُ، حَتَّى أَنْكَحَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أُسَامَةَ بْنَ زَيْدٍ، رَضِيَ اللهُ عَنْهُمَا. (ن)', 'ഫാത്വിമ ബിൻതു ഖൈസ്(റ): മഹതി അബൂ അംറുബ്നു ഹഫ്സ്(റ)വിന്റെ ഭാര്യയായിരുന്നു. റസൂൽ(സ) അലി(റ)വിനെ യമനിലേക്കയച്ചപ്പോൾ അബൂഅംറ്(റ) അവരോടൊപ്പം പുറപ്പെടുകയും ഫാത്വിമ(റ)യുടെ ശേഷിക്കുന്ന വിവാഹമോചന വാർത്തയുമായി ആളെ അയക്കുകയും ചെയ്തു. ഹാരിസുബ്നു ഹിഷാം(റ)വിനോടും ഇയാശുബ്നു അബീ റബീഅ(റ)വിനോടും അബൂഅംറ്(റ) മഹതിയുടെ ചെലവ് നിർവ്വഹിക്കാൻ ആവശ്യപ്പെട്ടിരുന്നു. തന്റെ ഭർത്താവ് തനിക്ക് നൽകാനാവശ്യപ്പെട്ട കാര്യം ചോദിച്ച് കൊണ്ട് മഹതി ഹാരിസ്(റ), ഇയാശ്(റ) എന്നിവരിലേക്ക് ആളെ അയച്ചു. അപ്പോൾ അവർ പറഞ്ഞു: അല്ലാഹുവാണ് സത്യം, ഗർഭിണിയാണെങ്കിൽ മാത്രമേ ഞങ്ങൾ അവൾക്ക് ചെലവ് കൊടുക്കേണ്ടതൊള്ളൂ. മാത്രമല്ല, ഞങ്ങളുടെ അനുവാദപ്രകാരമല്ലാതെ അവൾക്ക് ഞങ്ങളുടെ താമസസ്ഥലത്ത് വരാൻ പറ്റുകയുമില്ല. മഹതി പറഞ്ഞു: അങ്ങനെ ഞാൻ റസൂൽ(സ)യുടെ അടുത്ത് ചെന്ന് വിവരം പറഞ്ഞു. അപ്പോൾ നബി(സ) അവരിരുവരെയും വാസ്തവമാക്കി. ഫാത്വിമ(റ) പറഞ്ഞു: റസൂലേ, ഇനി എവിടേക്കാണ് ഞാൻ പോകുക? റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു തന്റെ ഗ്രന്ഥത്തിൽ പേരെടുത്ത് പറഞ്ഞ ഇബ്നു ഉമ്മിമക്തൂമിന്റെ അടുത്തേക്ക് നീ പോകുക." ഫാത്വിമ(റ) പറഞ്ഞു: അങ്ങനെ ഞാൻ ഇബ്നു ഉമ്മിമക്തൂം(റ)വിന്റെയടുത്ത് ഇദ്ദ ഇരുന്നു. അദ്ദേഹം കാഴ്ചയില്ലാത്തയാളായിരുന്നു. ഞാൻ അദ്ദേഹത്തിന്റെ വീട്ടിലായിരുന്നു എന്റെ വസ്ത്രങ്ങൾ വെച്ചരുന്നത്. ശേഷം റസൂൽ(സ) മഹതിയെ ഉസാമതുബ്നു സൈദ്(റ)വിന് വിവാഹം ചെയ്ത് കൊടുത്തു. (ന)', 'فَاطِمَةَ بِنْتِ قَيْسٍ', 'ഫാത്വിമ ബിൻതു ഖൈസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 65, 65, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 75, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا كَانَ يَقُولُ: نَهَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ يَبِيعَ بَعْضُكُمْ عَلَى بَيْعِ بَعْضٍ، وَلَا يَخْطُبُ الرَّجُلُ عَلَى خِطْبَةِ الرَّجُلِ، حَتَّى يَتْرُكَ الْخَاطِبُ قَبْلَهُ أَوْ يَأْذَنَ لَهُ الْخَاطِبُ. (خ,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നിങ്ങളിൽ ചിലർ മറ്റുചിലരുടെ കച്ചവടത്തിനുമേൽ കച്ചവടം നടത്തുന്നതിനെയും ആദ്യം വിവാഹാഭ്യർത്ഥന നടത്തിയവൻ സമ്മതിക്കുകയോ ഒഴിവാക്കുകയോ ചെയ്യുന്നതിന് മുമ്പ് മറ്റൊരുത്തൻ വിവാഹാഭ്യർത്ഥന നടത്തുന്നതിനെയും റസൂൽ(സ) നിരോധിച്ചു. (ബു,ന,ജ)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['خ','ن','جه']::text[], array['ബു','ന','ജ']::text[], null, null, 65, 65, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 76, 'عَنْ فَاطِمَةَ بِنْتِ قَيْسٍ رَضِيَ اللهُ عَنْهَا قَالَتْ: طَلَّقَنِي زَوْجِي ثَلَاثًا، فَكَانَ يَرْزُقُنِي طَعَامًا فِيهِ شَيْءٌ، فَقُلْتُ وَاللهِ لَئِنْ كَانَتْ لِيَ النَّفَقَةُ وَالسُّكْنَى لَأَطْلُبَنَّهَا، وَلَا أَقْبَلُ هَذَا. فَقَالَ الْوَكِيلُ: لَيْسَ لَكِ سُكْنَى وَلَا نَفَقَةٌ. قَالَتْ: فَأَتَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَذَكَرْتُ ذَلِكَ لَهُ، فَقَالَ: "لَيْسَ لَكِ سُكْنَى وَلَا نَفَقَةٌ، فَاعْتَدِّي عِنْدَ فُلَانَةَ". قَالَتْ: وَكَانَ يَأْتِيهَا أَصْحَابُهُ، ثُمَّ قَالَ: "اعْتَدِّي عِنْدَ ابْنِ أُمِّ مَكْتُومٍ، فَإِنَّهُ أَعْمَى، فَإِذَا حَلَلْتِ فَآذِنِينِي". قَالَتْ: فَلَمَّا حَلَلْتُ آذَنْتُهُ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "وَمَنْ خَطَبَكِ". فَقُلْتُ: مُعَاوِيَةُ وَرَجُلٌ آخَرُ مِنْ قُرَيْشٍ. فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَمَّا مُعَاوِيَةُ فَإِنَّهُ غُلَامٌ مِنْ غِلْمَانِ قُرَيْشٍ لَا شَيْءَ لَهُ، وَأَمَّا الْآخَرُ فَإِنَّهُ صَاحِبُ شَرٍّ لَا خَيْرَ فِيهِ، وَلَكِنِ انْكِحِي أُسَامَةَ بْنَ زَيْدٍ". قَالَتْ: فَكَرِهْتُهُ، فَقَالَ لَهَا ذَلِكَ ثَلَاثَ مَرَّاتٍ، فَنَكَحْتُهُ. (ن)', 'ഫാത്വിമതു ബിൻത് ഖൈസ്(റ): എന്റെ ഭർത്താവ് എന്നെ മൂന്ന് ത്വലാഖും ചൊല്ലി. അവർ എനിക്ക് അൽപം ഭക്ഷണം നൽകാറുണ്ടായിരുന്നു. ഞാൻ പറഞ്ഞു: അല്ലാഹു തന്നെ സത്യം, എനിക്ക് ചെലവും പാർപ്പിടവുമുണ്ടെങ്കിൽ ഞാനത് ചോദിച്ച് വാങ്ങുകയും ഇപ്പോൾ ലഭിക്കുന്നത് സ്വീകരിക്കാതിരിക്കുകയും ചെയ്യും. ഇത് കേട്ടപ്പോൾ വകീൽ പറഞ്ഞു: നിനക്ക് പാർപ്പിടമോ ചെലവോ നിശ്ചയിക്കപ്പെട്ടിട്ടില്ല. അപ്പോൾ ഞാൻ നബി(സ)യുടെ അടുത്ത് ചെല്ലുകയും വിവരമറിയിക്കുകയും ചെയ്തു. നബി(സ) പറഞ്ഞു: "നിനക്ക് പാർപ്പിടമോ ചെലവോ നിശ്ചയിക്കപ്പെട്ടിട്ടില്ല. അതിനാൽ നീ ഇന്ന സ്ത്രീയുടെ വീട്ടിൽ ഇദ്ദ ഇരിക്കുക." ആ സ്ത്രീയുടെ വീട്ടിലേക്ക് പ്രവാചകരുടെ അനുചരർ വരാറുണ്ടായിരുന്നു. ശേഷം റസൂൽ(സ) പറഞ്ഞു: "നീ ഇബ്നു ഉമ്മിമക്തൂം(റ)വിന്റെയടുത്ത് ഇദ്ദയിരിക്കുക, കാരണം ഇബ്നു ഉമ്മിമക്തൂം അന്ധനാണ്. ഇദ്ദ കഴിഞ്ഞാൽ നീ എന്നെ അറിയിക്കുക." അങ്ങനെ എന്റെ ഇദ്ദ കഴിഞ്ഞപ്പോൾ ഞാൻ റസൂൽ(സ)യെ വിവരമറിയിച്ചു. തിരുമേനി(സ) ചോദിച്ചു: "ആരാണ് നിന്നെ വിവാഹാഭ്യർത്ഥന നടത്തിയത്." ഞാൻ പറഞ്ഞു: മുആവിയ(റ)യും ഖുറൈശിയ്യായ മറ്റൊരാളും. നബി(സ) പറഞ്ഞു: "മുആവിയ(റ) ഖുറൈശികളിലെ യുവാക്കളിൽ പെട്ട ഒരു യുവാവാണ്, അവന്റെയടുത്ത് ഒരു സമ്പത്തും ഇല്ല. മറ്റെയാൾ മോശക്കാരനാണ്, അവനിൽ നന്മയില്ല. നീ ഉസാമതുബ്നു സൈദ്(റ)വിനെ വിവാഹം കഴിക്കുക." മഹതി പറയുന്നു: ഞാൻ ആ വിവാഹം വെറുത്തു. റസൂൽ(സ) മൂന്ന് പ്രാവശ്യം എന്നോട് ഇപ്രകാരം പറഞ്ഞു. അവസാനം ഞാൻ സൈദ്(റ)വിനെ വിവാഹം ചെയ്തു. (ന)', 'فَاطِمَةَ بِنْتِ قَيْسٍ', 'ഫാത്വിമതു ബിൻത് ഖൈസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 65, 66, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 77, 'عَنْ فَاطِمَةَ بِنْتِ قَيْسٍ رَضِيَ اللهُ عَنْهَا تَقُولُ: قَالَ لِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا حَلَلْتِ فَآذِنِينِي". فَآذَنْتُهُ، فَخَطَبَهَا مُعَاوِيَةُ وَأَبُو الْجَهْمِ بْنُ صُخَيْرٍ وَأُسَامَةُ بْنُ زَيْدٍ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَمَّا مُعَاوِيَةُ فَرَجُلٌ تَرِبٌ لَا مَالَ لَهُ، وَأَمَّا أَبُو الْجَهْمِ فَرَجُلٌ ضَرَّابٌ لِلنِّسَاءِ، وَلَكِنْ أُسَامَةُ". فَقَالَتْ بِيَدِهَا هَكَذَا: أُسَامَةُ، أُسَامَةُ. فَقَالَ لَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "طَاعَةُ اللهِ وَطَاعَةُ رَسُولِهِ خَيْرٌ لَكِ". قَالَتْ: فَتَزَوَّجْتُهُ، فَاغْتَبَطْتُ بِهِ. (م,ت,ن,جه)', 'ഫാത്വിമ ബിൻത് ഖൈസ്(റ): എന്നോട് റസൂൽ(സ) പറഞ്ഞു: "നിന്റെ ഇദ്ദ കഴിഞ്ഞാൽ നീ എന്നോട് വിവരമറിയിക്കുക." അങ്ങനെ മഹതി നബി(സ)യോട് വിവരമറിയിച്ചു. ശേഷം മുആവിയ(റ)വും അബൂജഹമുബ്നു സുഖൈർ(റ)വും ഉസാമതുബ്നു സൈദ്(റ)വും അവരോട് വിവാഹാഭ്യർത്ഥന നടത്തി. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "മുആവിയ(റ) ദരിദ്രനാണ്, അബൂജഹം(റ) ഭാര്യമാരെ കൂടുതലായി അടിക്കുന്നവനാണ്. നീ ഉസാമ(റ)വിനെ വിവാഹം കഴിക്കുക." അന്നേരം മഹതി തന്റെ കൈകൊണ്ട് ആംഗ്യം കാട്ടി ഇപ്രകാരം പറഞ്ഞു: ഉസാമയോ, ഉസാമയോ. അപ്പോൾ മഹതിയോട് റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിനെയും അവന്റെ റസൂലിനെയും അനുസരിക്കുന്നതാണ് നിനക്കുത്തമം." മഹതി പറഞ്ഞു: അങ്ങനെ ഞാൻ ഉസാമ(റ)വിനെ വിവാഹം ചെയ്തു. അദ്ദേഹം കാരണം ഞാൻ സന്തോഷിക്കുകയും ചെയ്തു. (മു,തു,ന,ജ)', 'فَاطِمَةَ بِنْتِ قَيْسٍ', 'ഫാത്വിമ ബിൻത് ഖൈസ്(റ)', null, null, array['م','ت','ن','جه']::text[], array['മു','തു','ന','ജ']::text[], null, null, 66, 67, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 78, 'عَنِ الْحَسَنِ رَضِيَ اللهُ عَنْهُ قَالَ: تَزَوَّجَ عَقِيلُ بْنُ أَبِي طَالِبٍ امْرَأَةً مِنْ بَنِي جُشَمٍ، فَقِيلَ لَهُ: بِالرِّفَاءِ وَالْبَنِينَ. قَالَ: قُولُوا كَمَا قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "بَارَكَ اللهُ فِيكُمْ وَبَارَكَ لَكُمْ". (ن)', 'ഹസൻ(റ): ബനൂ ജസമിൽ പെട്ട ഒരു സ്ത്രീയെ അഖീലുബ്നു അബീ ത്വാലിബ്(റ) വിവാഹം ചെയ്തു. അപ്പോൾ നിങ്ങൾക്കിടയിൽ നല്ല ചേർച്ചയുണ്ടാവുകയും നിങ്ങൾക്ക് നല്ല സന്താനങ്ങളുണ്ടാവുകയും ചെയ്യട്ടെ എന്ന് അഖീൽ(റ)വിനോട് പറയപ്പെട്ടു. അന്നേരം അഖീൽ(റ) പറഞ്ഞു: നിങ്ങൾ അല്ലാഹുവിന്റെ റസൂൽ പറഞ്ഞത് പോലെ പറയുക: "അല്ലാഹു നിങ്ങളിൽ അനുഗ്രഹം ചെയ്യട്ടെ, അല്ലാഹു നിങ്ങൾക്ക് അനുഗ്രഹം ചെയ്യട്ടെ." (ന)', 'الْحَسَنِ', 'ഹസൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 67, 67, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 79, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَأَى عَلَى عَبْدِ الرَّحْمَنِ أَثَرَ صُفْرَةٍ، فَقَالَ: "مَا هَذَا". قَالَ: تَزَوَّجْتُ امْرَأَةً عَلَى وَزْنِ نَوَاةٍ مِنْ ذَهَبٍ. فَقَالَ: "بَارَكَ اللهُ لَكَ، أَوْلِمْ وَلَوْ بِشَاةٍ". (ن)', 'അനസ്(റ): അബ്ദുർറഹ്മാനുബ്നു ഔഫ്(റ)വിന്റെ ശരീരത്തിൽ റസൂൽ(സ) മഞ്ഞയടയാളം കണ്ടു. അവിടന്ന് ചോദിച്ചു: "എന്താണിത്?" അബ്ദുർറഹ്മാൻ പറഞ്ഞു: അൽപം സ്വർണ്ണത്തിനു പകരമായി ഞാനൊരു സ്ത്രീയെ വിവാഹം ചെയ്തു. റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു നിനക്ക് അനുഗ്രഹം ചെയ്യട്ടെ. ഒരു ആടിനെ അറുത്തെങ്കിലും നീ വിവാഹസദ്യ നൽകുക." (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 67, 67, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 80, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ أَحَقَّ الشَّرْطِ أَنْ يُوفَى بِهِ مَا اسْتَحْلَلْتُمْ بِهِ الْفُرُوجَ". (ق,د,ت,ن,جه)', 'ഉഖ്ബതുബ്നു ആമിർ(റ): നബി(സ) പറഞ്ഞു: "വിവാഹബന്ധം സ്ഥാപിക്കുമ്പോൾ നിശ്ചയിച്ച വ്യവസ്ഥകളാണ് കരാറുകളിൽ വെച്ച് ഏറെ കൃത്യതയോടെ പാലിക്കപ്പെടേണ്ടത്." (ബു,മു,ദ,തു,ന,ജ)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബതുബ്നു ആമിർ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 67, 67, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 81, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا كَانَ مِنْ صَدَاقٍ أَوْ حِبَاءٍ أَوْ هِبَةٍ قَبْلَ عِصْمَةِ النِّكَاحِ فَهُوَ لَهَا، وَمَا كَانَ بَعْدَ عِصْمَةِ النِّكَاحِ فَهُوَ لِمَنْ أُعْطِيَهُ أَوْ حُبِيَ، وَأَحَقُّ مَا يُكْرَمُ الرَّجُلُ بِهِ ابْنَتُهُ أَوْ أُخْتُهُ". (د,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "വിവാഹ ഉടമ്പടിക്ക് മുമ്പ് നൽകപ്പെട്ട മഹ്റും ദാനവും സമ്മാനവും ഭാര്യക്കാണ്. വിവാഹ ഉടമ്പടിക്ക് ശേഷമുള്ളത് നൽകപ്പെടുന്നവനുള്ളതാണ്. ഒരാൾ ബഹുമാനക്കപ്പെടാൻ ഏറ്റവും അർഹമായത് തന്റെ മകളെക്കൊണ്ടോ, തന്റെ സഹോദരിയെക്കൊണ്ടോ ആണ്. (ദ,ന,ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 67, 67, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 82, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا عَنِ ابْنِ عَبَّاسٍ قَالَا: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا نِكَاحَ إِلَّا بِوَلِيٍّ". وَفِي حَدِيثِ عَائِشَةَ: "وَالسُّلْطَانُ وَلِيُّ مَنْ لَا وَلِيَّ لَهُ". (د,ت,جه)', 'ആഇശ(റ), ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "രക്ഷിതാവിനെക്കൊണ്ടല്ലാതെ നികാഹില്ല." മറ്റൊരു നിവേദനം: "രക്ഷിതാവില്ലാത്തവന്റെ രക്ഷിതാവ് ഭരണാധികാരിയാണ്." (ദ,തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 68, 68, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=2 and h.hadith_no=82), 1, null, 'മറ്റൊരു നിവേദനം: "രക്ഷിതാവില്ലാത്തവന്റെ രക്ഷിതാവ് ഭരണാധികാരിയാണ്." (ദ,തു,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 83, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَيُّمَا امْرَأَةٍ نَكَحَتْ بِغَيْرِ إِذْنِ مَوَالِيهَا فَنِكَاحُهَا بَاطِلٌ" ثَلَاثَ مَرَّاتٍ "فَإِنْ دَخَلَ بِهَا فَالْمَهْرُ لَهَا بِمَا أَصَابَ مِنْهَا، فَإِنْ تَشَاجَرُوا فَالسُّلْطَانُ وَلِيُّ مَنْ لَا وَلِيَّ لَهُ". (د,ت,ن,جه)', 'ആഇശ(റ): റസൂൽ(സ) പറഞ്ഞു: "രക്ഷിതാക്കളുടെ സമ്മതമില്ലാതെ ഒരു സ്ത്രീ വിവാഹം ചെയ്താൽ, അവളുടെ വിവാഹം അസാധുവാണ്, അവിടന്ന് ഇത് മൂന്ന് പ്രാവശ്യം പറഞ്ഞു. അവൻ അവളുമായി വേഴ്ച നടത്തിയാൽ, വേഴ്ച നടത്തിയത് കാരണം അവൾക്കു നൽകിയ മഹ്റ് അവൾക്കുള്ളതാണ്." (ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 68, 68, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 84, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تُزَوِّجُ الْمَرْأَةُ الْمَرْأَةَ، وَلَا تُزَوِّجُ الْمَرْأَةُ نَفْسَهَا، فَإِنَّ الزَّانِيَةَ هِيَ الَّتِي تُزَوِّجُ نَفْسَهَا". (جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരു സ്ത്രീ മറ്റൊരു സ്ത്രീയെ വിവാഹം ചെയ്ത് കൊടുക്കരുത്. ഒരു സ്ത്രീ സ്വയം വിവാഹം ചെയ്യരുത്. സ്വയം വിവാഹം ചെയ്യുന്നവളാണ് വേശ്യ." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 68, 68, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 85, 'عَنْ أُمِّ حَبِيبَةَ رَضِيَ اللهُ عَنْهَا: أَنَّهَا كَانَتْ عِنْدَ ابْنِ جَحْشٍ فَهَلَكَ عَنْهَا، وَكَانَ فِيمَنْ هَاجَرَ إِلَى أَرْضِ الْحَبَشَةِ، فَزَوَّجَهَا النَّجَاشِيُّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهِيَ عِنْدَهُمْ. (د,ن)', 'ഉമ്മുഹബീബ(റ): അവർ ഇബ്നു ജഹ്ഷിന്റെ അടുത്തായിരുന്നു (ഭാര്യയായിരുന്നു). അങ്ങനെ അദ്ദേഹം അവരെ വേർപിരിഞ്ഞു (മരിച്ചു). ഇബ്നു ജഹ്ശ് അബ്സീനിയയുടെ നാട്ടിലേക്ക് ഹിജ്റപോയവരിൽ പെട്ടവരായിരുന്നു. അങ്ങനെ നജ്ജാശി രാജാവ് അവരെ റസൂൽ(സ)ക്ക് വിവാഹം ചെയ്ത് കൊടുത്തു. ഉമ്മുഹബീബ(റ) അപ്പോൾ അവരുടെ കൂടെയായിരുന്നു. (ദ,ന)', 'أُمِّ حَبِيبَةَ', 'ഉമ്മുഹബീബ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 68, 68, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 86, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْبَغَايَا اللَّاتِي يَنْكِحْنَ أَنْفُسَهُنَّ بِغَيْرِ بَيِّنَةٍ". (ت)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "ഒരു സാക്ഷി കൂടാതെ, സ്വയം വിവാഹം ചെയ്യുന്നവരാണ് വേശ്യകൾ ". (തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 68, 68, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 87, 'عَنْ سَمُرَةَ بْنِ جُنْدَبٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَيُّمَا امْرَأَةٍ زَوَّجَهَا وَلِيَّانِ فَهِيَ لِلْأَوَّلِ مِنْهُمَا، وَمَنْ بَاعَ بَيْعًا مِنْ رَجُلَيْنِ فَهُوَ لِلْأَوَّلِ مِنْهُمَا". حَسَنٌ. (د,ت,ن,جه)', 'സമുറതുബ്നു ജുൻദുബ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരു സ്ത്രീയെ രണ്ട് രക്ഷിതാക്കൾ (രണ്ട്പേർക്ക്) വിവാഹം ചെയ്ത് കൊടുത്താൽ അവൾ അവരിൽ ആദ്യം വിവാഹം ചെയ്തവനുള്ളതാണ്. ഒരാൾ രണ്ട് ആളുകൾക്ക് ഒരു സാധനം വിറ്റാൽ അത് അവരിൽ ആദ്യം വിറ്റവനുള്ളതാണ്." (ദ,തു,ന,ജ)', 'سَمُرَةَ بْنِ جُنْدَبٍ', 'സമുറതുബ്നു ജുൻദുബ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 68, 69, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 88, 'عَنْ مَعْقِلِ بْنِ يَسَارٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَتْ لِي أُخْتٌ تُخْطَبُ إِلَيَّ، فَأَتَانِي ابْنُ عَمٍّ لِي، فَأَنْكَحْتُهَا إِيَّاهُ، ثُمَّ طَلَّقَهَا طَلَاقًا لَهُ رَجْعَةٌ، ثُمَّ تَرَكَهَا حَتَّى انْقَضَتْ عِدَّتُهَا، فَلَمَّا خُطِبَتْ إِلَيَّ أَتَانِي يَخْطُبُهَا، فَقُلْتُ: لَا وَاللهِ لَا أُنْكِحُهَا أَبَدًا، قَالَ: فَفِيَّ نَزَلَتْ هَذِهِ الْآيَةُ: {وَإِذَا طَلَّقْتُمُ النِّسَاءَ فَبَلَغْنَ أَجَلَهُنَّ فَلَا تَعْضُلُوهُنَّ أَنْ يَنْكِحْنَ أَزْوَاجَهُنَّ} [البقرة: ٢٣٢] الْآيَةَ، قَالَ: فَكَفَّرْتُ عَنْ يَمِينِي، فَأَنْكَحْتُهَا إِيَّاهُ. (خ,د,ت)', 'മഅ്ഖിലുബ്നു യസാർ(റ): എനിക്കൊരു സഹോദരിയുണ്ടായിരുന്നു, എന്നോട് ആളുകൾ അവരുടെ വിവാഹാന്വേഷണം നടത്തിയിരുന്നു. അങ്ങനെ എന്റെയടുത്ത് പിതൃവ്യ സഹോദരൻ വന്നു. ഞാനവളെ അവന് വിവാഹം ചെയ്ത് കൊടുത്തു. പിന്നെ അവൻ അവളെ മടക്കിയെടുക്കാവുന്ന വിധത്തിൽ ത്വലാഖ് ചൊല്ലി അവളുടെ ഇദ്ദ കഴിയുന്നത് വരെ, അവൻ അവളെ തൃജിച്ചു. വീണ്ടും എന്റെയടുത്ത് അവളുടെ വിവാഹാന്വേഷണം വന്നപ്പോൾ പിതൃവ്യ സഹോദരൻ വന്നു. ഞാൻ പറഞ്ഞു: ഇല്ല, അല്ലാഹു തന്നെ സത്യം. അവളെ നിനക്ക് ഞാൻ വിവാഹം ചെയ്ത് തരില്ല. മഅ്ഖിലുബ്നു യസാർ(റ) പറയുന്നു: അപ്പോൾ എന്റെ വിഷയത്തിലാണ് ഈ സൂക്തം അവതരിച്ചത്. ''നിങ്ങൾ ഭാര്യമാരെ വിവാഹ മോചനം ചെയ്തിട്ട് അവർ അവരുടെ അവധി എത്തിച്ചാൽ അവർ തങ്ങളുടെ ഭർത്താക്കൻമാരുമായി വിവാഹത്തിലേർപ്പെടുന്നതിന് നിങ്ങൾ തടസ്സമുണ്ടാക്കരുത്.'' (അൽ ബഖറ: 232) അങ്ങനെ ഞാന് പ്രായശ്ചിത്തം നൽകി. ഞാൻ സഹോദരിയെ അവന് വിവാഹം ചെയ്ത് കൊടുത്തു. (ബു,ദ,തു)', 'مَعْقِلِ بْنِ يَسَارٍ', 'മഅ്ഖിലുബ്നു യസാർ(റ)', null, null, array['خ','د','ت']::text[], array['ബു','ദ','തു']::text[], 'البقرة: ٢٣٢', null, 69, 69, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 89, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا فِي هَذِهِ الْآيَةِ: {لَا يَحِلُّ لَكُمْ أَنْ تَرِثُوا النِّسَاءَ كَرْهًا وَلَا تَعْضُلُوهُنَّ} [النساء: ١٩] قَالَ: كَانَ الرَّجُلُ – إِذَا مَاتَ – كَانَ أَوْلِيَاؤُهُ أَحَقَّ بِامْرَأَتِهِ مِنْ وَلِيِّ نَفْسِهَا: إِنْ شَاءَ بَعْضُهُمْ زَوَّجَهَا – أَوْ زَوَّجُوهَا – وَإِنْ شَاءُوا لَمْ يُزَوِّجُوهَا، فَنَزَلَتْ هَذِهِ الْآيَةُ فِي ذَلِكَ. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): ''സ്ത്രീകളെ ബലാൽക്കാരമായി അനന്തരാവകാശ സ്വത്തായി എടുക്കൽ നിങ്ങൾക്കനുവദനീയമല്ല. അവരുടെ (ഭാര്യമാരുടെ) വിവാഹം തടസ്സപ്പെടുത്തരുത്.'' (അന്നിസാഅ്: 19) എന്ന സൂക്തത്തെക്കുറിച്ച് ഇബ്നുഅബ്ബാസ്(റ) പറയുന്നു: ഒരാൾ മരിച്ചാൽ അയാളുടെ രക്ഷിതാക്കളായിരുന്നു അവന്റെ ഭാര്യയുടെ രക്ഷിതാവിനേക്കാൾ, ഭാര്യയുമായി ഏറ്റവും ബന്ധപ്പെട്ടവർ. അവർ ഉദ്ദേശിക്കുന്നുവെങ്കിൽ അവളെ വിവാഹം കഴിപ്പിക്കുകയും, അവരുദ്ദേശിക്കുന്നുവെങ്കിൽ അവളെ വിവാഹം കഴിപ്പിക്കാതിരിക്കുകയും ചെയ്തു. അപ്പോഴാണ് ഈ സൂക്തം അവതരിക്കുന്നത്. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], 'النساء: ١٩', null, 69, 69, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 90, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: {لَا يَحِلُّ لَكُمْ أَنْ تَرِثُوا النِّسَاءَ كَرْهًا وَلَا تَعْضُلُوهُنَّ لِتَذْهَبُوا بِبَعْضِ مَا آتَيْتُمُوهُنَّ إِلَّا أَنْ يَأْتِينَ بِفَاحِشَةٍ مُبَيِّنَةٍ} [النساء: ١٩]. وَذَلِكَ: أَنَّ الرَّجُلَ كَانَ يَرِثُ امْرَأَةَ ذِي قَرَابَتِهِ، فَيَعْضُلُهَا حَتَّى تَمُوتَ أَوْ تَرُدَّ إِلَيْهِ صَدَاقَهَا، فَأَحْكَمَ اللهُ عَنْ ذَلِكَ، وَنَهَى عَنْ ذَلِكَ. وَفِي رِوَايَةٍ: فَوَعَظَ اللهُ ذَلِكَ. (خ,د)', 'ഇബ്നുഅബ്ബാസ്(റ): ''സ്ത്രീകളെ ബലാൽക്കാരമായിട്ട് അനന്തരാവകാശ സ്വത്തായി എടുക്കൽ നിങ്ങൾക്കനുവദനീയമല്ല. അവർക്ക് (ഭാര്യമാർക്ക്) നിങ്ങൾ കൊടുത്തിട്ടുള്ളതിൽ, ഒരു ഭാഗം തട്ടിയെടുക്കാൻ വേണ്ടി നിങ്ങളവരെ മുടക്കിയിടുകയും ചെയ്യരുത്. അവർ പ്രത്യക്ഷമായ വല്ല നീചവൃത്തിയും ചെയ്തെങ്കിലല്ലാതെ.'' (അന്നിസാഅ്:19) എന്ന സൂക്തത്തെക്കുറിച്ച് ഇബ്നുഅബ്ബാസ്(റ) പറയുന്നു: അടുത്ത ബന്ധുവായ സ്ത്രീയെ ഒരാൾ അനന്തരസ്വത്തായി സ്വീകരിച്ചിരുന്നു. അങ്ങനെ അവൾ മരിക്കുകയോ അവളുടെ മഹ്റ് തനിക്ക് തിരിച്ച് നൽകുകയോ ചെയ്യുന്നത് വരെ, അവൻ അവളെ വിവാഹം കഴിപ്പിക്കാതെ മുടക്കിയിട്ടു. അല്ലാഹു അത് തടയുകയും അത് നിരോധിക്കുകയും ചെയ്തു. മറ്റൊരു നിവേദനം: അപ്പോൾ അല്ലാഹു ഇത് ഉപദേശിച്ചു. (ബു,ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], 'النساء: ١٩', null, 69, 70, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=2 and h.hadith_no=90), 1, 'وَفِي رِوَايَةٍ: فَوَعَظَ اللهُ ذَلِكَ. (خ,د)', 'മറ്റൊരു നിവേദനം: അപ്പോൾ അല്ലാഹു ഇത് ഉപദേശിച്ചു. (ബു,ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 91, 'عَنْ مَعْقِلِ بْنِ يَسَارٍ رَضِيَ اللهُ عَنْهُ قَالَ: زَوَّجْتُ أُخْتًا لِي مِنْ رَجُلٍ فَطَلَّقَهَا، حَتَّى إِذَا انْقَضَتْ عِدَّتُهَا جَاءَ يَخْطُبُهَا، فَقُلْتُ لَهُ: زَوَّجْتُكَ وَفَرَشْتُكَ وَأَكْرَمْتُكَ، فَطَلَّقْتَهَا، ثُمَّ جِئْتَ تَخْطُبُهَا، لَا وَاللهِ لَا تَعُودُ إِلَيْكَ أَبَدًا، وَكَانَ رَجُلًا لَا بَأْسَ بِهِ، وَكَانَتِ الْمَرْأَةُ تُرِيدُ أَنْ تَرْجِعَ إِلَيْهِ، فَأَنْزَلَ اللهُ هَذِهِ الْآيَةَ {فَلَا تَعْضُلُوهُنَّ}، فَقُلْتُ: الْآنَ أَفْعَلُ يَا رَسُولَ اللهِ، قَالَ: فَزَوَّجَهَا إِيَّاهُ. (خ)', 'മഅ്ഖിലുബ്നു യസാർ(റ): എന്റെ സഹോദരിയെ ഞാനൊരാൾക്ക് വിവാഹം ചെയ്ത് കൊടുത്തു. അദ്ദേഹമവളെ വിവാഹമോചനം നടത്തി. സഹോദരിയുടെ ഇദ്ദ കഴിഞ്ഞപ്പോൾ അവളുടെ വിവാഹമന്വേഷിച്ച് അവൻ വന്നു. അപ്പോൾ ഞാനദ്ദേഹത്തോട് പറഞ്ഞു: നിങ്ങൾക്ക് ഞാനവളെ വിവാഹം ചെയ്ത് തന്നു. വിരിപ്പ് വിരിച്ച് തന്നു. നിങ്ങളെ ഞാൻ ബഹുമാനിച്ചു. എന്നിട്ടും നിങ്ങളവളെ വിവാഹമോചനം ചെയ്തു. വീണ്ടും വിവാഹം ചെയ്യാനാലോചിച്ച് കൊണ്ട് നിങ്ങളിതാ വന്നിരിക്കുന്നു. ഇല്ല. അല്ലാഹുവാണ് സത്യം, അവൾ നിങ്ങളുടെ അരികിലേക്ക് ഒരിക്കലും മടങ്ങിവരില്ല. ആ മനുഷ്യൻ ദോഷമില്ലാത്തവനായിരുന്നു. അവളാകട്ടെ അദ്ദേഹത്തിന്റെയടുത്ത് ചെല്ലാനാശിക്കുന്നു. അപ്പോഴാണ് ''നിങ്ങളവളെ വിവാഹം ചെയ്യിക്കാതെ തടഞ്ഞിടരുത്'' എന്ന സൂക്തമിറങ്ങിയത്. അപ്പോൾ ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഇനി ഞാനിങ്ങനെ ചെയ്ത് കൊള്ളാം. അദ്ദേഹത്തിന് ഞാനവളെ വിവാഹം ചെയ്ത് കൊടുത്തു. (ബു)', 'مَعْقِلِ بْنِ يَسَارٍ', 'മഅ്ഖിലുബ്നു യസാർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 70, 70, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 92, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنِّي تَزَوَّجْتُ امْرَأَةً مِنَ الْأَنْصَارِ، فَقَالَ لَهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "هَلْ نَظَرْتَ إِلَيْهَا؟ فَإِنَّ فِي عُيُونِ الْأَنْصَارِ شَيْئًا". قَالَ: قَدْ نَظَرْتُ إِلَيْهَا، قَالَ: "عَلَى كَمْ تَزَوَّجْتَهَا". قَالَ: عَلَى أَرْبَعِ أَوَاقٍ، فَقَالَ لَهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "عَلَى أَرْبَعِ أَوَاقٍ؟ كَأَنَّمَا تَنْحِتُونَ الْفِضَّةَ مِنْ عُرْضِ هَذَا الْجَبَلِ. مَا عِنْدَنَا مَا نُعْطِيكَ، وَلَكِنْ عَسَى أَنْ نَبْعَثَكَ فِي بَعْثٍ تُصِيبُ مِنْهُ". قَالَ: فَبَعَثَ بَعْثًا إِلَى بَنِي عَبْسٍ، بَعَثَ ذَلِكَ الرَّجُلَ فِيهِمْ. (م)', 'അബൂഹുറൈറ(റ): ഒരാൾ നബി(സ)യുടെ അടുത്ത് വന്ന് കൊണ്ട് പറഞ്ഞു: അൻസാറുകളിൽപെട്ട ഒരു സ്ത്രീയെ ഞാൻ വിവാഹം ചെയ്തു. അപ്പോൾ അദ്ദേഹത്തോട് നബി(സ) ചോദിച്ചു: "നീ അവളെ നോക്കിയോ? അൻസാറുകളുടെ ദൃഷ്ടിയിൽ ഒരു പ്രത്യേകതയുണ്ട്." അദ്ദേഹം പറഞ്ഞു: ഞാനവളെ നോക്കിയിട്ടുണ്ട്. നബി(സ) വീണ്ടും ചോദിച്ചു: "എത്ര മഹ്റിനാണ് നീ അവളെ വിവാഹം ചെയ്തത്." അദ്ദേഹം പറഞ്ഞു: നാല് ഊഖിയക്ക് (ഒരു ഊഖിയ 12 വെള്ളിത്തൂക്കം) നബി(സ) ചോദിച്ചു: "നാല് ഊഖയക്കോ? നിങ്ങൾ ഈ പർവ്വതത്തിന്റെ ഭാഗത്തുനിന്ന് വെള്ളി തുരന്നെടുക്കുകയാണോ? നിനക്ക് നൽകാനുള്ളത് നമ്മുടെ അടുത്തില്ല. എങ്കിലും നിന്നെ ഞാൻ യുദ്ധസംഘത്തോടൊപ്പം അയക്കാം. നിനക്കതിൽ നിന്ന് ഗനീമത് കിട്ടും." നബി(സ) ഒരു യുദ്ധസംഘത്തെ അയച്ചു. ഇയാളെയും നബി(സ) അക്കൂട്ടത്തിലയച്ചു. (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 70, 70, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 93, 'عَنْ سَهْلِ بْنِ سَعْدٍ رَضِيَ اللهُ عَنْهُ أَنَّ امْرَأَةً جَاءَتْ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللهِ جِئْتُ لِأَهَبَ لَكَ نَفْسِي، فَنَظَرَ إِلَيْهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَصَعَّدَ النَّظَرَ إِلَيْهَا وَصَوَّبَهُ، ثُمَّ طَأْطَأَ رَأْسَهُ، وَذَكَرَ الْحَدِيثَ، وَقَالَ فِي آخِرِهِ: قَالَ: "أَتَقْرَؤُهُنَّ عَنْ ظَهْرِ قَلْبِكَ؟" قَالَ: نَعَمْ. قَالَ: "اذْهَبْ فَقَدْ مَلَّكْتُكَهَا بِمَا مَعَكَ مِنَ الْقُرْآنِ". (خ)', 'സഹ്ലുബ്നു സഅ്ദ്(റ): (ഒരു നിവേദനത്തിൽ) ഒരു സ്ത്രീ റസൂൽ(സ)യുടെ അടുത്ത് വന്ന് കൊണ്ട് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, എന്റെ ശരീരം അവിടത്തേക്ക് നൽകാനാണ് ഞാൻ വന്നത്. റസൂൽ(സ) അവളെ നോക്കി. അവളുടെ മുകളിലേക്കും. താഴേക്കും നോക്കി. പിന്നെ അവിടന്ന് തലതാഴ്ത്തി. സഹ്ലുബ്നു സഅ്ദ്(റ) ഹദീസ് പറഞ്ഞു. അതിന്റെ അവസാനത്തിൽ പറയുന്നു: നബി(സ) പറഞ്ഞു: "അവ നിനക്ക് മനഃപാഠമാണോ?" അദ്ദേഹം പറഞ്ഞു: അതെ. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നീ പോയി കൊള്ളുക. നീ ഹൃദ്യസ്ഥമാക്കിയ ഖുർആൻ മഹ്റായി നിനക്ക് ഞാനവളെ വിവാഹം ചെയ്ത് തന്നിരിക്കുന്നു." (ബു)', 'سَهْلِ بْنِ سَعْدٍ', 'സഹ്ലുബ്നു സഅ്ദ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 70, 71, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 94, 'عَنْ سَهْلِ بْنِ أَبِي حَثْمَةَ، عَنْ مُحَمَّدِ بْنِ مَسْلَمَةَ رَضِيَ اللهُ عَنْهُمَا قَالَ: خَطَبْتُ امْرَأَةً، فَجَعَلْتُ أَتَخَبَّأُ لَهَا، حَتَّى نَظَرْتُ إِلَيْهَا فِي نَخْلٍ لَهَا. فَقِيلَ لَهُ: أَتَفْعَلُ هَذَا وَأَنْتَ صَاحِبُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ فَقَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِذَا أَلْقَى اللهُ فِي قَلْبِ امْرِئٍ خِطْبَةَ امْرَأَةٍ فَلَا بَأْسَ أَنْ يَنْظُرَ إِلَيْهَا". (جه)', 'സഹ്ലുബ്നു അബീ ഹസ്മ(റ): മുഹമ്മദുബ്നു മസ്ലമ(റ) പറയുന്നു. ഞാനൊരു സ്ത്രീയെ വിവാഹമന്വേഷിച്ചു. ഞാനവളെ ഒളിഞ്ഞ് നോക്കാൻ തുടങ്ങി. അവളുടെ ഒരു ഈന്തപ്പനത്തോട്ടത്തിൽ വെച്ച് ഞാനവളെ നോക്കി. അപ്പോൾ അദ്ദേഹത്തോട് ആരോ പറഞ്ഞു: നിങ്ങൾ റസൂൽ(സ)യുടെ അനുചരനായിട്ട് ഇങ്ങനെ ചെയ്യുന്നോ? അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "അല്ലാഹു ഒരാളുടെ മനസ്സിൽ ഒരു സ്ത്രീയെ വിവാഹം ചെയ്യാനുള്ള ആഗ്രഹം ജനിപ്പിച്ചാൽ അവളെ നോക്കുന്നതിൽ തെറ്റില്ല." (തു,ന,ജ)', 'سَهْلِ بْنِ أَبِي حَثْمَةَ، عَنْ مُحَمَّدِ بْنِ مَسْلَمَةَ', 'സഹ്ലുബ്നു അബീ ഹസ്മ(റ)', null, null, array['جه']::text[], array['തു','ന','ജ']::text[], null, null, 71, 71, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 95, 'عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَذَكَرْتُ لَهُ امْرَأَةً أَخْطُبُهَا. فَقَالَ: "اذْهَبْ فَانْظُرْ إِلَيْهَا فَإِنَّهُ أَجْدَرُ أَنْ يُؤْدَمَ بَيْنَكُمَا". فَأَتَيْتُ امْرَأَةً مِنَ الْأَنْصَارِ فَخَطَبْتُهَا إِلَى أَبَوَيْهَا، وَأَخْبَرْتُهُمَا بِقَوْلِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَكَأَنَّهُمَا كَرِهَا ذَلِكَ. قَالَ: فَسَمِعَتْ ذَلِكَ الْمَرْأَةُ وَهِيَ فِي خِدْرِهَا، فَقَالَتْ: إِنْ كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَمَرَكَ أَنْ تَنْظُرَ فَانْظُرْ، وَإِلَّا، فَأَنْشُدُكَ. كَأَنَّهَا أَعْظَمَتْ ذَلِكَ. قَالَ: فَنَظَرْتُ إِلَيْهَا فَتَزَوَّجْتُهَا. فَذَكَرَ مِنْ مُوَافَقَتِهَا. (ت,ن,جه)', 'മുഗീറതുബ്നു ശുഅ്ബ(റ): ഞാൻ നബി(സ)യുടെ അടുത്ത് ചെന്നു. ഞാൻ വിവാഹാലോചന നടത്തുന്ന സ്ത്രീയെക്കുറിച്ച് അവിടത്തോട് പറഞ്ഞു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നീ പോയി അവളെ നോക്കുക, അത് നിങ്ങൾക്കിടയിൽ സ്നേഹമുണ്ടാക്കാൻ ഏറ്റവും നല്ലതാണ്." ഞാൻ അൻസാറുകളിൽ പെട്ട ഒരു സ്ത്രീയുടെ അടുത്ത് ചെന്നു. ഞാനവളുടെ രക്ഷിതാക്കളോട് വിവാഹാലോചന നടത്തി. ഞാനവർ രണ്ടു പേരോടും നബി(സ) പറഞ്ഞത് അറിയിച്ചു. അവർക്കത് ഇഷ്ടപ്പെടാത്തതു പോലെ തോന്നി. സ്ത്രീ ഇത് അവളുടെ മറയിലിരുന്ന് കേട്ടു. അവർ പറഞ്ഞു: റസൂൽ(സ) നിങ്ങളോട് നോക്കാൻ പറഞ്ഞിട്ടുണ്ടെങ്കിൽ നോക്കിക്കൊള്ളുക. അവിടന്നങ്ങനെ പറഞ്ഞിട്ടില്ലെങ്കിൽ ഞാൻ അല്ലാഹുവിൽ സത്യം ചെയ്യുന്നു, നിങ്ങളങ്ങനെ ചെയ്യരുത്. അവളിത് വലിയ ഗുരുതരമായ വിഷമായി മനസ്സിലാക്കിയെന്ന് തോന്നുന്നു. മുഗീറ(റ) പറയുന്നു: ഞാനവളെ നോക്കുകയും അവളെ വിവാഹം കഴിക്കുകയും ചെയ്തു. അവർക്കിടയിലെ സ്നേഹബന്ധം പ്രശംസിക്കപ്പെട്ടു. (ത,ന,ജ)', 'الْمُغِيرَةِ بْنِ شُعْبَةَ', 'മുഗീറതുബ്നു ശുഅ്ബ(റ)', null, null, array['ت','ن','جه']::text[], array['ത','ന','ജ']::text[], null, null, 71, 71, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 96, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا خَطَبَ أَحَدُكُمْ الْمَرْأَةَ: فَإِنِ اسْتَطَاعَ أَنْ يَنْظُرَ إِلَى مَا يَدْعُوهُ إِلَى نِكَاحِهَا فَلْيَفْعَلْ". قَالَ: فَخَطَبْتُ جَارِيَةً فَكُنْتُ أَتَخَبَّأُ لَهَا، حَتَّى رَأَيْتُ مِنْهَا مَا دَعَانِي إِلَى نِكَاحِهَا وَتَزَوُّجِهَا فَتَزَوَّجْتُهَا. (م,د)', 'ജാബിറുബ്നു അബ്ദില്ലാഹ്(റ): റസൂൽ(സ) പറയുന്നു: "നിങ്ങൾ സ്ത്രീകളെ വിവാഹാലോചന നടത്തുമ്പോൾ വിവാഹത്തിലേക്ക് പ്രേരിപ്പിക്കുന്നത്ര നോക്കാൻ കഴിഞ്ഞാൽ അവൻ നോക്കട്ടെ." ജാബിർ(റ) പറഞ്ഞു: ഞാനൊരു സ്ത്രീയെ വിവാഹാന്വേഷണം നടത്തി. ഞാനവളെ മറഞ്ഞുനോക്കുകയായിരുന്നു. അങ്ങനെ അവളെ വിവാഹം കഴിക്കാൻ പ്രേരിപ്പിക്കുന്നത്ര ഞാനവളെ കണ്ടു. അങ്ങനെ വേളികഴിച്ചു. (മു,ദ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ലാഹ്(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 71, 72, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 97, 'عَنِ ابْنِ عُمَرَ، عَنْ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: تَأَيَّمَتْ حَفْصَةُ بِنْتُ عُمَرَ مِنْ خُنَيْسٍ يَعْنِي ابْنَ حُذَافَةَ، وَكَانَ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِمَّنْ شَهِدَ بَدْرًا، فَتُوُفِّيَ بِالْمَدِينَةِ، فَلَقِيتُ عُثْمَانَ بْنَ عَفَّانَ فَعَرَضْتُ عَلَيْهِ حَفْصَةَ فَقُلْتُ: إِنْ شِئْتَ أَنْكَحْتُكَ حَفْصَةَ. فَقَالَ: سَأَنْظُرُ فِي ذَلِكَ. فَلَبِثْتُ لَيَالِيَ، فَلَقِيتُهُ فَقَالَ: مَا أُرِيدُ أَنْ أَتَزَوَّجَ يَوْمِي هَذَا. قَالَ عُمَرُ: فَلَقِيتُ أَبَا بَكْرٍ الصِّدِّيقَ رَضِيَ اللهُ عَنْهُ فَقُلْتُ: إِنْ شِئْتَ أَنْكَحْتُكَ حَفْصَةَ. فَلَمْ يَرْجِعْ إِلَيَّ شَيْئًا، فَكُنْتُ عَلَيْهِ أَوْجَدَ مِنِّي عَلَى عُثْمَانَ رَضِيَ اللهُ عَنْهُ، فَلَبِثْتُ لَيَالِيَ، فَخَطَبَهَا إِلَيَّ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَنْكَحْتُهَا إِيَّاهُ، فَلَقِيَنِي أَبُو بَكْرٍ فَقَالَ: لَعَلَّكَ وَجَدْتَ عَلَيَّ حِينَ عَرَضْتَ عَلَيَّ حَفْصَةَ فَلَمْ أَرْجِعْ إِلَيْكَ شَيْئًا. قُلْتُ: نَعَمْ. قَالَ: فَإِنَّهُ لَمْ يَمْنَعْنِي حِينَ عَرَضْتَ عَلَيَّ أَنْ أَرْجِعَ إِلَيْكَ شَيْئًا إِلَّا أَنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَذْكُرُهَا، وَلَمْ أَكُنْ لِأُفْشِيَ سِرَّ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَلَوْ تَرَكَهَا نَكَحْتُهَا. (خ,ن)', 'ഇബ്നുഉമർ(റ): ഉമർ(റ) പറയുന്നു: ഖുനൈസുബ്നു ഹുദാഫയുടെ വേർപ്പാട് മൂലം ഉമർ(റ)വിന്റെ മകൾ ഹഫ്സ(റ) വിധവയായി. അദ്ദേഹം ബദ്റിൽ പങ്കെടുത്ത നബി(സ)യുടെ അനുചരരിൽ പെട്ടവനാണ്. ഖുനൈസുബ്നു ഹുദാഫ(റ) മദീനയിൽ വെച്ച് വഫാത്തായി. അങ്ങനെ ഞാൻ ഉസ്മാനുബ്നു അഫ്ഫാൻ(റ)വിനെ കണ്ടുമുട്ടി. ഞാനദ്ദേഹത്തോട് ഹഫ്സയുടെ വിവാഹകാര്യം പറഞ്ഞു. ഞാൻ പറഞ്ഞു: നിങ്ങളാഗ്രഹിക്കുന്നുവെങ്കിൽ നിങ്ങൾക്ക് ഞാൻ ഹഫ്സയെ വിവാഹം ചെയ്തു തരാം. അപ്പോൾ ഉസ്മാൻ(റ) പറഞ്ഞു: ഈ വിഷയം ഞാൻ ആലോചിക്കട്ടെ. ഞാൻ രാത്രികളോളം കാത്തുനിന്നു. അങ്ങനെ ഞാൻ ഉസ്മാൻ(റ)വിനെ കണ്ടുമുട്ടി. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: ഈ ദിവസം ഞാൻ വിവാഹം കഴിക്കാൻ ആഗ്രഹിക്കുന്നില്ല. ഉമർ(റ) പറയുന്നു: അങ്ങനെ ഞാൻ അബൂബക്കർ(റ)വിനെ കണ്ടുമുട്ടി. ഞാനദ്ദേഹത്തോട് പറഞ്ഞു: നിങ്ങൾക്കാഗ്രഹമുണ്ടെങ്കിൽ നിങ്ങൾക്ക് ഞാൻ ഹഫ്സയെ വിവാഹം ചെയ്തുതരാം. അബൂബക്കർ(റ) ഒന്നും പ്രതികരിച്ചില്ല. അബൂബക്കർ(റ)വിനോട് വല്ലാതെ ദേഷ്യം തോന്നി. ഞാൻ രാത്രികളോളം കാത്തുനിന്നു. അങ്ങനെ റസൂൽ(സ) എന്നോട് ഹഫ്സ(റ)യുടെ വിവാഹാഭ്യർത്ഥന നടത്തി. ഞാനവളെ റസൂൽ(സ)ക്ക് വിവാഹം ചെയ്തുകൊടുത്തു. അങ്ങനെ എന്നെ അബൂബക്കർ(റ) കണ്ടുമുട്ടി. അദ്ദേഹം പറഞ്ഞു: നിങ്ങളെന്നോട് ഹഫ്സയുടെ കാര്യം പറഞ്ഞപ്പോൾ ഞാൻ നിങ്ങളോട് ഒന്നും പ്രതികരിക്കാതിരുന്നതിൽ നിങ്ങൾക്കെന്നോട് ദേഷ്യമുണ്ടാകും. ഞാൻ പറഞ്ഞു: അതെ. അപ്പോൾ അബൂബക്കർ(റ) പറഞ്ഞു: ഹഫ്സ(റ)യെക്കുറിച്ച് റസൂൽ(സ) പറയുന്നത് കേട്ടതിനാലാണ് നിങ്ങളെന്നോട് അവളുടെ കാര്യം പറഞ്ഞപ്പോൾ ഞാൻ ഒന്നും പ്രതികരിക്കാതിരുന്നത്. റസൂൽ(സ)യുടെ രഹസ്യം വെളിപ്പെടുത്തുന്നത് എനിക്ക് യോജിച്ചതല്ല. അവിടുന്ന് അവരെ ഒഴിവാക്കിയിരുന്നെങ്കിൽ ഞാനവളെ വിവാഹം കഴിക്കുമായിരുന്നു. (ബു,ന)', 'ابْنِ عُمَرَ، عَنْ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 72, 72, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 98, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَتِ امْرَأَةٌ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَعَرَضَتْ عَلَيْهِ نَفْسَهَا، فَقَالَتْ: يَا رَسُولَ اللهِ، أَلَكَ فِيَّ حَاجَةٌ. وَفِي رِوَايَةٍ عَنْهُ: أَنَّ امْرَأَةً عَرَضَتْ نَفْسَهَا عَلَى النَّبِيِّ صَلَّ◌ى اللهُ عَلَيْهِ وَسَلَّمَ، فَضَحِكَتِ ابْنَةُ أَنَسٍ فَقَالَتْ: مَا كَانَ أَقَلَّ حَيَاءَهَا. فَقَالَ أَنَسٌ: هِيَ خَيْرٌ مِنْكِ، عَرَضَتْ نَفْسَهَا عَلَى النَّبِيِّ صَلَّ◌ى اللهُ عَلَيْهِ وَسَلَّمَ. (ن)', 'അനസുബ്നു മാലിക്(റ): ഒരു സ്ത്രീ റസൂൽ(സ)യുടെ അടുത്ത് വന്ന് തന്റെ ശരീരം അവിടത്തേക്ക് സമർപ്പിച്ചു. അവർ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അങ്ങേക്ക് എന്നെ ആവശ്യമുണ്ടോ? മറ്റൊരു നിവേദനം: ഒരു സ്ത്രീ തന്റെ ശരീരം റസൂൽ(സ)ക്ക് സമർപ്പിച്ചു. അപ്പോൾ അനസ്(റ)വിന്റെ പുത്രി ചിരിച്ചു. അവർ പറഞ്ഞു: അവൾക്കെന്താണ് തീരെ ലജ്ജയില്ലാത്തത്? അപ്പോൾ അനസ്(റ) പറഞ്ഞു: അവൾ നിന്നെക്കാൾ നല്ലവളാണ്. അവൾ അവളുടെ ശരീരം റസൂൽ(സ)ക്ക് സമർപ്പിച്ചു. (ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 73, 73, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=2 and h.hadith_no=98), 1, 'وَفِي رِوَايَةٍ عَنْهُ: أَنَّ امْرَأَةً عَرَضَتْ نَفْسَهَا عَلَى النَّبِيِّ صَلَّ◌ى اللهُ عَلَيْهِ وَسَلَّمَ، فَضَحِكَتِ ابْنَةُ أَنَسٍ فَقَالَتْ: مَا كَانَ أَقَلَّ حَيَاءَهَا. فَقَالَ أَنَسٌ: هِيَ خَيْرٌ مِنْكِ، عَرَضَتْ نَفْسَهَا عَلَى النَّبِيِّ صَلَّ◌ى اللهُ عَلَيْهِ وَسَلَّمَ. (ن)', 'മറ്റൊരു നിവേദനം: ഒരു സ്ത്രീ തന്റെ ശരീരം റസൂൽ(സ)ക്ക് സമർപ്പിച്ചു. അപ്പോൾ അനസ്(റ)വിന്റെ പുത്രി ചിരിച്ചു. അവർ പറഞ്ഞു: അവൾക്കെന്താണ് തീരെ ലജ്ജയില്ലാത്തത്? അപ്പോൾ അനസ്(റ) പറഞ്ഞു: അവൾ നിന്നെക്കാൾ നല്ലവളാണ്. അവൾ അവളുടെ ശരീരം റസൂൽ(സ)ക്ക് സമർപ്പിച്ചു. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 99, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْأَيِّمُ أَحَقُّ بِنَفْسِهَا مِنْ وَلِيِّهَا، وَالْبِكْرُ تُسْتَأْذَنُ – وفي رواية: وَالْيَتِيمَةُ تُسْتَأْمَرُ – فِي نَفْسِهَا، وَإِذْنُهَا صُمَاتُهَا". وفي رواية: "الْأَيِّمُ أَوْلَى بِأَمْرِهَا..". وفي رواية: "لَيْسَ لِلْوَلِيِّ مَعَ الثَّيِّبِ أَمْرٌ، وَالْيَتِيمَةُ تُسْتَأْمَرُ، فَصَمْتُهَا إِقْرَارُهَا". (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "കന്യകയല്ലാത്ത സ്ത്രീ തന്റെ വിഷയത്തിൽ തന്റെ രക്ഷിതാവിനെക്കാൾ ബന്ധപ്പെട്ടവളാണ്. കന്യകയോട് സമ്മതം ചോദിക്കപ്പെടണം. - മറ്റൊരു നിവേദനം: "അനാഥയോട് അവളുടെ വിഷയത്തിൽ കൂടിയാലോചന നടത്തണം. അവളുടെ സമ്മതം അവളുടെ മൗനമാണ്." മറ്റൊരു നിവേദനം: "കന്യകയല്ലാത്ത സ്ത്രീ തന്റെ വിഷയത്തിൽ ഏറ്റവും ബന്ധപ്പെട്ടവളാണ്." മറ്റൊരു നിവേദനം: "രക്ഷിതാവിന് കന്യകയല്ലാത്ത സ്ത്രീയോട് കൽപ്പനയില്ല. അനാഥയോട് കൂടിയാലോചന നടത്തണം. അവളുടെ മൗനം അവളുടെ സമ്മതമാണ്." (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 73, 73, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=2 and h.hadith_no=99), 1, 'وَفِي رِوَايَةٍ: وَالْيَتِيمَةُ تُسْتَأْمَرُ – فِي نَفْسِهَا، وَإِذْنُهَا صُمَاتُهَا".', 'മറ്റൊരു നിവേദനം: "അനാഥയോട് അവളുടെ വിഷയത്തിൽ കൂടിയാലോചന നടത്തണം. അവളുടെ സമ്മതം അവളുടെ മൗനമാണ്."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=2 and h.hadith_no=99), 2, 'وَفِي رِوَايَةٍ: "الْأَيِّمُ أَوْلَى بِأَمْرِهَا..".', 'മറ്റൊരു നിവേദനം: "കന്യകയല്ലാത്ത സ്ത്രീ തന്റെ വിഷയത്തിൽ ഏറ്റവും ബന്ധപ്പെട്ടവളാണ്."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=2 and h.hadith_no=99), 3, 'وَفِي رِوَايَةٍ: "لَيْسَ لِلْوَلِيِّ مَعَ الثَّيِّبِ أَمْرٌ، وَالْيَتِيمَةُ تُسْتَأْمَرُ، فَصَمْتُهَا إِقْرَارُهَا". (ن)', 'മറ്റൊരു നിവേദനം: "രക്ഷിതാവിന് കന്യകയല്ലാത്ത സ്ത്രീയോട് കൽപ്പനയില്ല. അനാഥയോട് കൂടിയാലോചന നടത്തണം. അവളുടെ മൗനം അവളുടെ സമ്മതമാണ്." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 100, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "اسْتَأْمِرُوا النِّسَاءَ فِي أَبْضَاعِهِنَّ". قِيلَ: فَإِنَّ الْبِكْرَ تَسْتَحِي وَتَسْكُتُ؟ قَالَ: "هُوَ إِذْنُهَا". (خ,ن)', 'ആഇശ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ സ്ത്രീകളോട് അവരുടെ വിവാഹകാര്യത്തിൽ കൂടിയാലോചന നടത്തുക." റസൂൽ(സ)യോട് ആരോ ചോദിച്ചു: കന്യക ലജ്ജിക്കുകയും മൗനമവലംബിക്കുകയും ചെയ്യില്ലേ. തിരുമേനി(സ) പറഞ്ഞു: "അത് അവളുടെ സമ്മതമാണ്." (ബു,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 73, 73, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 101, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "تُسْتَأْمَرُ الْيَتِيمَةُ فِي نَفْسِهَا، فَإِنْ سَكَتَتْ فَهُوَ إِذْنُهَا، وَإِنْ أَبَتْ فَلَا جَوَازَ عَلَيْهَا". وفي رواية: "فَإِنْ بَكَتْ أَوْ سَكَتَتْ". (د,ت,ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അനാഥയോട് അവളുടെ വിവാഹകാര്യത്തിൽ കൂടിയാലോചന നടത്തണം. അവൾ മൗനം ദീക്ഷിച്ചാൽ അത് അവളുടെ സമ്മതമാണ്. അവൾ വിസമ്മതിച്ചാൽ അവളെ മറികടക്കാൻ പാടില്ല." മറ്റൊരു നിവേദനത്തിൽ: "അവൾ കരഞ്ഞാലോ, മൗനമവലംബിച്ചാലോ" എന്നുണ്ട്. (ദ,തു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 73, 73, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=2 and h.hadith_no=101), 1, 'وَفِي رِوَايَةٍ: "فَإِنْ بَكَتْ أَوْ سَكَتَتْ". (د,ت,ن)', 'മറ്റൊരു നിവേദനത്തിൽ: "അവൾ കരഞ്ഞാലോ, മൗനമവലംബിച്ചാലോ" എന്നുണ്ട്. (ദ,തു,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 102, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "آمِرُوا النِّسَاءَ فِي بَنَاتِهِنَّ". (د)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "സ്ത്രീകളോട് അവരുടെ മകളുടെ വിവാഹകാര്യത്തിൽ കൂടിയാലോചന നടത്തുക." (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 74, 74, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 103, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ رَضِيَ اللهُ عَنْهُ وَمُجَمِّعِ بْنِ يَزِيدَ الْأَنْصَارِيَّيْنِ: أَنَّ رَجُلًا مِنْهُمْ يُدْعَى خِذَامًا أَنْكَحَ ابْنَةً لَهُ، فَكَرِهَتْ نِكَاحَ أَبِيهَا، فَأَتَتْ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَتْ لَهُ، فَرَدَّ عَلَيْهَا نِكَاحَ أَبِيهَا، فَنَكَحَتْ أَبَا لُبَابَةَ بْنَ عَبْدِ الْمُنْذِرِ. وَذَكَرَ يَحْيَى: أَنَّهَا كَانَتْ ثَيِّبًا. (خ,د,ن,جه)', 'അബ്ദുർറഹ്മാനുബ്നു യസീദ്(റ), മുജമ്മിഉബ്നു യസീദ്(റ): അവരുടെ കൂട്ടത്തിൽ പെട്ട ഖിദാമെന്ന് പേരുള്ള ഒരാൾ തന്റെ മകളെ വിവാഹം ചെയ്ത് കൊടുത്തു. തന്റെ പിതാവ് വിവാഹം കഴിപ്പിച്ചത് മകൾക്കിഷ്ടമായില്ല. അവർ റസൂൽ(സ)യുടെ അടുത്ത് ചെന്ന് വിഷയം പറഞ്ഞു. തന്റെ പിതാവ് അവരെ വിവാഹം കഴിപ്പിച്ചത് നബി(സ) പിൻവലിച്ചു. അവർ പിന്നെ അബൂലബാബുബ്നു അബ്ദിൽ മുൻദിറിനെ വിവാഹം കഴിച്ചു. യഹ്യ പറയുന്നു: അവർ കന്യകയായിരുന്നില്ല. (ബു,ദ,ന,ജ)', 'عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ', 'അബ്ദുർറഹ്മാനുബ്നു യസീദ്(റ)', null, null, array['خ','د','ن','جه']::text[], array['ബു','ദ','ന','ജ']::text[], null, null, 74, 74, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 104, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ فَتَاةً دَخَلَتْ عَلَيْهَا فَقَالَتْ: إِنَّ أَبِي زَوَّجَنِي ابْنَ أَخِيهِ لِيَرْفَعَ بِي خَسِيسَتَهُ، وَأَنَا كَارِهَةٌ. قَالَتْ: اجْلِسِي حَتَّى يَأْتِيَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَجَاءَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرْتُهُ، فَأَرْسَلَ إِلَى أَبِيهَا فَدَعَاهُ، فَجَعَلَ الْأَمْرَ إِلَيْهَا. فَقَالَتْ: يَا رَسُولَ اللهِ، قَدْ أَجَزْتُ مَا صَنَعَ أَبِي، وَلَكِنْ أَرَدْتُ أَنْ أَعْلَمَ: أَلِلنِّسَاءِ مِنَ الْأَمْرِ شَيْءٌ. (ن,جه)', 'ആഇശ(റ): ഒരു യുവതി അവരുടെ അടുത്ത് വന്ന് കൊണ്ട് പറഞ്ഞു: എന്റെ പിതാവ് തന്റെ നില ഉയർത്താൻ വേണ്ടി പിതാവിന്റെ സഹോദരപുത്രനെ എനിക്ക് വിവാഹം കഴിപ്പിച്ച് തന്നു. എനിക്ക് ഇഷ്ടമുണ്ടായിരുന്നില്ല. ആഇശ(റ) പറഞ്ഞു. നബി(സ) വരുന്നത് വരെ, നിങ്ങളിരിക്കുക. അങ്ങനെ റസൂൽ(സ) വന്നു. അവിടത്തോട് അവൾ വിഷയം ധരിപ്പിച്ചു. റസൂൽ(സ) അവളുടെ പിതാവിനെ ആളെ അയച്ചുവരുത്തി. അവിടന്ന് തീരുമാനം മകൾക്ക് വിട്ടുകൊടുത്തു. അപ്പോൾ മകൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, എന്റെ പിതാവ് ചെയ്തത് ഞാൻ സമ്മതിച്ചിരിക്കുന്നു. എങ്കിലും വിവാഹ തീരുമാനത്തിൽ സ്ത്രീക്ക് ഒരു പങ്കുമില്ലേയെന്ന് ഞാൻ അറിയാനാഗ്രഹിച്ചു. (ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 74, 74, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 105, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَيُّمَا عَبْدٍ تَزَوَّجَ بِغَيْرِ إِذْنِ سَيِّدِهِ فَهُوَ عَاهِرٌ". حَسَنٌ صَحِيحٌ. (د,ت,جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): നബി(സ) പറഞ്ഞു: "തന്റെ യജമാനന്റെ സമ്മതമില്ലാതെ വിവാഹം ചെയ്തവൻ വ്യഭിചാരിയാണ്." (ദ,തു,ജ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 74, 75, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 106, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا نَكَحَ الْعَبْدُ بِغَيْرِ إِذْنِ مَوْلَاهُ فَنِكَاحُهُ بَاطِلٌ". قَالَ أبو داود: هَذَا الْحَدِيثُ ضَعِيفٌ، وَهُوَ مَوْقُوفٌ، وَهُوَ قَوْلُ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا. (د)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "അടിമ തന്റെ യജമാനന്റെ അനുവാദമില്ലാതെ വിവാഹം ചെയ്താൽ, ആ വിവാഹം അസാധുവാണ്." അബൂ ദാവൂദ്(റ) പറയുന്നു: ഈ ഹദീസ് ബലഹീനമാണ്, അത് മൗഖൂഫാണ്. അത് ഇബ്നു ഉമർ(റ)വിന്റെ വാക്കാണ്. (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 75, 75, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 107, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ كَانَتْ لَهُ جَارِيَةٌ: فَأَدَّبَهَا فَأَحْسَنَ أَدَبَهَا، وَعَلَّمَهَا فَأَحْسَنَ تَعْلِيمَهَا، ثُمَّ أَعْتَقَهَا وَتَزَوَّجَهَا، فَلَهُ أَجْرَانِ. وَأَيُّمَا رَجُلٍ مِنْ أَهْلِ الْكِتَابِ آمَنَ بِنَبِيِّهِ وَآمَنَ بِمُحَمَّدٍ، فَلَهُ أَجْرَانِ. وَأَيُّمَا عَبْدٍ مَمْلُوكٍ أَدَّى حَقَّ اللهِ عَلَيْهِ وَحَقَّ مَوَالِيهِ، فَلَهُ أَجْرَانِ". (ق,ت,ن,جه)', 'അബൂമൂസ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾക്ക് ഒരടിമസ്ത്രീയുണ്ടായിട്ട് അവളെ നന്നായി മര്യാദ പഠിപ്പിക്കുകയും നല്ല നിലയിൽ വിദ്യ നൽകുകയും പിന്നെ അവളെ മോചിപ്പിച്ച് വിവാഹം കഴിക്കുകയും ചെയ്താൽ, അവന് രണ്ട് പ്രതിഫലമുണ്ട്. വേദക്കാരിൽ പെട്ട ഒരാൾ തന്റെ പ്രവാചകനിലും മുഹമ്മദ്(സ)യിലും വിശ്വസിച്ചാൽ, അവനും രണ്ട് പ്രതിഫലമുണ്ട്. ഒരടിമ അല്ലാഹുവിനുള്ള തന്റെ കടമയും തന്റെ ഉടമകളോടുള്ള തന്റെ കടമയും നിർവ്വഹിച്ചാൽ അവനും രണ്ട് പ്രതിഫലമുണ്ട്. (ബു,മു,തു,ന,ജ)', 'أَبِي مُوسَى', 'അബൂമൂസ(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 75, 75, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 108, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: صَارَتْ صَفِيَّةُ لِدِحْيَةَ الْكَلْبِيِّ، ثُمَّ صَارَتْ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَعْدُ، فَتَزَوَّجَهَا وَجَعَلَ عِتْقَهَا صَدَاقَهَا. (ق,د,ن,جه)', 'അനസ്(റ): സ്വഫിയ്യ(റ) ദിഹ്യതുൽ കൽബി(റ)വിന്റെ അടിമയായിരുന്നു. ശേഷം റസൂൽ(സ) അവരെ വിവാഹം കഴിക്കുകയും ചെയ്തു. അവളെ മോചിപ്പിച്ചത് അവൾക്കുള്ള മഹ്റാക്കി നിശ്ചയിച്ചു. (ബു,മു,ദ,ന,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 75, 75, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 109, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ غَزَا خَيْبَرَ، قَالَ: فَصَلَّيْنَا عِنْدَهَا صَلَاةَ الْغَدَاةِ بِغَلَسٍ، فَرَكِبَ نَبِيُّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَرَكِبَ أَبُو طَلْحَةَ، وَأَنَا رَدِيفُ أَبِي طَلْحَةَ، فَأَجْرَى نَبِيُّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي زُقَاقِ خَيْبَرَ، وَإِنَّ رُكْبَتِي لَتَمَسُّ فَخِذَ نَبِيِّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَانْحَسَرَ الْإِزَارُ عَنْ فَخِذِ نَبِيِّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَإِنِّي لَأَرَى بَيَاضَ فَخِذِ نَبِيِّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا دَخَلَ الْقَرْيَةَ قَالَ: "اللهُ أَكْبَرُ، خَرِبَتْ خَيْبَرُ، إِنَّا إِذَا نَزَلْنَا بِسَاحَةِ قَوْمٍ فَسَاءَ صَبَاحُ الْمُنْذَرِينَ". قَالَهَا ثَلَاثَ مَرَّاتٍ، قَالَ: وَقَدْ خَرَجَ الْقَوْمُ إِلَى أَعْمَالِهِمْ، فَقَالُوا: مُحَمَّدٌ [وَاللهِ]! – قَالَ عَبْدُ الْعَزِيزِ: وَقَالَ بَعْضُ أَصْحَابِنَا: مُحَمَّدٌ وَالْخَمِيسُ –. قَالَ: وَأَصَبْنَاهَا عَنْوَةً، وَجُمِعَ السَّبْيُ، فَجَاءَهُ دِحْيَةُ فَقَالَ: يَا رَسُولَ اللهِ، أَعْطِنِي جَارِيَةً مِنَ السَّبْيِ؟ فَقَالَ: "اذْهَبْ فَخُذْ جَارِيَةً". فَأَخَذَ صَفِيَّةَ بِنْتَ حُيَيٍّ، فَجَاءَ رَجُلٌ إِلَى نَبِيِّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: يَا نَبِيَّ اللهِ، أَعْطَيْتَ دِحْيَةَ صَفِيَّةَ بِنْتَ حُيَيٍّ سَيِّدِ قُرَيْظَةَ وَالنَّضِيرِ مَا تَصْلُحُ إِلَّا لَكَ. قَالَ: "ادْعُوهُ بِهَا". قَالَ: فَجَاءَ بِهَا، فَلَمَّا نَظَرَ إِلَيْهَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "خُذْ جَارِيَةً مِنَ السَّبْيِ غَيْرَهَا". قَالَ: وَأَعْتَقَهَا وَتَزَوَّجَهَا. فَقَالَ لَهُ ثَابِتٌ: يَا أَبَا حَمْزَةَ، مَا أَصْدَقَهَا؟ قَالَ: نَفْسَهَا، أَعْتَقَهَا وَتَزَوَّجَهَا، حَتَّى إِذَا كَانَ بِالطَّرِيقِ جَهَّزَتْهَا لَهُ أُمُّ سُلَيْمٍ، فَأَهْدَتْهَا لَهُ مِنَ اللَّيْلِ، فَأَصْبَحَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَرُوسًا، فَقَالَ: "مَنْ كَانَ عِنْدَهُ شَيْءٌ فَلْيَجِئْ بِهِ". قَالَ: وَبَسَطَ نِطَعًا، قَالَ: فَجَعَلَ الرَّجُلُ يَجِيءُ بِالْأَقِطِ، وَجَعَلَ الرَّجُلُ يَجِيءُ بِالتَّمْرِ، وَجَعَلَ الرَّجُلُ يَجِيءُ بِالسَّمْنِ، فَحَاسُوا حَيْسًا، فَكَانَتْ وَلِيمَةَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (م)', 'അനസ്(റ): റസൂൽ(സ) ഖൈബറിനോട് യുദ്ധം ചെയ്തു. ഇരുട്ടിൽ ഖൈബറിന്റെ അടുത്ത് വെച്ച് ഞങ്ങൾ സുബ്ഹി നമസ്കരിച്ചു. അല്ലാഹുവിന്റെ പ്രവാചകൻ(സ)യും അബൂത്വൽഹ(റ)യും വാഹനപ്പുറത്ത് കയറി. ഞാൻ അബൂത്വൽഹ(റ)വിന്റെ പിറകിലാണ് യാത്ര ചെയ്തത്. അനന്തരം നബി(സ) ഖൈബറിലെ തെരുവീഥികളിലൂടെ വാഹനമോടിച്ചു. എന്റെ കാൽമുട്ട് നബി(സ)യുടെ തുടയിൽ തട്ടുന്നുണ്ട്. നബി(സ)യുടെ തുണി നീങ്ങി അവിടത്തെ തുട അൽപം വെളിവായി. നബി(സ)യുടെ തുടയുടെ വെളുപ്പ് നിറം ഞാൻ കാണുന്നു. ഗ്രാമത്തിൽ പ്രവേശിച്ചപ്പോൾ നബി(സ) പറഞ്ഞു: "അല്ലാഹു അക്ബറാണ് ഖൈബർ നശിച്ചിരിക്കുന്നു. നാമൊരു സമൂഹത്തിന്റെ മുറ്റത്തിറങ്ങിയാൽ താക്കീത് നൽകപ്പെടുന്നവരുടെ പ്രഭാതം എത്രമോശമാണ്." അവിടന്നത് മൂന്ന് പ്രാവശ്യം പറഞ്ഞു. ജനങ്ങൾ അവരുടെ ജോലികളിലേക്ക് പുറപ്പെട്ടു. അവർ പറഞ്ഞു. മുഹമ്മദാണത്, അല്ലാഹു തന്നെ സത്യം. അബ്ദുൽ അസീസ്(റ) പറയുന്നു: ചിലരുടെ നിവേദനം അനുസരിച്ച് മുഹമ്മദും സൈന്യവുമിതാ വന്നിരിക്കുന്നു എന്നാണവർ പറഞ്ഞത്. നിവേദകൻ പറയുന്നു: അങ്ങനെ ഖൈബർ ഞങ്ങൾ ശക്തി ഉപയോഗിച്ച് കീഴ്പ്പെടുത്തി. തടവുകാരെയെല്ലാം ഒരു സ്ഥലത്ത് ഒരുമിച്ച് കൂട്ടുകയും ചെയ്തു. അദ്ദേഹം ദിഹ്യ(റ) തിരുമേനി(സ)യുടെ അടുത്ത് വന്ന് കൊണ്ട് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, തടവുകാരിൽ നിന്ന് ഒരു പെൺകുട്ടിയെ എനിക്ക് തന്നാൽ കൊള്ളാമായിരുന്നു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നീ പോയി ഒരു പെൺകുട്ടിയെ എടുത്ത് കൊള്ളുക." ഉടനെ അദ്ദേഹം ചെന്ന് ഹുയയ്യിന്റെ മകൾ സ്വഫിയ്യ(റ)യെ എടുത്തു. അന്നേരം ഒരു മനുഷ്യൻ നബി(സ)യുടെ അടുത്ത് ചെന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഖുറൈദ, നദീർ എന്നീ ഗോത്രക്കാരുടെ നേതാവായ ഹുയയ്യിന്റെ മകൾ സ്വഫിയ്യയെ അങ്ങ് ദിഹ്യതിനു നൽകിയിരിക്കുന്നു. അവൾ അങ്ങേക്ക് മാത്രമേ യോജിക്കുകയുള്ളൂ. തിരുമേനി(സ) പറഞ്ഞു: "അവനോട് അവളെ കൊണ്ടുവരാൻ പറയുക." ഉടനെ അവനവളെ കൊണ്ടുവന്നു. അവളെ കണ്ടപ്പോൾ അവിടന്ന് പറഞ്ഞു: "നീ തടവുകാരിൽ നിന്നു വേറെ ഒരു പെൺകുട്ടിയെ എടുത്തു കൊള്ളുക." നിവേദകൻ പറയുന്നു: നബി(സ) അവരെ മോചിപ്പിക്കുകയും വിവാഹം കഴിക്കുകയും ചെയ്തു. സാബിത്(റ) അനസ്(റ)വിനോട് ചോദിച്ചു: ഓ അബൂഹംസാ, എന്താണ് സ്വഫിയ്യ(റ)ക്ക് നബി(സ) മഹ്റ് കൊടുത്തത്? അദ്ദേഹം പറഞ്ഞു: മഹതിയുടെ ശരീരം. അതായത് തിരുമേനി(സ) അവരെ മോചിപ്പിക്കുകയും ശേഷം വിവാഹം കഴിക്കുകയും ചെയ്തു. അനന്തരം വഴിയിൽ വെച്ച് ഉമ്മുസുലൈം(റ) സ്വഫിയ്യ(റ)യെ ഒരുക്കുകയും രാത്രി അവരെ തിരുമേനി(സ)യുടെ അടുക്കലേക്ക് ആനയിക്കുകയും അങ്ങനെ തിരുമേനി(സ) മധുവിധു ആഘോഷിക്കുകയും ചെയ്തു. പിന്നീട് ഒരു തോൽ നിലത്ത് വിരിച്ച് കൊണ്ട് നബി(സ) പറഞ്ഞു: "ആരുടെ പക്കലെങ്കിലും ഭക്ഷണസാധനം വല്ലതുമുണ്ടെങ്കിൽ അവനത് കൊണ്ടുവരിക." അപ്പോൾ ഒരാൾ പാൽകട്ടി കൊണ്ട് വന്നു. മറ്റൊരാൾ കാരക്കയും വേറൊരാൾ നെയ്യും കൊണ്ടുവന്നു. അവരത് മുഴുവൻ കൂട്ടിച്ചേർത്തു. അതായിരുന്നു റസൂൽ(സ)യുടെ വിവാഹ സദ്യ. (മു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م']::text[], array['മു']::text[], 'وَاللهِ', null, 75, 76, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 110, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "ثَلَاثَةٌ يُؤْتَوْنَ أَجْرَهُمْ مَرَّتَيْنِ: عَبْدٌ أَدَّى حَقَّ اللهِ وَحَقَّ مَوَالِيهِ، فَذَاكَ يُؤْتَى أَجْرَهُ مَرَّتَيْنِ. وَرَجُلٌ كَانَتْ عِنْدَهُ جَارِيَةٌ وَضِيئَةٌ، فَأَدَّبَهَا فَأَحْسَنَ أَدَبَهَا، ثُمَّ أَعْتَقَهَا ثُمَّ تَزَوَّجَهَا، يَبْتَغِي بِذَلِكَ وَجْهَ اللهِ، فَذَلِكَ يُؤْتَى أَجْرَهُ مَرَّتَيْنِ. وَرَجُلٌ آمَنَ بِالْكِتَابِ الْأَوَّلِ، ثُمَّ جَاءَ الْكِتَابُ الْآخَرُ فَآمَنَ بِهِ، فَذَلِكَ يُؤْتَى أَجْرَهُ مَرَّتَيْنِ". حَسَنٌ صَحِيحٌ. (ق,ت,ن,جه)', 'അബൂമൂസൽ അശ്അരി(റ): മൂന്നാളുകൾക്ക് രണ്ട് പ്രാവശ്യം കൂലി നൽകപ്പെടും. അല്ലാഹുവിന്റെയും തന്റെ യജമാനന്റെയും കടപ്പാട് നിറവേറ്റിയ അടിമ. ഇവന് രണ്ട് പ്രാവശ്യം പ്രതിഫലം നൽകപ്പെടും. മറ്റൊരാൾ തന്റെയടുത്തുള്ള അടിമസ്ത്രീക്ക് അല്ലാഹുവിന്റെ നല്ല പ്രീതി ആഗ്രഹിച്ച് മര്യാദ പഠിപ്പിക്കുകയും അവളെ മോചിപ്പിക്കുകയും എന്നിട്ട് അവളെ വിവാഹം കഴിക്കുകയും ചെയ്തവനാണ്. ഇവനും രണ്ട് പ്രാവശ്യം പ്രതിഫലം നൽകപ്പെടും. വേറൊരാൾ, ആദ്യത്തെ വേദഗ്രന്ഥത്തിൽ വിശ്വസിക്കുകയും രണ്ടാമത്തെ വേദഗ്രന്ഥം വന്നപ്പോൾ അതിലും വിശ്വസിക്കുകയും ചെയ്തവനാണ്. അവനും രണ്ട് പ്രാവശ്യം പ്രതിഫലം നൽകപ്പെടും." (ബു,മു,തു,ന,ജ)', 'أَبِي مُوسَى', 'അബൂമൂസൽ അശ്അരി(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 76, 77, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 111, 'عَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الرَّجُلِ يَأْتِي جَارِيَةَ امْرَأَتِهِ، قَالَ: "إِنْ كَانَتْ أَحَلَّتْهَا لَهُ جَلَدْتُهُ مِائَةً، وَإِنْ لَمْ تَكُنْ أَحَلَّتْهَا لَهُ رَجَمْتُهُ". وفي رواية: أَنَّ رَجُلًا يُقَالُ لَهُ عَبْدُالرَّحْمَنِ بْنِ حُنَيْنٍ، وَيُنْبَزُ قُرْقُورًا: أَنَّهُ وَقَعَ بِجَارِيَةِ امْرَأَتِهِ، فَرُفِعَ إِلَى النُّعْمَانِ بْنِ بَشِيرٍ، فَقَالَ: لَأَقْضِيَنَّ فِيهَا بِقَضِيَّةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: إِنْ كَانَتْ أَحَلَّتْهَا لَكَ جَلَدْتُكَ، وَإِنْ لَمْ تَكُنْ أَحَلَّتْهَا لَكَ رَجَمْتُكَ بِالْحِجَارَةِ. فَكَانَتْ أَحَلَّتْهَا لَهُ فَجَلَدَ مِائَةً. (ت,ن)', 'നുഅ്മാനുബ്നു ബഷീർ(റ): തന്റെ ഭാര്യയുടെ അടിമസ്ത്രീയുടെ അടുത്ത് ചെല്ലുന്നവനെക്കുറിച്ച് നബി(സ) പറയുന്നു: "അടിമസ്ത്രീ അവന് സമ്മതം നൽകിയെങ്കിൽ താൻ അവനെ നൂറടി അടിക്കും. അവൾ അവന് സമ്മതം നൽകിയിട്ടില്ലെങ്കിൽ അവനെ എറിഞ്ഞ് കൊല്ലും." മറ്റൊരു നിവേദനം: അബ്ദുർറഹ്മാനുബ്നു ഹുനൈൻ(റ): അദ്ദേഹത്തിന് ഖുർഖൂറെന്ന് ഓമനപ്പേരുണ്ട്. അദ്ദേഹം തന്റെ ഭാര്യയുടെ അടിമസ്ത്രീയുമായി വേഴ്ചയിലേർപ്പെട്ടു. വിഷയം അദ്ദേഹം നുഅ്മാനുബ്നു ബഷീർ(റ)വിലേക്കെത്തിച്ചു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അവളിൽ ഞാൻ റസൂൽ(സ)യുടെ വിധി നടപ്പിലാക്കും. അവൾ നിനക്ക് സമ്മതം നൽകിയതാണെങ്കിൽ ഞാൻ നിന്നെ അടിക്കും. അവൾ നിനക്ക് സമ്മതം തന്നിട്ടില്ലെങ്കിൽ ഞാൻ നിന്നെ കല്ലെറിയും. അവൾ അവന് സമ്മതം നൽകിയിരുന്നു. അത് കാരണം അയാളെ നൂറടി അടിച്ചു. (തു,ന)', 'النُّعْمَانِ بْنِ بَشِيرٍ', 'നുഅ്മാനുബ്നു ബഷീർ(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 77, 77, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=2 and h.hadith_no=111), 1, 'وَفِي رِوَايَةٍ: أَنَّ رَجُلًا يُقَالُ لَهُ عَبْدُالرَّحْمَنِ بْنِ حُنَيْنٍ، وَيُنْبَزُ قُرْقُورًا: أَنَّهُ وَقَعَ بِجَارِيَةِ امْرَأَتِهِ، فَرُفِعَ إِلَى النُّعْمَانِ بْنِ بَشِيرٍ، فَقَالَ: لَأَقْضِيَنَّ فِيهَا بِقَضِيَّةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: إِنْ كَانَتْ أَحَلَّتْهَا لَكَ جَلَدْتُكَ، وَإِنْ لَمْ تَكُنْ أَحَلَّتْهَا لَكَ رَجَمْتُكَ بِالْحِجَارَةِ. فَكَانَتْ أَحَلَّتْهَا لَهُ فَجَلَدَ مِائَةً. (ت,ن)', 'മറ്റൊരു നിവേദനം: അബ്ദുർറഹ്മാനുബ്നു ഹുനൈൻ(റ): അദ്ദേഹത്തിന് ഖുർഖൂറെന്ന് ഓമനപ്പേരുണ്ട്. അദ്ദേഹം തന്റെ ഭാര്യയുടെ അടിമസ്ത്രീയുമായി വേഴ്ചയിലേർപ്പെട്ടു. വിഷയം അദ്ദേഹം നുഅ്മാനുബ്നു ബഷീർ(റ)വിലേക്കെത്തിച്ചു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അവളിൽ ഞാൻ റസൂൽ(സ)യുടെ വിധി നടപ്പിലാക്കും. അവൾ നിനക്ക് സമ്മതം നൽകിയതാണെങ്കിൽ ഞാൻ നിന്നെ അടിക്കും. അവൾ നിനക്ക് സമ്മതം തന്നിട്ടില്ലെങ്കിൽ ഞാൻ നിന്നെ കല്ലെറിയും. അവൾ അവന് സമ്മതം നൽകിയിരുന്നു. അത് കാരണം അയാളെ നൂറടി അടിച്ചു. (തു,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 112, 'عَنْ سَلَمَةَ بْنِ الْمُحَبِّقِ رَضِيَ اللهُ عَنْهُ قَالَ: قَضَى النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي رَجُلٍ وَطِئَ جَارِيَةَ امْرَأَتِهِ: "إِنْ كَانَ اسْتَكْرَهَهَا فَهِيَ حُرَّةٌ، وَعَلَيْهِ لِسَيِّدَتِهَا مِثْلُهَا، وَإِنْ كَانَتْ طَاوَعَتْهُ فَهِيَ لَهُ، وَعَلَيْهِ لِسَيِّدَتِهَا مِثْلُهَا". وفي رواية: أَنَّ رَجُلًا غَشِيَ جَارِيَةً لامْرَأَتِهِ فَرُفِعَ ذَلِكَ إِلَى رَسُولِ اللهِ فَقَالَ: "إِنْ كَانَ اسْتَكْرَهَهَا فَهِيَ حُرَّةٌ مِنْ مَالِهِ، وَعَلَيْهِ الشَّرْوَى لِسَيِّدَتِهَا. وَإِنْ كَانَتْ طَاوَعَتْهُ فَهِيَ لِسَيِّدَتِهَا، وَمِثْلُهَا مِنْ مَالِهِ". (ن)', 'സലമതുബ്നുൽ മുഹബ്ബഖ്(റ): തന്റെ ഭാര്യയുടെ അടിമസ്ത്രീയുമായി ബന്ധപ്പെട്ടയാളിൽ നബി(സ)യുടെ വിധി ഇതാണ്. അവൻ അവളെ ബലാൽക്കാരമായി ചെയ്തതാണെങ്കിൽ, അവൾ സ്വതന്ത്രയാണ്. അവൻ യജമാനസ്ത്രീക്ക് (ഭാര്യക്ക്) അവളെപ്പോലോത്ത ഒരു അടിമസ്ത്രീയെ നൽകണം. അവൾ അവന് സമ്മതം നൽകിയിട്ടുണ്ടെങ്കിൽ അടിമസ്ത്രീ അവന്റെയായി മാറും. അവളെപ്പോലോത്ത ഒരു അടിമസ്ത്രീയെ യജമാനസ്ത്രീക്ക് (ഭാര്യക്ക്) അവൻ നൽകണം. മറ്റൊരു നിവേദനം: ഒരാൾ തന്റെ ഭാര്യയുടെ അടിമസ്ത്രീയുമായി ബന്ധപ്പെട്ടു. ഇത് റസൂൽ(സ)യുടെ അടുത്തെത്തി. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "അവൻ അവളെ ബലാൽസംഗം ചെയ്തതാണെങ്കിൽ തന്റെ സ്വത്ത് കൊണ്ട് അവൾ സ്വതന്ത്രയാണ്. (അവളെ മോചിപ്പിക്കണം.) അവളുടെ വില യജമാനസ്ത്രീക്ക് നൽകാൻ അവൻ ബാധ്യസ്ഥനാണ്. അവൾ അവന് സമ്മതം നൽകിയെങ്കിൽ അവൾ തന്റെ യജമാനസ്ത്രീക്ക് തന്നെയാണ്. അവളെപ്പോലോത്ത അടിമസ്ത്രീയെ തന്റെ സമ്പത്തിൽ നിന്ന് അവൻ നൽകുകയും വേണം." (ന)', 'سَلَمَةَ بْنِ الْمُحَبِّقِ', 'സലമതുബ്നുൽ മുഹബ്ബഖ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 77, 77, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=2 and h.hadith_no=112), 1, 'وَفِي رِوَايَةٍ: أَنَّ رَجُلًا غَشِيَ جَارِيَةً لامْرَأَتِهِ فَرُفِعَ ذَلِكَ إِلَى رَسُولِ اللهِ فَقَالَ: "إِنْ كَانَ اسْتَكْرَهَهَا فَهِيَ حُرَّةٌ مِنْ مَالِهِ، وَعَلَيْهِ الشَّرْوَى لِسَيِّدَتِهَا. وَإِنْ كَانَتْ طَاوَعَتْهُ فَهِيَ لِسَيِّدَتِهَا، وَمِثْلُهَا مِنْ مَالِهِ". (ن)', 'മറ്റൊരു നിവേദനം: ഒരാൾ തന്റെ ഭാര്യയുടെ അടിമസ്ത്രീയുമായി ബന്ധപ്പെട്ടു. ഇത് റസൂൽ(സ)യുടെ അടുത്തെത്തി. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "അവൻ അവളെ ബലാൽസംഗം ചെയ്തതാണെങ്കിൽ തന്റെ സ്വത്ത് കൊണ്ട് അവൾ സ്വതന്ത്രയാണ്. (അവളെ മോചിപ്പിക്കണം.) അവളുടെ വില യജമാനസ്ത്രീക്ക് നൽകാൻ അവൻ ബാധ്യസ്ഥനാണ്. അവൾ അവന് സമ്മതം നൽകിയെങ്കിൽ അവൾ തന്റെ യജമാനസ്ത്രീക്ക് തന്നെയാണ്. അവളെപ്പോലോത്ത അടിമസ്ത്രീയെ തന്റെ സമ്പത്തിൽ നിന്ന് അവൻ നൽകുകയും വേണം." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 113, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا جَلَبَ وَلَا جَنَبَ وَلَا شِغَارَ فِي الْإِسْلَامِ، وَمَنِ انْتَهَبَ نُهْبَةً فَلَيْسَ مِنَّا". (د,ت,ن)', 'ഇംറാനുബ്നു ഹുസ്വൈൻ(റ): റസൂൽ(സ) പറഞ്ഞു: കുതിര പന്തയത്തിൽ വേറെയൊരുത്തനെ വീഴ്ത്താൻ വേണ്ടി, തന്റെ കുതിരയെ അവന്റെ കുതിരക്ക് പിന്നാലെ ഓടിക്കലും, പന്തയത്തിൽ തന്നെ മുൻകടന്ന കുതിരയെ അകറ്റലും, രണ്ടുപേർ തങ്ങളുടെ മക്കളെ വിവാഹമൂല്യം നൽകാതെ, പരസ്പരം വിവാഹം കഴിച്ച് കൊടുക്കലും ഇസ്ലാമിൽ പെട്ടതല്ല. (ദ,തു,ന)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹുസ്വൈൻ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 78, 78, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 114, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الشِّغَارِ، وَالشِّغَارُ: أَنْ يُزَوِّجَ الرَّجُلُ الرَّجُلَ ابْنَتَهُ عَلَى أَنْ يُزَوِّجَهُ ابْنَتَهُ، وَلَيْسَ بَيْنَهُمَا صَدَاقٌ. (ق,د,ت,ن,جه)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) ശിഗാർ നിരോധിച്ചിരിക്കുന്നു. ശിഗാർ എന്നാൽ ഒരാൾ തന്റെ മകളെ വേറൊരാൾക്ക് അയാളുടെ മകളെ തനിക്ക് വിവാഹം ചെയ്ത് കൊടുക്കും എന്ന വ്യവസ്ഥയിൽ തന്റെ മകളെ വിവാഹമൂല്യമില്ലാതെ വിവാഹം ചെയ്തുകൊടുക്കുക. (ബു,മു,ദ,തു,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 78, 78, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 115, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ هُرْمُزٍ الْأَعْرَجِ: أَنَّ الْعَبَّاسَ بْنَ عَبْدِ اللهِ بْنِ الْعَبَّاسِ أَنْكَحَ عَبْدَ الرَّحْمَنِ بْنَ الْحَكَمِ ابْنَتَهُ، وَأَنْكَحَهُ عَبْدُ الرَّحْمَنِ ابْنَتَهُ، وَكَانَا جَعَلَا صَدَاقًا، فَكَتَبَ مُعَاوِيَةُ إِلَى مَرْوَانَ يَأْمُرُهُ بِالتَّفْرِيقِ بَيْنَهُمَا، وَقَالَ فِي كِتَابِهِ: هَذَا الشِّغَارُ الَّذِي نَهَى عَنْهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (د)', 'അബ്ദുർറഹ്മാനുബ്നു ഹുർമുസ്(റ): അബ്ബാസുബ്നു അബ്ദില്ലാഹിബ്നിൽ അബ്ബാസ്(റ) അബ്ദുർറഹ്മാനുബ്നുൽ ഹകമിന് തന്റെ മകളെ വിവാഹം ചെയ്ത് കൊടുത്തു. അദ്ദേഹത്തിന് അബ്ദുർറഹ്മാൻ തന്റെ മകളെയും വിവാഹം ചെയ്ത് കൊടുത്തു. അതവർ വിവാഹമൂല്യമാക്കി പരിഗണിച്ചു. അപ്പോൾ മുആവിയ(റ) അവരെ വേർപിരിക്കാൻ ആവശ്യപ്പട്ടുകൊണ്ട് മർവാന് ഒരു കത്തെഴുതി. അദ്ദേഹം തന്റെ കത്തിൽ പറയുന്നു: ഈ ശിഗാർ റസൂൽ(സ) നിരോധിച്ചതാണ്. (ദ)', 'عَبْدِ الرَّحْمَنِ بْنِ هُرْمُزٍ الْأَعْرَجِ', 'അബ്ദുർറഹ്മാനുബ്നു ഹുർമുസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 78, 78, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 116, 'عَنْ [قَيْسٍ قَالَ: سَمِعْتُ] عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا نَغْزُو مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَيْسَ لَنَا نِسَاءٌ، فَقُلْنَا: أَلَا نَسْتَخْصِي؟ فَنَهَانَا عَنْ ذَلِكَ، ثُمَّ رَخَّصَ لَنَا أَنْ نَنْكِحَ الْمَرْأَةَ بِالثَّوْبِ إِلَى أَجَلٍ، ثُمَّ قَرَأَ عَبْدُ اللهِ: {يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تُحَرِّمُوا طَيِّبَاتِ مَا أَحَلَّ اللهُ لَكُمْ وَلَا تَعْتَدُوا إِنَّ اللهَ لَا يُحِبُّ الْمُعْتَدِينَ} [المائدة: ٨٧]. (م)', 'ഖൈസ്(റ): ഞാൻ അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ) പറയുന്നത് കേട്ടു: ഞങ്ങൾ റസൂൽ(സ)യുടെ കൂടെ യുദ്ധം ചെയ്യുകയായിരുന്നു. ഞങ്ങളുടെ കൂടെ ഭാര്യമാരുണ്ടായിരുന്നില്ല. ഞങ്ങൾ ചോദിച്ചു: ഞങ്ങൾ വന്ധീകരണം നടത്തട്ടെയോ? അപ്രകാരം ചെയ്യുന്നത് റസൂൽ(സ) തടഞ്ഞു. പിന്നെ അവിടന്ന് ഞങ്ങൾക്ക് നിശ്ചിത അവധി വരെ, വസ്ത്രം നൽകി സ്ത്രീയെ വിവാഹം കഴിക്കാൻ അനുമതി തന്നു. ഇത് പറഞ്ഞ ശേഷം ''ഓ സത്യവിശ്വാസികളേ, അല്ലാഹു നിങ്ങൾക്ക് അനുവദിച്ച നല്ല വസ്തുക്കളെ നിങ്ങൾ നിങ്ങൾക്ക് നിഷിദ്ധമാക്കരുത്. നിങ്ങൾ അതിരുകടക്കുകയുമരുത്, അതിരുകടക്കുന്നവരെ അല്ലാഹു ഇഷ്ടപ്പെടുന്നില്ല.'' (അൽ മാഇദ:87) എന്ന ഖുർആൻ വാക്യം അബ്ദുല്ല(റ) ഓതിക്കേൾപ്പിച്ചു. (മു)', '[قَيْسٍ قَالَ', 'ഖൈസ്(റ)', null, null, array['م']::text[], array['മു']::text[], 'المائدة: ٨٧', null, 78, 79, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 117, 'عَنْ جَابِرِ بْنِ عَبْدِاللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: كُنَّا نَسْتَمْتِعُ بِالْقَبْضَةِ مِنَ التَّمْرِ وَالدَّقِيقِ الْأَيَّامَ، عَلَى عَهْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَبِي بَكْرٍ رَضِيَ اللهُ عَنْهُ، حَتَّى نَهَى عَنْهُ عُمَرُ رَضِيَ اللهُ عَنْهُ فِي شَأْنِ عَمْرِو بْنِ حُرَيْثٍ. (م)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ)യുടെ കാലത്തും അബൂബക്കർ(റ)വിന്റെ കാലത്തും ഞങ്ങൾ ഒരു പിടി കാരക്കയും ഗോതമ്പ് പൊടിയും നൽകിക്കൊണ്ട് നിശ്ചിതകാലത്തേക്ക് വിവാഹം കഴിച്ചിരുന്നു. പിന്നെ അംറുബ്നു ഹുനൈസ്(റ)വിന്റെ വിഷയത്തിൽ ഉമർ(റ) അത് നിരോധിച്ചു. (മു)', 'جَابِرِ بْنِ عَبْدِاللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 79, 79, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 118, 'عَنْ جَابِرِ بْنِ عَبْدِاللهِ وَسَلَمَةَ بْنِ الْأَكْوَعِ رَضِيَ اللهُ عَنْهُمْ قَالَا: كُنَّا فِي جَيْشٍ، فَأَتَانَا رَسُولُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "إِنَّهُ قَدْ أُذِنَ لَكُمْ أَنْ تَسْتَمْتِعُوا فَاسْتَمْتِعُوا". (خ)', 'ജാബിറുബ്നു അബ്ദില്ല(റ), സലമതുബ്നുൽ അക്വഅ്(റ): അവർ പറയുന്നു: ഞങ്ങൾ ഒരു യുദ്ധ സൈന്യത്തിലായിരുന്നു. അങ്ങനെ ഞങ്ങളുടെ അടുത്ത് റസൂൽ(സ) വന്നു. അവിടന്ന് പറഞ്ഞു: "നിങ്ങൾക്ക് അൽപ സമയത്തേക്കുള്ള വിവാഹത്തിന് അനുവാദം ലഭിച്ചിരിക്കുന്നു. അത് കൊണ്ട് നിങ്ങൾ അത് ചെയ്ത് കൊള്ളുക." (ബു)', 'جَابِرِ بْنِ عَبْدِاللهِ وَسَلَمَةَ بْنِ الْأَكْوَعِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 79, 79, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 119, 'عَنِ الرَّبِيعِ بْنِ سَبْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ أَبَاهُ غَزَا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَتْحَ مَكَّةَ، قَالَ: فَأَقَمْنَا بِهَا خَمْسَ عَشْرَةَ – ثَلَاثِينَ بَيْنَ لَيْلَةٍ وَيَوْمٍ – فَأَذِنَ لَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي مُتْعَةِ النِّسَاءِ، فَخَرَجْتُ أَنَا وَرَجُلٌ مِنْ قَوْمِي وَلِي عَلَيْهِ فَضْلٌ فِي الْجَمَالِ، وَهُوَ قَرِيبٌ مِنَ الدَّمَامَةِ، مَعَ كُلِّ وَاحِدٍ مِنَّا بُرْدٌ، فَبُرْدِي خَلَقٌ، وَأَمَّا بُرْدُ ابْنِ عَمِّي فَبُرْدٌ جَدِيدٌ غَضٌّ، حَتَّى إِذَا كُنَّا بِأَسْفَلِ مَكَّةَ – أَوْ: بِأَعْلَاهَا – فَتَلَقَّتْنَا فَتَاةٌ مِثْلُ الْبَكْرَةِ الْعَنَطْنَطَةِ، فَقُلْنَا [لَهَا] هَلْ لَكِ أَنْ يَسْتَمْتِعَ مِنْكِ أَحَدُنَا؟ قَالَتْ: وَمَاذَا تَبْذُلَانِ؟ فَنَشَرَ كُلُّ وَاحِدٍ مِنَّا بُرْدَهُ، فَجَعَلَتْ تَنْظُرُ إِلَى الرَّجُلَيْنِ وَيَرَاهَا صَاحِبِي تَنْظُرُ إِلَى عِطْفِهَا، فَقَالَ: إِنَّ بُرْدَ هَذَا خَلَقٌ وَبُرْدِي جَدِيدٌ غَضٌّ، فَتَقُولُ: بُرْدُ هَذَا لَا بَأْسَ بِهِ، ثَلَاثَ مِرَارٍ أَوْ مَرَّتَيْنِ، ثُمَّ اسْتَمْتَعْتُ مِنْهَا، فَلَمْ أَخْرُجْ حَتَّى حَرَّمَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (م,ن)', 'റബീഉബ്നു സബ്റ(റ): റസൂൽ(സ)യുടെ കൂടെ അദ്ദേഹം ഫത്ഹ്മക്കയിൽ യുദ്ധം ചെയ്തു. പിതാവ് പറയുന്നു: അവിടെ ഞങ്ങൾ പതിനഞ്ച് ദിവസം - രാവും പകലും കൂടി മുപ്പത് - ദിവസം താമസിച്ചു. അന്നേരം സ്ത്രീകളെ നിശ്ചിത ദിവസത്തേക്ക് മാത്രമായി വിവാഹം ചെയ്യുവാൻ നബി(സ) ഞങ്ങൾക്ക് അനുമതി നൽകി. അതനുസരിച്ച് ഞാനും ഞങ്ങളുടെ കൂട്ടത്തിൽ പെട്ട ഒരു മനുഷ്യനും പുറപ്പെട്ടു. ഞാനവനെക്കാൾ സുന്ദരനാണ്. അദ്ദേഹം എറെക്കുറെ വിരൂപനാണ്. ഞങ്ങൾ ഇരുവരുടെയും വശം ഒരു പുതപ്പുണ്ട്. എന്റെ പുതപ്പ് നുരുമ്പിയതും പഴയതുമാണ്. എന്റെ പിതൃവ്യപുത്രനായ കൂട്ടുകാരന്റെ പുതപ്പ് പുതിയതും മിനുസമുള്ളതുമാണ്. അങ്ങനെ ഞങ്ങൾ മക്കയുടെ താഴ്ഭാഗത്ത്, - അല്ലെങ്കിൽ മുകൾ ഭാഗത്ത് - നിൽക്കുമ്പോൾ ലക്ഷണമൊത്ത സുന്ദരിയായ ഒരു യുവതി ഞങ്ങളെ കണ്ടുമുട്ടി. ഉടനെ ഞങ്ങളിലൊരുവൻ നീയുമായി താൽക്കാലിക വിവാഹബന്ധം സ്ഥാപിക്കുന്നത് നിനക്ക് ഇഷ്ടമാണോ? അവൾ ചോദിച്ചു: നിങ്ങൾ എന്താണ് എനിക്കു വേണ്ടി ചെലവ് ചെയ്യുക? ഉടനെ ഞങ്ങളിൽ ഓരോരുത്തരും അവരവരുടെ പുതപ്പ് നിവർത്തിക്കാണിച്ചു കൊടുത്തു. അന്നേരം അവൾ രണ്ടാളുകളെയും നോക്കാൻ തുടങ്ങി. എന്റെ കൂട്ടുകാരൻ അവളുടെ എല്ലാ ഭാഗങ്ങളിലേക്കും നോക്കിക്കൊണ്ട് അവളെ ശരിക്കും കാണുകയും, എന്റെ കൂട്ടുകാരന്റെ പുതപ്പ് പഴയതാണ്. എന്റെ പുതപ്പ് പുതിയതും നല്ല മിനുസമുള്ളതാണ്, എന്നിങ്ങനെ പറയുകയും ചെയ്തു. അന്നേരം അവൾ എന്നെ ചൂണ്ടിക്കാണിച്ചു കൊണ്ട് ഇവന്റെ പുതപ്പിന് യാതൊരു തരക്കേടുമില്ല എന്ന് ആവർത്തിച്ച് പറയുകയും ചെയ്യുന്നുണ്ട്. ഞാൻ അവളുമായി താൽക്കാലിക ദാമ്പത്യബന്ധത്തിലേർപ്പെട്ടു. എന്നിട്ട് നബി(സ) ഈ വിവാഹം നിഷിദ്ധമാക്കുന്നതു വരെ ഞാനവളെ വിട്ടുപോന്നില്ല. (മു,ന)', 'الرَّبِيعِ بْنِ سَبْرَةَ', 'റബീഉബ്നു സബ്റ(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], 'لَهَا', null, 79, 79, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 120, 'عَنْ سَبْرَةَ الْجُهَنِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّهُ كَانَ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "يَا أَيُّهَا النَّاسُ، إِنِّي قَدْ كُنْتُ أَذِنْتُ لَكُمْ فِي الِاسْتِمْتَاعِ مِنَ النِّسَاءِ، وَإِنَّ اللهَ قَدْ حَرَّمَ ذَلِكَ إِلَى يَوْمِ الْقِيَامَةِ، فَمَنْ كَانَ عِنْدَهُ مِنْهُنَّ شَيْءٌ فَلْيُخَلِّ سَبِيلَهَا، وَلَا تَأْخُذُوا مِمَّا آتَيْتُمُوهُنَّ شَيْئًا". (م)', 'സബ്റത്തുൽ ജുഹനി(റ): അദ്ദേഹം റസൂൽ(സ)യുടെ കൂടെയായിരുന്നു. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "ഓ ജനങ്ങളേ, നിങ്ങൾക്ക് ഞാൻ സ്ത്രീകളെ അവധിവെച്ച് വിവാഹം കഴിക്കാൻ സമ്മതം നൽകിയിരുന്നു. അന്ത്യദിനം വരെ അല്ലാഹു അത് നിഷിദ്ധമാക്കിയിരിക്കുന്നു. നിങ്ങൾ ആരുടെയെങ്കിലും അടുത്ത് മുത്അ വിവാഹം ചെയ്ത് വല്ല ഭാര്യമാരുമുണ്ടെങ്കിൽ അവരെ ഒഴിവാക്കിക്കൊള്ളുക. നിങ്ങൾ അവർക്ക് നൽകിയതിൽ നിന്നൊന്നും തിരിച്ചു വാങ്ങരുത്. (മു)', 'سَبْرَةَ الْجُهَنِيِّ', 'സബ്റത്തുൽ ജുഹനി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 80, 80, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 121, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: إِنَّمَا كَانَتِ الْمُتْعَةُ فِي أَوَّلِ الْإِسْلَامِ، كَانَ الرَّجُلُ يَقْدَمُ الْبَلْدَةَ لَيْسَ لَهُ بِهَا مَعْرِفَةٌ، فَيَتَزَوَّجُ الْمَرْأَةَ بِقَدْرِ مَا يَرَى أَنَّهُ يُقِيمُ، فَتَحْفَظُ لَهُ مَتَاعَهُ وَتُصْلِحُ لَهُ شَيْئَهُ، حَتَّى إِذَا نَزَلَتِ الْآيَةُ: {إِلَّا عَلَى أَزْوَاجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَانُهُمْ} [المؤمنون: ٦] قَالَ ابْنُ عَبَّاسٍ: فَكُلُّ فَرْجٍ سِوَى هَذَيْنِ فَهُوَ حَرَامٌ. (ت)', 'ഇബ്നുഅബ്ബാസ്(റ): മുത്അ വിവാഹം ഇസ്ലാമിന്റെ ആദ്യകാലത്തായിരുന്നു. ഒരാൾ ഒരു പരിചയവുമില്ലാത്ത സ്ഥലത്ത് ചെന്നാൽ അവിടെ താമസിക്കുന്ന കാലം കൊണ്ട് വിവാഹം കഴിക്കുകയും അവൾ അവന്റെ സാധനങ്ങൾ സൂക്ഷിക്കുകയും അവന്റെ വസ്തുക്കളൊക്കെ ശരിയാക്കിക്കൊടുക്കുകയും ചെയ്യും. അങ്ങനെ ''അവരുടെ ഭാര്യമാരോ അടിമകളോ അല്ലാതെ'' (മുഅ്മിനൂൻ: 6) എന്ന സൂക്തമിറങ്ങി. ഇബ്നുഅബ്ബാസ്(റ) പറയുന്നു: ഇവർ രണ്ടു പേരോടുമല്ലാത്ത എല്ലാ ലൈംഗിക ബന്ധവും നിഷിദ്ധമാണ് എന്നർത്ഥം. (തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], 'المؤمنون: ٦', null, 80, 80, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 122, 'عَنِ الزُّهْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا عِنْدَ عُمَرَ بْنِ عَبْدِ الْعَزِيزِ، فَتَذَاكَرْنَا مُتْعَةَ النِّسَاءِ، فَقَالَ لَهُ رَجُلٌ يُقَالُ لَهُ رَبِيعُ بْنُ سَبْرَةَ: أَشْهَدُ عَلَى أَبِي أَنَّهُ حَدَّثَ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْهَا فِي حَجَّةِ الْوَدَاعِ. (م,د,ن,جه)', 'സുഹ്രി(റ): ഞങ്ങൾ ഉമറുബ്നു അബ്ദിൽ അസീസ്(റ)വിന്റെ കൂടെയായിരുന്നു. അപ്പോൾ ഞങ്ങൾ സ്ത്രീകളെ മുത്അ വിവാഹം ചെയ്യുന്നതിനെക്കുറിച്ച് സംസാരിച്ചു. അപ്പോൾ റബീഉബ്നു സബ്റ എന്ന് പേരുള്ള ഒരാൾ പറഞ്ഞു: റസൂൽ(സ) ഹജ്ജത്തുൽ വിദാഇൽ അത് നിരോധിച്ചെന്ന് എന്റെ പിതാവ് പറഞ്ഞു എന്നതിന് ഞാൻ സാക്ഷി നിൽക്കുന്നു. (മു,ദ,ന,ജ)', 'الزُّهْرِيِّ', 'സുഹ്രി(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 80, 80, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 123, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ: بَلَغَهُ أَنَّ رَجُلًا لَا يَرَى بِالْمُتْعَةِ بَأْسًا، فَقَالَ: إِنَّكَ تَائِهٌ، إِنَّهُ نَهَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْهَا وَعَنْ لُحُومِ الْحُمُرِ الْأَهْلِيَّةِ يَوْمَ خَيْبَرَ. (ن)', 'അലി(റ): മുത്അ വിവാഹത്തിലൊരു പ്രശ്നമില്ലെന്ന് വിശ്വസിക്കുന്ന ഒരാളെക്കുറിച്ച് അലി(റ) അറിഞ്ഞു. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: നീ കൊതിയുള്ളവനാണ്. അത് റസൂൽ(സ) നിരോധിച്ചിട്ടുണ്ട്. സ്ത്രീകളെ മുത്അ വിവാഹം ചെയ്യുന്നതും നാടൻ കഴുതകളുടെ മാംസം കഴിക്കുന്നതും ഖൈബർ ദിവസത്തിൽ നിരോധിച്ചിരിക്കുന്നു. (ന)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 80, 80, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 124, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: لَمَّا وَلِيَ عُمَرُ بْنُ الْخَطَّابِ خَطَبَ النَّاسَ فَقَالَ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَذِنَ لَنَا فِي الْمُتْعَةِ ثَلَاثًا، ثُمَّ حَرَّمَهَا. وَاللهِ، لَا أَعْلَمُ أَحَدًا يَتَمَتَّعُ وَهُوَ مُحْصَنٌ إِلَّا رَجَمْتُهُ بِالْحِجَارَةِ، إِلَّا أَنْ يَأْتِيَنِي بِأَرْبَعَةٍ يَشْهَدُونَ: أَنَّ رَسُولَ اللهِ أَحَلَّهَا بَعْدَ إِذْ حَرَّمَهَا. (جه)', 'ഇബ്നുഉമർ(റ): ഉമറുബ്നുൽ ഖത്താബ്(റ) അധികാരമേറ്റെടുത്തപ്പോൾ ജനങ്ങളോട് പ്രസംഗിച്ചു. അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) മൂന്നു പ്രാവശ്യം മുത്അ വിവാഹം നമുക്ക് അനുവദനീയമാക്കി. പിന്നീടവിടുന്ന് അത് നിഷിദ്ധമാക്കി. അല്ലാഹു തന്നെ സത്യം, വിവാഹിതനായ ഒരാൾ മുത്അ വിവാഹം കഴിക്കുന്നത് ഞാൻ അറിഞ്ഞാൽ അവനെ ഞാൻ എറിഞ്ഞു കൊല്ലുന്നതാണ്, റസൂൽ(സ) അത് നിഷിദ്ധമാക്കിയതിന് ശേഷം അനുവദനീയമാക്കിയത്. സാക്ഷി നിൽക്കുന്ന നാലു പേരെ അവൻ എന്റെയടുത്ത് കൊണ്ടുവന്നാലൊഴികെ. (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 80, 81, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 125, 'عَنْ نُبَيْهِ بْنِ وَهْبٍ رَضِيَ اللهُ عَنْهُ أَنَّ عُمَرَ بْنَ عُبَيْدِ اللهِ أَرَادَ أَنْ يُزَوِّجَ طَلْحَةَ بْنَ عُمَرَ بِنْتَ شَيْبَةَ بْنِ جُبَيْرٍ، فَأَرْسَلَ إِلَى أَبَانَ بْنِ عُثْمَانَ يَحْضُرُ ذَلِكَ، وَهُوَ أَمِيرُ الْحَجِّ، فَقَالَ أَبَانُ: سَمِعْتُ عُثْمَانَ بْنَ عَفَّانَ يَقُولُ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يَنْكِحُ الْمُحْرِمُ وَلَا يُنْكَحُ، وَلَا يَخْطُبُ". (م,د,ت,ن,جه)', 'നുബൈഹുബ്നു വഹബ്(റ): ഉമറുബ്നു ഉബൈദില്ല(റ) ത്വൽഹത്തുബ്നു ഉമർ(റ)വിനെ ശൈബത്തുബ്നു ജുബൈർ(റ)വിന്റെ മകൾക്ക് വിവാഹം ചെയ്തു കൊടുക്കാൻ ആഗ്രഹിച്ചു. ഇതിന് സന്നഹിതനാവാൻ അബാനുബ്നു ഉസ്മാൻ(റ)വിന്റെ അടുത്തേക്ക് അദ്ദേഹം ആളെ അയച്ചു. അദ്ദേഹം ഹജ്ജിന്റെ അമീറാണ്. അപ്പോൾ അബാൻ(റ) പറഞ്ഞു: "ഇഹ്റാം ചെയ്തവൻ വിവാഹം കഴിക്കുകയോ വിവാഹം ചെയ്തുകൊടുക്കുകയോ വിവാഹാഭ്യർത്ഥന നടത്തുകയോ ചെയ്യരുത്" എന്ന് റസൂൽ(സ) പറഞ്ഞതായി ഉസ്മാനുബ്നു അഫ്ഫാൻ(റ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്. (മു,ദ,തു,ന,ജ)', 'نُبَيْهِ بْنِ وَهْبٍ', 'നുബൈഹുബ്നു വഹബ്(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 81, 81, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 126, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ:: تَزَوَّجَ – فِي رِوَايَةٍ: نَكَحَ – رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ – مَيْمُونَةُ وَهُوَ مُحْرِمٌ بِسَرِفَ. وَفِي رِوَايَةٍ: جَعَلَتْ أَمْرَهَا إِلَى الْعَبَّاسِ فَأَنْكَحَهَا إِيَّاهُ. (م,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) മുഹ്രിമായിരിക്കെ മൈമൂന ബിൻത് ഹാരിസ്(റ)യെ വിവാഹം കഴിച്ചു. മറ്റൊരു നിവേദനം: മൈമൂന(റ) അവരുടെ കാര്യം അബ്ബാസ്(റ)വിനെ ഏൽപിച്ചു. അബ്ബാസ്(റ) റസൂൽ(സ)ക്ക് അവളെ വിവാഹം ചെയ്തുകൊടുത്തു. (മു,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 81, 81, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=2 and h.hadith_no=126), 1, 'وَفِي رِوَايَةٍ: جَعَلَتْ أَمْرَهَا إِلَى الْعَبَّاسِ فَأَنْكَحَهَا إِيَّاهُ. (م,ن)', 'മറ്റൊരു നിവേദനം: മൈമൂന(റ) അവരുടെ കാര്യം അബ്ബാസ്(റ)വിനെ ഏൽപിച്ചു. അബ്ബാസ്(റ) റസൂൽ(സ)ക്ക് അവളെ വിവാഹം ചെയ്തുകൊടുത്തു. (മു,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 127, 'عَنْ يَزِيدَ بْنِ الْأَصَمِّ رَضِيَ اللهُ عَنْهُ قَالَ: حَدَّثَتْنِي مَيْمُونَةُ بِنْتُ الْحَارِثِ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَزَوَّجَهَا وَهُوَ حَلَالٌ، قَالَ: وَكَانَتْ خَالَتِي وَخَالَةَ ابْنِ عَبَّاسٍ. (م,د,ت,جه)', 'യസീദുബ്നുൽ അസമ്മ്(റ): എന്നോട് മൈമൂന ബിൻതുൽ ഹാരിസ്(റ) ഇപ്രകാരം പറഞ്ഞു: നബി(സ) ഇഹ്റാം കെട്ടാത്ത അവസ്ഥയിലാണ് അവരെ വിവാഹം ചെയ്തത്. നിവേദകൻ പറയുന്നു: അവർ എന്റെയും അബ്ബാസ്(റ)വിന്റെയും മാതൃസഹോദരിയായിരുന്നു. (മു,ദ,തു,ജ)', 'يَزِيدَ بْنِ الْأَصَمِّ', 'യസീദുബ്നുൽ അസമ്മ്(റ)', null, null, array['م','د','ت','جه']::text[], array['മു','ദ','തു','ജ']::text[], null, null, 81, 81, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 128, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَى أَنْ تُنْكَحَ الْمَرْأَةُ عَلَى عَمَّتِهَا، أَوِ الْعَمَّةُ عَلَى ابْنَةِ أَخِيهَا، أَوِ الْمَرْأَةُ عَلَى خَالَتِهَا، أَوِ الْخَالَةُ عَلَى بِنْتِ أُخْتِهَا، وَلَا تُنْكَحُ الصُّغْرَى عَلَى الْكُبْرَى، وَلَا الْكُبْرَى عَلَى الصُّغْرَى. حَسَنٌ صَحِيحٌ. (م,د,ت,ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) ഒരു സ്ത്രീയോടൊപ്പം അവളുടെ പിതൃസഹോദരിയെയും, അല്ലെങ്കിൽ പിതൃസഹോദരിക്കൊപ്പം സഹോദരപുത്രിയെയും, ഒരു സ്ത്രീയോടൊപ്പം അവളുടെ മാതൃസഹോദരിയെയും, മാതൃസഹോദരിയോടൊപ്പം അവളുടെ സഹോദരപുത്രിയെയും, വലിയ സഹോദരിയോടൊപ്പം ചെറിയ സഹോദരിയെയും, ചെറിയ സഹോദരിയോടൊപ്പം വലിയ സഹോദരിയെയും വിവാഹം കഴിക്കൽ റസൂൽ(സ) നിരോധിച്ചിരിക്കുന്നു. (മു,ദ,തു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 81, 82, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 129, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ كَرِهَ أَنْ يُجْمَعَ بَيْنَ الْعَمَّةِ وَالْخَالَةِ، وَبَيْنَ الْخَالَتَيْنِ وَالْعَمَّتَيْنِ. (د,ت)', 'ഇബ്നുഅബ്ബാസ്(റ): മാതൃസഹോദരി, പിതൃസഹോദരി എന്നിവർക്കിടയിലും രണ്ട് മാതൃസഹോദരികൾക്കിടയിലും, രണ്ട് പിതൃസഹോദരികൾക്കിടയിലും ഒരുമിച്ചുകൂട്ടൽ നബി(സ) വെറുത്തിരുന്നു. (ദ,തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 82, 82, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 130, 'عَنِ الْمِسْوَرِ بْنِ مَخْرَمَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ – وَهُوَ عَلَى الْمِنْبَرِ – يَقُولُ: "إِنَّ بَنِي هِشَامِ بْنِ الْمُغِيرَةِ اسْتَأْذَنُونِي أَنْ يُنْكِحُوا ابْنَتَهُمْ عَلِيَّ بْنَ أَبِي طَالِبٍ. فَلَا آذَنُ لَهُمْ، ثُمَّ لَا آذَنُ لَهُمْ، ثُمَّ لَا آذَنُ لَهُمْ. إِلَّا أَنْ يُرِيدَ عَلِيُّ بْنُ أَبِي طَالِبٍ أَنْ يُطَلِّقَ ابْنَتِي وَيَنْكِحَ ابْنَتَهُمْ. فَإِنَّمَا هِيَ بَضْعَةٌ مِنِّي، يَرِيبُنِي مَا رَابَهَا، وَيُؤْذِينِي مَا آذَاهَا". (ق,د,ت,جه)', 'മിസ്വറുബ്നു മഖ്റമ(റ): റസൂൽ(സ) മിമ്പറിൽ വെച്ച് പറയുന്നത് ഞാൻ കേട്ടു: "ബനൂഹിഷാം അവരുടെ മകളെ അലിയ്യുബ്നു അബീത്വാലിബ്(റ)വിന് വിവാഹം കഴച്ച് കൊടുക്കാൻ എന്നോട് സമ്മതം ചോദിച്ചു. ഞാനവർക്ക് സമ്മതം നൽകുകയില്ല. പിന്നെയും ഞാനവർക്ക് സമ്മതം നൽകുകയില്ല, ഞാനവർക്ക് സമ്മതം നൽകുകയില്ല. അലിയ്യുബ്നു അബീത്വാലിബ്(റ) എന്റെ മകളെ വിവാഹ മോചനം നടത്താനും അവരുടെ മകളെ വിവാഹം കഴിക്കാനും ഉദ്ദേശിക്കുന്നുവെങ്കിലൊഴികെ. അവൾ എന്റെ ഭാഗമാണ്. അവളെ വിഷമിപ്പിക്കുന്നത് എന്നെയും വിഷമിപ്പിക്കും. അവളെ ബുദ്ധിമുട്ടിക്കുന്നത് എന്നെയും ബുദ്ധിമുട്ടിക്കും." (ബു,മു,ദ,തു,ജ)', 'الْمِسْوَرِ بْنِ مَخْرَمَةَ', 'മിസ്വറുബ്നു മഖ്റമ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 82, 82, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 131, 'عَنْ زَيْنَبَ بِنْتِ أَبِي سَلَمَةَ رَضِيَ اللهُ عَنْهُمَا، عَنْ أُمِّ حَبِيبَةَ – رَضِيَ اللهُ عَنْهَا – أَنَّهَا قَالَتْ: يَا رَسُولَ اللهِ، هَلْ لَكَ فِي أُخْتِي؟ قَالَ: "فَأَصْنَعُ مَاذَا". قَالَتْ: تَزَوَّجْهَا. قَالَ: "فَإِنَّ ذَلِكَ أَحَبُّ إِلَيْكِ". قَالَتْ: نَعَمْ، لَسْتُ لَكَ بِمُخْلِيَةٍ، وَأَحَبُّ مَنْ يَشْرَكُنِي فِي خَيْرٍ أُخْتِي. قَالَ: "إِنَّهَا لَا تَحِلُّ لِي". قَالَتْ: فَإِنَّهُ قَدْ بَلَغَنِي أَنَّكَ تَخْطُبُ دُرَّةَ بِنْتَ أُمِّ سَلَمَةَ؟ قَالَ: "بِنْتُ أَبِي سَلَمَةَ". قَالَتْ: نَعَمْ. قَالَ: "وَاللهِ لَوْ لَمْ تَكُنْ رَبِيبَتِي مَا حَلَّتْ لِي، إِنَّهَا لَابْنَةُ أَخِي مِنَ الرَّضَاعَةِ، فَلَا تَعْرِضْنَ عَلَيَّ بَنَاتِكُنَّ وَلَا أَخَوَاتِكُنَّ". (ن)', 'സൈനബ് ബിൻത് അബീസലമ(റ): ഉമ്മു ഹബീബ(റ) ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അങ്ങേക്ക് എന്റെ സഹോദരിയെ ആവശ്യമുണ്ടോ? റസൂൽ(സ) പറഞ്ഞു: "ഞാനെന്ത് ചെയ്യാനാണ്." മഹതി പറഞ്ഞു: അവിടന്ന് അവളെ വിവാഹം കഴിച്ചാലും. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഇത് നിനക്ക് ഇഷ്ടമാണോ?" ഉമ്മു ഹബീബ(റ) പറഞ്ഞു: അതെ, അങ്ങയെ ഞാൻ ഒഴിവാക്കില്ല, ഒരു നന്മയിൽ എന്റെ സഹോദരി എന്നോട് പങ്കാളിയാവുന്നത് ഞാൻ ഏറെ ഇഷ്ടപ്പെടുന്നു. നബി(സ) പറഞ്ഞു: "അവൾ എനിക്ക് അനുവദനീയമാകില്ല." ഉമ്മു ഹബീബ(റ) ചോദിച്ചു: അങ്ങ് ഉമ്മുസലമയുടെ മകൾ ദുർറയെ വിവാഹാലോചന നടത്തുണ്ടെന്ന് ഞാൻ അറിഞ്ഞു. നബി(സ) ചോദിച്ചു: "അബൂ സലമ(റ)യുടെ മകളോ." ഉമ്മു ഹബീബ(റ) പറയുന്നു: നബി(സ) പറഞ്ഞു: "അവൾ എന്റെ വളർത്തുപുത്രിയല്ലെങ്കിലും എനിക്കവൾ ഹലാലാകില്ല. നിശ്ചയം അവൾ എന്റെ മുലകുടിബന്ധത്തിലെ സഹോദരന്റെ പുത്രിയാണ്. നിന്റെ മക്കളെയോ, സഹോദരികളെയോ എന്റെയടുക്കൽ വിവാഹത്തിനായി കൊണ്ടുവരരുത്." (ന)', 'زَيْنَبَ بِنْتِ أَبِي سَلَمَةَ', 'സൈനബ് ബിൻത് അബീസലമ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 82, 83, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 132, 'عَنْ زَيْنَبَ بِنْتِ أَبِي سَلَمَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ أُمَّ حَبِيبَةَ قَالَتْ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: إِنَّا قَدْ تَحَدَّثْنَا أَنَّكَ نَاكِحٌ دُرَّةَ بِنْتَ أَبِي سَلَمَةَ؟ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَعَلَى أُمِّ سَلَمَةَ؟ لَوْ أَنِّي لَمْ أَنْكِحْ أُمَّ سَلَمَةَ مَا حَلَّتْ لِي، إِنَّ أَبَاهَا أَخِي مِنَ الرَّضَاعَةِ". (ن)', 'സൈനബ് ബിൻത് അബീസലമ(റ): ഉമ്മുഹബീബ(റ) റസൂൽ(സ)യോട് ചോദിച്ചു: അവിടന്ന് അബൂസലമയുടെ മകൾ ദുർറയെ വിവാഹം കഴിക്കുന്നുണ്ടെന്ന് ഞങ്ങൾ സംസാരിച്ചിരുന്നു. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "ഉമ്മുസലമക്ക് മീതെയോ?, ഞാൻ ഉമ്മുസലമയെ വിവാഹം കഴിച്ചിട്ടെല്ലെങ്കിലും അവൾ എനിക്ക് അനുവദനീയമാകില്ല, അവളുടെ പിതാവ് എന്റെ മുലകുടിബന്ധത്തിലെ സഹോദരനാണ്." (ന)', 'زَيْنَبَ بِنْتِ أَبِي سَلَمَةَ', 'സൈനബ് ബിൻത് അബീസലമ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 83, 83, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 133, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا، أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يُحَرِّمُ الْحَرَامُ الْحَلَالَ". [ز: في سنده ضعيف] (جه)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "നിഷിദ്ധമായത് അനുവദനീയമായതിനെ നിഷിദ്ധമാക്കില്ല." ഈ ഹദീസിന്റെ പരമ്പരയിൽ ബലഹീനനുണ്ട്. (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيف', null, 83, 83, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 134, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا، وَقَدْ سُئِلَتْ: كَمْ كَانَ صَدَاقُ نِسَاءِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ قَالَتْ: كَانَ صَدَاقُهُ فِي أَزْوَاجِهِ اثْنَتَيْ عَشْرَةَ أُوقِيَّةً وَنَشًّا. هَلْ تَدْرِي مَا النَّشُّ؟ هُوَ نِصْفُ أُوقِيَّةٍ. وَذَلِكَ خَمْسُ مِائَةِ دِرْهَمٍ. (م,د,ن,جه)', 'ആഇശ(റ): മഹതി ചോദിക്കപ്പെട്ടു: നബി(സ)യുടെ ഭാര്യമാരുടെ മഹ്റ് എത്രയായിരുന്നു? മഹതി പറഞ്ഞു: നബി(സ) തന്റെ ഭാര്യമാർക്ക് നൽകിയ മഹ്റ് പന്ത്രണ്ട് ഊഖിയയും ഒരു നശ്ശും ആയിരുന്നു. ''നശ്ശ്'' എന്താണെന്ന് നിനക്കറിയുമോ? അത് ഒരു ഊഖിയയുടെ പകുതിയാണ്. അത് (മൊത്തത്തിൽ) അഞ്ഞൂറ് ദിർഹമാണ്. (മു,ദ,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 83, 83, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 135, 'عَنْ أَبِي الْعَجْفَاءِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ عُمَرُ بْنُ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ : أَلَا، لَا تُغْلُوا صُدُقَ النِّسَاءِ، فَإِنَّهُ لَوْ كَانَ مَكْرُمَةً وَفِي الدُّنْيَا أَوْ تَقْوَى عِنْدَ اللهِ عَزَّ وَجَلَّ كَانَ أَوْلَاكُمْ بِهِ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، مَا أَصْدَقَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ امْرَأَةً مِنْ نِسَائِهِ، وَلَا أُصْدِقَتِ امْرَأَةٌ مِنْ بَنَاتِهِ أَكْثَرَ مِنْ ثِنْتَيْ عَشْرَةَ أُوقِيَّةً، وَإِنَّ الرَّجُلَ لَيُغْلِي بِصَدُقَةِ امْرَأَتِهِ حَتَّى يَكُونَ لَهَا عَدَاوَةٌ فِي نَفْسِهِ، وَحَتَّى يَقُولَ: كُلِّفْتُ لَكُمْ عِلْقَ الْقِرْبَةِ. وَكُنْتُ غُلَامًا عَرَبِيًّا مُوَلَّدًا، فَلَمْ أَدْرِ مَا عِلْقُ الْقِرْبَةِ. قَالَ: وَأُخْرَى يَقُولُونَهَا لِمَنْ قُتِلَ فِي مَغَازِيكُمْ أَوْ مَاتَ: قُتِلَ فُلَانٌ شَهِيدًا، أَوْ مَاتَ فُلَانٌ شَهِيدًا، وَلَعَلَّهُ أَنْ يَكُونَ قَدْ أَوْقَرَ عَجُزَ دَابَّتِهِ أَوْ دَفَّ رَاحِلَتِهِ ذَهَبًا أَوْ وَرِقًا، يَطْلُبُ التِّجَارَةَ، فَلَا تَقُولُوا ذَاكُمْ، وَلَكِنْ قُولُوا كَمَا قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ قُتِلَ فِي سَبِيلِ اللهِ أَوْ مَاتَ فَهُوَ فِي الْجَنَّةِ". (د,ت,ن)', 'അബുൽ അജ്ഫാഅ്(റ): ഉമറുബ്നുൽ ഖത്താബ്(റ)  പറയുന്നു: സ്ത്രീകളുടെ മഹ്റിൽ നിങ്ങൾ കൂട്ടിപ്പറയരുത്. കാരണം, നിശ്ചയമായും അത് ദുൻയാവിൽ ആദരിക്കപ്പെടുന്നതും, അല്ലാഹുവിന്റെ അടുക്കൽ തഖ്വയുടെ ഭാഗവുമായിരുന്നെങ്കിൽ അത് കൊണ്ടേറ്റവും ബന്ധപ്പെട്ടതും അവകാശപ്പെട്ടതും നബി(സ)യാണ്. നബി(സ)യുടെ ഭാര്യമാരിലോ പെൺമക്കളിലോ ഒരാളും തന്നെ പന്ത്രണ്ട് ഊഖിയയിലേറെ മഹ്റ് നൽകപ്പെട്ടിട്ടില്ല. നിശ്ചയമായും ഒരു മനുഷ്യന് തന്റെ ഭാര്യയോട് ശത്രുതയുണ്ടാകുമാറ് അവളുടെ മഹ്റ് അവന് ഭാരമായിത്തീരും. പാത്രത്തിലുള്ളത് വരെ, അല്ലെങ്കിൽ പാത്രത്തിലൂടെ ഒലിക്കുന്ന വെള്ളം വരെ നിനക്ക് വേണ്ടി ചെലവഴിക്കേണ്ടിവന്നുവെന്നവൻ പറയുന്ന ഘട്ടത്തിലെത്തും. അബുൽ അജ്ഫാഅ്(റ) പറയുന്നു: ഞാൻ ജൻമം കൊണ്ട് അറബിയ്യായ കുട്ടിയാണ്. ''ഇൽഖുൽ ഖിർബത്'' (പാത്രത്തിലുള്ളത്) എന്നാൽ എന്തെന്ന് എനിക്കറിയില്ല. ഉമർ(റ) പറഞ്ഞു: വേറൊരു വിഷയം നിങ്ങളുടെ യുദ്ധങ്ങളിൽ കൊല്ലപ്പെടുകയോ, മരിക്കുകയോ ചെയ്തവരെക്കുറിച്ച് ഇന്നയാൾ രക്തസാക്ഷിയായി കൊല്ലപ്പെട്ടുവെന്നും, ഇന്നയാൾ രക്തസാക്ഷിയായി മരിച്ചുവെന്നും പറയുന്നതാണ്. ഒരുപക്ഷേ, അയാൾ (മരിച്ചവൻ) അവൻ മൃഗത്തിന് പിന്നിലോ, വാഹത്തിന്റെ ഏതെങ്കിലും വശത്തോ കച്ചവടാവശ്യാർത്ഥം സ്വർണ്ണമോ വെള്ളിയോ നിറച്ചിട്ടുണ്ടാകും, അത് കൊണ്ട് നിങ്ങൾ അങ്ങനെ പറയരുത്. മറിച്ച് നബി(സ) പറഞ്ഞ പോലെ "ആരെങ്കിലും അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ കൊല്ലപ്പെടുകയോ മരിക്കുകയോ ചെയ്താൽ അവൻ സ്വർഗ്ഗത്തിലാണ്." എന്ന് പറയുക. (ദ,തു,ന)', 'أَبِي الْعَجْفَاءِ', 'അബുൽ അജ്ഫാഅ്(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 83, 84, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 136, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَزَوَّجَ عَائِشَةَ عَلَى مَتَاعِ بَيْتٍ، قِيمَتُهُ خَمْسُونَ دِرْهَمًا. [ز: في إسناده ضعيف] (جه)', 'അബൂസഈദിൽ ഖുദ്രി(റ): നബി(സ) ആഇശ(റ)യെ വിവാഹം കഴിച്ചത് ഒരു വീട്ടിലേക്കാവശ്യമായ ചരക്ക് മഹർ നൽകിയാണ്. അതിന്റെ വില അഞ്ഞൂറ് ദിർഹമാണ്. (ഈ ഹദീസിന്റെ പരമ്പരയിൽ ബലഹീനനുണ്ട്.) (ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 84, 84, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 137, 'عَنْ أُمِّ حَبِيبَةَ رَضِيَ اللهُ عَنْهَا: أَنَّهَا كَانَتْ تَحْتَ عُبَيْدِ اللهِ بْنِ جَحْشٍ، فَمَاتَ بِأَرْضِ الْحَبَشَةِ، فَزَوَّجَهَا النَّجَاشِيُّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَمْهَرَهَا عَنْهُ أَرْبَعَةَ آلَافٍ، وَبَعَثَ بِهَا إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَعَ شُرَحْبِيلَ بْنِ حَسَنَةَ. وفي رواية: أَنَّ النَّجَاشِيَّ زَوَّجَ أُمَّ حَبِيبَةَ بِنْتَ أَبِي سُفْيَانَ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، عَلَى صَدَاقِ أَرْبَعَةِ آلَافِ دِرْهَمٍ، وَكَتَبَ بِذَلِكَ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَبِلَ. (د)', 'ഉമ്മുഹബീബ(റ): മഹതി അബ്ദുല്ലാഹിബ്നു ജഹ്ശിന്റെ ഭാര്യയായിരുന്നു. അദ്ദേഹം ഹബശയിൽ വെച്ച് മരിച്ചപ്പോൾ നജ്ജാശി 4000 ദിർഹം നബി(സ)ക്ക് വേണ്ടി മഹ്റായി കൊടുക്കുകയും മഹതിയെ നബി(സ)ക്ക് വിവാഹം ചെയ്ത് കൊടുക്കുകയും ചെയ്തു. ശുറഹ്ബീലുബ്നു ഹസന(റ)വിനോട് കൂടെ മഹതിയെ റസൂൽ(സ)യുടെ അടുത്തേക്ക് അയച്ചു.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=2 and h.hadith_no=137), 1, 'وَفِي رِوَايَةٍ: أَنَّ النَّجَاشِيَّ زَوَّجَ أُمَّ حَبِيبَةَ بِنْتَ أَبِي سُفْيَانَ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، عَلَى صَدَاقِ أَرْبَعَةِ آلَافِ دِرْهَمٍ، وَكَتَبَ بِذَلِكَ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَبِلَ. (د)', 'മറ്റൊരു നിവേദനത്തിൽ: നാലായിരം ദിർഹം മഹ്റായി നൽകി നജ്ജാശി ഉമ്മുഹബീബ(റ)യെ റസൂൽ(സ)ക്ക് വിവാഹം കഴിച്ചു കൊടുത്തു. റസൂൽ(സ)യെ ഈ വിവരം എഴുതി അറിയിച്ചു. അവിടന്ന് അത് സ്വീകരിച്ചു. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 138, 'عَنْ أُمِّ حَبِيبَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَزَوَّجَهَا وَهِيَ بِأَرْضِ الْحَبَشَةِ، زَوَّجَهَا النَّجَاشِيُّ وَأَمْهَرَهَا أَرْبَعَةَ آلَافٍ، وَجَهَّزَهَا مِنْ عِنْدِهِ، وَبَعَثَ بِهَا مَعَ شُرَحْبِيلَ بْنِ حَسَنَةَ، وَلَمْ يَبْعَثْ إِلَيْهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِشَيْءٍ، وَكَانَ مَهْرُ نِسَائِهِ أَرْبَعَ مِائَةِ دِرْهَمٍ. (ن)', 'ഉമ്മുഹബീബ(റ): മഹതി ഹബശയിലായിരിക്കെ റസൂൽ(സ) അവരെ വിവാഹം കഴിച്ചു. നജ്ജാശി അവരെ വിവാഹം കഴിപ്പിച്ചു. നാലായിരം ദിർഹം മഹ്റായി നൽകുകയും ചെയ്തു. നജ്ജാശി തന്നെ മഹതിയെ അണിയിച്ചൊരുക്കി. ശുറൈഹീലുബ്നു ഹസന(റ)നോട് കൂടെ മഹതിയെ റസൂൽ(സ)യുടെ അടുത്തേക്കയുച്ചു. റസൂൽ(സ) മഹതിക്ക് ഒന്നും അയച്ചു കൊടുത്തില്ല. റസൂൽ(സ)യുടെ ഭാര്യമാരുടെ മഹ്ര് 400 ദിർഹമായിരുന്നു. (ന)', 'أُمِّ حَبِيبَةَ', 'ഉമ്മുഹബീബ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 84, 84, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 139, 'عَنْ عُرْوَةَ بْنِ الزُّبَيْرِ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سَأَلَ عَائِشَةَ عَنْ قَوْلِ اللهِ عَزَّ وَجَلَّ: {وَإِنْ خِفْتُمْ أَلَّا تُقْسِطُوا فِي الْيَتَامَى فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ} [النّساء: ٣]. قَالَتْ: يَا ابْنَ أُخْتِي، هِيَ الْيَتِيمَةُ تَكُونُ فِي حَجْرِ وَلِيِّهَا، فَتُشَارِكُهُ فِي مَالِهِ فَيُعْجِبُهُ مَالُهَا وَجَمَالُهَا، فَيُرِيدُ وَلِيُّهَا أَنْ يَتَزَوَّجَهَا بِغَيْرِ أَنْ يُقْسِطَ فِي صَدَاقِهَا، فَيُعْطِيَهَا مِثْلَ مَا يُعْطِيهَا غَيْرُهُ، فَنُهُوا أَنْ يَنْكِحُوهُنَّ إِلَّا أَنْ يُقْسِطُوا لَهُنَّ، وَيَبْلُغُوا بِهِنَّ أَعْلَى سُنَّتِهِنَّ مِنَ الصَّدَاقِ، فَأُمِرُوا أَنْ يَنْكِحُوا مَا طَابَ لَهُمْ مِنَ النِّسَاءِ سِوَاهُنَّ. قَالَ عُرْوَةُ: قَالَتْ عَائِشَةُ: ثُمَّ إِنَّ النَّاسَ اسْتَفْتَوْا رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَعْدُ فِيهِنَّ، فَأَنْزَلَ اللهُ عَزَّ وَجَلَّ {وَيَسْتَفْتُونَكَ فِي النِّسَاءِ قُلِ اللهُ يُفْتِيكُمْ فِيهِنَّ} إِلَى قَوْلِهِ: {وَتَرْغَبُونَ أَنْ تَنْكِحُوهُنَّ} [النّساء: ١٢٧] قَالَتْ عَائِشَةُ: وَالَّذِي ذَكَرَ اللهُ تَعَالَى أَنَّهُ يُتْلَى فِي الْكِتَابِ الْآيَةُ الْأُولَى الَّتِي فِيهَا: {وَإِنْ خِفْتُمْ أَلَّا تُقْسِطُوا فِي الْيَتَامَى فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ}. قَالَتْ عَائِشَةُ: وَقَوْلُ اللهِ فِي الْآيَةِ الْأُخْرَى: {وَتَرْغَبُونَ أَنْ تَنْكِحُوهُنَّ} رَغْبَةَ أَحَدِكُمْ عَنْ يَتِيمَتِهِ الَّتِي تَكُونُ فِي حَجْرِهِ حِينَ تَكُونُ قَلِيلَةَ الْمَالِ وَالْجَمَالِ، فَنُهُوا أَنْ يَنْكِحُوا مَا رَغِبُوا فِي مَالِهَا مِنْ يَتَامَى النِّسَاءِ إِلَّا بِالْقِسْطِ، مِنْ أَجْلِ رَغْبَتِهِمْ عَنْهُنَّ. (ن)', 'ഉർവതുബ്നു സുബൈർ(റ): ''അനാഥകളുടെ കാര്യത്തിൽ നിങ്ങൾക്ക് നീതി പാലിക്കാനാകില്ലെന്ന് നിങ്ങൾ ഭയപ്പെടുന്ന പക്ഷം (മറ്റു) സ്ത്രീകളിൽ നിന്ന് നിങ്ങൾ ഇഷ്ടപ്പെടുന്ന വരെ വിവാഹം ചെയ്തു കൊള്ളുക.'' (നിസാഅ്: 3) എന്ന അല്ലാഹുവിന്റെ തിരുവചനത്തെ സംബന്ധിച്ച് അദ്ദേഹം ആഇശ(റ)യോട് ചോദിച്ചു. മഹതി പറഞ്ഞു: എന്റെ സഹോദരി പുത്രാ, തന്റെ വലിയ്യിന്റെ (രക്ഷാ കർത്താവ്) സംരക്ഷണത്തിൽ കഴിയുന്ന അനാഥ പെൺകുട്ടിയാണത്. അവൾ വലിയ്യിനോട് സമ്പത്തിൽ പങ്കാളിയാകുന്നു. അവളുടെ സൗന്ദര്യവും സമ്പത്തും അവനെ ആകർശിക്കുകയും, അങ്ങനെ അവൾക്ക് യോജിച്ച മഹ്റ് നൽകാതെ അവളെ വിവാഹം കഴിക്കാമെന്ന് അവൻ മോഹിക്കുകയും ചെയ്യുന്നു. മറ്റുള്ളവർ അവൾക്ക് കൊടുക്കുന്നത് പോലെ മാത്രമേ  അവൻ കൊടുക്കൂ. അതിനാൽ തന്നെ, അവരോട് നീതി പാലിക്കാതെയും മഹ്റിൽ അവൾക്ക് ആ നിലയനുസരിച്ച് ലഭിക്കാവുന്നത് കൊടുക്കാതെയും അവരെ ഈ രക്ഷിതാക്കൾ വിവാഹം കഴിക്കുന്നത് നിരോധിക്കപ്പെട്ടിരിക്കുന്നു. അത് കൊണ്ടാണ് ആ അനാഥകളല്ലാത്ത മറ്റ് സ്ത്രീകളിൽ നിന്ന് ഇഷ്ടമുള്ളവരെ വിവാഹം കഴിക്കാൻ അവർ കൽപ്പിക്കപ്പെട്ടത്. ഉർവ്വ(റ) പറയുന്നു: മഹതി പറഞ്ഞു: പിന്നെ ചിലയാളുകൾ നബി(സ)യോട് ഇവരുടെ വിഷയത്തിൽ അഭിപ്രായം ചോദിച്ചപ്പോൾ അല്ലാഹു തആല ''സ്ത്രീകളുടെ കാര്യത്തിൽ അങ്ങയോടവർ വിധി തേടുന്നു. അങ്ങ് പറയുക: അവരുടെ കാര്യത്തിൽ അല്ലാഹു നിങ്ങൾക്ക് വിധി നൽകും.'' എന്നത് മുതൽ ''അനാഥകളെ വിവാഹം കഴിക്കാൻ അവർ ആഗ്രഹിക്കുകയും ചെയ്യുന്നു'' (നിസാഅ്:127) എന്നത് വരെയുള്ള സൂക്തമിറങ്ങി. ആഇശ(റ) പറഞ്ഞു: ''ഗ്രന്ഥത്തിൽ വായിച്ച് കേൾപ്പിക്കപ്പെടുന്നത്'' എന്ന്  അല്ലാഹു തആല പറഞ്ഞത് ''അനാഥകളുടെ കാര്യത്തിൽ നിങ്ങൾക്ക് നീതി പാലിക്കാനാകില്ലെന്ന് നിങ്ങൾ ഭയപ്പെടുകയാണെങ്കിൽ (മറ്റു) സ്ത്രീകളിൽ നിന്ന് നിങ്ങൾ ഇഷ്ടപ്പെടുന്നതിനെ വിവാഹം ചെയ്തുകൊള്ളുക.'' എന്നുൾക്കൊള്ളുന്ന ആദ്യത്തെ സൂക്തത്തെ സംബന്ധിച്ചാണ്. ആഇശ(റ) പറയുന്നു: മറ്റൊരു ആയത്തിൽ ''നിങ്ങൾ വിവാഹം കഴിക്കാൻ ആഗ്രഹിക്കുകയും ചെയ്യുന്ന'' എന്ന അല്ലാഹുവിന്റെ തിരുവചനം, സമ്പത്തും സൗന്ദര്യം കുറഞ്ഞ അവസ്ഥയിൽ തന്റെ സംരക്ഷണത്തിൽ കഴിയുന്ന അനാഥ കുട്ടിയെ വെറുക്കുന്നതിനെ സംബന്ധിച്ചാണ്. ഇങ്ങനെയുള്ള (സമ്പത്തും സൗന്ദര്യവും കുറഞ്ഞ) അനാഥകളെ വെറുക്കുന്നത് കാരണം തന്നെ, നീതിയോടെയല്ലാതെ, അനാഥകളായ പെൺകുട്ടികളുടെ സമ്പത്തിൽ കണ്ണ്വെച്ച്  അവരെ വിവാഹം കഴിക്കുന്നത് നിരോധിക്കപ്പെട്ടു. (ന)', 'عُرْوَةَ بْنِ الزُّبَيْرِ', 'ഉർവതുബ്നു സുബൈർ(റ)', null, null, array['ن']::text[], array['ന']::text[], 'النّساء: ١٢٧', null, 85, 85, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 140, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ الصَّدَاقُ إِذْ كَانَ فِينَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَشْرَةَ أَوَاقٍ. (ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) ഉണ്ടായിരുന്നപ്പോൾ മഹ്റ് പത്ത് ഊഖിയയായിരുന്നു. (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 85, 86, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 141, 'عَنْ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ جَاءَتْهُ امْرَأَةٌ فَقَالَتْ: إِنِّي وَهَبْتُ نَفْسِي لَكَ. فَقَامَتْ طَوِيلًا، فَقَالَ رَجُلٌ: يَا رَسُولَ اللهِ، فَزَوِّجْنِيهَا، إِنْ لَمْ تَكُنْ لَكَ بِهَا حَاجَةٌ. فَقَالَ: "هَلْ عِنْدَكَ مِنْ شَيْءٍ تُصْدِقُهَا". فَقَالَ: مَا عِنْدِي إِلَّا إِزَارِي هَذَا. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِزَارُكَ، إِنْ أَعْطَيْتَهَا جَلَسْتَ وَلَا إِزَارَ لَكَ، فَالْتَمِسْ شَيْئًا". قَالَ: مَا أَجِدُ. قَالَ: "فَالْتَمِسْ وَلَوْ خَاتَمًا مِنْ حَدِيدٍ". قَالَ: فَالْتَمَسَ فَلَمْ يَجِدْ شَيْئًا. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "هَلْ مَعَكَ مِنَ الْقُرْآنِ شَيْءٌ". قَالَ: نَعَمْ، سُورَةُ كَذَا وَسُورَةُ كَذَا، لِسُوَرٍ سَمَّاهَا. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "زَوَّجْتُكَهَا بِمَا مَعَكَ مِنَ الْقُرْآنِ". حَسَنٌ صَحِيحٌ. (ق,د,ت,ن,جه)', 'സഹ്ലുബ്നു സഅദിസ്സാഇദി(റ): റസൂൽ(സ)യുടെ അടുത്ത് ഒരു സ്ത്രീ വന്ന് പറഞ്ഞു: ഞാൻ എന്റെ ശരീരം അങ്ങേക്ക് നൽകിയിരിക്കുന്നു, അങ്ങനെ അവൾ ദീർഘമായി നിന്നു. തദവസരത്തിൽ ഒരാൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അങ്ങേക്ക് അവളെക്കൊണ്ട് ഒരാവശ്യവുമില്ലെങ്കിൽ അവളെ എനിക്ക് വിവാഹം ചെയ്ത് തരിക. നബി(സ) ചോദിച്ചു: "അവൾക്ക് മഹ്റ് കൊടുക്കാൻ നിന്റെ പക്കൽ വല്ലതുമുണ്ടോ?" അയാൾ പറഞ്ഞു: ഞാൻ ധരിച്ചിരിക്കുന്ന ഈ തുണിയല്ലാതെ ഒന്നും എന്റെ അടുത്തില്ല. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിന്റെ ഈ തുണി അവൾക്ക് കൊടുത്താൽ, അവളതെടുക്കും. നിനക്ക് തുണിയുണ്ടാവുകയുമില്ല, അത് കൊണ്ട് എന്തെങ്കിലും അന്വേഷിക്ക്." അയാൾ പറഞ്ഞു: എനിക്ക് കിട്ടിയില്ല. തിരുമേനി(സ) പറഞ്ഞു: "ഒരു ഇരുമ്പിന്റെ മോതിരമെങ്കിലും നീ അന്വേഷിക്കുക." നിവേദകൻ പറയുന്നു: അയാൾ അന്വേഷിച്ചെങ്കിലും അയാൾക്കൊന്നും ലഭിച്ചില്ല. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു:"നിനക്ക് ഖുർആനിൽ നിന്ന് വല്ലതും അറിയുമോ?" അയാൾ പറഞ്ഞു: അതെ. ഇന്നാലിന്ന സൂറത്തുകൾ അറിയാം. അയാൾ കുറച്ച് സൂറതുകൾ എണ്ണിപ്പറഞ്ഞു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു:"ഖുർആനിൽ നിന്ന് നിനക്കറിയാവുന്നതിന് പകരമായി ഞാൻ അവളെ നിനക്ക് വിവാഹം ചെയ്തു തന്നിരിക്കുന്നു." (ബു,മു,ദ,തു,ന,ജ)', 'سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ', 'സഹ്ലുബ്നു സഅദിസ്സാഇദി(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 86, 86, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 142, 'عَنْ مَكْحُولٍ، نَحْوَ خَبَرِ سَهْلٍ، قَالَ: وَكَانَ مَكْحُولٌ يَقُولُ: لَيْسَ ذَلِكَ لِأَحَدٍ بَعْدَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (د)', 'മക്ഹൂൽ: സഹ്ൽ(റ)വിന്റെതിനു സമാനമായ ഹദീസ് പറഞ്ഞു. നിവേദകൻ പറയുന്നു: മക്ഹൂൽ പറയുമായിരുന്നു: റസൂൽ(സ)ക്ക് ശേഷം ഇത് ആർക്കും ബാധകമല്ല. (ദ)', 'مَكْحُولٍ، نَحْوَ خَبَرِ سَهْلٍ، قَالَ', 'മക്ഹൂൽ', null, null, array['د']::text[], array['ദ']::text[], null, null, 86, 86, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 143, 'عَنْ عَامِرِ بْنِ رَبِيعَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ امْرَأَةً مِنْ بَنِي فَزَارَةَ تَزَوَّجَتْ عَلَى نَعْلَيْنِ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَرَضِيتِ مِنْ نَفْسِكِ وَمَالِكِ بِنَعْلَيْنِ". قَالَتْ: نَعَمْ. قَالَ فَأَجَازَهُ. حَسَنٌ صَحِيحٌ. (ت,جه)', 'ആമിറുബ്നു റബീഅ(റ): ബനൂ ഫുസാറയിൽ പെട്ട ഒരു സ്ത്രീ രണ്ട് ചെരുപ്പുകൾ മഹ്റായി സ്വീകരിച്ചാണ് വിവാഹം കഴിച്ചത്. അപ്പോൾ റസൂൽ(സ) ചോദിച്ചു: "നിന്റെ ശരീരത്തിനും സമ്പത്തിനും രണ്ട് ചെരുപ്പുകൾ കൊണ്ട് നീ തൃപ്തിപ്പെടുമോ." അവൾ പറഞ്ഞു: അതെ. നിവേദകൻ പറയുന്നു: നബി(സ) ആ വിവാഹത്തിന് അനുമതി നൽകി. (തു,ജ)', 'عَامِرِ بْنِ رَبِيعَةَ', 'ആമിറുബ്നു റബീഅ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 86, 86, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 144, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَأَى عَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ وَعَلَيْهِ رَدْعُ زَعْفَرَانٍ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَهْيَمْ". فَقَالَ: يَا رَسُولَ اللهِ، تَزَوَّجْتُ امْرَأَةً. قَالَ: "مَا أَصْدَقْتَهَا". قَالَ: وَزْنَ نَوَاةٍ مِنْ ذَهَبٍ، قَالَ: "أَوْلِمْ وَلَوْ بِشَاةٍ". (ق,د,ت,ن,جه)', 'അനസ്(റ): റസൂൽ(സ) അബ്ദുർറഹ്മാനുബ്നു ഔഫ്(റ)വിനെ കണ്ടു. അവരുടെ ശരീരത്തിൽ കുങ്കുമത്തിന്റെ അംശമുണ്ടായിരുന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "എന്താണ് നിന്റെ വിശേഷം?". അബ്ദുർറഹ്മാനുബ്നു ഔഫ്(റ) പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞാനൊരു സ്ത്രീയെ വിവാഹം കഴിച്ചു. റസൂൽ(സ) ചോദിച്ചു: "എന്താണ് മഹ്റ് കൊടുത്തത്?" ഇബ്നു ഔഫ്(റ) പറഞ്ഞു: ഈത്തപ്പഴക്കുരുവിന്റെ തൂക്കം സ്വർണ്ണം. റസൂൽ(സ) പറഞ്ഞു: "ഒരാട് കൊണ്ടെങ്കിലും നീ വിവാഹ സദ്യ നടത്തുക." (ബു,മു,ദ,തു,ന,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 86, 87, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 145, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ أَعْطَى فِي صَدَاقِ امْرَأَةٍ مِلْءَ كَفَّيْهِ سَوِيقًا أَوْ تَمْرًا فَقَدِ اسْتَحَلَّ". (د)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ തന്റെ ഉള്ളം കൈ നിറയെ ധാന്യപ്പൊടിയോ കാരക്കയോ ആണ് സ്ത്രീക്ക് മഹ്റായി കൊടുത്തതെങ്കിൽ അവൾ അവന് അനുവദനീയമായിരിക്കുന്നു." (ദ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 87, 87, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 146, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا كَانَ مِنْ صَدَاقٍ أَوْ حِبَاءٍ أَوْ عِدَةٍ قَبْلَ عِصْمَةِ النِّكَاحِ فَهُوَ لَهَا، وَمَا كَانَ بَعْدَ عِصْمَةِ النِّكَاحِ فَهُوَ لِمَنْ أَعْطَاهُ. وَأَحَقُّ مَا يُكْرَمُ عَلَيْهِ الرَّجُلُ ابْنَتُهُ أَوْ أُخْتُهُ". (د,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) പറഞ്ഞു: "വിവാഹ ഇടപാടിനു മുമ്പ് നൽകപ്പെടുന്ന മഹ്റും സമ്മാനവും ദാനവും പെണ്ണിനുള്ളതാണ്. വിവാഹ ഇടപാടിനു ശേഷം നൽകപ്പെടുന്നത് അതു നൽകപ്പെട്ടവെന്നാണ്. അവന്റെ മകളും സഹോദരിയുമാണ് ഒരുവനെ ബഹുമാനിതനാക്കാൻ ഏറ്റവും യോജിച്ചത്." (ദ,ന,ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 87, 87, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 147, 'عَنْ مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ ثَوْبَانَ، عَنْ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنَّ عَلِيًّا رَضِيَ اللهُ عَنْهُ لَمَّا تَزَوَّجَ فَاطِمَةَ بِنْتَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَرَادَ أَنْ يَدْخُلَ بِهَا، فَمَنَعَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَتَّى يُعْطِيَهَا شَيْئًا، فَقَالَ: يَا رَسُولَ اللهِ، لَيْسَ لِي شَيْءٌ. فَقَالَ لَهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَعْطِهَا دِرْعَكَ". فَأَعْطَاهَا دِرْعَهُ، ثُمَّ دَخَلَ بِهَا.وفي رواية: عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، مِثْلَهُ. (د)', 'മുഹമ്മദുബ്നു അബ്ദുർറഹ്മാനുബ്നു സൗബാൻ(റ): ഒരു സ്വഹാബിയിൽ നിന്ന് നിവേദനം ചെയ്യുന്നു: അലി(റ) റസൂൽ(സ)യുടെ പുത്രി ഫാത്വിമ ബീവി(റ)യെ വിവാഹം കഴിച്ചപ്പോൾ മഹതിയുമായി ബന്ധപ്പെടാനാഗ്രഹിച്ചു. അപ്പോൾ റസൂൽ(സ) അലി(റ)വിനെ മഹതിക്ക് എന്തെങ്കിലും നൽകുന്നത് വരെ ബന്ധപ്പെടുന്നതിൽ നിന്നും തടഞ്ഞു. അലി(റ) പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, എന്റെയടുത്ത് ഒന്നുമില്ല. അപ്പോൾ റസൂൽ(സ) അലി(റ)വിനോട് പറഞ്ഞു: "നിന്റെ അങ്കി അവൾക്ക് കൊടുക്കുക." അങ്ങനെ അലി(റ) തന്റെ അങ്കി ഫാത്വിമ ബീവി(റ)ക്ക് കൊടുത്തു. പിന്നെ മഹതിയുമായി ബന്ധപ്പെട്ടു. മറ്റൊരു നിവേദനത്തിൽ: ഇബ്നുഅബ്ബാസ്(റ)വിൽ നിന്ന് ഇപ്രകാരം നിവേദനം ചെയ്യപ്പെട്ടിട്ടുണ്ട്. (ദ)', 'مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ ثَوْبَانَ، عَنْ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ', 'മുഹമ്മദുബ്നു അബ്ദുർറഹ്മാനുബ്നു സൗബാൻ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 87, 87, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=2 and h.hadith_no=147), 1, 'وَفِي رِوَايَةٍ: عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، مِثْلَهُ. (د)', 'മറ്റൊരു നിവേദനത്തിൽ: ഇബ്നുഅബ്ബാസ്(റ)വിൽ നിന്ന് ഇപ്രകാരം നിവേദനം ചെയ്യപ്പെട്ടിട്ടുണ്ട്. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 148, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: أَمَرَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ لَا أُدْخِلَ امْرَأَةً عَلَى زَوْجِهَا قَبْلَ أَنْ يُعْطِيَهَا شَيْئًا. (د,جه)', 'ആഇശ(റ): ഭാര്യക്ക് എന്തെങ്കിലും നൽകുന്നതിന് മുമ്പ് ഒരു ഭർത്താവിനെയും തന്റെ ഭാര്യയുമായി ബന്ധപ്പെടാനനുവദിക്കരുതെന്ന് റസൂൽ(സ) എന്നോട് കൽപ്പിച്ചു. (ദ,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 87, 87, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 149, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: خطب أبو طلحة أمّ سُلَيْمٍ، فَقَالَتْ: وَاللهِ مَا مِثْلُكَ يَا أَبَا طَلْحَةَ يُرَدُّ، وَلَكِنَّكَ رَجُلٌ كَافِرٌ وَأَنَا امْرَأَةٌ مُسْلِمَةٌ، وَلَا يَحِلُّ لِي أَنْ أَتَزَوَّجَكَ، فَإِنْ تُسْلِمْ فَذَاكَ مَهْرِي، وَمَا أَسْأَلُكَ غَيْرَهُ. فَأَسْلَمَ، فَكَانَ ذَلِكَ مَهْرَهَا. قَالَ ثَابِتٌ: فَمَا سَمِعْتُ بِامْرَأَةٍ قَطُّ كَانَتْ أَكْرَمَ مَهْرًا مِنْ أُمِّ سُلَيْمٍ: الْإِسْلَامَ، فَدَخَلَ بِهَا فَوَلَدَتْ لَهُ. (ن)', 'അനസ്(റ): അബൂത്വൽഹ(റ) ഉമ്മുസുലൈം(റ)യോട് വിവഹാലോചന നടത്തി. മഹതി പറഞ്ഞു: അല്ലാഹു തന്നെയാണ് സത്യം, അബൂ ത്വൽഹാ, അങ്ങയെപ്പോലുള്ളവർ തിരിച്ചയക്കപ്പെടില്ല. പക്ഷേ, അങ്ങ് സത്യനിഷേധിയും ഞാൻ മുസ്ലിമായ ഒരു സ്ത്രീയുമാണ്. അങ്ങയെ വിവാഹം കഴിക്കൽ എനിക്കനുവദനീയമല്ല. താങ്കൾ മുസ്ലിമാകുകയാണെങ്കിൽ അതാണെന്റെ മഹ്റ്. വേറെ ഒന്നും നിങ്ങളോട് ഞാൻ ചോദിക്കുകയില്ല. അങ്ങനെ അബൂത്വൽഹ(റ) മുസ്ലിമായി. അതായിരുന്നു അവരുടെ മഹ്റ്. സാബിത്(റ) പറയുന്നു: ഉമ്മുസുലൈം(റ)യേക്കാൾ മഹ്റ് മാന്യമായ ഒരു സ്ത്രീയെക്കുറിച്ചും ഇന്നുവരെ ഞാൻ കേട്ടിട്ടില്ല. അവരുടെ മഹ്റ് ഇസ്ലാം ആയിരുന്നു. അങ്ങനെ അവർ ബന്ധപ്പെട്ടു. അവർക്ക് സന്താനങ്ങളുണ്ടാകുകയും ചെയ്തു. (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 88, 88, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 150, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَعْتَقَ صَفِيَّةَ وَجَعَلَهُ صَدَاقَهَا. وفي رواية: أَعْتَقَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَفِيَّةَ، وَجَعَلَ عِتْقَهَا مَهْرَهَا. (ن)', 'അനസ്(റ): റസൂൽ(സ) സ്വഫിയ്യ(റ)യെ സ്വതന്ത്രയാക്കുകയും, ആ സ്വാതന്ത്ര്യത്തെ മഹതിയുടെ മഹ്റാക്കുകയും ചെയ്തു. മറ്റൊരു നിവേദനം: റസൂൽ(സ) സ്വഫിയ്യ(റ)യെ സ്വതന്ത്രയാക്കി. ആ സ്വാതന്ത്ര്യത്തെ അവിടുന്ന്  മഹതിയുടെ മഹ്റാക്കുകയും ചെയ്തു. (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 88, 88, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=57 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=2 and h.hadith_no=150), 1, 'وَفِي رِوَايَةٍ: أَعْتَقَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَفِيَّةَ، وَجَعَلَ عِتْقَهَا مَهْرَهَا. (ن)', 'മറ്റൊരു നിവേദനം: റസൂൽ(സ) സ്വഫിയ്യ(റ)യെ സ്വതന്ത്രയാക്കി. ആ സ്വാതന്ത്ര്യത്തെ അവിടുന്ന്  മഹതിയുടെ മഹ്റാക്കുകയും ചെയ്തു. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 151, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ أَتَاهُ قَوْمٌ فَقَالُوا: إِنَّ رَجُلًا مِنَّا تَزَوَّجَ امْرَأَةً وَلَمْ يَفْرِضْ لَهَا صَدَاقًا، وَلَمْ يَجْمَعْهَا إِلَيْهِ حَتَّى مَاتَ؟ فَقَالَ عَبْدُ اللهِ: مَا سُئِلْتُ مُنْذُ فَارَقْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَشَدَّ عَلَيَّ مِنْ هَذِهِ، فَأْتُوا غَيْرِي. فَاخْتَلَفُوا إِلَيْهِ فِيهَا شَهْرًا، ثُمَّ قَالُوا لَهُ فِي آخِرِ ذَلِكَ: مَنْ نَسْأَلُ إِنْ لَمْ نَسْأَلْكَ، وَأَنْتَ مِنْ جِلَّةِ أَصْحَابِ مُحَمَّدٍ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِهَذَا الْبَلَدِ، وَلَا نَجِدُ غَيْرَكَ. قَالَ: سَأَقُولُ فِيهَا بِجَهْدِ رَأْيِي، فَإِنْ كَانَ صَوَابًا فَمِنَ اللهِ وَحْدَهُ لَا شَرِيكَ لَهُ، وَإِنْ كَانَ خَطَأً فَمِنِّي وَمِنَ الشَّيْطَانِ، وَاللهُ وَرَسُولُهُ مِنْهُ بُرَآءُ: أَرَى أَنْ أَجْعَلَ لَهَا صَدَاقَ نِسَائِهَا، لَا وَكْسَ وَلَا شَطَطَ، وَلَهَا الْمِيرَاثُ، وَعَلَيْهَا الْعِدَّةُ أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا. قَالَ: وَذَلِكَ بِسَمْعِ أُنَاسٍ مِنْ أَشْجَعَ، فَقَامُوا فَقَالُوا: نَشْهَدُ أَنَّكَ قَضَيْتَ بِمَا قَضَى بِهِ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي امْرَأَةٍ مِنَّا يُقَالُ لَهَا بَرْوَعُ بِنْتُ وَاشِقٍ، قَالَ: فَمَا رُئِيَ عَبْدُ اللهِ فَرِحَ فَرْحَةً يَوْمَئِذٍ إِلَّا بِإِسْلَامِهِ. (د,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): കുറച്ചാളുകൾ വന്ന് ഇബ്നു മസ്ഊദ്(റ)വിനോട് ചോദിച്ചു: ഞങ്ങളിൽ പെട്ട ഒരാൾ ഒരു സ്ത്രീയെ വിവാഹം കഴിക്കുകയും, അവൾക്കൊരു മഹ്റ് നിശ്ചയിക്കാതെ, അവളുമായി ബന്ധപ്പെടാതെ അയാൾ മരിക്കുകയും ചെയ്തു. ഇതിലുള്ള വിധിയെന്താണ്? ഇബ്നു മസ്ഊദ്(റ) പറഞ്ഞു: റസൂൽ(സ)യുട വിയോഗം മുതൽ ഇതിനേക്കാൾ ഗൗരവമേറിയ ഒരു ചോദ്യം ഞാൻ ചോദിക്കപ്പെട്ടിട്ടില്ല. അത്കൊണ്ട് നിങ്ങൾ ഞാനല്ലാത്ത വേറൊരാളുടെ അടുത്തേക്ക് പോകുക. അങ്ങനെ അവർ ഒരു മാസത്തോളം മാറിമാറി വന്നു. അവസാനം പറഞ്ഞു: നിങ്ങളോട് ചോദിക്കാതെ വേറെയാരോട് ചോദിക്കാനാണ്. നബി(സ)യുടെ ഈ നാട്ടിലെ അനുചരരിൽ ഉന്നതരിൽ പെട്ടവരാണല്ലോ അങ്ങ്. നിങ്ങളെയല്ലാതെ വേറെ ആരെയും ഞങ്ങൾക്ക് കിട്ടില്ല. ഇബ്നു മസ്ഊദ്(റ) പറഞ്ഞു: ഈ വിഷയത്തിൽ ഗഹനമായി ചിന്തിച്ച് ഞാൻ വിധി പറയാം. അത് ശരിയാണെങ്കിൽ അല്ലാഹുവിന്റെ ഭാഗത്ത് നിന്നാണ്, പിഴവെങ്കിൽ എന്റെയും ശൈത്വാന്റെയും ഭാഗത്ത് നിന്നാണ്. അല്ലാഹുവും അവന്റെ തിരുദൂതരും നിരപരാധികളാണ്. എന്റെ അഭിപ്രായം, അവളെപ്പോലോത്ത സ്ത്രീകൾക്ക് കിട്ടാവുന്ന മഹ്റിന് അവൾ അർഹതപ്പെട്ടവളാണ്. അതിൽക്കൂടുതലോ കുറവോ ഇല്ല. അനന്തരാവകാശ സ്വത്തിനും അർഹതപ്പെട്ടവളാണവൾ. നാല് മാസവും പത്ത് ദിവസവും അവൾ ഇദ്ദയിരിക്കണം. നിവേദകൻ പറയുന്നു: ഇത് അശ്ജഅ് ഗോത്രത്തിൽ പെട്ട കുറച്ചാളുകൾ കേൾക്കെയായിരുന്നു. അവരെണീറ്റ് പറഞ്ഞു: ഞങ്ങളിൽ പെട്ട ബിർവഅ ബിൻത് വാഷിഖ് എന്ന സ്ത്രീയുടെ വിഷയത്തിൽ അങ്ങ് വിധിച്ചത് പോലെ റസൂൽ(സ) വിധിച്ചിരുന്നുവെന്ന് ഞങ്ങൾ സാക്ഷ്യപ്പെടുത്തുന്നു. നിവേദകൻ പറയുന്നു: ഇബ്നു മസ്ഊദ്(റ) ആ നിമിഷം സന്തോഷിച്ചത്ര സന്തോഷിച്ചതായിട്ട്, താൻ മുസ്ലിമായ സന്ദർഭത്തിലല്ലാതെ വേറെ ഒരു നിമിഷം കാണപ്പെട്ടിട്ടില്ല. (ദ,തു,ന,ജ)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 88, 89, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 152, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ لِرَجُلٍ: "أَتَرْضَى أَنْ أُزَوِّجَكَ فُلَانَةَ". قَالَ: نَعَمْ، وَقَالَ لِلْمَرْأَةِ: "أَتَرْضَيْنَ أَنْ أُزَوِّجَكِ فُلَانًا". قَالَتْ: نَعَمْ. فَزَوَّجَ أَحَدَهُمَا صَاحِبَهُ، فَدَخَلَ بِهَا الرَّجُلُ، وَلَمْ يَفْرِضْ لَهَا صَدَاقًا، وَلَمْ يُعْطِهَا شَيْئًا، وَكَانَ مِمَّنْ شَهِدَ الْحُدَيْبِيَةَ، وَكَانَ مَنْ شَهِدَ الْحُدَيْبِيَةَ لَهُ سَهْمٌ بِخَيْبَرَ، فَلَمَّا حَضَرَتْهُ الْوَفَاةُ قَالَ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ زَوَّجَنِي فُلَانَةَ، وَلَمْ أَفْرِضْ لَهَا صَدَاقًا وَلَمْ أُعْطِهَا شَيْئًا، وَإِنِّي أُشْهِدُكُمْ أَنِّي أَعْطَيْتُهَا مِنْ صَدَاقِهَا سَهْمِي بِخَيْبَرَ. فَأَخَذَتْ سَهْمًا، فَبَاعَتْهُ بِمِائَةِ أَلْفٍ. قَالَ أبو داود: وَزَادَ عُمَرُ بْنُ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ – وَحَدِيثُهُ أَتَمُّ – فِي أَوَّلِ الْحَدِيثِ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "خَيْرُ النِّكَاحِ أَيْسَرُهُ". وَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِلرَّجُلِ.. ثُمَّ سَاقَ مَعْنَاهُ. (د)', 'ഉഖ്ബതുബ്നു ആമിർ(റ): നബി(സ) ഒരാളോട് ചോദിച്ചു: "ഞാൻ ഇന്ന സ്ത്രീയെ വിവാഹം ചെയ്ത് തരുന്നത് നിനക്ക് ഇഷ്ടമാണോ" അയാൾ പറഞ്ഞു: അതെ. സ്ത്രീയോട് ചോദിച്ചു: "ഞാൻ ഇന്നയാളെ നിനക്ക് വിവാഹം ചെയ്ത് തരൽ നീ ഇഷ്ടപ്പെടുന്നുണ്ടോ" അവൾ പറഞ്ഞു: അതെ. അങ്ങനെ അവരെ പരസ്പരം ഇണകളാക്കി. അയാൾ അവളുമായി ബന്ധപ്പെട്ടു. പക്ഷേ, അവൾക്ക് എന്തെങ്കിലും കൊടുക്കുകയോ, മഹ്റ് നിശ്ചയിക്കുകയോ ചെയ്തില്ല. അദ്ദേഹം ഹുദൈബിയ്യ സന്ധിയിൽ പങ്കെടുത്തവരായിരുന്നു. ഹുദൈബിയയിൽ പങ്കെടുത്തവർക്ക് ഖൈബർ യുദ്ധമുതലിൽ നിന്നും ഒരു ഓഹരിയുണ്ടായിരുന്നു. മരണമാസന്നമായപ്പോൾ അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) എനിക്ക് ഇന്നാലിന്ന സ്ത്രീയെ വിവാഹം കഴിപ്പിച്ച് തന്നു. ഞാൻ അവളുടെ മഹ്റ് പറയുകയോ, അവൾക്കെന്തെങ്കിലും കൊടുക്കുകയോ ചെയ്തിട്ടില്ല. ഖൈബറിലെ എന്റെ ഓഹരി അവൾക്ക് മഹ്റായി ഞാൻ കൊടുത്തിരുന്നുവെന്നതിന് നിങ്ങളെ ഞാൻ സാക്ഷികളാക്കുന്നു. അവൾ ആ ഓഹരിയെടുക്കുകയും, ഒരു ലക്ഷത്തിന് വിൽക്കുകയും ചെയ്തു.
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 153, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ فِي بَرِيرَةَ ثَلَاثُ سُنَنٍ: إِحْدَى السُّنَنِ أَنَّهَا أُعْتِقَتْ فَخُيِّرَتْ فِي زَوْجِهَا. وَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْوَلَاءُ لِمَنْ أَعْتَقَ". وَدَخَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَالْبُرْمَةُ تَفُورُ بِلَحْمٍ، فَقُرِّبَ إِلَيْهِ خُبْزٌ وَأُدْمٌ مِنْ أُدْمِ الْبَيْتِ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَلَمْ أَرَ بُرْمَةً فِيهَا لَحْمٌ". فَقَالُوا: بَلَى يَا رَسُولَ اللهِ، ذَلِكَ لَحْمٌ تُصُدِّقَ بِهِ عَلَى بَرِيرَةَ، وَأَنْتَ لَا تَأْكُلُ الصَّدَقَةَ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "هُوَ عَلَيْهَا صَدَقَةٌ وَهُوَ لَنَا هَدِيَّةٌ".
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=2 and h.hadith_no=153), 1, 'وَفِي رِوَايَةٍ: أَرَادَ أَهْلُهَا أَنْ يَبِيعُوهَا وَيَشْتَرِطُوا الْوَلَاءَ، فَذَكَرْتُ ذَلِكَ لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "اشْتَرِيهَا وَأَعْتِقِيهَا، فَإِنَّمَا الْوَلَاءُ لِمَنْ أَعْتَقَ". وَأُعْتِقَتْ، فَخَيَّرَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَاخْتَارَتْ نَفْسَهَا. وَكَانَ يُتَصَدَّقُ عَلَيْهَا، فَتُهْدِي لَنَا مِنْهُ، فَذَكَرْتُ ذَلِكَ لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "كُلُوهُ، فَإِنَّهُ عَلَيْهَا صَدَقَةٌ وَهُوَ لَنَا هَدِيَّةٌ".', 'മറ്റൊരു നിവേദനം: ബരീറയുടെ യജമാനൻമാർ അവളെ രക്ഷാധികാരം അവർക്കായിരിക്കണമെന്ന നിബന്ധനയോടെ വിൽക്കാൻ തീരുമാനിച്ചു. ഈ വിഷയം റസൂൽ(സ)യോട് ഞാൻ പറഞ്ഞപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നീ (ആഇശ) അവളെ വാങ്ങിയിട്ട് മോചിപ്പിക്കുക, നിശ്ചയമായും രക്ഷാധികാരം മോചിപ്പിച്ചവന് മാത്രമാണ്." അവൾ മോചിപ്പിക്കപ്പെടുകയും ഭർത്താവിന്റെ വിഷയത്തിൽ അവൾക്ക് സ്വന്തം ഇഷ്ടം ചെയ്യാനുള്ള അനുമതി നൽകപ്പെടുകയും ചെയ്തു. അവൾ സ്വന്തത്തെ തെരെഞ്ഞെടുത്തു (ഭർത്താവിനെ വേണ്ടെന്നുവെച്ചു). അവൾക്ക് സ്വദഖ ലഭിക്കാറുണ്ടായിരുന്നു. അതിൽ നിന്ന് ഞങ്ങൾക്കവൾ ഹദ്യ ചെയ്യും. ഇക്കാര്യം നബി(സ)യോട് പറഞ്ഞപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളത് ഭക്ഷിക്കുക, നിശ്ചയം, അതവൾക്ക് സ്വദഖയും നമുക്ക് ഹദ്യയുമാണ്."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=2 and h.hadith_no=153), 2, 'وَفِي رِوَايَةٍ: قَالَتْ: اشْتَرَيْتُ بَرِيرَةَ، فَاشْتَرَطَ أَهْلُهَا وَلَاءَهَا، فَذَكَرْتُ ذَلِكَ لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "أَعْتِقِيهَا، فَإِنَّمَا الْوَلَاءُ لِمَنْ أَعْطَى الْوَرِقَ". قَالَتْ: فَأَعْتَقْتُهَا، فَدَعَاهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَخَيَّرَهَا مِنْ زَوْجِهَا. قَالَتْ: لَوْ أَعْطَانِي كَذَا وَكَذَا مَا أَقَمْتُ عِنْدَهُ. فَاخْتَارَتْ نَفْسَهَا، وَكَانَ زَوْجُهَا حُرًّا.', 'മറ്റൊരു നിവേദനത്തിൽ: ആഇശ(റ) പറഞ്ഞു: ഞാൻ ബരീറ(റ)യെ വാങ്ങി. അവളുടെ യജമാനന്മാർ അവളുടെ രക്ഷാധികാരം അവർക്കായിരിക്കണമെന്ന് നിബന്ധനവെച്ചു. ഞാനിത് നബി(സ)യെ അിറയിച്ചു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നീ അവളെ മോചിപ്പിക്കുക, രക്ഷാധികാരം പണം നൽകിയവർക്കാണ്." മഹതി പറയുന്നു: ഞാനവളെ മോചിപ്പിച്ചു. റസൂൽ(സ) അവളെ വിളിച്ചു. ഭർത്താവിന്റെ വിഷയത്തിൽ സ്വന്തം ഇഷ്ടംചെയ്യാൻ അനുമതി നൽകിയപ്പോൾ ബരീറ(റ) പറഞ്ഞു: അയാൾ ഇത്രയിത്ര തന്നാലും ഞാനയാളുടെ അടുത്ത് നിൽക്കില്ല." മഹതിയുടെ ഭർത്താവ് സ്വതന്ത്രനായിരുന്നു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=2 and h.hadith_no=153), 3, 'وَفِي رِوَايَةٍ: قَالَتْ: كَاتَبَتْ بَرِيرَةُ عَلَى نَفْسِهَا بِتِسْعِ أَوَاقٍ فِي كُلِّ سَنَةٍ بِأُوقِيَّةٍ، فَأَتَتْ عَائِشَةَ تَسْتَعِينُهَا، فَقَالَتْ: لَا، إِلَّا أَنْ يَشَاءُوا أَنْ أَعُدَّهَا لَهُمْ عَدَّةً وَاحِدَةً، وَيَكُونَ الْوَلَاءُ لِي. فَذَهَبَتْ بَرِيرَةُ فَكَلَّمَتْ فِي ذَلِكَ أَهْلَهَا فَأَبَوْا عَلَيْهَا، إِلَّا أَنْ يَكُونَ الْوَلَاءُ لَهُمْ. فَجَاءَتْ إِلَى عَائِشَةَ وَجَاءَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عِنْدَ ذَلِكَ، فَقَالَتْ لَهَا مَا قَالَ أَهْلُهَا. فَقَالَتْ: لَا هَا اللهِ إِذًا، إِلَّا أَنْ يَكُونَ الْوَلَاءُ لِي، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا هَذَا". فَقَالَتْ: يَا رَسُولَ اللهِ، إِنَّ بَرِيرَةَ أَتَتْنِي تَسْتَعِينُ بِي عَلَى كِتَابَتِهَا، فَقُلْتُ: لَا، إِلَّا أَنْ يَشَاءُوا أَنْ أَعُدَّهَا لَهُمْ عَدَّةً وَاحِدَةً، وَيَكُونَ الْوَلَاءُ لِي، فَذَكَرْتُ ذَلِكَ لِأَهْلِهَا فَأَبَوْا عَلَيْهَا إِلَّا أَنْ يَكُونَ الْوَلَاءُ لَهُمْ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "ابْتَاعِيهَا وَاشْتَرِطِي لَهُمُ الْوَلَاءَ، فَإِنَّ الْوَلَاءَ لِمَنْ أَعْتَقَ". ثُمَّ قَامَ فَخَطَبَ النَّاسَ فَحَمِدَ اللهَ وَأَثْنَى عَلَيْهِ، ثُمَّ قَالَ: "مَا بَالُ أَقْوَامٍ يَشْتَرِطُونَ شُرُوطًا لَيْسَتْ فِي كِتَابِ اللهِ عَزَّ وَجَلَّ، يَقُولُونَ أَعْتِقْ فُلَانًا وَالْوَلَاءُ لِي، كِتَابُ اللهِ عَزَّ وَجَلَّ أَحَقُّ وَشَرْطُ اللهِ أَوْثَقُ، وَكُلُّ شَرْطٍ لَيْسَ فِي كِتَابِ اللهِ فَهُوَ بَاطِلٌ وَإِنْ كَانَ مِائَةَ شَرْطٍ". فَخَيَّرَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ زَوْجِهَا – وَكَانَ عَبْدًا – فَاخْتَارَتْ نَفْسَهَا. قَالَ عُرْوَةُ: فَلَوْ كَانَ حُرًّا مَا خَيَّرَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (ن)', 'മറ്റൊരു നിവേദനത്തിൽ: ഓരോ വർഷവും ഒരു ഊഖിയ എന്ന നിലക്ക് ഒമ്പത് ഊഖിയക്ക് പകരം ബരീറ സ്വശരീരത്തിന് മോചനക്കരാർ എഴുതി. അങ്ങനെ അവൾ ആഇശ(റ)യോട് സഹായം ചോദിച്ച് വന്നു. മഹതി പറഞ്ഞു: അത് ഞാനവർക്ക് ഒറ്റയടിക്ക് നൽകാൻ അവർ ഇഷ്ടപ്പെട്ടാലല്ലാതെ പറ്റില്ല, രക്ഷാധികാരം എനിക്കാവുകയും വേണം. അങ്ങനെ ബരീറ പോയി യജമാനന്മാരോട് സംസാരിച്ചെങ്കിലും രക്ഷാധികാരം അവർക്ക് ലഭിക്കാത്തതിൽ അവർ വിസമ്മതിച്ചു. അവൾ ആഇശ(റ)യുടെ അടുത്ത് വന്ന സമയത്ത് തന്നെ റസൂൽ(സ)യും കടന്നുവന്നു. ആഇശ(റ)യോട് യജമാനന്മാർ പറഞ്ഞ വിഷയം ബരീറ പറഞ്ഞു. മഹതി പറഞ്ഞു: രക്ഷാധികാരം എനിക്കില്ലെങ്കിൽ പറ്റില്ല. അപ്പോൾ റസൂൽ(സ) ചോദിച്ചു: "എന്താണ് വിഷയം?" മഹതി പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ബരീറ അവളുടെ മോചനക്കരാറിന് സഹായം തേടി എന്നെ സമീപിച്ചു. ഞാൻ പറഞ്ഞു: ഞാനവർക്കത് ഒന്നിച്ച് കൊടുക്കൽ അവർ ഇഷ്ടപ്പെട്ടാലല്ലാതെ എനിക്കത് പറ്റില്ല. രക്ഷാധികാരം എനിക്കാവുകയും വേണം. അവളത് യജമാനരോട് പറഞ്ഞെങ്കിലും രക്ഷാധികാരം അവർക്കില്ലെങ്കിൽ ഇടപാട് വേണ്ടെന്ന് വെച്ചിരിക്കുകയാണ്. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "നീ അവളെ വാങ്ങുകയും രക്ഷാധികാരം അവരോട് ഉപാധിവെക്കുകയും ചെയ്യുക. നിശ്ചയമായും രക്ഷാധികാരം മോചിപ്പിച്ചർക്കാണ്." അങ്ങനെ റസൂൽ(സ) എഴുന്നേറ്റ് നിന്ന് ജനങ്ങളോട് പ്രസംഗിക്കാൻ തുടങ്ങി. അല്ലാഹുവിനെ സ്തുതിക്കുകയും പുകഴ്തുകയും ചെയ്തു, എന്നിട്ട് പറഞ്ഞു: "അല്ലാഹുവിന്റെ ഗ്രന്ഥത്തിലില്ലാത്ത നിബന്ധനകളെ ഉപാധിയാക്കുന്നവരുടെ കഥയെന്താണ്. നീ ഇന്നയാളെ സ്വതന്ത്രനാക്കൂ, രക്ഷാധികാരം എനിക്കാണ് എന്നവർ പറയുന്നു. അനുസരിക്കപ്പെടാൻ ഏറ്റവും ബന്ധപ്പെട്ടത് അല്ലാഹുവിന്റെ ഗ്രന്ഥമാണ്, അല്ലാഹുവിന്റെ ഉപാധിയാണ് ഏറ്റവും ദൃഢമായത്. അല്ലാഹുവിന്റെ ഗ്രന്ഥത്തിലില്ലാത്ത ഏതൊരു ഉപാധിയും അത് നൂറ് ഉപാധിയാണെങ്കിലും നിലനിൽക്കുന്നതല്ല." അങ്ങനെ റസൂൽ(സ) ബരീറക്ക് ഭർത്താവിന്റെ കാര്യത്തിൽ തെരെഞ്ഞെടുക്കാനുള്ള അവസരം നൽകി. ഭർത്താവ് അടിമയായിരുന്നു. അവൾ സ്വന്തത്തെ തെരഞ്ഞെടുത്തു. ഉർവ(റ) പറഞ്ഞു: ഭർത്താവ് സ്വതന്ത്രനായിരുന്നുവെങ്കിൽ റസൂൽ(സ) അവൾക്ക് തെരഞ്ഞെടുക്കാനുള്ള അവസരം നൽകില്ലായിരുന്നു. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 154, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ زَوْجُ بَرِيرَةَ حُرًّا، فَخَيَّرَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (ت)', 'ആഇശ(റ): ബരീറയുടെ ഭർത്താവ് സ്വതന്ത്രനായിരുന്നു. അത് കൊണ്ടാണ് റസൂൽ(സ) അവർക്ക് ഭർത്താവിന്റെ വിഷയത്തിൽ തെരഞ്ഞെടുക്കുവാനുള്ള അവസരം നൽകിയത്. (തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 91, 92, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 155, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ زَوْجَ بَرِيرَةَ كَانَ عَبْدًا أَسْوَدَ لِبَنِي الْمُغِيرَةِ، يَوْمَ أُعْتِقَتْ بَرِيرَةُ – وَاللهِ – لَكَأَنِّي بِهِ فِي طُرُقِ الْمَدِينَةِ وَنَوَاحِيهَا، وَإِنَّ دُمُوعَهُ لَتَسِيلُ عَلَى لِحْيَتِهِ، يَتَرَضَّاهَا لِتَخْتَارَهُ، فَلَمْ تَفْعَلْ. حَسَنٌ صَحِيحٌ. (ت)', 'ഇബ്നുഅബ്ബാസ്(റ): ബരീറയുടെ ഭർത്താവ് ബനൂ മുഗീറക്കാരുടെ കറുത്ത അടിമയായിരുന്നു. അല്ലാഹുവിനെ തന്നെ സത്യം. ബരീറ സ്വതന്ത്രയാക്കപ്പെട്ട ദിവസം, മദീനയുടെ വഴിയോരങ്ങളിൽ അയൾ നടക്കുന്നത് ഞാൻ കാണുന്നു. കണ്ണുനീർ തന്റെ താടിയിലൂടെ ഒലിച്ചിറങ്ങുന്നു. അവൾ തന്നെ തെരഞ്ഞെടുക്കണമെന്ന് അവർ ആഗ്രഹിക്കുന്നു. പക്ഷേ, അവളത് ചെയ്തില്ല. (തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 92, 92, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 156, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ زَوْجُ بَرِيرَةَ عَبْدًا يُقَالُ لَهُ مُغِيثٌ، كَأَنِّي أَنْظُرُ إِلَيْهِ يَطُوفُ خَلْفَهَا وَيَبْكِي، وَدُمُوعُهُ تَسِيلُ عَلَى خَدِّهِ. فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِلْعَبَّاسِ: "يَا عَبَّاسُ، أَلَا تَعْجَبُ مِنْ حُبِّ مُغِيثٍ بَرِيرَةَ، وَمِنْ بُغْضِ بَرِيرَةَ مُغِيثًا". فَقَالَ لَهَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَوْ رَاجَعْتِيهِ، فَإِنَّهُ أَبُو وَلَدِكِ". قَالَتْ: يَا رَسُولَ اللهِ، تَأْمُرُنِي؟ قَالَ: "إِنَّمَا أَشْفَعُ". قَالَتْ: لَا حَاجَةَ لِي فِيهِ. (خ,د,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ബരീറയുടെ ഭർത്താവ് ''മുഗീസ്'' എന്ന് പേരുള്ള അടിമയായിരുന്നു. അവളുടെ പിന്നിൽ അവൻ കരഞ്ഞ് നടന്ന് കൊണ്ടിരിക്കുന്നത് ഞാനിങ്ങനെ കാണുകയാണ്, കണ്ണുനീർ തന്റെ കവിളിലൂടെ ഒലിച്ചുകൊണ്ടിരിക്കുകയാണ്. അപ്പോൾ നബി(സ) അബ്ബാസ്(റ)വിനോട് പറഞ്ഞു: "അബ്ബാസേ, മുഗീസിന് ബരീറയോടുള്ള സ്നേഹത്തിലും ബരീറക്ക് മുഗീസിനോടുള്ള ദേഷ്യത്തിലും നീ അത്ഭുതപ്പെടുന്നുണ്ടോ?" നബി(സ) ബരീറയോട് പറഞ്ഞു: "നീ അയാളെ മടക്കിയെടുത്തിരുന്നെങ്കിൽ നന്നായിരുന്നു, കാരണം അയാൾ നിന്റെ കുട്ടികളുടെ പിതാവല്ലേ." അവൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അങ്ങ് എന്നോട് കൽപ്പിക്കുകയാണോ. റസൂൽ(സ) പറഞ്ഞു: "ഞാൻ ശുപാർശ ചെയ്യുക മാത്രമാണ്." അവൾ പറഞ്ഞു: എനിക്കയാളെ ആവശ്യമില്ല. (ബു,ദ,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ','د','ن','جه']::text[], array['ബു','ദ','ന','ജ']::text[], null, null, 92, 92, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 157, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: أُمِرَتْ بَرِيرَةُ أَنْ تَعْتَدَّ بِثَلَاثِ حِيَضٍ. (جه)', 'ആഇശ(റ): മൂന്ന് ആർത്തവ കാലം ഇദ്ദയിരിക്കാൻ ബരീറ(റ) കൽപ്പിക്കപ്പെട്ടു. (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 92, 92, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 158, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا رَفَّأَ قَالَ: "بَارَكَ اللهُ لَكُمْ، وَبَارَكَ عَلَيْكُمْ، وَجَمَعَ بَيْنَكُمَا فِي خَيْرٍ". (د,ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) വിവാഹം കഴിച്ചവനെ ''അല്ലാഹു നിങ്ങൾക്ക് അനുഗ്രഹം ചെയ്യട്ടെ, നിങ്ങൾക്കുണ്ടാകുന്നതിൽ അനുഗ്രഹം ചെയ്യട്ടേ, നിങ്ങൾക്കിടയിൽ നന്മയെ അല്ലാഹു ഒരുമിച്ചുകൂട്ടട്ടെ'' എന്ന് പറഞ്ഞായിരുന്നു ആശംസിച്ചിരുന്നത്. (ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 92, 92, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 159, 'عَنْ عَقِيلِ بْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ تَزَوَّجَ امْرَأَةً مِنْ بَنِي جُشَمَ، فَقَالُوا: بِالرِّفَاءِ وَالْبَنِينَ. فَقَالَ: لَا تَقُولُوا هَكَذَا، وَلَكِنْ قُولُوا كَمَا قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اللَّهُمَّ بَارِكْ لَهُمْ وَبَارِكْ عَلَيْهِمْ". (جه)', 'അഖീലുബ്നു അബീത്വാലിബ്(റ): അദ്ദേഹം ബനൂ ജുശമിൽപെട്ട ഒരു സ്ത്രീയെ വിവാഹം കഴിച്ചപ്പോൾ അവർ പറഞ്ഞു: "സന്താനവും ക്ഷേമാഐശ്വര്യവും ഉണ്ടാകട്ടെ." അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: നിങ്ങളിങ്ങനെ പറയരുത്. മറിച്ച് റസൂൽ(സ) പറഞ്ഞ പോലെ നിങ്ങൾ പറയുക: "അല്ലാഹുവേ, അവർക്കും, അവർക്കുണ്ടാകുന്നതിലും നീ അനുഗ്രഹം ചൊരിയണേ." (ജ)', 'عَقِيلِ بْنِ أَبِي طَالِبٍ', 'അഖീലുബ്നു അബീത്വാലിബ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 92, 93, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 160, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: تَزَوَّجَنِي النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي شَوَّالٍ، وَبَنَى بِي فِي شَوَّالٍ فَأَيُّ نِسَائِهِ كَانَ أَحْظَى عِنْدَهُ مِنِّي! وَكَانَتْ عَائِشَةُ تَسْتَحِبُّ أَنْ تُدْخِلَ نِسَاءَهَا فِي شَوَّالٍ. (م,ت,ن,جه)', 'ആഇശ(റ): നബി(സ) എന്നെ വിവാഹം കഴിച്ചത് ശവ്വാൽ മാസത്തിലാണ്, വീട് കൂടിയതും ശവ്വാൽ മാസത്തിലാണ്. റസൂൽ(സ)യുടെ ഭാര്യമാരിൽ റസൂലിന്റെ അടുത്ത് എന്നേക്കാൾ ഭാഗ്യം സിദ്ധിച്ച മറ്റേത് ഭാര്യയാണുള്ളത്! ആഇശ(റ) തന്റെ സ്ത്രീകളെ (സഹോദരിമാരുടെ പെൺമക്കളെ) ശവ്വാലിൽ (ഭർത്താകക്കൻമാരുടെ അടുത്തേക്ക്) പ്രവേശിപ്പിക്കുന്നത് ഇഷ്ടപ്പെട്ടിരുന്നു. (മു,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','ت','ن','جه']::text[], array['മു','തു','ന','ജ']::text[], null, null, 93, 93, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 161, 'عَنِ الْحَارِثِ بْنِ هِشَامٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَزَوَّجَ أُمَّ سَلَمَةَ فِي شَوَّالٍ، وَجَمَعَهَا إِلَيْهِ فِي شَوَّالٍ. [ز: في إسناده مدلس عنعنه] (جه)', 'ഹാരിസുബ്നു ഹിശാം(റ): നബി(സ) ഉമ്മുസലമ(റ)യെ വിവാഹം കഴിച്ചത് ശവ്വാൽ മാസത്തിലാണ്, തന്നിലേക്ക് കൂട്ടിയതും ശവ്വാലിലാണ്. (ജ)', 'الْحَارِثِ بْنِ هِشَامٍ', 'ഹാരിസുബ്നു ഹിശാം(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده مدلس عنعنه', null, 93, 93, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 162, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: تَزَوَّجَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَنَا بِنْتُ سِتٍّ، وَدَخَلَ عَلَيَّ وَأَنَا بِنْتُ تِسْعِ سِنِينَ، وَكُنْتُ أَلْعَبُ بِالْبَنَاتِ. وفي رواية: قَالَتْ: تَزَوَّجَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهِيَ بِنْتُ سِتِّ سِنِينَ، وَبَنَى بِهَا وَهِيَ بِنْتُ تِسْعٍ. (ن)', 'ആഇശ(റ): എനിക്ക് ആറ് വയസ്സുള്ളപ്പോഴാണ് റസൂൽ(സ) എന്നെ വിവാഹം കഴിച്ചത്. ഞാനുമായി വീട് കൂടിയത് എനിക്ക് ഒമ്പത് വയസ്സുള്ളപ്പോഴും. ഞാൻ പെൺകുട്ടികളുടെ കൂട്ടത്തിൽ കളിക്കുമായിരുന്നു. മറ്റൊരു നിവേദനം: മഹതിക്ക് ആറ് വയസ്സുള്ളപ്പോഴാണ് റസൂൽ(സ) മഹതിയെ വിവാഹം കഴിച്ചത്. മഹതിയുമായി വീട് കൂടിയത് ഒമ്പതുകാരിയായപ്പോഴാണ്. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 93, 93, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=62 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=2 and h.hadith_no=162), 1, 'وَفِي رِوَايَةٍ: قَالَتْ: تَزَوَّجَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهِيَ بِنْتُ سِتِّ سِنِينَ، وَبَنَى بِهَا وَهِيَ بِنْتُ تِسْعٍ. (ن)', 'മറ്റൊരു നിവേദനം: മഹതിക്ക് ആറ് വയസ്സുള്ളപ്പോഴാണ് റസൂൽ(സ) മഹതിയെ വിവാഹം കഴിച്ചത്. മഹതിയുമായി വീട് കൂടിയത് ഒമ്പതുകാരിയായപ്പോഴാണ്. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 163, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ غَزَا خَيْبَرَ، فَصَلَّيْنَا عِنْدَهَا الْغَدَاةَ بِغَلَسٍ، فَرَكِبَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَرَكِبَ أَبُو طَلْحَةَ، وَأَنَا رَدِيفُ أَبِي طَلْحَةَ، فَأَخَذَ نَبِيُّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي زُقَاقِ خَيْبَرَ، وَإِنَّ رُكْبَتِي لَتَمَسُّ فَخِذَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَإِنِّي لَأَرَى بَيَاضَ فَخِذِ نَبِيِّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا دَخَلَ الْقَرْيَةَ قَالَ: "اللهُ أَكْبَرُ، خَرِبَتْ خَيْبَرُ، إِنَّا إِذَا نَزَلْنَا بِسَاحَةِ قَوْمٍ فَسَاءَ صَبَاحُ الْمُنْذَرِينَ". قَالَهَا ثَلَاثَ مَرَّاتٍ، قَالَ: وَخَرَجَ الْقَوْمُ إِلَى أَعْمَالِهِمْ، فَقَالُوا: مُحَمَّدٌ وَالْخَمِيسُ. وَأَصَبْنَاهَا عَنْوَةً، فَجُمِعَ السَّبْيُ، فَجَاءَ دِحْيَةُ فَقَالَ: يَا نَبِيَّ اللهِ، أَعْطِنِي جَارِيَةً مِنَ السَّبْيِ. قَالَ: "اذْهَبْ فَخُذْ جَارِيَةً". فَأَخَذَ صَفِيَّةَ بِنْتَ حُيَيٍّ، فَجَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا نَبِيَّ اللهِ، أَعْطَيْتَ دِحْيَةَ صَفِيَّةَ بِنْتَ حُيَيٍّ سَيِّدَةَ قُرَيْظَةَ وَالنَّضِيرِ، مَا تَصْلُحُ إِلَّا لَكَ. قَالَ: "ادْعُوهُ بِهَا". فَجَاءَ بِهَا، فَلَمَّا نَظَرَ إِلَيْهَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "خُذْ جَارِيَةً مِنَ السَّبْيِ غَيْرَهَا". قَالَ: وَإِنَّ نَبِيَّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَعْتَقَهَا وَتَزَوَّجَهَا. فَقَالَ لَهُ ثَابِتٌ: يَا أَبَا حَمْزَةَ، مَا أَصْدَقَهَا؟ قَالَ: نَفْسَهَا، أَعْتَقَهَا وَتَزَوَّجَهَا. قَالَ: حَتَّى إِذَا كَانَ بِالطَّرِيقِ جَهَّزَتْهَا لَهُ أُمُّ سُلَيْمٍ فَأَهْدَتْهَا إِلَيْهِ مِنَ اللَّيْلِ، فَأَصْبَحَ عَرُوسًا. قَالَ: "مَنْ كَانَ عِنْدَهُ شَيْءٌ فَلْيَجِئْ بِهِ". قَالَ: وَبَسَطَ نِطَعًا، فَجَعَلَ الرَّجُلُ يَجِيءُ بِالْأَقِطِ، وَجَعَلَ الرَّجُلُ يَجِيءُ بِالتَّمْرِ، وَجَعَلَ الرَّجُلُ يَجِيءُ بِالسَّمْنِ، فَحَاسُوا حَيْسَةً، فَكَانَتْ وَلِيمَةَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (ن)', 'അനസ്(റ): റസൂൽ(സ) ഖൈബറിൽ യുദ്ധം ചെയ്തു. അതിനടുത്ത് വെച്ച് ഇരുട്ടിലാണ് ഞങ്ങൾ സുബ്ഹി നിസ്കരിച്ചത്. അങ്ങനെ നബി(സ)യും അബൂത്വൽഹ(റ)വും വാഹനപ്പുറത്ത് കയറി, ഞാൻ അബൂത്വൽഹയുടെ പിന്നിലിരിക്കുകയാണ്, അങ്ങനെ ഖൈബറിന്റെ തെരുവീഥിയിലൂടെ നബി(സ) സഞ്ചരിക്കാൻ തുടങ്ങി. എന്റെ കാൽമുട്ട് റസൂൽ(സ)യുടെ തുടയിൽ തട്ടുന്നുണ്ട്, നബി(സ)യുടെ തുടയുടെ വെളുപ്പ് ഞാൻ കാണുന്നുണ്ട്. അങ്ങനെ ആ ഗ്രാമത്തിൽ കയറിയപ്പോൾ നബി(സ) മൂന്ന് പ്രാവശ്യം പറഞ്ഞു: "അല്ലാഹുവാണ് ഏറ്റവും വലിയവൻ, ഖൈബറിതാ ശൂന്യമായിരിക്കുന്നു, ഞങ്ങൾ ആരുടെയെങ്കിലും കളത്തിൽ പ്രവേശിച്ചാൽ ഭയപ്പെടുത്തപ്പെട്ടവന്റെ പ്രഭാതം വിഷമകരം തന്നെ." റസൂൽ(സ) ഇത് മൂന്ന് പ്രാവശ്യം പറഞ്ഞു. നിവേദകൻ പറയുന്നു: അങ്ങനെ ജനങ്ങളെല്ലാം അവരുടെ കാര്യങ്ങൾ ചെയ്യാൻ പോയി. അവർ പറഞ്ഞു: മുഹമ്മദും(സ) സംഘവുമിതാ. നിർബന്ധിച്ച് തന്നെ ഗ്രാമത്തെ ഞങ്ങളെത്തിച്ചു, അടിമകളെ ഒരുമിച്ചുകൂട്ടി. ദിഹ്യ(റ) വന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ പ്രവാചകരേ, അടിമകളിൽ നിന്ന് ഒരു പെണ്ണിനെ എനിക്ക് തരൂ. നബി(സ) പറഞ്ഞു: "നീ പോയി ഒരു പെണ്ണിനെ എടുക്ക്." ദിഹ്യ(റ) പിടിച്ചത് സ്വഫിയ്യ ബിൻതു ഹുയയ്യ(റ)യെയായിരുന്നു, അങ്ങനെ ഒരാൾ വന്ന് റസൂൽ(സ)യോട് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഖുറൈളയുടെയും നളീറിന്റെയും നേതാവായ സ്വഫിയ്യ ബിൻത് ഹുയയ്യിനെ അങ്ങ് കൊടുത്തുവല്ലേ. അവൾ അങ്ങേക്കല്ലാതെ യോജിക്കുകയില്ല. നബി(സ) പറഞ്ഞു: "ദിഹ്യയോട് അവളെ കൊണ്ടുവരാൻ പറയൂ." ദിഹ്യ(റ) അവളെ കൊണ്ടുവന്നു. നബി(സ) മഹതിയിലേക്ക് നോക്കിയിട്ട് അദ്ദേഹത്തോട് പറഞ്ഞു: "നീ വേറൊരുത്തിയെ എടുത്തോളൂ." അനസ്(റ) പറയുന്നു: നബി(സ) മഹതിയെ സ്വതന്ത്രയാക്കുകയും വിവാഹം കഴിക്കുകയും ചെയ്തു. സാബിത്(റ) അനസ്(റ)വിനോട് ചോദിച്ചു: അബൂഹംസാ, നബി(സ) മഹതിക്ക് എന്താണ് മഹ്റ് കൊടുത്തത്? അനസ്(റ) പറഞ്ഞു: മഹതിയുടെ ശരീരത്തെ, അവളെ സ്വതന്ത്രയാക്കി വിവാഹം ചെയ്തു. അനസ്(റ) പറയുന്നു: അങ്ങനെ വഴിയിലായിരിക്കെ ഉമ്മുസുലൈം(റ) മഹതിയെ റസൂൽ(സ)ക്ക് വേണ്ടി അണിയിച്ചൊരുക്കുകയും രാത്രിയിൽ നബി(സ)ക്ക് ഏൽപ്പിച്ച് കൊടുക്കുകയും ചെയ്തു. അങ്ങനെ മണവാളനായി, നബി(സ) പറഞ്ഞു: "എന്തെങ്കിലും കൈവശമുള്ളവൻ അത് കൊണ്ട് വരട്ടെ." നബി(സ) ഊറക്കിടപ്പെട്ടൊരു തോൽ വിരിച്ചു, ചിലർ പാൽക്കട്ടി കൊണ്ടുവന്നു. ചിലർ കാരക്ക കൊണ്ടുവന്നു. ചിലർ നെയ്യ് കൊണ്ടുവന്നു. അവർ അത് കൊണ്ടൊരു വിഭവമുണ്ടാക്കി. അതായിരുന്നു റസൂൽ(സ)യുടെ വിവാഹ സദ്യ. (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 93, 94, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=63 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 164, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَقَامَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَيْنَ خَيْبَرَ وَالْمَدِينَةِ ثَلَاثًا يُبْنِي بِصَفِيَّةَ بِنْتِ حُيَيٍّ، فَدَعَوْتُ الْمُسْلِمِينَ إِلَى وَلِيمَتِهِ، فَمَا كَانَ فِيهَا مِنْ خُبْزٍ وَلَا لَحْمٍ، أَمَرَ بِالْأَنْطَاعِ وَأَلْقَى عَلَيْهَا مِنَ التَّمْرِ وَالْأَقِطِ وَالسَّمْنِ، فَكَانَتْ وَلِيمَتَهُ، فَقَالَ الْمُسْلِمُونَ: إِحْدَى أُمَّهَاتِ الْمُؤْمِنِينَ، أَوْ مِمَّا مَلَكَتْ يَمِينُهُ. فَقَالُوا: إِنْ حَجَبَهَا فَهِيَ مِنْ أُمَّهَاتِ الْمُؤْمِنِينَ، وَإِنْ لَمْ يَحْجُبْهَا فَهِيَ مِمَّا مَلَكَتْ يَمِينُهُ. فَلَمَّا ارْتَحَلَ وَطَّأَ لَهَا خَلْفَهُ، وَمَدَّ الْحِجَابَ بَيْنَهَا وَبَيْنَ النَّاسِ. (ن)', 'അനസ്(റ): നബി(സ) സ്വഫിയ്യയോട് കൂടെ വീട് കൂടാൻ വേണ്ടി മദീനക്കും ഖൈബറിനുമിടയിൽ മൂന്ന് ദിവസം നിന്നു. നബി(സ)യുടെ വിവാഹ സദ്യയിലേക്ക് ഞാനാണ് മുസ്‌ലിമീങ്ങളെ ക്ഷണിച്ചത്. ഇറച്ചിയും പത്തിരിയുമുണ്ടായിരുന്നില്ല. ഈറക്കിടപ്പെട്ട തോൽ വിരിക്കാൻ പറഞ്ഞു. കാരക്കയും പാൽകട്ടിയും നെയ്യും അതിൽ കൊണ്ടിടപ്പെട്ടു. അതായിരുന്നു നബി(സ)യുടെ വിവാഹ സദ്യ. അപ്പോൾ മുസ്‌ലിംകൾ പറഞ്ഞു: ഉമ്മഹാതുൽ മുഅ്മിനീങ്ങളിൽപെട്ട ഒരു മഹതി, അല്ലെങ്കിൽ ഉടമപ്പെടുത്തപ്പെട്ടവളൾ(അടിമ). അവർ പറഞ്ഞു: നബി(സ) മഹതിക്ക് ഹിജാബ് ഇട്ടാൽ മഹതി ഉമ്മഹാതുൽ മുഅ്മിനീങ്ങളിൽ പെട്ടവരായിരിക്കും. ഹിജാബ് ഇട്ടില്ലെങ്കിൽ അടിമസ്ത്രീകളിൽ പെട്ടവളായിരിക്കും. യാത്ര തുടങ്ങിയപ്പോൾ നബി(സ) മഹതിയെ പിന്നിലിരുത്തി, മഹതിയുടെയും ജനങ്ങളുടെയും ഇടയിൽ മറയിടുകയും ചെയ്തു. (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 94, 95, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=63 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 165, 'عَنْ مُحَمَّدِ بْنِ حَاطِبٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "فَصْلُ مَا بَيْنَ الْحَلالِ وَالْحَرَامِ الدُّفُّ وَالصَّوْتُ فِي النِّكَاحِ". وفي رواية: "إِنَّ فَصْلَ مَا بَيْنَ الْحَلالِ وَالْحَرَامِ الصَّوْتُ". (ت,ن,جه)', 'മുഹമ്മദുബ്നു ഹാത്വിബ്(റ): "തിരുദൂതർ(സ) പറഞ്ഞു: "വിവാഹത്തിൽ ഹലാലും ഹറാമും വേർതിരിക്കുന്നത് പരസ്യം ചെയ്യലും ദഫുമാണ്." മറ്റൊരു നിവേദനം: ഹലാലും ഹറാമും വേർതിരിക്കുന്നത് ശബ്ദമാണ്." (തു,ന,ജ)', 'مُحَمَّدِ بْنِ حَاطِبٍ', 'മുഹമ്മദുബ്നു ഹാത്വിബ്(റ)', null, null, array['ت','ن','جه']::text[], array['തു','ന','ജ']::text[], null, null, 95, 95, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=2 and h.hadith_no=165), 1, 'وَفِي رِوَايَةٍ: "إِنَّ فَصْلَ مَا بَيْنَ الْحَلالِ وَالْحَرَامِ الصَّوْتُ". (ت,ن,جه)', 'മറ്റൊരു നിവേദനം: ഹലാലും ഹറാമും വേർതിരിക്കുന്നത് ശബ്ദമാണ്." (തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 166, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَعْلِنُوا هَذَا النِّكَاحَ، وَاجْعَلُوهُ فِي الْمَسَاجِدِ، وَاضْرِبُوا عَلَيْهِ بِالدُّفُوفِ". حَسَنٌ. (ت)', 'ആഇശ(റ): റസൂൽ(സ) പറഞ്ഞു: "വിവാഹം നിങ്ങൾ പരസ്യം ചെയ്യുക. അത് പള്ളിയിൽ വെച്ചാക്കുക, അതിനുവേണ്ടി നിങ്ങൾ ദഫ്മുട്ടുകയും ചെയ്യുക." (തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 95, 95, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 167, 'عَنِ الرُّبَيِّعِ بِنْتِ مُعَوِّذٍ رَضِيَ اللهُ عَنْهُ قَالَتْ: جَاءَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَدَخَلَ عَلَيَّ غَدَاةَ بُنِيَ بِي، فَجَلَسَ عَلَى فِرَاشِي كَمَجْلِسِكَ مِنِّي، وَجُوَيْرِيَاتٌ لَنَا يَضْرِبْنَ بِدُفُوفِهِنَّ وَيَنْدُبْنَ مَنْ قُتِلَ مِنْ آبَائِي يَوْمَ بَدْرٍ، إِلَى أَنْ قَالَتْ إِحْدَاهُنَّ: وَفِينَا نَبِيٌّ يَعْلَمُ مَا فِي غَدٍ. فَقَالَ لَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اسْكُتِي عَنْ هَذِهِ، وَقُولِي الَّذِي كُنْتِ تَقُولِينَ قَبْلَهَا". حَسَنٌ صَحِيحٌ. (خ,د,ت)', 'റുബയ്യിഅ് ബിൻത് മുഅവ്വിദ്(റ): ഞാൻ വീട് കൂടപ്പെട്ട ദിവസം രാവിലെ നബി(സ) എന്റെ അടുത്ത് വന്നു, നീ ഇരിക്കുന്നതുപോലെ എന്റെ വിരിപ്പിലിരുന്നു, കുറച്ച് യുവതികൾ ദഫ്മുട്ടുകയും ബദ്ർ ദിവസം കൊല്ലപ്പെട്ട തന്റെ പിതാമഹൻമാരെ പുകഴ്ത്തിക്കൊണ്ടിരിക്കുകയും ചെയ്തു. എത്രത്തോളമെന്നാൽ അവരിലൊരുത്തി പറഞ്ഞു: നാളെയുണ്ടാകുന്ന വിഷയങ്ങളറിയുന്ന ഒരു നബി ഞങ്ങളിലുണ്ട്. അവളോട് റസൂൽ(സ) പറഞ്ഞു: "ഇതിനെക്കുറിച്ച് സംസാരിക്കരുത്, മുമ്പ് പറഞ്ഞിരുന്നത് തന്നെ പറയുക." (ബു,ദ,തു)', 'الرُّبَيِّعِ بِنْتِ مُعَوِّذٍ', 'റുബയ്യിഅ് ബിൻത് മുഅവ്വിദ്(റ)', null, null, array['خ','د','ت']::text[], array['ബു','ദ','തു']::text[], null, null, 95, 95, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 168, 'عَنْ عَامِرِ بْنِ سَعْدٍ الْبَجَلِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: دَخَلْتُ عَلَى قُرَظَةَ بْنِ كَعْبٍ وَأَبِي مَسْعُودٍ الأَنْصَارِيِّ فِي عُرْسٍ، وَإِذَا جَوَارٍ يُغَنِّينَ، فَقُلْتُ: أَنْتُمَا صَاحِبَا رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَمِنْ أَهْلِ بَدْرٍ، يُفْعَلُ هَذَا عِنْدَكُمْ؟ فَقَالَ: اجْلِسْ إِنْ شِئْتَ فَاسْمَعْ مَعَنَا، وَإِنْ شِئْتَ اذْهَبْ، قَدْ رُخِّصَ لَنَا فِي اللَّهْوِ عِنْدَ الْعُرْسِ. (ن)', 'ആമിറുബ്നു സഅ്ദിനിൽ ബജലീ(റ): ഒരു വിവാഹത്തിൽ വെച്ച് ഖറളതുബ്നു കഅ്ബ്(റ)വിന്റെയും അബൂമസ്ഊദിൽ അൻസാരി(റ)വിന്റെയും അടുത്തേക്ക് ഞാൻ ചെന്നു. അവിടെ കുറച്ച യുവതികൾ പാട്ടു പാടുന്നുണ്ട്. ഞാൻ ചോദിച്ചു: നിങ്ങൾ രണ്ടുപേരും റസൂൽ(സ)യുടെ അനുചരരും ബദ്റിൽ പങ്കെടുത്തവരുമല്ലേ, നിങ്ങളുടെ സാന്നിധ്യത്തിലാണല്ലോ ഇത് നടക്കുന്നത്? അവർ പറഞ്ഞു: നിനക്കിഷ്ടമെങ്കിൽ ഞങ്ങളുടെ കൂടെ ഇരുന്ന് കേട്ടോളൂ, വേണമെങ്കിൽ നിനക്ക് പോകുകയും ചെയ്യാം. വിവാഹദിനത്തിലുള്ള വിനോദത്തിൽ അല്ലാഹുവിന്റെ റസൂൽ(സ) ഞങ്ങൾക്ക് ഇളവ് ചെയ്ത് തന്നിട്ടുണ്ട്. (ന)', 'عَامِرِ بْنِ سَعْدٍ الْبَجَلِيِّ', 'ആമിറുബ്നു സഅ്ദിനിൽ ബജലീ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 95, 96, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 169, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: دَخَلَ عَلَيَّ أَبُو بَكْرٍ، وَعِنْدِي جَارِيَتَانِ مِنْ جَوَارِي الأَنْصَارِ، تُغَنِّيَانِ بِمَا تَقَاوَلَتْ بِهِ الأَنْصَارُ فِي يَوْمِ بُعَاثٍ، قَالَتْ: وَلَيْسَتَا بِمُغَنِّيَتَيْنِ، فَقَالَ أَبُو بَكْرٍ رَضِيَ اللهُ عَنْهُ: أَبِمَزْمُورِ الشَّيْطَانِ فِي بَيْتِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ وَذَلِكَ فِي يَوْمِ عِيدِ الْفِطْرِ. فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَا أَبَا بَكْرٍ، إِنَّ لِكُلِّ قَوْمٍ عِيدًا، وَهَذَا عِيدُنَا". (ق,جه)', 'ആഇശ(റ): അൻസാറുകളിൽ പെട്ട രണ്ട് യുവതികൾ എന്റെ അടുത്തുണ്ടായിരിക്കെ അബൂബക്കർ(റ) കടന്നുവന്നു. ''ബുഗാസ് ദിന''ത്തിൽ അൻസാറുകൾ പാടിയിരുന്ന ഗാനം അവർ പാടിക്കൊണ്ടിരിക്കുകയാണ്. മഹതി പറഞ്ഞു: അവർ പാട്ടുകാരികളല്ല. അപ്പോൾ അബൂബക്കർ(റ) പറഞ്ഞു: നബി(സ)യുടെ വീട്ടിലാണോ ശൈത്വാന്റെ കീർത്തനം? അത് ചെറിയ പെരുന്നാൾ ദിനത്തിലായിരുന്നു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അബൂബക്കറേ, ഓരോ വിഭാഗത്തിനും ഓരോ ആഘോഷമുണ്ട്, ഇന്നാണ് നമ്മുടെ ആഘോഷം." (ബു,മു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 96, 96, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 170, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَرَّ بِبَعْضِ الْمَدِينَةِ، فَإِذَا هُوَ بِجَوَارٍ يَضْرِبْنَ بِدُفِّهِنَّ وَيَتَغَنَّيْنَ وَيَقُلْنَ:
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 171, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَنْكَحَتْ عَائِشَةُ ذَاتَ قَرَابَةٍ لَهَا مِنَ الأَنْصَارِ، فَجَاءَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "أَهَدَيْتُمُ الْفَتَاةَ". قَالُوا: نَعَمْ. قَالَ: "أَرْسَلْتُمْ مَعَهَا مَنْ يُغَنِّي". قَالَتْ: لا. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ الأَنْصَارَ قَوْمٌ فِيهِمْ غَزَلٌ، فَلَوْ بَعَثْتُمْ مَعَهَا مَنْ يَقُولُ: أَتَيْنَاكُمْ أَتَيْنَاكُمْ، فَحَيَّانَا وَحَيَّاكُمْ". (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ആഇശ(റ) അൻസാറുകളിൽ തന്റെ ബന്ധത്തിൽ പെട്ട ഒരു സ്ത്രീയെ വിവാഹം കഴിപ്പിച്ചു. അപ്പോൾ റസൂൽ(സ) വന്ന് ചോദിച്ചു: "നിങ്ങൾ ആ യുവതിക്ക് വല്ല ഹദ്യയും നൽകിയോ." അവർ പറഞ്ഞു: അതെ. റസൂൽ(സ) ചോദിച്ചു: "അവളുടെ കൂടെ പാട്ടപാടുന്നവരെ അയച്ചോ." മഹതി പറഞ്ഞു: ഇല്ല. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "വർണ്ണിച്ച് പാടാനറിയുന്നവരുള്ള ജനതയാണ് അൻസാറുകൾ, ''ഞങ്ങളിതാ വന്നിരിക്കുന്നു, നിങ്ങൾക്കും ഞങ്ങൾക്കും ദീർഘായുസ്സ് നേരുന്നു.'' എന്ന പാടുന്ന ആരെയെങ്കിലും അയക്കാമായിരുന്നു." (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 96, 96, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 172, 'عَنْ مُجَاهِدٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ مَعَ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا، فَسَمِعَ صَوْتَ طَبْلٍ، فَأَدْخَلَ إِصْبَعَيْهِ فِي أُذُنَيْهِ ثُمَّ تَنَحَّى، حَتَّى فَعَلَ ذَلِكَ ثَلاثَ مَرَّاتٍ، ثُمَّ قَالَ: هَكَذَا فَعَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (جه)', 'മുജാഹിദ്(റ): ഞാൻ ഇബ്നു ഉമർ(റ)വിന്റെ കൂടെയായിരിക്കെ, അദ്ദേഹം ഒരു ചെണ്ടയുടെ ശബ്ദം കേട്ടു. അദ്ദേഹം തന്റെ രണ്ട് വിരലുകളെടുത്ത് ചെവിയിൽ വെക്കുകയും അവിടന്ന് അകന്നുപോകുകയും ചെയ്തു. അദ്ദേഹം അങ്ങനെ മൂന്ന് പ്രാവശ്യം ചെയ്തു. എന്നിട്ട് പറഞ്ഞു: ഇങ്ങനെയായിരുന്നു റസൂൽ(സ) ചെയ്തിരുന്നത്. (ജ)', 'مُجَاهِدٍ', 'മുജാഹിദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 96, 97, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 173, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: مَا أَوْلَمَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى امْرَأَةٍ مِنْ نِسَائِهِ أَكْثَرَ أَوْ أَفْضَلَ مِمَّا أَوْلَمَ عَلَى زَيْنَبَ. فَقَالَ ثَابِتٌ الْبُنَانِيُّ: بِمَا أَوْلَمَ؟ قَالَ: أَطْعَمَهُمْ خُبْزًا وَلَحْمًا حَتَّى تَرَكُوهُ. (م)', 'അനസുബ്നു മാലിക്(റ): സൈനബ്(റ)യുടെ പേരിൽ നടത്തിയ വിവാഹസദ്യയേക്കാൾ മഹത്തരവും ധാരാളവുമായി വേറൊരു ഭാര്യക്കും നബി(സ) വിവാഹസദ്യ കൊടുത്തിട്ടില്ല. സാബിതുൽ ബുനാനീ(റ) ചോദിച്ചു: എന്താണ് റസൂൽ(സ) വിവാഹ സദ്യ കൊടുത്തത്? അനസ്(റ) പറഞ്ഞു: പത്തിരിയും ഇറച്ചിയും അവർക്ക് മതിയാവോളം റസൂൽ(സ) ഭക്ഷിപ്പിച്ചു. (മു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 97, 97, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 174, 'عَنْ صَفِيَّةَ بِنْتِ شَيْبَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: أَوْلَمَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى بَعْضِ نِسَائِهِ بِمُدَّيْنِ مِنْ شَعِيرٍ. (خ)', 'സ്വഫിയ്യ ബിൻത് ശൈബ(റ): നബി(സ) തന്റെ ഭാര്യമാരിൽ ചിലർക്ക് രണ്ട് മുദ്ദ് ബാർലിയാണ് വിവാഹ സദ്യ നൽകിയത്. (ബു)', 'صَفِيَّةَ بِنْتِ شَيْبَةَ', 'സ്വഫിയ്യ ബിൻത് ശൈബ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 97, 97, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 175, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَوْلَمَ عَلَى صَفِيَّةَ بِنْتِ حُيَيٍّ بِسَوِيقٍ وَتَمْرٍ. حَسَنٌ. (ت)', 'അനസുബ്നു മാലിക്(റ): സ്വഫിയ്യ ബിൻത് ഹുയയ്യ്(റ)ക്ക് ധാന്യപ്പൊടിയും കാരക്കയുമാണ് റസൂൽ(സ) വിവാഹ സദ്യ നൽകിയത്. (തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 97, 97, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 176, 'عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "طَعَامُ أَوَّلِ يَوْمٍ حَقٌّ، وَطَعَامُ يَوْمِ الثَّانِي سُنَّةٌ، وَطَعَامُ يَوْمِ الثَّالِثِ سُمْعَةٌ، وَمَنْ سَمَّعَ سَمَّعَ اللهُ بِهِ". (د,ت,جه)', 'ഇബ്നു മസ്ഊദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ആദ്യ ദിവസത്തെ ഭക്ഷണം ബാധ്യതയാണ്, രണ്ടാം ദിവസം ഭക്ഷണം സുന്നത്താണ്, മൂന്നാം ദിവസത്തെ ഭക്ഷണം ഖ്യാതിയാണ്, ആരെങ്കിലും ഖ്യാതിക്ക് വേണ്ടിയാണ് ചെയ്തതെങ്കിൽ അവന് ഖ്യാതി കൊടുക്കും." (ദ,തു,ജ)', 'ابْنِ مَسْعُودٍ', 'ഇബ്നു മസ്ഊദ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 97, 97, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 177, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: تَزَوَّجَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَدَخَلَ بِأَهْلِهِ، قَالَ: فَصَنَعَتْ أُمِّي أُمُّ سُلَيْمٍ حَيْسًا، فَجَعَلَتْهُ فِي تَوْرٍ، فَقَالَتْ: يَا أَنَسُ اذْهَبْ بِهَذَا إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقُلْ: بَعَثَتْ بِهَذَا إِلَيْكَ أُمِّي وَهِيَ تُقْرِئُكَ السَّلامَ، وَتَقُولُ: إِنَّ هَذَا لَكَ مِنَّا قَلِيلٌ يَا رَسُولَ اللهِ، قَالَ: فَذَهَبْتُ بِهَا إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: إِنَّ أُمِّي تُقْرِئُكَ السَّلامَ، وَتَقُولُ: إِنَّ هَذَا لَكَ مِنَّا قَلِيلٌ [يَا رَسُولَ اللهِ]. فَقَالَ: "ضَعْهُ". ثُمَّ قَالَ: "اذْهَبْ فَادْعُ لِي فُلانًا وَفُلانًا وَفُلانًا وَمَنْ لَقِيتَ". وَسَمَّى رِجَالاً، قَالَ: فَدَعَوْتُ مَنْ سَمَّى وَمَنْ لَقِيتُ. قَالَ: قُلْتُ لأَنَسٍ: عَدَدَ كَمْ كَانُوا؟ قَالَ: زُهَاءَ ثَلاثِ مِائَةٍ، وَقَالَ لِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَا أَنَسُ هَاتِ التَّوْرَ". قَالَ: فَدَخَلُوا حَتَّى امْتَلأَتِ الصُّفَّةُ وَالْحُجْرَةُ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لِيَتَحَلَّقْ عَشَرَةٌ عَشَرَةٌ، وَلْيَأْكُلْ كُلُّ إِنْسَانٍ مِمَّا يَلِيهِ". قَالَ: فَأَكَلُوا حَتَّى شَبِعُوا، قَالَ: فَخَرَجَتْ طَائِفَةٌ وَدَخَلَتْ طَائِفَةٌ حَتَّى أَكَلُوا كُلُّهُمْ، فَقَالَ لِي: "يَا أَنَسُ ارْفَعْ". قَالَ: فَرَفَعْتُ، فَمَا أَدْرِي حِينَ وَضَعْتُ كَانَ أَكْثَرَ أَمْ حِينَ رَفَعْتُ؟ قَالَ: وَجَلَسَ طَوَائِفُ مِنْهُمْ يَتَحَدَّثُونَ فِي بَيْتِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ جَالِسٌ، وَزَوْجَتُهُ مُوَلِّيَةٌ وَجْهَهَا إِلَى الْحَائِطِ. فَثَقُلُوا عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَخَرَجَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَسَلَّمَ عَلَى نِسَائِهِ ثُمَّ رَجَعَ، فَلَمَّا رَأَوْا رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَدْ رَجَعَ ظَنُّوا أَنَّهُمْ قَدْ ثَقُلُوا عَلَيْهِ، قَالَ: فَابْتَدَرُوا الْبَابَ فَخَرَجُوا كُلُّهُمْ، وَجَاءَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَتَّى أَرْخَى السِّتْرَ، وَدَخَلَ وَأَنَا جَالِسٌ فِي الْحُجْرَةِ، فَلَمْ يَلْبَثْ إِلاَّ يَسِيرًا حَتَّى خَرَجَ عَلَيَّ وَأُنْزِلَتْ هَذِهِ الآيَةُ، فَخَرَجَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَقَرَأَهُنَّ عَلَى النَّاسِ: {يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَدْخُلُوا بُيُوتَ النَّبِيِّ إِلَّا أَنْ يُؤْذَنَ لَكُمْ إِلَى طَعَامٍ غَيْرَ نَاظِرِينَ إِنَاهُ وَلَكِنْ إِذَا دُعِيتُمْ فَادْخُلُوا فَإِذَا طَعِمْتُمْ فَانْتَشِرُوا وَلَا مُسْتَأْنِسِينَ لِحَدِيثٍ إِنَّ ذَلِكُمْ كَانَ يُؤْذِي النَّبِيَّ} إِلَى آخِرِ الآيَةِ [الأحزاب: ٥٣] قَالَ الْجَعْدُ: قَالَ أَنَسُ بْنُ مَالِكٍ: أَنَا أَحْدَثُ النَّاسِ عَهْدًا بِهَذِهِ الآيَاتِ، وَحُجِبْنَ نِسَاءُ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (م)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) വിവാഹം കഴിച്ച് തന്റെ ഭാര്യയുമായി വീട് കൂടി. എന്റെ ഉമ്മ ഉമ്മുസുലൈം(റ) കാരക്കയും പാൽകട്ടിയും നെയ്യും ചേർത്തൊരു ഭക്ഷണമുണ്ടാക്കി, ഒരു തളികയിൽ വെച്ചിട്ടെന്നോട് പറഞ്ഞു: അനസേ, ഇതുമായി നീ റസൂൽ(സ)യുടെ സന്നിധിയിലേക്ക് പോകുകയും എന്റെ മാതാവ് അങ്ങേക്ക് സലാം പറഞ്ഞിട്ടുണ്ടെന്ന് പറയുകയും ചെയ്യുക. ശേഷം പറയുക: അല്ലാഹുവിന്റെ റസൂലേ, ഇത് ഞങ്ങളിൽ നിന്നും അങ്ങേക്ക് വളരെ കുറവാണ്. അങ്ങനെ ഞാൻ അതുമായി റസൂൽ(സ)യുടെ സന്നിധിയിൽ ചെന്ന് പറഞ്ഞു: എന്റെ മാതാവ് അങ്ങേക്ക് സലാം പറയുന്നു, ഞങ്ങളിൽ നിന്ന് അങ്ങേക്കിത് വളരെ കുറവാണെന്നും എന്റെ മാതാവ് പറയുന്നു, റസൂലേ. റസൂൽ(സ) പറഞ്ഞു: "നീ അതവിടെ വെക്കുക." നീ പോയി ഇന്നാലിന്നവരെയും നീ കണ്ടുമുട്ടുന്നവരെയും ഇങ്ങോട്ട് ക്ഷണിക്കുക. നിവേദകൻ പറയുന്നു: അങ്ങനെ ഞാൻ കണ്ടുമുട്ടിയവരെയും നബി(സ) പേരെടുത്ത് പറഞ്ഞവരെയും ഞാൻ ക്ഷണിച്ചു. അവരെത്രയായിരുന്നുവെന്ന് ഞാൻ അനസ്(റ)വിനോട് ചോദിച്ചു. അനസ്(റ) പറഞ്ഞു: മുന്നൂറോളം പേരുണ്ട്. അനസ്(റ) പറയുന്നു: എന്നോട് തിരുമേനി(സ) പറഞ്ഞു: "അനസേ, നീ ആ തളിക കൊണ്ടുവാ." അങ്ങനെ അവരെല്ലാവരും വന്നു, റൂമും പൂമുഖവുമൊക്കെ നിറഞ്ഞുകവിഞ്ഞു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "പത്താളുകൾ വീതം വട്ടമിട്ടിരിക്കട്ടെ, ഓരോരുത്തരും അവനോടടുത്തത് ഭക്ഷിച്ചുകൊള്ളുക." അവരെല്ലാവരും വയറ് നിറയുവോളം ഭക്ഷണം കഴിച്ചു. ഒരു കൂട്ടം പോകുമ്പോൾ മറ്റൊരു കൂട്ടം വരും, അങ്ങനെ എല്ലാവരും ഭക്ഷിച്ചു. റസൂൽ(സ) എന്നോട് പറഞ്ഞു: "അനസേ, ഉയർത്ത്." ഞാനത് ഉയർത്തിയപ്പോൾ താഴെ വെച്ചപ്പോഴാണോ ഉയർത്തിയപ്പോഴാണോ കൂടുതലുണ്ടായിരുന്നതെന്ന് എനിക്കറിയാൻ കഴിഞ്ഞില്ല. അങ്ങനെ അവിടത്തെ വീട്ടിലിരുന്ന് കുറച്ചാളുകൾ സംസാരിക്കാൻ തുടങ്ങി. റസൂൽ(സ) ഇരിക്കുകയാണ്, അവിടത്തെ ഭാര്യയാണെങ്കിൽ ചുമരിനോട് മുഖം തിരിച്ച് നിൽക്കുകയാണ്. അവർ റസൂൽ(സ)ക്ക് ഭാരമായി. അങ്ങനെ റസൂൽ(സ) പുറപ്പെട്ട് തന്റെ ഭാര്യമാർക്ക് സലാം പറഞ്ഞ് തിരിച്ചുവന്നു. റസൂൽ(സ) തിരിച്ചുവന്നത് അവർ കണ്ടപ്പോൾ അവർ റസൂൽ(സ)ക്ക് ഭാരമാണെന്ന് അവർക്ക് മനസ്സിലായി. പെട്ടെന്ന് എല്ലാവരും പുറത്ത് പോയി. റസൂൽ(സ) വന്ന് വിരി താഴ്ത്തി, റൂമിലേക്ക് വന്നു. ഞാനവിടെ ഇരിക്കുകയാണ്. അധികം താമസിച്ചില്ല, റസൂൽ(സ) എന്റെ അടുത്ത് വന്നു. അവിടെ സൂക്തമവതരിച്ചു. അത് റസൂൽ(സ) വന്ന് ജനങ്ങൾക്ക് ഓതിക്കേൾപ്പിച്ചു: ''സത്യവിശ്വാസികളേ, ഭക്ഷണത്തിന് (നിങ്ങളെ ക്ഷണിക്കുകയും) നിങ്ങൾക്ക് സമ്മതം ലഭിക്കുകയും ചെയ്താലല്ലാതെ നബി(സ)യുടെ വീട്ടിൽ നിങ്ങൾ കടന്നു ചെല്ലരുത്, അത് (ഭക്ഷണം) പാകമാകുന്നത് നിങ്ങൾ നോക്കിയിരിക്കുന്നവരാകരുത്. പക്ഷേ, നിങ്ങൾ ക്ഷണിക്കപ്പെട്ടാൽ നിങ്ങൾ കടന്നുചെല്ലുക. നിങ്ങൾ ഭക്ഷണം കഴിച്ചാൽ പിരിഞ്ഞ്പോവുകയും ചെയ്യുക. നിങ്ങൾ വർത്തമാനം പറഞ്ഞുരസിച്ചിരിക്കുന്നവരാകുകയും അരുത്. തീർച്ചയായും അതൊക്കെ നബി(സ)യെ ശല്യപ്പെടുത്തുന്നതാകുന്നു.'' ഈ സൂക്തത്തിന്റെ അവസാനം വരെ ഇറങ്ങി. (അഹ്സാബ്:53) ജഅ്ദ് എന്നവർ പറഞ്ഞു: അനസ്(റ) പറഞ്ഞു: ഈ ആയത്തുകളുമായി ഏറ്റവും അടുത്ത സമയക്കാരൻ ഞാനാണ്, നബി(സ)യുടെ ഭാര്യമാർ ഹിജാബ് ഇടപെട്ടു. (മു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['م']::text[], array['മു']::text[], 'الأحزاب: ٥٣', null, 97, 99, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 178, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَأَى عَلَى عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ أَثَرَ صُفْرَةٍ، فَقَالَ: "مَا هَذَا؟ أَوْ: مَهْ". فَقَالَ: يَا رَسُولَ اللهِ، إِنِّي تَزَوَّجْتُ امْرَأَةً عَلَى وَزْنِ نَوَاةٍ مِنْ ذَهَبٍ. فَقَالَ: "بَارَكَ اللهُ لَكَ، أَوْلِمْ وَلَوْ بِشَاةٍ". (ق,ت,ن,جه)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) അബ്ദുർറഹ്മാനുബ്നു ഔഫ്(റ)വിന്റെ ശരീരത്തിൽ (സുഗന്ധത്തിന്റെ) മഞ്ഞനിറം കണ്ടു. റസൂൽ(സ) ചോദിച്ചു: എന്താണിത്? അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഈത്തപ്പക്കുരുവിന് തുല്യം തൂക്കമുള്ള സ്വർണ്ണത്തിന് പകരം ഞാനൊരു സ്ത്രീയെ വിവാഹം കഴിച്ചു. റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു നിനക്ക് ബർകത് ചെയ്യട്ടെ, ഒരാട് കൊണ്ടെങ്കിലും നീ വിവാഹ സദ്യ നടത്തുക." (ബു,മു,തു,ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 99, 99, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 179, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: قَالَ شَهِدْتُ لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَلِيمَةً، مَا فِيهَا لَحْمٌ وَلَا خُبْزٌ. (جه)', 'അനസ്(റ): ഞാൻ നബി(സ)യുടെ ഒരു വിവാഹ സദ്യയിൽ പങ്കെടുത്തു. അതിൽ ഇറച്ചിയും റൊട്ടിയും ഉണ്ടായിരുന്നില്ല.(ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 99, 99, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 180, 'عَنْ عَائِشَةَ وَأُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهُمَا قَالَتَا: أَمَرَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ نُجَهِّزَ فَاطِمَةَ حَتَّى نُدْخِلَهَا عَلَى عَلِيٍّ، فَعَمَدْنَا إِلَى الْبَيْتِ، فَفَرَشْنَاهُ تُرَابًا لَيِّنًا مِنْ أَعْرَاضِ الْبَطْحَاءِ، ثُمَّ حَشَوْنَا مِرْفَقَتَيْنِ لِيفًا، فَنَفَشْنَاهُ بِأَيْدِينَا، ثُمَّ أَطْعَمْنَا تَمْرًا وَزَبِيبًا، وَسَقَيْنَا مَاءً عَذْبًا، وَعَمَدْنَا إِلَى عُودٍ، فَعَرَضْنَاهُ فِي جَانِبِ الْبَيْتِ لِيُلْقَى عَلَيْهِ الثَّوْبُ وَيُعَلَّقَ عَلَيْهِ السِّقَاءُ، فَمَا رَأَيْنَا عُرْسًا أَحْسَنَ مِنْ عُرْسِ فَاطِمَةَ.. [ز: في سنده ضعيف] (جه)', 'ആഇശ(റ), ഉമ്മുസലമ(റ): അലി(റ)വിന്റെ അടുത്തേക്ക് പറഞ്ഞയക്കാൻ വേണ്ടി ഫാത്വിമ(റ)യെ അണിയിച്ചൊരുക്കാൻ നബി(സ) ഞങ്ങളോട് കൽപിച്ചു. ഞങ്ങൾ വീട്ടിൽ പോയി. താഴ്വര ഭാഗത്തുണ്ടാകുന്ന നല്ലമിനുസമുള്ള മണ്ണ് കൊണ്ട് വീടിന്റെ നിലം ഞങ്ങൾ തേച്ചു. പിന്നെ ഈത്തപ്പനനാവ് നിറച്ച് രണ്ട് തലയിണയുണ്ടാക്കുകയും അവയെ ഞങ്ങളുടെ കൈകൊണ്ട് പരത്തുകയും ചെയ്തു. പിന്നെ നബി(സ) ഞങ്ങളെ ഈത്തപ്പഴവും മുന്തിരിയും ഭക്ഷിപ്പിക്കുകയും, സംശുദ്ധമായ വെള്ളം കുടിപ്പിക്കുകയും ചെയ്തു. വസ്ത്രവും വെള്ളപ്പാത്രവും തൂക്കാൻ വേണ്ടി ഒരു മരക്കമ്പ് വീടിന് ഒരുവശത്ത് ബന്ധിച്ചു. അങ്ങനെ ഫാത്വിമയുടെ വിവാഹത്തേക്കാൾ മനോഹരമായൊരു മംഗല്യം ഞങ്ങൾ കണ്ടിട്ടില്ല. (ഈ ഹദീസിന്റെ പരമ്പരയിൽ ബലഹീനനുണ്ട്.) (ജ)', 'عَائِشَةَ وَأُمِّ سَلَمَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيف', null, 99, 99, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 181, 'عَنْ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: دَعَا أَبُو أُسَيْدٍ السَّاعِدِيُّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَى عُرْسِهِ، فَكَانَتْ خَادِمَهُمُ الْعَرُوسُ. قَالَتْ: تَدْرِي مَا سَقَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ قَالَتْ: أَنْقَعْتُ تَمَرَاتٍ مِنَ اللَّيْلِ، فَلَمَّا أَصْبَحْتُ صَفَّيْتُهُنَّ، فَأَسْقَيْتُهُنَّ إِيَّاهُ. (ق,جه)', 'സഹ്ലുബ്നു സഅ്ദിസ്സാഇദി(റ): അബൂഉസൈദുസ്സാഇദി(റ) റസൂൽ(സ)യെ തന്റെ വിവാഹത്തിലേക്ക് ക്ഷണിച്ചു, അറൂസ് എന്ന സ്ത്രീയായിരുന്നു അവരുടെ സേവക. അവൾ ചോദിച്ചു: ഞാൻ റസൂൽ(സ)യെ കുടിപ്പിച്ചതെന്നാണെന്ന് നിനക്കറിയുമോ? അവൾ പറഞ്ഞു: രാത്രിയിൽ കുറച്ച് കാരക്ക ഞാൻ കുതിർത്തി വെച്ചു. രാവിലെ അത് അരിച്ച് ശുദ്ധിയാക്കി. ശേഷം അത് റസൂൽ(സ)യെ കുടിപ്പിക്കുകയും ചെയ്തു. (ബു,മു,ജ)', 'سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ', 'സഹ്ലുബ്നു സഅ്ദിസ്സാഇദി(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 99, 100, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 182, 'عَنْ نَافِعٍ رَضِيَ اللهُ عَنْهُ: أَنَّ ابْنَ عُمَرَ رَضِيَ اللهُ عَنْهُمَا كَانَ يَقُولُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا دَعَا أَحَدُكُمْ أَخَاهُ فَلْيُجِبْ، عُرْسًا كَانَ أَوْ نَحْوَهُ". (م)', 'നാഫിഅ്(റ): ഇബ്നു ഉമർ(റ) നബി(സ) പറഞ്ഞതായി പറയാറുണ്ടായിരുന്നു: "വിവാഹമോ അത് പോലോ ത്തതോ ആകട്ടെ, നിങ്ങലിലൊരാൾ തന്റെ സഹോദരനെ ക്ഷണിച്ചാൽ അവൻ ആ വിളിക്കുത്തരം ചെയ്യട്ടെ." (മു)', 'نَافِعٍ', 'നാഫിഅ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 100, 100, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 183, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا دُعِيَ أَحَدُكُمْ فَلْيُجِبْ، فَإِنْ كَانَ صَائِمًا فَلْيُصَلِّ، وَإِنْ كَانَ مُفْطِرًا فَلْيَطْعَمْ". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിലാരെങ്കിലും ക്ഷണിക്കപ്പെട്ടാൽ അവൻ വിളിക്കുത്തരം ചെയ്യട്ടെ, നോമ്പുകാരനാണെങ്കിൽ അവൻ നിസ്കരിക്കട്ടെ, നോമ്പുകാരനല്ലെങ്കിൽ അവൻ ഭക്ഷിച്ച് കൊള്ളട്ടെ." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 100, 100, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 184, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "شَرُّ الطَّعَامِ طَعَامُ الْوَلِيمَةِ، يُمْنَعُهَا مَنْ يَأْتِيهَا، وَيُدْعَى إِلَيْهَا مَنْ يَأْبَاهَا. وَمَنْ لَمْ يُجِبِ الدَّعْوَةَ فَقَدْ عَصَى اللهَ وَرَسُولَهُ". (م)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഏറ്റവും മോശപ്പെട്ട ഭക്ഷണം, വരുന്നവർ തടയപ്പെടുകയും വരാത്തവർ ക്ഷണിക്കപ്പെടുകയും ചെയ്യുന്ന വിവാഹ സദ്യയാണ്, ക്ഷണത്തിന് ഉത്തരം നൽകാത്തവൻ അല്ലാഹുവിനും റസൂലിനും എതിര് പ്രവർത്തിച്ചിരിക്കുന്നു." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 100, 100, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 185, 'عَنْ أَبِي مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ يُقَالُ لَهُ أَبُو شُعَيْبٍ إِلَى غُلامٍ لَهُ لَحَّامٍ، فَقَالَ: اصْنَعْ لِي طَعَامًا يَكْفِي خَمْسَةً، فَإِنِّي رَأَيْتُ فِي وَجْهِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْجُوعَ. قَالَ: فَصَنَعَ طَعَامًا، ثُمَّ أَرْسَلَ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَدَعَاهُ وَجُلَسَاءَهُ الَّذِينَ مَعَهُ، فَلَمَّا قَامَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ اتَّبَعَهُمْ رَجُلٌ لَمْ يَكُنْ مَعَهُمْ حِينَ دُعُوا، فَلَمَّا انْتَهَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَى الْبَابِ قَالَ لِصَاحِبِ الْمَنْزِلِ: "إِنَّهُ اتَّبَعَنَا رَجُلٌ لَمْ يَكُنْ مَعَنَا حِينَ دَعَوْتَنَا، فَإِنْ أَذِنْتَ لَهُ دَخَلَ". قَالَ: فَقَدْ أَذِنَّا لَهُ، فَلْيَدْخُلْ. حَسَنٌ صَحِيحٌ. (ق,ت)', 'അബൂ മസ്ഊദ്(റ): അബൂ ശുഐബെന്നൊരാൾ മാംസക്കച്ചവക്കാരനായ തന്റെ അടിമയുടെ അടുത്ത് ചെന്ന് പറഞ്ഞു: അഞ്ചാളുകൾക്കുള്ള ഭക്ഷണം ഒരുക്കിവെക്ക്. റസൂൽ(സ)യുടെ മുഖത്ത് ഞാൻ വിശപ്പ് കാണുന്നു. അങ്ങനെ അടിമ ഭക്ഷണമുണ്ടാക്കി റസൂൽ(സ)ക്ക് കൊടുത്തയക്കുകയും നബി(സ)യെയും കൂടെയുള്ളവരെയും വിളിക്കുകയും ചെയ്തു. നബി(സ) എഴുന്നേറ്റപ്പോൾ, ക്ഷണിക്കപ്പെട്ട സമയത്ത് അവരുടെ കൂട്ടത്തിലില്ലാതിരുന്ന ഒരാൾ അവരെ പിന്തുടർന്നു, വാതിൽക്കലെത്തിയപ്പോൾ നബി(സ) വീട്ടുകാരനോട് പറഞ്ഞു: "നീ ഞങ്ങളെ ക്ഷണിച്ച സമയത്ത് ഞങ്ങളോടൊപ്പം ഇല്ലാതിരുന്നരാൾ ഞങ്ങളോടൊപ്പമുണ്ട്. നീ സമ്മതിക്കുകയാണെങ്കിൽ അയാൾ കടന്നുവരും." അയാൾ പറഞ്ഞു: ഞങ്ങളയാൾക്ക് സമ്മതം കൊടുത്തിരിക്കുന്നു. എന്നാലയാൾ വന്നുകൊള്ളട്ടെ. (ബു,മു,തു)', 'أَبِي مَسْعُودٍ', 'അബൂ മസ്ഊദ്(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 100, 100, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 186, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: جَهَّزَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَاطِمَةَ فِي خَمِيلٍ وَقِرْبَةٍ وَوِسَادَةٍ حَشْوُهَا إِذْخِرٌ. (ن)', 'അലി(റ): റസൂൽ(സ) ഫാത്വിമ ബീവി(റ)യെ ഒരുക്കി നിർത്തിയത് രോമം പൊന്തിയ ഒരു തരം വസ്ത്രം, തോൽപ്പാത്രം, ഒരുതരം പുല്ല് നിറച്ച തലയിണ എന്നിവ കൊണ്ടായിരുന്നു. (ന)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 101, 101, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 187, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "فِرَاشٌ لِلرَّجُلِ، وَفِرَاشٌ لأَهْلِهِ، وَالثَّالِثُ لِلضَّيْفِ وَالرَّابِعُ لِلشَّيْطَانِ". (ن)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരു വിരിപ്പ് സ്വന്തത്തിനും ഒരു വിരിപ്പ് വീട്ടുകാർക്കും മൂന്നാമത്തേത് അതിഥിക്കും നാലാമത്തേത് ശൈത്വാനുമുള്ളതുമാണ്." (ആവശ്യമില്ലാത്തത് കാരണം, അത് അഹങ്കാരത്തെ സൂചിപ്പിക്കുന്നു.) (ന)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 101, 101, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 188, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ لِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "هَلْ تَزَوَّجْتَ". قُلْتُ: نَعَمْ. قَالَ: "هَلِ اتَّخَذْتُمْ أَنْمَاطًا". قُلْتُ: وَأَنَّى لَنَا أَنْمَاطٌ؟ قَالَ: "إِنَّهَا سَتَكُونُ". (ن)', 'ജാബിർ(റ): റസൂൽ(സ) ചോദിച്ചു: "നീ വിവാഹം കഴിച്ചോ?" ഞാൻ പറഞ്ഞു: അതെ. അവിടന്ന് ചോദിച്ചു: "വിരിപ്പുകൾ വാങ്ങിയോ?" ഞാൻ ചോദിച്ചു: ഞങ്ങൾക്കെവിടെനിന്നാണ് വിരിപ്പുകൾ ലഭിക്കുക? നബി(സ) പറഞ്ഞു: "നിശ്ചയം അൽപം കഴിഞ്ഞ് അതുണ്ടാകും." (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 101, 101, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 189, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا أَنَّ عَلِيًّا رَضِيَ اللهُ عَنْهُ قَالَ: تَزَوَّجْتُ فَاطِمَةَ رَضِيَ اللهُ عَنْهَا، فَقُلْتُ: يَا رَسُولَ اللهِ، ابْنِ بِي. قَالَ: "أَعْطِهَا شَيْئًا". قُلْتُ: مَا عِنْدِي مِنْ شَيْءٍ. قَالَ: "فَأَيْنَ دِرْعُكَ الْحُطَمِيَّةُ". قُلْتُ: هِيَ عِنْدِي. قَالَ: "فَأَعْطِهَا إِيَّاهُ". (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): അലി(റ) പറഞ്ഞു: ഞാൻ ഫാത്വിമ(റ)യെ വിവാഹം കഴിച്ചപ്പോൾ റസൂൽ(സ)യോട് ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഫാത്വിമയുമായി വീട് കൂടാൻ എന്നെ അനുവദിക്കൂ. നബി(സ) പറഞ്ഞു: "നീ അവൾക്ക് വല്ലതും കൊടുക്കുക." ഞാൻ പറഞ്ഞു: എന്റെ അടുത്ത് ഒന്നുമില്ല. നബി(സ) ചോദിച്ചു: "വാളുകളെ പൊട്ടിക്കുന്ന നിന്റെ അങ്കിയെവിടെ." ഞാൻ പറഞ്ഞു: അത് എന്റെ അടുത്തുണ്ട്. നബി(സ) പറഞ്ഞു: "എന്നാൽ അത് അവൾക്ക് കൊടുക്കുക." (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 101, 101, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 190, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا تَزَوَّجَ أَحَدُكُمُ امْرَأَةً أَوِ اشْتَرَى خَادِمًا فَلْيَقُلِ: اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا وَخَيْرَ مَا جَبَلْتَهَا عَلَيْهِ، وَأَعُوذُ بِكَ مِنْ شَرِّهَا وَمِنْ شَرِّ مَا جَبَلْتَهَا عَلَيْهِ. وفي رواية: ثُمَّ لِيَأْخُذْ بِنَاصِيَتِهَا، وَلْيَدْعُ بِالْبَرَكَةِ. وَإِذَا اشْتَرَى بَعِيرًا فَلْيَأْخُذْ بِذِرْوَةِ سَنَامِهِ وَلْيَقُلْ مِثْلَ ذَلِكَ". (د,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും ഒരു സ്ത്രീയെ വിവാഹം ചെയ്യുകയോ ഒരു പിരചാരകയെ വാങ്ങുകയോ ചെയ്താൽ അവൻ പറയട്ടെ: അല്ലാഹുവേ, നിശ്ചയം ഞാൻ നിന്നോട് അവളുടെ നന്മയും നീ അവളെ  ഏതൊരു നന്മയുടെ പ്രത്യക്ഷത്തിലാണോ സൃഷ്ടിച്ചത് അതും ചോദിക്കുന്നു. ഞാൻ നിന്നോട് അവളുടെ തിന്മയിൽ നിന്നും നീ അവളെ ഏതൊരു തിന്മയുടെ മേൽ പടച്ചുവോ അതിൽ നിന്നും കാവൽ തേടുന്നു. മറ്റൊരു റിപ്പോർട്ടിൽ: പിന്നീട് അവളുടെ മൂർദ്ധാവിൽ പിടിക്കുകയും അവൾക്ക് ബറക്കത്തിന് വേണ്ടി പ്രാർത്ഥിക്കുകയും വേണം. അവനൊരു ഒട്ടകം വാങ്ങിയാൽ അവൻ അതിന്റെ പൂഞ്ഞയുടെ നെറുകെയിൽ പിടിക്കുകയും അതുപോലെ പറയുകയും വേണം." (ദ,ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 101, 102, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=2 and h.hadith_no=190), 1, 'وَفِي رِوَايَةٍ: ثُمَّ لِيَأْخُذْ بِنَاصِيَتِهَا، وَلْيَدْعُ بِالْبَرَكَةِ. وَإِذَا اشْتَرَى بَعِيرًا فَلْيَأْخُذْ بِذِرْوَةِ سَنَامِهِ وَلْيَقُلْ مِثْلَ ذَلِكَ". (د,جه)', 'മറ്റൊരു നിവേദനിൽ: പിന്നീട് അവളുടെ മൂർദ്ധാവിൽ പിടിക്കുകയും അവൾക്ക് ബറക്കത്തിന് വേണ്ടി പ്രാർത്ഥിക്കുകയും വേണം. അവനൊരു ഒട്ടകം വാങ്ങിയാൽ അവൻ അതിന്റെ പൂഞ്ഞയുടെ നെറുകെയിൽ പിടിക്കുകയും അതുപോലെ പറയുകയും വേണം." (ദ,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 191, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا أَفَادَ أَحَدُكُمُ امْرَأَةً – أَوْ خَادِمًا، أَوْ دَابَّةً – فَلْيَأْخُذْ بِنَاصِيَتِهَا وَلْيَقُلِ: اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ خَيْرِهَا وَخَيْرِ مَا جُبِلَتْ عَلَيْهِ، وَأَعُوذُ بِكَ مِنْ شَرِّهَا وَشَرِّ مَا جُبِلَتْ عَلَيْهِ". (د,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിൽ ആരെങ്കിലും ഒരു സ്ത്രീയെയോ ഒരു പരിചാരകനെയോ ഒരു മൃഗത്തെയോ സമ്പാദിച്ചാൽ അവൻ അവയുടെ മുതുകിൽ പിടിച്ച് പറയട്ടെ. ''അല്ലാഹുവേ, നിശ്ചയം ഇതിന്റെ നന്മയും ഇതിനെ ഏതൊരു നന്മയുടെ മേലിലാണോ നീ പടച്ചത് അതും നിന്നോട് ഞാൻ ചോദിക്കുന്നു. ഇതിന്റെ തിന്മയിൽ നിന്നും നീ ഇതിനെ ഏതൊരു തിന്മയുടെ മേലാണോ സൃഷ്ടിച്ചത് അതിൽ നിന്നും ഞാൻ നിന്നോട് കാവൽ തേടുന്നു." (ദ,ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 102, 102, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 192, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَوْ أَنَّ أَحَدَكُمْ إِذَا أَتَى امْرَأَتَهُ قَالَ: اللَّهُمَّ جَنِّبْنِي الشَّيْطَانَ وَجَنِّبِ الشَّيْطَانَ مَا رَزَقْتَنِي. ثُمَّ كَانَ بَيْنَهُمَا وَلَدٌ، لَمْ يُسَلِّطِ اللهُ عَلَيْهِ الشَّيْطَانَ. أَوْ: لَمْ يَضُرَّهُ". (ق,د,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിൽ ആരെങ്കിലും തന്റെ ഭാര്യയെ സമീപിക്കുകയും ''അല്ലാഹുവേ, നീ എന്നിൽ നിന്നും പിശാചിനെ അകറ്റണേ. നീ എനിക്ക് നൽകിയതിൽ നിന്നും പിശാചിനെ അകറ്റണേ'' എന്ന് പറയുകയും, പിന്നീട് (അതിൽ) അവർക്കൊരു കുഞ്ഞുണ്ടാവുകയും ചെയ്താൽ അതിന്റെ മേൽ അല്ലാഹു പിശാചിന് അധികാരം നൽകുകയില്ല. അല്ലെങ്കിൽ: "അവനെ ബുദ്ധിമുട്ടാക്കുകയില്ല." (ബു,മു,ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 102, 102, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 193, 'عَنْ أَبِي نَضْرَةَ الْمُنْذِرِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: حَدَّثَنِي شَيْخٌ مِنْ طُفَاوَةَ قَالَ: تَثَوَّيْتُ أَبَا هُرَيْرَةَ بِالْمَدِينَةِ فَلَمْ أَرَ رَجُلاً مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَشَدَّ تَشْمِيرًا وَلا أَقْوَمَ عَلَى ضَيْفٍ مِنْهُ، فَبَيْنَمَا أَنَا عِنْدَهُ يَوْمًا وَهُوَ عَلَى سَرِيرٍ لَهُ، وَمَعَهُ كِيسٌ فِيهِ حَصًى أَوْ نَوًى، وَأَسْفَلَ مِنْهُ جَارِيَةٌ لَهُ سَوْدَاءُ، وَهُوَ يُسَبِّحُ بِهَا، حَتَّى إِذَا أَنْفَدَ مَا فِي الْكِيسِ أَلْقَاهُ إِلَيْهَا فَجَمَعَتْهُ فَأَعَادَتْهُ فِي الْكِيسِ، فَدَفَعَتْهُ إِلَيْهِ، فَقَالَ: أَلا أُحَدِّثُكَ عَنِّي وَعَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: قُلْتُ: بَلَى، قَالَ: بَيْنَا أَنَا أُوعَكُ فِي الْمَسْجِدِ، إِذْ جَاءَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَتَّى دَخَلَ الْمَسْجِدَ، فَقَالَ: "مَنْ أَحَسَّ الْفَتَى الدَّوْسِيَّ" ثَلاثَ مَرَّاتٍ، فَقَالَ رَجُلٌ: يَا رَسُولَ اللهِ، هُوَ ذَا يُوعَكُ فِي جَانِبِ الْمَسْجِدِ. فَأَقْبَلَ يَمْشِي حَتَّى انْتَهَى إِلَيَّ، فَوَضَعَ يَدَهُ عَلَيَّ فَقَالَ: لِي مَعْرُوفًا، فَنَهَضْتُ، فَانْطَلَقَ يَمْشِي حَتَّى أَتَى مَقَامَهُ الَّذِي يُصَلِّي فِيهِ، فَأَقْبَلَ عَلَيْهِمْ وَمَعَهُ صَفَّانِ مِنْ رِجَالٍ وَصَفٌّ مِنْ نِسَاءٍ، أَوْ: صَفَّانِ مِنْ نِسَاءٍ وَصَفٌّ مِنْ رِجَالٍ، فَقَالَ: "إِنْ أَنْسَانِي الشَّيْطَانُ شَيْئًا مِنْ صَلاتِي فَلْيُسَبِّحِ الْقَوْمُ وَلْيُصَفِّقِ النِّسَاءُ". قَالَ: فَصَلَّى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَلَمْ يَنْسَ مِنْ صَلاتِهِ شَيْئًا، فَقَالَ: "مَجَالِسَكُمْ مَجَالِسَكُمْ هَهُنَا". ثُمَّ حَمِدَ اللهَ تَعَالَى وَأَثْنَى عَلَيْهِ، ثُمَّ قَالَ: "أَمَّا بَعْدُ". فَقَالَ: "هَلْ مِنْكُمُ الرَّجُلُ إِذَا أَتَى أَهْلَهُ فَأَغْلَقَ عَلَيْهِ بَابَهُ وَأَلْقَى عَلَيْهِ سِتْرَهُ، وَاسْتَتَرَ بِسِتْرِ اللهِ". قَالُوا: نَعَمْ، قَالَ: "ثُمَّ يَجْلِسُ بَعْدَ ذَلِكَ فَيَقُولُ: فَعَلْتُ كَذَا، فَعَلْتُ كَذَا". قَالَ: فَسَكَتُوا، قَالَ: فَأَقْبَلَ عَلَى النِّسَاءِ فَقَالَ: "هَلْ مِنْكُنَّ مَنْ تُحَدِّثُ". فَسَكَتْنَ، فَجَثَتْ فَتَاةٌ كَعَابٌ عَلَى إِحْدَى رُكْبَتَيْهَا، وَتَطَاوَلَتْ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِيَرَاهَا وَيَسْمَعَ كَلامَهَا، فَقَالَتْ: يَا رَسُولَ اللهِ، إِنَّهُمْ لَيَتَحَدَّثُونَ، وَإِنَّهُنَّ لَيَتَحَدَّثْنَهُ. فَقَالَ: "هَلْ تَدْرُونَ مَا مَثَلُ ذَلِكَ". فَقَالَ: "إِنَّمَا مَثَلُ ذَلِكَ مَثَلُ شَيْطَانَةٍ لَقِيَتْ شَيْطَانًا فِي السِّكَّةِ، فَقَضَى مِنْهَا حَاجَتَهُ وَالنَّاسُ يَنْظُرُونَ إِلَيْهِ. أَلا وَإِنَّ طِيبَ الرِّجَالِ مَا ظَهَرَ رِيحُهُ وَلَمْ يَظْهَرْ لَوْنُهُ، أَلا إِنَّ طِيبَ النِّسَاءِ مَا ظَهَرَ لَوْنُهُ وَلَمْ يَظْهَرْ رِيحُهُ. أَلا لا يُفْضِيَنَّ رَجُلٌ إِلَى رَجُلٍ، وَلا امْرَأَةٌ إِلَى امْرَأَةٍ، إِلاَّ إِلَى وَلَدٍ أَوْ وَالِدٍ". وَذَكَرَ ثَالِثَةً فَأَنْسِيتُهَا. (د,ت,ن)', 'അബൂനള്റത്തുനിൽ മുൻദിറുബ്നി മാലിക്(റ): തുഫാവയിൽ നിന്നുള്ള ഒരാൾ എനിക്ക് ഹദീസ് പറഞ്ഞുതന്നു കൊണ്ട് പറഞ്ഞു: ഞാൻ മദീനയിൽ അബൂഹുറൈറ(റ)യുടെ അതിഥിയായിരുന്നു. നബി(സ)യുടെ അനുചരരിൽ വെച്ച്, അബൂഹുറൈറയേക്കാൾ ഏറ്റവും ശക്തമായി ആരാധനയിൽ അർപ്പണമുള്ളവരായും നന്നായി അതിഥിസൽക്കാരം നടത്തുന്നവരായും ഒരാളെയും ഞാൻ കണ്ടിട്ടില്ല. ഒരു ദിനം അദ്ദേഹം തന്റെ കട്ടിലിരിക്കവെ ഞാൻ അദ്ദേഹത്തിന്റെ അടുക്കലുണ്ടായിരുന്നു. അദ്ദേഹത്തിന്റെ കൂടെ ചരൽക്കല്ലുകൾ, അല്ലെങ്കിൽ ഈത്തപ്പഴക്കുരുകൾ ഉള്ള ഒരു ഉറയുണ്ടായിരുന്നു. തന്റെ കറുത്തവർഗ്ഗക്കാരിയായ പരിചാരിക അടുത്ത് (താഴെ) ഉണ്ടായിരുന്നു. അദ്ദേഹം അവകൊണ്ട് (ചരൽക്കല്ലു കൊണ്ട്/ഈത്തപ്പഴക്കുരു കൊണ്ട്) തസ്ബീഹ് ചൊല്ലുന്നു. ആ ഉറയിൽ അദ്ദേഹമിട്ട ചരൽക്കല്ലുകൾ/ഈത്തപ്പഴക്കുരുകൾ കഴിയുമ്പോൾ അവ അവൾ (പരിചാരിക) ഒരുമിച്ചുകൂട്ടി (വീണ്ടും) ആ ഉറയിലേക്ക് മടക്കിയിട്ട് അദ്ദേഹത്തിന് നൽകുന്നു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: ഞാൻ എന്നെക്കുറിച്ചും റസൂലുല്ലാഹി(സ)യെക്കുറിച്ചും (ഹദീസ്) പറഞ്ഞുതരട്ടെയോ? ഞാൻ പറഞ്ഞു: അതെ. അദ്ദേഹം പറഞ്ഞു: ഒരിക്കൽ ഞാൻ പള്ളിയിൽ പനിച്ച് കിടക്കവെ, റസൂൽ(സ) വന്ന് പള്ളിയിൽ പ്രവേശിച്ചു. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "അദൗസീ യുവാവിനെ ആരെങ്കിലും കണ്ടോ?" ഇപ്രകാരം മൂന്ന് പ്രാവശ്യം ചോദിച്ചു. അപ്പോൾ ഒരാൾ പറഞ്ഞു: "അല്ലാഹുവിന്റെ റസൂലേ, അദ്ദഹമിതാ പള്ളിയുടെ ഒരുഭാഗത്ത് പനിപിടിച്ച് കിടക്കുന്നു. അവിടന്ന് നടന്നുവന്ന് എന്റെ അടുക്കലെത്തി. അവിടത്തെ തൃക്കരം എന്റെ മേൽ വെച്ചു. എന്നോട് നല്ലവാക്കുകകൾ സംസാരിച്ചു. ഞാൻ എഴുന്നേറ്റു. അപ്പോൾ അവിടന്ന് നിസ്കരിക്കുന്ന സ്ഥലത്തേക്ക് നടക്കാൻ തുടങ്ങി. അവിടന്ന് അവർക്ക് (ജനങ്ങൾക്ക്) നേരെ അഭിമുഖമായി നിന്നു, അവിടത്തോട് കൂടെ രണ്ട്വരി പുരുഷൻമാരും ഒരു വരി സ്ത്രീകളുമുണ്ടായിരുന്നു. അല്ലെങ്കിൽ രണ്ട് വരി സ്ത്രീകളും ഒരുവരി പുരുഷൻമാരും. അവിടന്നരുളി: "പിശാച് എന്റെ നിസ്കാരത്തിൽ എന്നെ വല്ലതും മറപ്പിച്ചാൽ പുരുഷന്മാർ തസ്ബീഹ് ചൊല്ലുകയും സ്ത്രീകൾ കൈയടിക്കുകയും വേണം." നിവേദകൻ പറഞ്ഞു: എന്നിട്ടവിടന്ന് നിസ്കരിച്ചു. തന്റെ നിസ്കാരത്തിൽ നിന്ന് അവിടന്ന് ഒന്നും മറന്നില്ല. അവിടന്നരുളി: "നിങ്ങൾ ഇവിടെ നിങ്ങളുടെ ഇരിപ്പിടങ്ങളിൽ ഇരിക്കുക. നിങ്ങൾ ഇവിടെ നിങ്ങളുടെ ഇരിപ്പിടങ്ങളിൽ ഇരിക്കുക." പിന്നീട് അവിടന്ന് അല്ലാഹുവിനെ സ്തുതിച്ചു അവനെ പുകഴ്തി. പിന്നീട് പറഞ്ഞു: "പ്രാരംഭ പ്രാർത്ഥനകൾക്ക് ശേഷം" എന്നിട്ട് പറഞ്ഞു: "തന്റെ ഭാര്യയെ സമീപിച്ച്, വാതിലടച്ച്, തന്റെ മേൽ ഒരു മറയിടുകയും അല്ലാഹുവിന്റെ മറകൊണ്ട് മറതേടുകയും ചെയ്യുന്ന ആരെങ്കിലും നിങ്ങളിലുണ്ടോ?" അവർ പറഞ്ഞു: അതെ. അവിടന്ന് പറഞ്ഞു: "പിന്നീട് അവൻ ഇരിക്കുകയും ഞാൻ ഇപ്രകാരം ചെയ്തു, ഇപ്രകാരം ചെയ്തു എന്ന് പറയുകയും ചെയ്യുന്നുവൻ?" നിവേദകൻ പറയുന്നു: അവർ മൗനം ഭജിച്ചു. നിവേദകൻ പറയുന്നു: അപ്പോൾ അവിടന്ന് സ്ത്രീകളെ അഭിമുഖീകരിച്ച് പറഞ്ഞു: "നങ്ങളിലാരെങ്കിലും (അത്) പറയുന്നവരുണ്ടോ?" അവർ മൗനികളായി. അപ്പോൾ ഒരു യുവതി തന്റെ ഒരു കാൽമുട്ടിൽ അമർന്നിരിക്കുകയും നബി(സ)ക്ക് തന്നെ കാണാനും തന്റെ സംസാരം കേൾക്കാനും വേണ്ടി തല ഉയർത്തുകയും ചെയ്തു. അവൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, നിശ്ചയം അവർ (പുരുഷന്മാർ) അവരുടെ (സംഭോഗ) രഹസ്യങ്ങൾ പറയാറുണ്ട്. നിശ്ചയം അവർ(സ്ത്രീകൾ) തങ്ങളുടെ സംഭോഗ രഹസ്യങ്ങൾ സംസാരിക്കാറുണ്ട്. അവിടന്ന് പറഞ്ഞു: "അതിന്റെ ഉപമ എന്താണെന്ന് നിങ്ങൾക്കറിയുമോ?" എന്നിട്ട് പറഞ്ഞു: "നിശ്ചയം അതിനുദാഹരണം ഒരു പെൺപിശാച് ആൺപിശാചുമായി വഴിയോരത്ത് വെച്ച് കണ്ടുമുട്ടുകയും തന്റെ ആവശ്യം ജനങ്ങൾ നോക്കിനിൽക്കെ അവൾ പൂർത്തീകരികരിക്കുകയും ചെയ്യുന്ന പോലെ മാത്രമാണ്. അറിയുക! നിശ്ചയം വാസന വെളിവാകുന്നതും നിറം വ്യക്തമാകാത്തതുമാണ് പുരുഷൻമാരുടെ സുഗന്ധം. അറിയുക! നിശ്ചയം നിറം വ്യക്തമാകുന്നതും വാസന പ്രകടമാകാത്തതുമാണ് സ്ത്രീകളുടെ സുഗന്ധം. അറിയുക! ഒരു പുരുഷനും മറ്റൊരു പുരുഷന്റെ കൂടെ കിടിക്കരുത്. ഒരു സ്ത്രീയും മറ്റൊരു സ്ത്രീയുടെ കൂടെ കിടക്കരുത്. സന്താനങ്ങളുടെയോ മാതാപിതാക്കളുടെയോ കൂടെയല്ലാതെ." മൂന്നാമതൊരു കാര്യം അവിടന്ന് പറഞ്ഞത് ഞാൻ മറന്നുപോയി. (ദ,തു,ന)', 'أَبِي نَضْرَةَ الْمُنْذِرِ بْنِ مَالِكٍ', 'അബൂനള്റത്തുനിൽ മുൻദിറുബ്നി മാലിക്(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 102, 104, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=72 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 194, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ مِنْ أَشَرِّ النَّاسِ عِنْدَ اللهِ مَنْزِلَةً يَوْمَ الْقِيَامَةِ الرَّجُلَ يُفْضِي إِلَى امْرَأَتِهِ وَتُفْضِي إِلَيْهِ، ثُمَّ يَنْشُرُ سِرَّهَا". (م)', 'അബൂസഈദിൽ ഖുദ്രി(റ): റസൂൽ(സ) പറഞ്ഞു: "തന്റെ ഭാര്യയിലേക്കും അവൾ ഇവനിലേക്കും ഇഴുകിക്കിടക്കുകയും, പിന്നീട് അവളുടെ രഹസ്യങ്ങൾ പരത്തുകയും ചെയ്യുന്നവനാണ് അന്ത്യനാളിൽ, തീർച്ചയായും, അല്ലാഹുവിന്റെയടുത്ത് പദവിയിൽ ഏറ്റവും മോശപ്പെട്ടവൻ." (മു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 104, 104, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=72 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 195, 'عَنْ مُعَاوِيَةَ بْنِ حَيْدَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللهِ، عَوْرَاتُنَا: مَا نَأْتِي مِنْهَا وَمَا نَذَرُ؟ قَالَ: "احْفَظْ عَوْرَتَكَ إِلاَّ مِنْ زَوْجَتِكَ أَوْ مَا مَلَكَتْ يَمِينُكَ". قُلْتُ: يَا رَسُولَ اللهِ أَرَأَيْتَ إِنْ كَانَ الْقَوْمُ بَعْضُهُمْ فِي بَعْضٍ؟ قَالَ: "إِنِ اسْتَطَعْتَ أَنْ لا تُرِيَهَا أَحَدًا فَلا تُرِيَنَّهَا". قُلْتُ: يَا رَسُولَ اللهِ، فَإِنْ كَانَ أَحَدُنَا خَالِيًا؟ قَالَ: "فَاللهُ أَحَقُّ أَنْ يُسْتَحْيَا مِنْهُ مِنَ النَّاسِ". (خ,د,ت,جه)', 'മുആവിയതുബ്നു ഹൈദ(റ): ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞങ്ങളുടെ നഗ്നതകൾ ഞങ്ങൾ പ്രാപിക്കുന്നതും ഞങ്ങൾ അനുവദിക്കുന്നതുമല്ലെയോ? അവിടന്നരുളി: "നീ നിന്റെ നഗ്നത, നിന്റെ ഭാര്യയും നിന്റെ അടിമയുമല്ലാത്തവരിൽ നിന്ന് സൂക്ഷിക്കുക." ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ജനങ്ങൾ പരസ്പരം കൂടിയുള്ള(സ്ഥലം)താണെങ്കിലോ? അവിടന്ന് പറഞ്ഞു: "അത് (നഗ്നത) ഒരാളെയും കാണിക്കാതിരിക്കാൻ നിനക്ക് സാധിക്കുമെങ്കിൽ നീ ഒരിക്കലുമത് കാണിക്കരുത്." ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞങ്ങളിലൊരാൾ ഒറ്റക്കാണെങ്കിലോ? അവിടന്നരുളി: "ജനങ്ങളേക്കാൾ അല്ലാഹുവാണ് ലജ്ജിക്കാൻ ഏറ്റവും ബന്ധപ്പെട്ടവൻ." (ബു,ദ,തു,ജ)', 'مُعَاوِيَةَ بْنِ حَيْدَةَ', 'മുആവിയതുബ്നു ഹൈദ(റ)', null, null, array['خ','د','ت','جه']::text[], array['ബു','ദ','തു','ജ']::text[], null, null, 104, 104, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=73 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 196, 'عَنْ عُتْبَةَ بْنِ عَبْدٍ السُّلَمِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا أَتَى أَحَدُكُمْ أَهْلَهُ فَلْيَسْتَتِرْ، وَلا يَتَجَرَّدْ تَجَرُّدَ الْعَيْرَيْنِ". [ز: في إسناده ضعيف] (جه)', 'ഉത്ബതുബ്നു അബ്ദിനിസ്സുലമി(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളാരെങ്കിലും തന്റെ ഭാര്യയെ സമീപിക്കുകയാണെങ്കിൽ അവൻ മറയിടട്ടെ. രണ്ട് കഴുതകളെപ്പോലെയുള്ള സ്വാതന്ത്ര്യം (പോലെ) അവൻ സ്വതന്ത്രനാകരുത്." (പരമ്പരയിൽ ഒരു ബലഹീനനുണ്ട്.) (ജ)', 'عُتْبَةَ بْنِ عَبْدٍ السُّلَمِيِّ', 'ഉത്ബതുബ്നു അബ്ദിനിസ്സുലമി(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 105, 105, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=73 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 197, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: مَا نَظَرْتُ – أَوْ مَا رَأَيْتُ – فَرْجَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَطُّ. (جه)', 'ആഇശ(റ): ഞാൻ ഒരിക്കലും റസൂൽ(സ)യുടെ ഗുഹ്യസ്ഥാനം കണ്ടിട്ടില്ല അല്ലെങ്കിൽ നോക്കിയിട്ടില്ല. (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 105, 105, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=73 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 198, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لا يَنْظُرُ اللهُ عَزَّ وَجَلَّ إِلَى رَجُلٍ جَامَعَ امْرَأَتَهُ فِي دُبُرِهَا". (د,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "തന്റെ ഭാര്യയെ പിറകിലൂടെ സംയോഗം ചെയ്തവനെ അല്ലാഹു നോക്കുകയില്ല." (ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 105, 105, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 199, 'عَنْ خُزَيْمَةَ بْنِ ثَابِتٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللهَ لا يَسْتَحْيِي مِنَ الْحَقِّ" ثَلاثَ مَرَّاتٍ "لا تَأْتُوا النِّسَاءَ فِي أَدْبَارِهِنَّ". (جه)', 'ഖുസൈമതുബ്നു സാബിത്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം അല്ലാഹു സത്യം വ്യക്തമാക്കുന്നതിൽ ലജ്ജിക്കുന്നില്ല." ഇപ്രകാരം മൂന്ന് പ്രാവശ്യം പറഞ്ഞു: "നിങ്ങൾ സ്ത്രീകളെ അവരുടെ പിറകിലൂടെ സമീപിക്കരുത്." (ജ)', 'خُزَيْمَةَ بْنِ ثَابِتٍ', 'ഖുസൈമതുബ്നു സാബിത്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 105, 105, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 200, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَتْ يَهُودُ تَقُولُ: مَنْ أَتَى امْرَأَتَهُ فِي قُبُلِهَا، مِنْ دُبُرِهَا، كَانَ الْوَلَدُ أَحْوَلَ. فَأَنْزَلَ اللهُ سُبْحَانَهُ: {نِسَاؤُكُمْ حَرْثٌ لَكُمْ فَأْتُوا حَرْثَكُمْ أَنَّى شِئْتُمْ} [البقرة: ٢٢٣] (م,ت,جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): ജൂതൻമാർ പറയുമായിരുന്നു: ആരെങ്കിലും ഭാര്യയെ അവളുടെ മുൻഭാഗത്ത് കൂടി പിറകിൽ ബന്ധപ്പെട്ടാൽ, കുട്ടി കോങ്കണ്ണനായിരിക്കും. അപ്പോൾ അല്ലാഹു ''സ്ത്രീകൾ നിങ്ങളുടെ കൃഷിയിടങ്ങളാണ്. നിങ്ങളുടെ കൃഷിയിടങ്ങളിലേക്ക് നിങ്ങൾ ഇച്ഛിക്കുന്നത് പോലെ സമീപിക്കുക.'' (അൽബഖറ:223) എന്ന സൂക്തം ഇറക്കി. (മ,തു,ജ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['م','ت','جه']::text[], array['മ','തു','ജ']::text[], 'البقرة: ٢٢٣', null, 105, 105, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 201, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَلْعُونٌ مَنْ أَتَى امْرَأَتَهُ فِي دُبُرِهَا". (د,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "തന്റെ ഭാര്യയെ പിറകിലൂടെ സമീപിച്ചവൻ ശപിക്കപ്പെട്ടവനാണ്." (ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 105, 105, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 202, 'عَنْ عَلِيِّ بْنِ طَلْقٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَى أَعْرَابِيٌّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللهِ، الرَّجُلُ مِنَّا يَكُونُ فِي الْفَلاةِ، فَتَكُونُ مِنْهُ الرُّوَيْحَةُ، وَيَكُونُ فِي الْمَاءِ قِلَّةٌ؟ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا فَسَا أَحَدُكُمْ فَلْيَتَوَضَّأْ، وَلا تَأْتُوا النِّسَاءَ فِي أَعْجَازِهِنَّ، فَإِنَّ اللهَ لا يَسْتَحْيِي مِنَ الْحَقِّ". حَسَنٌ. (د,ت)', 'അലിയ്യുബ്നു ത്വൽഖ്(റ): നബി(സ)യുടെ പക്കൽ ഒരു അഅ്റാബി വന്നു. അയാൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, ഞങ്ങളിലൊരാൾ മരുഭൂമിയിൽ ആവുകയും അങ്ങനെ അയാളിൽ നിന്ന് ചെറിയ കാറ്റ് ഉണ്ടാവുകയും വെള്ളത്തിൽ കമ്മി വരികയും ചെയ്താൽ എന്തുചെയ്യണം? അപ്പോൾ റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "നിങ്ങളിലാരെങ്കിലും കീഴ്വായു വിട്ടാൽ അവൻ വുളൂഅ് ചെയ്യട്ടെ. നിങ്ങൾ സ്ത്രീകളെ അവരുടെ നിതംബങ്ങളിലൂടെ സമീപിക്കരുത്. നിശ്ചയം അല്ലാഹു സത്യം വ്യക്തമാക്കുന്നതിൽ ലജ്ജിക്കുന്നില്ല." (ദ,തു)', 'عَلِيِّ بْنِ طَلْقٍ', 'അലിയ്യുബ്നു ത്വൽഖ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 105, 106, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 203, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: إِنَّ ابْنَ عُمَرَ – وَاللهُ يَغْفِرُ لَهُ – أَوْهَمَ، إِنَّمَا كَانَ هَذَا الْحَيُّ مِنَ الأَنْصَارِ – وَهُمْ أَهْلُ وَثَنٍ – مَعَ هَذَا الْحَيِّ مِنْ يَهُودَ – وَهُمْ أَهْلُ كِتَابٍ – وَكَانُوا يَرَوْنَ لَهُمْ فَضْلاً عَلَيْهِمْ فِي الْعِلْمِ، فَكَانُوا يَقْتَدُونَ بِكَثِيرٍ مِنْ فِعْلِهِمْ، وَكَانَ مِنْ أَمْرِ أَهْلِ الْكِتَابِ أَنْ لا يَأْتُوا النِّسَاءَ إِلاَّ عَلَى حَرْفٍ، وَذَلِكَ أَسْتَرُ مَا تَكُونُ الْمَرْأَةُ، فَكَانَ هَذَا الْحَيُّ مِنَ الأَنْصَارِ قَدْ أَخَذُوا بِذَلِكَ مِنْ فِعْلِهِمْ، وَكَانَ هَذَا الْحَيُّ مِنْ قُرَيْشٍ يَشْرَحُونَ النِّسَاءَ شَرْحًا مُنْكَرًا، وَيَتَلَذَّذُونَ مِنْهُنَّ مُقْبِلاتٍ وَمُدْبِرَاتٍ وَمُسْتَلْقِيَاتٍ، فَلَمَّا قَدِمَ الْمُهَاجِرُونَ الْمَدِينَةَ تَزَوَّجَ رَجُلٌ مِنْهُمْ امْرَأَةً مِنَ الأَنْصَارِ، فَذَهَبَ يَصْنَعُ بِهَا ذَلِكَ، فَأَنْكَرَتْهُ عَلَيْهِ، وَقَالَتْ: إِنَّمَا كُنَّا نُؤْتَى عَلَى حَرْفٍ، فَاصْنَعْ ذَلِكَ وَإِلاَّ فَاجْتَنِبْنِي، حَتَّى شَرِيَ أَمْرُهُمَا، فَبَلَغَ ذَلِكَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَنْزَلَ اللهُ عَزَّ وَجَلَّ: {نِسَاؤُكُمْ حَرْثٌ لَكُمْ فَأْتُوا حَرْثَكُمْ أَنَّى شِئْتُمْ} أَيْ: مُقْبِلاتٍ وَمُدْبِرَاتٍ وَمُسْتَلْقِيَاتٍ، يَعْنِي بِذَلِكَ مَوْضِعَ الْوَلَدِ. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): ''അതിനാൽ നിങ്ങളുടെ കൃഷിസ്ഥലത്തേക്ക് നിങ്ങൾ ഇച്ഛിക്കുന്നപോലെ പോകുക.'' എന്ന സൂക്തത്തെ ഇബ്നു ഉമർ(റ) തെറ്റായി മനസ്സിലാക്കി - അല്ലാഹു അദ്ദേഹത്തിന് മഗ്ഫിറത് നൽകട്ടെ. നിശ്ചയം വസ്തുത, ബിംബിരാധകരായ അൻസാറുകൾ വേദക്കാരായ ജൂതന്മാരുമായി നല്ല ബന്ധത്തിലായിരുന്നു. അൻസാരികൾ ജൂതന്മാർക്ക് വിജ്ഞാനത്തിൽ തങ്ങളേക്കാൾ ശ്രേഷ്ഠത കൽപ്പിച്ച് പോന്നിരുന്നു. ജൂതരുടെ മിക്ക പ്രവർത്തനങ്ങളും അവർ പിൻപറ്റിയിരുന്നു. കിതാബിന്റെ ആളുകളുടെ കാര്യങ്ങളിൽപ്പെട്ടതായിരുന്നു, ഒരൊറ്റ നിലയിൽ മാത്രം സ്ത്രീയെ സമീപിക്കുക എന്നത്. അത് സ്ത്രീകൾക്ക് ഏറ്റവും മറ നൽകുന്നതാണ്. അൻസാരികളും ജൂതന്മാരുടെ ഈ പ്രവർത്തനം തുടങ്ങിക്കഴിഞ്ഞിരുന്നു. ഖുറൈശികൾ സ്ത്രീകളെ വളെരെ വെളിവാക്കുകയും അവരുടെ മുന്നിലൂടെയും പിന്നിലൂടെയും വശങ്ങളിലൂടെയും സുഖമെടുക്കുകയും ചെയ്യുമായിരുന്നു. അങ്ങനെ മുഹാജിറുകൾ മദീനയിലെത്തിയപ്പോൾ അവരിലൊരാൾ അൻസാരികളിൽ പെട്ട ഒരു സ്ത്രീയെ വിവാഹം കഴിച്ചു. അപ്പോൾ അദ്ദേഹം അവളോട് അത് പോലെ (ഖുറൈശികൾ ചെയ്തിരുന്നപോലെ) ചെയ്തുതുടങ്ങി. അപ്പോൾ അവളദ്ദേഹത്തെ തടഞ്ഞു. അവൾ പറഞ്ഞു: ഞങ്ങൾ ഒരു ഭാഗത്തിലൂടെ മാത്രമേ സമീപിക്കപ്പെടാറുള്ളൂ. താങ്കളും അപ്രകാരം ചെയ്യുക. അല്ലെങ്കിൽ എന്നെ ഒഴിവാക്കുക. അങ്ങനെ അവരിരുവരുടെയും കാര്യം ആകെ പരന്നു. വിവരം റസൂൽ(സ)യുടെ അടുത്തെത്തി. അപ്പോൾ അല്ലാഹു ''നിങ്ങളുടെ സ്ത്രീകൾ നിങ്ങൾക്കുള്ള കൃഷിയിടമാണ്. നിങ്ങളുടെ കൃഷിയിടത്തെ നിങ്ങളിച്ഛിക്കും പോലെ സമീപിക്കുക.'' എന്ന ആയത് ഇറക്കി. അഥവാ, മുന്നിട്ടുകൊണ്ടും പിന്നിട്ടുകൊണ്ടും ചെരിഞ്ഞ്കിടന്നും. അഥവാ, കുട്ടിവരുന്ന സ്ഥലം (ഇപ്രകാരമാക്കിക്കൊണ്ടെല്ലാം ബന്ധപ്പെടാം.) (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 106, 106, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 204, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ الْيَهُودَ كَانَتْ إِذَا حَاضَتْ مِنْهُمُ امْرَأَةٌ أَخْرَجُوهَا مِنَ الْبَيْتِ، وَلَمْ يُؤَاكِلُوهَا وَلَمْ يُشَارِبُوهَا وَلَمْ يُجَامِعُوهَا فِي الْبَيْتِ، فَسُئِلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ ذَلِكَ، فَأَنْزَلَ اللهُ سُبْحَانَهُ وَتَعَالَى: {وَيَسْأَلُونَكَ عَنِ الْمَحِيضِ قُلْ هُوَ أَذًى فَاعْتَزِلُوا النِّسَاءَ فِي الْمَحِيضِ} [البقرة: ٢٢٢] إِلَى آخِرِ الآيَةِ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "جَامِعُوهُنَّ فِي الْبُيُوتِ، وَاصْنَعُوا كُلَّ شَيْءٍ غَيْرَ النِّكَاحِ". فَقَالَتِ الْيَهُودُ: مَا يُرِيدُ هَذَا الرَّجُلُ أَنْ يَدَعَ شَيْئًا مِنْ أَمْرِنَا إِلاَّ خَالَفَنَا فِيهِ. فَجَاءَ أُسَيْدُ بْنُ حُضَيْرٍ وَعَبَّادُ ابْنُ بِشْرٍ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالا: يَا رَسُولَ اللهِ، إِنَّ الْيَهُودَ تَقُولُ كَذَا وَكَذَا، أَفَلا نَنْكِحُهُنَّ فِي الْمَحِيضِ؟ فَتَمَعَّرَ وَجْهُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَتَّى ظَنَنَّا أَنْ قَدْ وَجَدَ عَلَيْهِمَا، فَخَرَجَا، فَاسْتَقْبَلَتْهُمَا هَدِيَّةٌ مِنْ لَبَنٍ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَبَعَثَ فِي آثَارِهِمَا، فَظَنَنَّا أَنَّهُ لَمْ يَجِدْ عَلَيْهِمَا. (م,د,ت,ن,جه)', 'അനസുബ്നു മാലിക്(റ): ജൂതന്മാർ അവരിൽ പെട്ട ഏതെങ്കിലും സ്ത്രീക്ക് ആർത്തവം ഉണ്ടായാൽ അവർ അവളെ വീട്ടിൽ നിന്നിറക്കുക. വീട്ടിൽ വെച്ച് അവളുടെ കൂടെ ഭക്ഷണം കഴിക്കുകയോ കൂടെ കുടിക്കുകയോ കൂട്ടത്തിലേർപ്പെടുകയോ ചെയ്യാറില്ല. ഇതേക്കുറിച്ച് റസൂലുല്ലാഹി(സ) ചോദിക്കപ്പെട്ടു. അപ്പോൾ അല്ലാഹു ''അവർ താങ്കളോട് ആർത്തവകാരിയെക്കുറിച്ച് ചോദിക്കും. താങ്കൾ പറയുക: അത് വൃത്തികേടാണ്, അവരെ ആർത്തവത്തിലായി ഒഴിവാക്കുക (ബന്ധത്തിലേർപ്പെടാതിരിക്കുക) തുടങ്ങി സൂക്തത്തിന്റെ അവസാനം വരെ ഇറക്കി. അപ്പോൾ റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "നിങ്ങൾ അവരോട് വീട്ടിൽ കൂടെക്കൂടുക, എല്ലാ കാര്യങ്ങളും ചെയ്യുക, സംഭോഗമൊഴികെ." അപ്പോൾ ജൂതന്മാർ പറഞ്ഞു: ഈ മനുഷ്യൻ നമ്മുടെ ഒരു കാര്യവും നമ്മോട് എതിരായിട്ടല്ലാതെ ചെയ്യാൻ ഉദ്ദേശിക്കുന്നില്ല. അപ്പോൾ ഉസൈദുബ്നുഹുളൈറും അബ്ബാസുബ്നു ബിശ്റും റസൂലുല്ലാഹി(സ)യെ സമീപിച്ച് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, നിശ്ചയം ജൂതന്മാർ ഇപ്രകാരവും ഇപ്രകാരവുമൊക്കെ പറയുന്നുണ്ട്. ഞങ്ങൾക്ക് അവരെ ആർത്തവത്തിലിരിക്കെ വിവാഹം കഴിക്കാമോ? അപ്പോൾ തിരുമേനി(സ)യുടെ തിരുമുഖം, അവിടന്ന് ഞങ്ങളോട് ദേഷ്യപ്പെട്ടുവെന്ന് ഞങ്ങൾക്ക് തോന്നും വിധം വ്യത്യാസപ്പെട്ടു. അപ്പോൾ ഇരുവരും പുറത്ത് പോയി. അപ്പോൾ, റസൂൽ(സ)ക്ക് ഹദ്യയായുള്ള പാൽ അവരുടെ മുന്നിലെത്തി. അവിടന്ന് അവർ ഇരുവർക്കും പിന്നാലെ ആളെ അയച്ചു. അപ്പോൾ ഞങ്ങൾക്ക്, അവിടന്ന് അവരോട് ദേഷ്യപ്പെട്ടിട്ടില്ല എന്ന് മനസ്സിലായി. (മു,ദ,തു,ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], 'البقرة: ٢٢٢', null, 106, 107, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=75 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 205, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كُنْتُ أَنَا وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَبِيتُ فِي الشِّعَارِ الْوَاحِدِ، وَأَنَا حَائِضٌ طَامِثٌ، فَإِنْ أَصَابَهُ مِنِّي شَيْءٌ غَسَلَ مَكَانَهُ وَلَمْ يَعْدُهُ، وَإِنْ أَصَابَ – تَعْنِي ثَوْبَهُ – مِنْهُ شَيْءٌ غَسَلَ مَكَانَهُ وَلَمْ يَعْدُهُ، وَصَلَّى فِيهِ. (د,ن)', 'ആഇശ(റ): ഞാനും റസൂൽ(സ)യും എന്റെ ആർത്തവകാലത്ത് രാത്രിയിൽ ഒരേ വിരിപ്പിൽ കിടക്കാറുണ്ടായിരുന്നു. എന്നിൽ നിന്നും വല്ലതും തട്ടിയാൽ ആ ഭാഗം അവിടന്ന് കഴുകുമായിരുന്നു. അതിനപ്പുറം കഴുകുമായിരുന്നില്ല. അവിടന്ന് അതിൽ നിസ്കരിക്കുകയും ചെയ്യുമായിരുന്നു. (ദ,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 107, 107, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=75 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 206, 'عَنْ مَيْمُونَةَ بِنْتِ الْحَارِثِ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا أَرَادَ أَنْ يُبَاشِرَ امْرَأَةً مِنْ نِسَائِهِ – وَهِيَ حَائِضٌ – أَمَرَهَا أَنْ تَتَّزِرَ، ثُمَّ يُبَاشِرُهَا. (ق,د,ت,ن,جه)', 'മൈമൂന ബിൻതു ഹാരിസ്(റ): റസൂൽ(സ) ഭാര്യയുമായി സ്പർശനത്തിലേർപ്പെടാൻ ആഗ്രഹിച്ചാൽ - അവർ ആർത്തവകാരിയായിരിക്കെ - അവളോട് അടിവസ്ത്രം ധരിക്കാൻ കൽപ്പിക്കുകയും സ്പർശനത്തിലേർപ്പെടുകയും ചെയ്യുമായിരുന്നു. (ബു,മു,ദ,തു,ന,ജ)', 'مَيْمُونَةَ بِنْتِ الْحَارِثِ', 'മൈമൂന ബിൻതു ഹാരിസ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 107, 107, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=75 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 207, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ – فِي الَّذِي يَأْتِي امْرَأَتَهُ وَهِيَ حَائِضٌ – قَالَ: "يَتَصَدَّقُ بِدِينَارٍ، أَوْ: بِنِصْفِ دِينَارٍ". (د,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ)യിൽ നിന്ന് നിവേദനം ചെയ്യുന്നു: തന്റെ ഭാര്യയെ അവൾ ആർത്തവകാരിയായിരിക്കെ ബന്ധപ്പെടുന്നവനെക്കുറിച്ച് അവിടന്ന് പറഞ്ഞു: "അവൻ ഒരു ദീനാർ സ്വദഖ ചെയ്യണം, അല്ലെങ്കിൽ അര ദീനാർ." (ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 108, 108, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=76 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 208, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: إِذَا أَصَابَهَا فِي الدَّمِ فَدِينَارٌ، وَإِذَا أَصَابَهَا فِي انْقِطَاعِ الدَّمِ فَنِصْفُ دِينَارٍ. (د,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): അവൾക്ക് രക്തം വരുന്ന സമയത്ത് ബന്ധപ്പെട്ടാൽ ഒരു ദീനാറും അവൾക്ക് രക്തം വരാത്ത സമയത്ത് (ആർത്തവ സമയത്തിൽ നിന്ന് തന്നെ) ബന്ധപ്പെട്ടാൽ അര ദീനാറുമാണ് സ്വദഖ ചെയ്യേണ്ടത്. (ദ,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 108, 108, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=76 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 209, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "كُلُّ أُمَّتِي مُعَافَاةٌ إِلاَّ الْمُجَاهِرِينَ، وَإِنَّ مِنَ الإِجْهَارِ أَنْ يَعْمَلَ الْعَبْدُ بِاللَّيْلِ عَمَلاً، ثُمَّ يُصْبِحُ قَدْ سَتَرَهُ رَبُّهُ، فَيَقُولُ: يَا فُلانُ قَدْ عَمِلْتُ الْبَارِحَةَ كَذَا وَكَذَا، وَقَدْ بَاتَ يَسْتُرُهُ رَبُّهُ، فَيَبِيتُ يَسْتُرُهُ رَبُّهُ، وَيُصْبِحُ يَكْشِفُ سِتْرَ اللهِ عَنْهُ". (م)', 'അബൂഹുറൈറ(റ): ഞാൻ റസൂൽ(സ) പറയുന്നത് കേട്ടു: "എന്റെ സമുദായം മുഴുവൻ സംരക്ഷിതരാണ്, (രഹസ്യകാര്യങ്ങൾ) വിളിച്ചുപറയുന്നവർ ഒഴികെ. നിശ്ചയം (രഹസ്യങ്ങൾ) വിളിച്ചുപറയുന്നതിൽ പെട്ടതാണ്, ഒരടിമ രാത്രിയിൽ ഒരു പ്രവർത്തി ചെയ്യുകയും പിന്നീട് നേരം വെളുക്കുമ്പോൾ മഹോന്നതനായ രക്ഷിതാവ് അതിനെ മറക്കുകയും എന്നിട്ട് അവൻ ''ഏ, ഞാനിന്നലെ രാത്രി ഇന്നാലിന്നത് ചെയ്തു'' എന്ന് പറയുകയും ചെയ്യൽ. അവന്റെ രക്ഷിതാവ് അത് മറച്ചുവെച്ച നിലയിൽ അവൻ രാത്രിയായി. അവന്റെ രക്ഷിതാവ് അത് മറച്ചുവെച്ച നിലയിൽ അവൻ രാത്രിയായിക്കൊണ്ടേയിരുന്നു. അങ്ങനെ അവൻ നേരം പുലരുമ്പോൾ അവന്റെ പ്രവർത്തനത്തെ അല്ലാഹു മറച്ചതിനെ അവൻ (പൊളിച്ച്) വെളിവാക്കുന്നു." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 108, 108, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=77 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 210, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: سَأَلَ رَجُلٌ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الْعَزْلِ؟ فَقَالَ: "أَوَ تَفْعَلُونَ؟ لا عَلَيْكُمْ أَنْ لا تَفْعَلُوا، فَإِنَّهُ لَيْسَ مِنْ نَسَمَةٍ قَضَى اللهُ لَهَا أَنْ تَكُونَ إِلاَّ هِيَ كَائِنَةٌ". (جه)', 'അബൂസഈദിൽ ഖുദ്രീ(റ): ഒരാൾ റസൂൽ(സ)യോട് ഇന്ദ്രിയം കടത്താതിരിക്കാനുള്ള നടപടിയെക്കുറിച്ച് ചോദിച്ചു: അവിടന്ന് പറഞ്ഞു: "നിങ്ങളത് ചെയ്യുന്നുവോ? അങ്ങനെ ചെയ്യാതിരിക്കണമെന്ന് നിങ്ങൾക്ക് നിർബന്ധമില്ല. കാരണം, ഉണ്ടാവണമെന്ന് അല്ലാഹു വിധിച്ച ജീവൻ ഒരിക്കലും ഉണ്ടാകാതിരിക്കില്ല." (ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രീ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 108, 108, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 211, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا نَعْزِلُ عَلَى عَهْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَالْقُرْآنُ يَنْزِلُ. (ق,ت,جه)', 'ജാബിർ(റ): റസൂൽ(സ)യുടെ കാലത്ത് ഞങ്ങൾ ഇന്ദ്രിയ വിഛേദനം ചെയ്യാറുണ്ടായിരുന്നു, ഖുർആൻ ഇറങ്ങിക്കൊണ്ടുമിരുന്നു. (ബു,മു,തു,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 108, 109, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 212, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ قَالَ: نَهَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ يُعْزَلَ عَنِ الْحُرَّةِ إِلاَّ بِإِذْنِهَا. [ز: في إسناده ضعيف] (جه)', 'ഉമറുബ്നുൽ ഖത്താബ്(റ): സ്വതന്ത്രയായ സ്ത്രീയിൽ നിന്ന് അവളുടെ സമ്മതമില്ലാതെ ഇന്ദ്രിയ വിഛേദനം നടത്തൽ റസൂൽ(സ) വിരോധിച്ചിരിക്കുന്നു. (പരമ്പരയിൽ ബലഹീനനുണ്ട്) (ജ)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമറുബ്നുൽ ഖത്താബ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 109, 109, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 213, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْنَا يَا رَسُولَ اللهِ، إِنَّا كُنَّا نَعْزِلُ، فَزَعَمَتِ الْيَهُودُ أَنَّهَا الْمَوْءُودَةُ الصُّغْرَى؟ فَقَالَ: "كَذَبَتِ الْيَهُودُ، إِنَّ اللهَ إِذَا أَرَادَ أَنْ يَخْلُقَهُ فَلَمْ يَمْنَعْهُ". (ت)', 'ജാബിർ(റ): ഞങ്ങൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, തീർച്ചയായും ഞങ്ങൾ ഇന്ദ്രിയ വിഛേദനം ചെയ്യുമായിരുന്നു. അപ്പോൾ ജൂതൻമാർ വാദിക്കുന്നു: അത് ചെറിയ തരം ''കുഴിച്ചുമൂടൽ'' ആകുന്നു. തിരുമേനി(സ) അരുളി: "ജൂതന്മാർ കള്ളം പറഞ്ഞിരിക്കുന്നു. നിശ്ചയം അല്ലാഹു അതിനെ പടക്കാൻ ഉദ്ദേശിച്ചിരുന്നുവെങ്കിൽ ഒരിക്കലും അത് തടയപ്പെടുകയില്ല." (തു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 109, 109, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 214, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُ – ذُكِرَ ذَلِكَ عِنْدَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْعَزْلُ – قَالَ: "فَلِمَ يَفْعَلُ أَحَدُكُمْ؟ – وَلَمْ يَقُلْ: فَلا يَفْعَلْ أَحَدُكُمْ – فَإِنَّهُ لَيْسَتْ مِنْ نَفْسٍ مَخْلُوقَةٍ إِلاَّ اللهُ خَالِقُهَا". (م,د,ت,ن)', 'അബൂസഈദ്(റ): നബി(സ)യുടെ അടുക്കൽ ഒരിക്കൽ ഇന്ദ്രിയ വിഛേദനം പരാമർശിക്കപ്പെട്ടു. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "നിങ്ങളിലൊരുത്തൻ എന്തിനത് ചെയ്യുന്നു? - അവിടന്ന് നിങ്ങളിലൊരാളും അപ്രകാരം ചെയ്യരുത് എന്ന് പറഞ്ഞില്ല - കാരണം, സൃഷ്ടിക്കപ്പെടേണ്ട ഏതൊരു ജീവനും അല്ലാഹു സൃഷ്ടിച്ചിട്ടല്ലാതെയില്ല." (മു,ദ,തു,ന)', 'أَبِي سَعِيدٍ', 'അബൂസഈദ്(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 109, 109, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 215, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلاً قَالَ: يَا رَسُولَ اللهِ، إِنَّ لِي جَارِيَةً وَأَنَا أَعْزِلُ عَنْهَا، وَأَنَا أَكْرَهُ أَنْ تَحْمِلَ، وَأَنَا أُرِيدُ مَا يُرِيدُ الرِّجَالُ، وَإِنَّ الْيَهُودَ تُحَدِّثُ أَنَّ الْعَزْلَ مَوْءُودَةُ الصُّغْرَى؟ قَالَ: "لَوْ أَرَادَ اللهُ أَنْ يَخْلُقَهُ مَا اسْتَطَعْتَ أَنْ تَصْرِفَهُ". (د,ت,ن)', 'അബൂസഈദിനിൽ ഖുദ്രി(റ): ഒരാൾ അല്ലാഹുവിന്റെ റസൂലേ, എനിക്ക് ഒരു പരിചാരികയുണ്ട്, ഞാനവളിൽ നിന്ന് ഇന്ദ്രിയ വിഛേദനം നടത്താറുണ്ട്. അവൾ ഗർഭം ധരിക്കുന്നത് ഞാനിഷ്ടപ്പെടുന്നില്ല. പുരുഷൻമാർ ഉദ്ദേശിക്കുന്നത് ഞാനും ഉദ്ദേശിക്കുന്നു. (എന്നാൽ) നിശ്ചയം ജൂതർ ഇന്ദ്രിയ വിഛേദനം ചെറിയ ''കുഴിച്ച് മൂടൽ'' ആണ് എന്ന് പറയുന്നു. അവിടന്ന് പറഞ്ഞു: "അല്ലാഹു അതിനെ സൃഷ്ടിക്കണമെന്ന് ഉദ്ദേശിച്ചാൽ താങ്കൾക്ക് അത് തിരിച്ചുകളയാൻ സാധ്യമല്ല." (ദ,തു,ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിനിൽ ഖുദ്രി(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 109, 109, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 216, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجْنَا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي غَزْوَةِ بَنِي الْمُصْطَلِقِ، فَأَصَبْنَا سَبْيًا مِنْ سَبْيِ الْعَرَبِ، فَاشْتَهَيْنَا النِّسَاءَ، وَاشْتَدَّتْ عَلَيْنَا الْعُزْبَةُ، وَأَحْبَبْنَا الْفِدَاءَ، فَأَرَدْنَا أَنْ نَعْزِلَ، ثُمَّ قُلْنَا: نَعْزِلُ وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَيْنَ أَظْهُرِنَا قَبْلَ أَنْ نَسْأَلَهُ عَنْ ذَلِكَ؟ فَسَأَلْنَاهُ عَنْ ذَلِكَ، فَقَالَ: "مَا عَلَيْكُمْ أَنْ لا تَفْعَلُوا، مَا مِنْ نَسَمَةٍ كَائِنَةٍ إِلَى يَوْمِ الْقِيَامَةِ إِلاَّ وَهِيَ كَائِنَةٌ". (ق,د,ن)', 'അബൂസഈദിനിൽ ഖുദ്രി(റ): ഞങ്ങൾ റസൂൽ(സ)യുടെ കൂടെ ബനുൽ മുസ്തലഖ് യുദ്ധത്തിന് പുറപ്പെട്ടു. ഞങ്ങൾക്ക് കുറച്ച് അറബി സ്ത്രീകളെ ബന്ധികളായി കിട്ടി. അപ്പോൾ ഞങ്ങൾക്ക് സ്ത്രീകളോട് ഇച്ഛതോന്നി. ഞങ്ങൾക്ക് ഭാര്യമാരിൽ നിന്ന് അകന്ന് അധികദിവസം കഴിച്ചുകൂട്ടേണ്ടി വരികയും ഇവരെ പിഴ വാങ്ങി വിട്ടയക്കാൻ ഞങ്ങൾ ഉദ്ദേശിക്കുകയും ചെയ്തത് കൊണ്ട് (സ്വതന്ത്രനിൽ നിന്ന് കുട്ടികളുണ്ടായാൽ അടിമത്വം അവസാനിക്കും. അപ്പോൾ അടിമയെ വിൽക്കാനാവില്ല.) ഞങ്ങൾ ഇന്ദ്രിയ വിഛേദനം നടത്താൻ ഉദ്ദേശിച്ചു. ഞങ്ങൾ പരസ്പരം പറഞ്ഞു: റസൂൽ(സ) നമ്മുടെ മുന്നിലുണ്ടായിരിക്കെ അവിടത്തോട് ഇതേക്കുറിച്ച് ചോദിക്കും മുമ്പ് ഇന്ദ്രിയ വിഛേദനം ചെയ്യുകയോ? അങ്ങനെ ഞങ്ങൾ അവിടത്തോട് ഇതേക്കുറിച്ച് ചോദിച്ചു. അവിടന്ന് പറഞ്ഞു: "നിങ്ങൾക്കങ്ങനെ ചെയ്യാതിരിക്കൽ നിർബന്ധമില്ല. അന്ത്യനാൾ വരെ ഉണ്ടാവേണ്ട ഒരു ജീവനും ഉണ്ടാകാതിരിക്കുകയുമില്ല. (ബു,മു,ദ,ന)', 'أَبِي سَعِيدٍ', 'അബൂസഈദിനിൽ ഖുദ്രി(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 109, 110, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 217, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ مِنَ الأَنْصَارِ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: إِنَّ لِي جَارِيَةً أَطُوفُ عَلَيْهَا، وَأَنَا أَكْرَهُ أَنْ تَحْمِلَ، فَقَالَ: "اعْزِلْ عَنْهَا إِنْ شِئْتَ، فَإِنَّهُ سَيَأْتِيهَا مَا قُدِّرَ لَهَا". قَالَ: فَلَبِثَ الرَّجُلُ ثُمَّ أَتَاهُ، فَقَالَ: إِنَّ الْجَارِيَةَ قَدْ حَمَلَتْ، قَالَ: "قَدْ أَخْبَرْتُكَ أَنَّهُ سَيَأْتِيهَا مَا قُدِّرَ لَهَا". (م,د,جه)', 'ജാബിർ(റ): അൻസാരികളിൽപ്പെട്ട ഒരാൾ റസൂൽ(സ)യുടെ അടുത്ത് വന്ന് പറഞ്ഞു: എനിക്കൊരു പരിചാരികയുണ്ട്. അവളുടെ അടുത്ത് ഞാൻ രാത്രിയിൽ ചെല്ലാറുണ്ട്. ഞാനാണെങ്കിൽ അവൾ ഗർഭിണിയാകുന്നത് ഇഷ്ടപ്പെടുന്നുമില്ല. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "താങ്കൾ ഉദ്ദേശിക്കുന്നുവെങ്കിൽ അവളിൽ നിന്ന് ഇന്ദ്രിയ വിഛേദനം ചെയ്യുക. കാരണം അവളിൽ വിധിക്കപ്പെട്ടത് അവളിലൂടെ വരികതന്നെ ചെയ്യും." നിവേദകൻ പറയുന്നു: കുറച്ച് കഴിഞ്ഞ് ആ മനുഷ്യൻ വീണ്ടും അവിടത്തെ സമീപിച്ചു. എന്നിട്ട് പറഞ്ഞു: ആ പരിചാരിക ഗർഭിണിയായിട്ടുണ്ട്. അവിടന്നരുളി: "ഞാൻ നിന്നോട് പറഞ്ഞിരുന്നു: നിശ്ചയം അവൾക്ക് വിധിക്കപ്പെട്ടത് അവൾക്ക് വരികതന്നെ ചെയ്യുമെന്ന്." (മു,ദ,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 110, 110, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 218, 'عَنْ أَبِي سَعِيدٍ الزُّرَقِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلاً سَأَلَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الْعَزْلِ، فَقَالَ: إِنَّ امْرَأَتِي تُرْضِعُ، وَأَنَا أَكْرَهُ أَنْ تَحْمِلَ؟ فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ مَا قَدْ قُدِّرَ فِي الرَّحِمِ سَيَكُونُ". (ن)', 'അബൂസഈദിനിസ്സുറഖി(റ): ഒരാൾ റസൂൽ(സ)യോട് ഇന്ദ്രിയവിഛേദത്തെക്കുറിച്ച് ചോദിച്ചു: എന്നിട്ട് പറഞ്ഞു എന്റെ ഭാര്യ മുല കൊടുക്കുന്നു. അവൾ ഗർഭം ധരിക്കുന്നത് ഞാൻ വെറുക്കുന്നു? അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "ഗർഭപാത്രത്തിൽ വിധിക്കപ്പെട്ടത് ഉണ്ടാവുക തന്നെ ചെയ്യും." (ന)', 'أَبِي سَعِيدٍ الزُّرَقِيِّ', 'അബൂസഈദിനിസ്സുറഖി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 110, 110, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 219, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: ذُكِرَ الْعَزْلُ عِنْدَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "وَمَا ذَاكُمْ". قَالُوا: الرَّجُلُ تَكُونُ لَهُ الْمَرْأَةُ تُرْضِعُ، فَيُصِيبُ مِنْهَا وَيَكْرَهُ أَنْ تَحْمِلَ مِنْهُ. وَالرَّجُلُ تَكُونُ لَهُ الأَمَةُ، فَيُصِيبُ مِنْهَا وَيَكْرَهُ أَنْ تَحْمِلَ مِنْهُ. قَالَ: "فَلا عَلَيْكُمْ أَنْ لا تَفْعَلُوا ذَاكُمْ، فَإِنَّمَا هُوَ الْقَدْرُ". قَالَ ابْنُ عَوْنٍ: فَحَدَّثْتُ بِهِ الْحَسَنَ فَقَالَ: وَاللهِ لَكَأَنَّ هَذَا زَجْرٌ. (م)', 'അബൂസഈദിൽ ഖുദ്രി(റ): ഇന്ദ്രിയ വിഛേദനത്തെക്കുറിച്ച് നബി(സ)യോട് പറയപ്പെട്ടു. അവിടന്ന് ചോദിച്ചു: "അത് എന്താണ്?" അവർ പറഞ്ഞു: മുലകൊടുത്തുകൊണ്ടിരിക്കുന്ന ഭാര്യയുള്ള പുരുഷൻ. അവൻ അവളുമായി ബന്ധപ്പടുന്നു. എന്നാൽ അതിൽ ഭാര്യ ഗർഭിണിയാകുന്നത് വെറുക്കുകയും ചെയ്യുന്നു. അടിമസ്ത്രീയുള്ള ഒരു പുരുഷൻ അവൻ അവളുമായി ബന്ധപ്പെടുന്നു. എന്നാൽ അവൾ ഗർഭിണിയാകുന്നത് വെറുക്കുകയും ചെയ്യുന്നു. അപ്പോൾ അവിടന്നരുളി: "നിങ്ങൾ അങ്ങനെ ചെയ്യാതിരിക്കണമെന്നില്ല. നിശ്ചയം അത് വിധിയാണ്." ഇബ്നു ഔൻ പറയുന്നു: ഞാനിത് ഹസൻ(റ)വിനോട് പറഞ്ഞു: അപ്പോൾ ഹസൻ(റ) പറഞ്ഞു: അല്ലാഹു തന്നെ സത്യം. ഇതൊരു വിരോധിക്കപ്പെട്ട കാര്യം പോലെയുണ്ട്. (മു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 110, 110, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 220, 'عَنْ جَابِرٍ [بْنِ عَبْدِ اللهِ] رَضِيَ اللهُ عَنْهُمَا قَالَ: سَأَلَ رَجُلٌ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "إِنَّ عِنْدِي جَارِيَةً لِي، وَأَنَا أَعْزِلُ عَنْهَا، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ ذَلِكَ لَنْ يَمْنَعَ شَيْئًا أَرَادَهُ اللهُ". قَالَ: فَجَاءَ الرَّجُلُ فَقَالَ: يَا رَسُولَ اللهِ إِنَّ الْجَارِيَةَ الَّتِي كُنْتُ ذَكَرْتُهَا لَكَ حَمَلَتْ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَنَا عَبْدُ اللهِ وَرَسُولُهُ". (م)', 'ജാബിർ(റ): ഒരാൾ നബി(സ)യോട് ചോദിച്ചു: എന്റെയടുക്കൽ എന്റെയൊരു പരിചാരികയുണ്ട്. ഞാനവളിൽ നിന്ന് ഇന്ദ്രിയ വിഛേദനം നടത്താറുണ്ട്. അപ്പോൾ റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "നിശ്ചയം, അത് അല്ലാഹു ഉദ്ദേശിച്ച ഒന്നും തടയുകയില്ല തന്നെ." നിവേദകൻ പറയുന്നു: പിന്നീട് ആ മനുഷ്യൻ വന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, തീർച്ചയായും ഞാൻ അങ്ങയോട് പറഞ്ഞിരുന്ന പരിചാരിക ഗർഭിണിയായിരിക്കുന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഞാൻ അല്ലാഹുവിന്റെ അടിമയും അവന്റെ ദൂതനുമാണ്." (മു)', 'جَابِرٍ [بْنِ عَبْدِ اللهِ]', 'ജാബിർ(റ)', null, null, array['م']::text[], array['മു']::text[], 'بْنِ عَبْدِ اللهِ', null, 110, 111, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 221, 'عَنْ جُدَامَةَ بِنْتِ وَهْبٍ [الأَسَدِيَّةِ] أُخْتِ عُكَّاشَةَ رَضِيَ اللهُ عَنْهُمَا قَالَتْ: حَضَرْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي أُنَاسٍ وَهُوَ يَقُولُ: "لَقَدْ هَمَمْتُ أَنْ أَنْهَى عَنِ الْغِيلَةِ، فَنَظَرْتُ فِي الرُّومِ وَفَارِسَ فَإِذَا هُمْ يُغِيلُونَ أَوْلادَهُمْ، فَلا يَضُرُّ أَوْلادَهُمْ ذَلِكَ شَيْئًا". ثُمَّ سَأَلُوهُ عَنِ الْعَزْلِ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "ذَلِكَ الْوَأْدُ الْخَفِيُّ". (م,د,ت,جه)', 'ജുദാമതു ബിൻതുവഹബിനിൽ അസദിയ്യ(റ): മഹതി ഉക്കാശ(റ)വിന്റെ സഹോദരിയാണ്. മഹതി പറയുന്നു: റസൂലുല്ലാഹി(സ) ഒരു കൂട്ടമാളുകളോട് കൂടെ ഇരിക്കുമ്പോൾ ഞാനവിടെ ചെന്നു. അന്നേരം അവിടന്ന് പറഞ്ഞു: "ഗർഭകാലത്ത് കുട്ടികൾക്ക് മുലകൊടുക്കുന്നത് നിരോധിക്കാൻ ഞാൻ ഉദ്ദേശിച്ചിരുന്നു. എന്നാൽ പേർഷ്യക്കാരും റോമക്കാരും ഗർഭ കാലത്ത് കുട്ടികൾക്ക് മുലകൊടുക്കുന്നുവെന്ന് ഞാൻ അറിഞ്ഞു. അത് അവരുടെ കുട്ടികളെ ബുദ്ധിമുട്ടാക്കുന്നുമില്ല." പിന്നീടവർ ഇന്ദ്രിയവിഛേദനത്തെക്കുറിച്ച് അവിടത്തോട് ചോദിച്ചു. അവിടന്ന് പറഞ്ഞു: "അത് ഗോപ്യമായി ജീവനോടെ കുഴിച്ചുമൂടലാണ്." (മു,ദ,തു,ജ)', 'جُدَامَةَ بِنْتِ وَهْبٍ [الأَسَدِيَّةِ] أُخْتِ عُكَّاشَةَ', 'ജുദാമതു ബിൻതുവഹബിനിൽ അസദിയ്യ(റ)', null, null, array['م','د','ت','جه']::text[], array['മു','ദ','തു','ജ']::text[], 'الأَسَدِيَّةِ', null, 111, 111, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=79 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 222, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا، عَنْ جُدَامَةَ بِنْتِ وَهْبٍ الأَسَدِيَّةِ أَنَّهَا قَالَتْ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "قَدْ أَرَدْتُ أَنْ أَنْهَى عَنِ الْغِيَالِ، فَإِذَا فَارِسُ وَالرُّومُ يُغِيلُونَ، فَلا يَقْتُلُونَ أَوْلادَهُمْ". وَسَمِعْتُهُ يَقُولُ – وَسُئِلَ عَنِ الْعَزْلِ – فَقَالَ: "هُوَ الْوَأْدُ الْخَفِيُّ". (م,د,ت,جه)', 'ആഇശ(റ): ജുദാമതു ബിൻത് വഹ്ബിനിൽ അസദിയ്യ(റ): റസൂലുല്ലാഹി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ഗർഭ കാലത്ത് കുട്ടിക്ക് മുലകൊടുക്കുന്നത് നിരോധിക്കാൻ ഞാൻ ഉദ്ദേശിച്ചിരുന്നു. അപ്പോഴതാ പേർഷ്യയിലും റോമിലും അവർ ഗർഭകാലത്ത് കുട്ടികൾക്ക് മുലകൊടുക്കുന്നു. അവർ അവരുടെ കുട്ടികളെ കൊല്ലുന്നില്ല." അവിടന്ന് പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട് - ഇന്ദ്രിയവിഛേദനത്തെക്കുറിച്ച് അവിടന്ന് ചോദിക്കപ്പെട്ടു - അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "അത് നേരിയ കുഴിച്ചുമൂടൽ (ജീവനോടെ) ആണ്." (മു,ദ,തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','د','ت','جه']::text[], array['മു','ദ','തു','ജ']::text[], null, null, 111, 111, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=79 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 223, 'عَنْ أَسْمَاءَ بِنْتِ يَزِيدَ بْنِ السَّكَنِ رَضِيَ اللهُ عَنْهَا: أَنَّهَا سَمِعَتْ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لا تَقْتُلُوا أَوْلادَكُمْ سِرًّا، فَوَالَّذِي نَفْسِي بِيَدِهِ، إِنَّ الْغَيْلَ لَيُدْرِكُ الْفَارِسَ عَلَى ظَهْرِ فَرَسِهِ حَتَّى يَصْرَعَهُ". (د,جه)', 'അസ്മാഅ് ബിൻത് യസീദിനിബ്നിസ്സകൻ(റ): റസൂൽ(സ) പറയുന്നത് മഹതി കേട്ടു: "നിങ്ങളുടെ മക്കളെ നിങ്ങൾ രഹസ്യമായി കൊല്ലരുത്. നിശ്ചയം, എന്റെ ശരീരം (ആത്മാവ്) ആരുടെ കയ്യിലാണോ അവൻ തന്നെയാണ് സത്യം, നിശ്ചയം, ഗർഭകാലത്ത് മുലപ്പാൽ കൊടുക്കുന്നത് കുതിരസവാരിക്കാരനെ തന്റെ കുതിരപ്പുറത്ത് നിന്ന് തള്ളിയിടുന്ന അവസ്ഥയിലെത്തിക്കും." (ദ,ജ)', 'أَسْمَاءَ بِنْتِ يَزِيدَ بْنِ السَّكَنِ', 'അസ്മാഅ് ബിൻത് യസീദിനിബ്നിസ്സകൻ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 111, 111, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=79 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 224, 'عَنْ بَصْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: تَزَوَّجْتُ امْرَأَةً بِكْرًا فِي سِتْرِهَا، فَدَخَلْتُ عَلَيْهَا، فَإِذَا هِيَ حُبْلَى، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَهَا الصَّدَاقُ بِمَا اسْتَحْلَلْتَ مِنْ فَرْجِهَا، وَالْوَلَدُ عَبْدٌ لَكَ، فَإِذَا وَلَدَتْ فَاجْلِدُوهَا. أَوْ قَالَ: فَحُدُّوهَا". وفي رواية: وَفَرَّقَ بَيْنَهُمَا. (د)', 'ബസ്റതുബ്നു അക്സം(റ): ഞാൻ കന്യകയായ ഒരു സ്ത്രീയെ അവളുടെ മറയിൽ (പാർപ്പിടത്തിൽ) വെച്ച് വിവാഹം ചെയ്തു. ഞാനവളുടെ അടുക്കൽ കയറിവന്നു. അപ്പോൾ അവളതാ ഗർഭിണിയാണ്. അപ്പോൾ റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "താങ്കൾ അവളുടെ ഗുഹ്യം ഹലാലാക്കിയതിനാൽ മഹ്റ് അവൾക്കുള്ളതാണ്. കുട്ടി നിന്റെ അടിമയാണ്. അവൾ പ്രസവിച്ചാൽ അവളെ (വ്യഭിചാരക്കുറ്റത്തിന്റെ അടി) അടിക്കുക." അല്ലെങ്കിൽ "അവളുടെ മേൽ വ്യഭിചാരത്തിന്റെ ശിക്ഷ നടപ്പിലാക്കുക." മറ്റൊരു നിവേദനത്തിൽ: റസൂൽ(സ) അവരുടെ വിവാഹബന്ധം വേർപ്പെടുത്തി. (ദ)', 'بَصْرَةَ', 'ബസ്റതുബ്നു അക്സം(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 112, 112, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=80 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=2 and h.hadith_no=224), 1, 'وَفِي رِوَايَةٍ: وَفَرَّقَ بَيْنَهُمَا. (د)', 'മറ്റൊരു നിവേദനത്തിൽ: റസൂൽ(സ) അവരുടെ വിവാഹബന്ധം വേർപ്പെടുത്തി. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 225, 'عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: [أَنَّهُ] أَتَى بِامْرَأَةٍ مُجِحٍّ عَلَى بَابِ فُسْطَاطٍ، فَقَالَ: "لَعَلَّهُ يُرِيدُ أَنْ يُلِمَّ بِهَا". فَقَالُوا: نَعَمْ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَقَدْ هَمَمْتُ أَنْ أَلْعَنَهُ لَعْنًا يَدْخُلُ مَعَهُ قَبْرَهُ، كَيْفَ يُورِّثُهُ وَهُوَ لا يَحِلُّ لَهُ؟ كَيْفَ يَسْتَخْدِمُهُ وَهُوَ لا يَحِلُّ لَهُ". (م)', 'അബുദ്ദർദാഅ്(റ): നന്നായി ഗർഭമുള്ള ഒരു സ്ത്രീയെ ഒരാൾ നബി(സ)യുടെ അടുക്കൽ കൊണ്ടുവന്നു. അവിടന്ന് പറഞ്ഞു: "അയാൾ അവളുമായി (ലൈംഗിക) ബന്ധത്തിലേർപ്പെടാൻ ഉദ്ദേശിക്കുന്നുണ്ടാവും." അവർ പറഞ്ഞു: അതെ. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "അയാളെ, അയാളുടെ കൂടെ ഖബ്റിൽ പ്രവേശിക്കുന്ന ശാപം ശപിക്കാൻ തീർച്ചയായും ഞാൻ കരുതിയതാണ്. അവന് അനുവദനീയമല്ലാതെ എങ്ങനെയാണവൻ അവന് അനന്തരം നൽകുക. എങ്ങിനെയാണവനെ പരിചാരകനാക്കുക, അവന് അത് അനുവദനീയമല്ലെന്നിരിക്കെ." (മു)', 'أَبِي الدَّرْدَاءِ', 'അബുദ്ദർദാഅ്(റ)', null, null, array['م']::text[], array['മു']::text[], 'أَنَّهُ', null, 112, 112, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=81 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 226, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَوْمَ حُنَيْنٍ بَعَثَ جَيْشًا إِلَى أَوْطَاسَ فَلَقُوا عَدُوًّا، فَقَاتَلُوهُمْ فَظَهَرُوا عَلَيْهِمْ، وَأَصَابُوا لَهُمْ سَبَايَا، فَكَأَنَّ نَاسًا مِنْ أَصْحَابِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَحَرَّجُوا مِنْ غِشْيَانِهِنَّ، مِنْ أَجْلِ أَزْوَاجِهِنَّ مِنَ الْمُشْرِكِينَ، فَأَنْزَلَ اللهُ عَزَّ وَجَلَّ فِي ذَلِكَ: {وَالْمُحْصَنَاتُ مِنَ النِّسَاءِ إِلاَّ مَا مَلَكَتْ أَيْمَانُكُمْ} [النساء: ٢٤] أَيْ فَهُنَّ لَكُمْ حَلالٌ إِذَا انْقَضَتْ عِدَّتُهُنَّ. (م,د,ت,ن)', 'അബൂസഈദിൽ ഖുദ്രി(റ): ഹുനൈൻ ദിവസം റസൂലുല്ലാഹി(സ) ഔത്വാസിലേക്ക് സൈന്യത്തെ അയച്ചു. അവർ ശത്രുക്കളെ കണ്ടുമുട്ടി. ഉടൻ അവരെ യുദ്ധം ചെയ്തു കീഴടക്കി. അങ്ങനെ അവർക്ക് സ്ത്രീബന്ധികളെ കിട്ടി. അപ്പോൾ തിരുമേനി(സ)യുടെ അനുചരരിൽ പെട്ട ചിലയാളുകൾ അവരെ സമീപിക്കുന്നതിൽ നിന്ന് വിട്ടുനിന്നു, അവരുടെ ഭർത്താക്കൻമാർ മുശ്രിക്കുകളാ(ബഹുദൈവവിശ്വാസികൾ)യത് കാരണം. അപ്പോൾ മഹോന്നതനായ അല്ലാഹു ഇക്കാര്യത്തിൽ ''വിവാഹിതരായ എല്ലാ സ്ത്രീകളും നിങ്ങളുടെ വലതുകരങ്ങൾ അധികാരപ്പെടുത്തിയവർ (അടിമസ്ത്രീകൾ) ഒഴികെ'' (നിസാഅ്: 24) എന്ന ആയത് ഇറക്കി. അഥവാ, അവർ നിങ്ങൾക്ക് ഹലാലാണ് അവരുടെ ഇദ്ദാകാലം വിട്ടുകഴിഞ്ഞാൽ. (മു,ദ,തു,ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], 'النساء: ٢٤', null, 112, 112, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=81 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 227, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ – وَرَفَعَهُ – أَنَّهُ قَالَ: فِي سَبَايَا أَوْطَاسٍ: "لا تُوطَأُ حَامِلٌ حَتَّى تَضَعَ، وَلَا غَيْرُ ذَاتِ حَمْلٍ حَتَّى تَحِيضَ حَيْضَةً". (د)', 'അബൂസഈദിൽ ഖുദ്രി(റ): അദ്ദേഹം മർഫൂഅ് ആക്കി ഉദ്ദരിക്കുന്നു - ഔത്വാസിലെ സ്ത്രീ ബന്ധികളെക്കുറിച്ച് പറഞ്ഞു: "ഒരു ഗർഭിണിയും പ്രസവിക്കും വരെ സംഭോഗം ചെയ്യപ്പെടാവതല്ല, ഗർഭമില്ലാത്തവർ ഒരു ആർത്തവം ഉണ്ടാവുന്നത് വരെയും (സംഭോഗം ചെയ്യാൻ) പാടില്ല." (ദ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 112, 113, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=81 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 228, 'عَنْ رُوَيْفِعِ بْنِ ثَابِتٍ الْأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: أَمَا إِنِّي لَا أَقُولُ لَكُمْ إِلَّا مَا سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ يَوْمَ حُنَيْنٍ، قَالَ: "لَا يَحِلُّ لِامْرِئٍ يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ أَنْ يَسْقِيَ مَاءَهُ زَرْعَ غَيْرِهِ". يَعْنِي إِتْيَانَ الْحَبَالَى. "وَلَا يَحِلُّ لِامْرِئٍ يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ أَنْ يَقَعَ عَلَى امْرَأَةٍ مِنَ السَّبْيِ حَتَّى يَسْتَبْرِئَهَا – وَفِي رِوَايَةٍ: بِحَيْضَةٍ – وَلَا يَحِلُّ لِامْرِئٍ يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ أَنْ يَبِيعَ مَغْنَمًا حَتَّى يُقْسَمَ". وَفِي رِوَايَةٍ: "وَمَنْ كَانَ يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ فَلَا يَرْكَبْ دَابَّةً مِنْ فَيْءِ الْمُسْلِمِينَ حَتَّى إِذَا أَعْجَفَهَا رَدَّهَا فِيهِ، وَمَنْ كَانَ يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ فَلَا يَلْبَسْ ثَوْبًا مِنْ فَيْءِ الْمُسْلِمِينَ حَتَّى إِذَا أَخْلَقَهُ رَدَّهُ فِيهِ". (د,ت)', 'റുവൈഫിഉബ്നു സാബിതുൽ അൻസാരി(റ): അറിയുക, നിശ്ചയം ഹുനൈൻ യുദ്ധദിവസം റസൂൽ(സ) പറയുന്നതായി ഞാൻ കേട്ടതുമാത്രമാണ് നിങ്ങളോട് ഞാൻ പറയുന്നിത്. അവിടന്നരുളി: "അല്ലാഹുവിലും അന്ത്യനാളിലും വിശ്വസിക്കുന്ന ഒരാൾക്കും തന്റെ ജലം മറ്റുള്ളവന്റെ കൃഷിയിടത്തിൽ കുടിപ്പിക്കൽ അനുവദനീയമല്ല." ഗർഭിണികളെ സമീപിക്കലാണ് അവിടന്ന് ഉദ്ദേശിക്കുന്നത്. "അല്ലാഹുവിലും അന്ത്യനാളിലും വിശ്വസിക്കുന്ന ഒരുത്തനും, ബന്ദികളായ സ്ത്രീകളുടെ ഗർഭപാത്രം ഒഴിയുന്നത് വരെ അവരോട് ബന്ധപ്പെടൽ - ഒരു നിവേദനത്തിൽ: ആർത്തവത്തിൽ - അനുവദനീയമല്ല. അല്ലാഹുവിലും അന്ത്യദിനത്തിലും വിശ്വസിക്കുന്ന ഒരാൾക്കും യുദ്ധമുതൽ വീതിക്കപ്പെടുന്നത് വരെ വിൽക്കൽ അനുവദനീയമല്ല." മറ്റൊരു റിപ്പോർട്ടിൽ: "അല്ലാഹുവിലും അന്ത്യനാളിലും വല്ലവനും വിശ്വസിക്കുന്നുവെങ്കിൽ അവൻ മുസ്ലിംകളുടെ യുദ്ധമുതലിൽ നിന്നുള്ള ഒരു മൃഗത്തിനു പുറത്തും സവാരി ചെയ്യരുത്. അങ്ങനെ അത് മെലിഞ്ഞാൽ അവൻ തിരിച്ചുകൊണ്ടുവരും. ആരെങ്കിലും അല്ലാഹുവിലും അന്ത്യദിനത്തിലും വിശ്വസിക്കുന്നുവെങ്കിൽ മുസ്ലിംകളുടെ യുദ്ധമുതലിൽ നിന്ന് ഒരു വസ്തുവും അവൻ ധരിക്കാതിരിക്കട്ടെ. അങ്ങനെ അത് പഴകിയാൽ അവൻ അതിലേക്ക് മടക്കുകയും ചെയ്യും." (ദ,തു)', 'رُوَيْفِعِ بْنِ ثَابِتٍ الْأَنْصَارِيِّ', 'റുവൈഫിഉബ്നു സാബിതുൽ അൻസാരി(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 113, 113, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=81 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=2 and h.hadith_no=228), 1, 'وَفِي رِوَايَةٍ: بِحَيْضَةٍ – وَلَا يَحِلُّ لِامْرِئٍ يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ أَنْ يَبِيعَ مَغْنَمًا حَتَّى يُقْسَمَ".', 'മറ്റൊരു നിവേദനിൽ: "അല്ലാഹുവിലും അന്ത്യനാളിലും വല്ലവനും വിശ്വസിക്കുന്നുവെങ്കിൽ അവൻ മുസ്ലിംകളുടെ യുദ്ധമുതലിൽ നിന്നുള്ള ഒരു മൃഗത്തിനു പുറത്തും സവാരി ചെയ്യരുത്. അങ്ങനെ അത് മെലിഞ്ഞാൽ അവൻ തിരിച്ചുകൊണ്ടുവരും. ആരെങ്കിലും അല്ലാഹുവിലും അന്ത്യദിനത്തിലും വിശ്വസിക്കുന്നുവെങ്കിൽ മുസ്ലിംകളുടെ യുദ്ധമുതലിൽ നിന്ന് ഒരു വസ്തുവും അവൻ ധരിക്കാതിരിക്കട്ടെ. അങ്ങനെ അത് പഴകിയാൽ അവൻ അതിലേക്ക് മടക്കുകയും ചെയ്യും." (ദ,തു)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=2 and h.hadith_no=228), 2, 'وَفِي رِوَايَةٍ: "وَمَنْ كَانَ يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ فَلَا يَرْكَبْ دَابَّةً مِنْ فَيْءِ الْمُسْلِمِينَ حَتَّى إِذَا أَعْجَفَهَا رَدَّهَا فِيهِ، وَمَنْ كَانَ يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ فَلَا يَلْبَسْ ثَوْبًا مِنْ فَيْءِ الْمُسْلِمِينَ حَتَّى إِذَا أَخْلَقَهُ رَدَّهُ فِيهِ". (د,ت)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 229, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تِسْعُ نِسْوَةٍ، فَكَانَ إِذَا قَسَمَ بَيْنَهُنَّ لَا يَنْتَهِي إِلَى الْمَرْأَةِ الْأُولَى إِلَّا فِي تِسْعٍ، فَكُنَّ يَجْتَمِعْنَ كُلَّ لَيْلَةٍ فِي بَيْتِ الَّتِي يَأْتِيهَا، فَكَانَ فِي بَيْتِ عَائِشَةَ فَجَاءَتْ زَيْنَبُ، فَمَدَّ يَدَهُ إِلَيْهَا، فَقَالَتْ: هَذِهِ زَيْنَبُ، فَكَفَّ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَدَهُ، فَتَقَاوَلَتَا حَتَّى اسْتَخَبَتَا. وَأُقِيمَتِ الصَّلَاةُ، فَمَرَّ أَبُو بَكْرٍ عَلَى ذَلِكَ فَسَمِعَ أَصْوَاتَهُمَا، فَقَالَ: اخْرُجْ يَا رَسُولَ اللهِ إِلَى الصَّلَاةِ وَاحْثُ فِي أَفْوَاهِهِنَّ التُّرَابَ، فَخَرَجَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَتْ عَائِشَةُ: الْآنَ يَقْضِي النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَاتَهُ، فَيَجِيءُ أَبُو بَكْرٍ فَيَفْعَلُ [بِي] وَيَفْعَلُ. فَلَمَّا قَضَى النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَاتَهُ أَتَاهَا أَبُو بَكْرٍ فَقَالَ لَهَا قَوْلًا شَدِيدًا، وَقَالَ: أَتَصْنَعِينَ هَذَا؟ (م)', 'അനസ്(റ): നബി(സ)ക്ക് ഒമ്പത് ഭാര്യമാരുണ്ടായിരുന്നു: അവിടന്ന് ഓരോരുത്തർക്കും ഓരോ ദിവസം ഊഴം നിശ്ചയിച്ചുകൊടുത്തതുകൊണ്ട്, ഒമ്പത് ദിവസം കൊണ്ടേ എല്ലാവരുടെയും അടുത്ത് ഒരുപ്രാവശ്യം എത്തിയിരുന്നുള്ളൂ. എല്ലാ രാത്രിയിലും ഊഴം അനുസരിച്ച് നബി(സ) എത്തിച്ചേരുന്ന വീട്ടിൽ ഭാര്യമാരെല്ലാവരും ഒരുമിച്ചുകൂടുമായിരുന്നു. അങ്ങനെ അവിടന്ന് ആഇശ(റ)യുടെ വീട്ടിലായിരിക്കുമ്പോൾ സൈനബ്(റ) അവിടെ വന്നു. നബി(സ) മഹതിയുടെ നേരെ കൈനീട്ടി. അപ്പോൾ മഹതി പറഞ്ഞു: ഇത് സൈനബാണ്. ഉടനെ നബി(സ) തന്റെ കൈ പിൻവലിച്ചു. അനന്തരം അവർ രണ്ടുപേരും (ആഇശ(റ)യും സൈനബ്(റ)യും) ഉച്ചത്തിൽ സംസാരിക്കാൻ തുടങ്ങി. നിസ്കാരത്തിന് ഇഖാമത് വിളിക്കപ്പെട്ടു. അപ്പോൾ അബൂബക്കർ(റ) അതിലൂടെ വരികയും ബഹളം കേൾക്കാനിടയാവുകയും ചെയ്തു. അബൂബക്കർ(റ) പറഞ്ഞു: റസൂലേ, അങ്ങ് നിസ്കാരത്തിന് പുറപ്പെട്ടാലും, അവരുടെ വായയിൽ മണ്ണ് വാരിയിടൂ. അങ്ങനെ നബി(സ) നിസ്കരിക്കാൻ പോയി. അപ്പോൾ ആഇശ(റ) പറഞ്ഞു: നബി(സ) ഇപ്പോൾ നിസ്കാരം കഴിക്കുകയും, ഉടനെ അബൂബക്കർ(റ) വന്ന് എന്നെ എന്തെങ്കിലും ചെയ്യുകയും ചെയ്യും. നബി(സ)യുടെ നിസ്കാരം കഴിഞ്ഞപ്പോൾ അബൂബക്കർ(റ) ആഇശ(റ)യുടെ അടുത്ത് വന്ന്, നീ ഇങ്ങനെയൊക്കെ ചെയ്തുവല്ലേ എന്ന് പറയുകയും ശക്തമായി ശകാരിക്കുകയും ചെയ്തു. (മു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م']::text[], array['മു']::text[], 'بِي', null, 113, 114, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=82 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 230, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ كَانَتْ لَهُ امْرَأَتَانِ، يَمِيلُ مَعَ إِحْدَاهُمَا عَلَى الْأُخْرَى، جَاءَ يَوْمَ الْقِيَامَةِ وَأَحَدُ شِقَّيْهِ سَاقِطٌ". (د,ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ആർക്കെങ്കിലും രണ്ട് ഭാര്യമാർ ഉണ്ടാവുകയും, അവരിൽ ഒരാൾ ഉണ്ടായിരിക്കെ, മറ്റവളിലേക്ക് ചായ്വ് കാണിച്ചാൽ അന്ത്യനാളിൽ അവൻ രണ്ട് വശങ്ങളിൽ ഒന്ന് കുഴഞ്ഞവനായിട്ടായിരിക്കും വരിക." (ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 114, 114, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=82 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 231, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقْسِمُ بَيْنَ نِسَائِهِ فَيَعْدِلُ، ثُمَّ يَقُولُ: "اللَّهُمَّ هَذَا فِعْلِي فِيمَا أَمْلِكُ، فَلَا تَلُمْنِي فِيمَا تَمْلِكُ وَلَا أَمْلِكُ". (د,ت,جه)', 'ആഇശ(റ): റസൂൽ(സ) തന്റെ ഭാര്യമാർക്കിടയിൽ വീതം വെക്കാറുണ്ടായിരുന്നു. അപ്പോൾ നീതി കാണിക്കാറുണ്ടായിരുന്നു. എന്നിട്ട് പറയും: "അല്ലാഹുവേ, ഞാൻ അധികാരപ്പെടുത്തിയവയിൽ എന്റെ പ്രവർത്തനമിതാണ്. അതിനാൽ നീ അധികാരപ്പെടുത്തിയതും ഞാൻ അധികാരപ്പെടുത്താത്തതുമായതിൽ നീ എന്നെ ആക്ഷേപിക്കരുതേ." (ദ,തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 114, 114, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=82 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 232, 'عَنْ أَسْمَاءَ رَضِيَ اللهُ عَنْهَا: أَنَّ امْرَأَةً قَالَتْ: يَا رَسُولَ اللهِ، إِنَّ لِي ضَرَّةً فَهَلْ عَلَيَّ جُنَاحٌ إِنْ تَشَبَّعْتُ مِنْ زَوْجِي غَيْرَ الَّذِي يُعْطِينِي؟ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْمُتَشَبِّعُ بِمَا لَمْ يُعْطَ كَلَابِسِ ثَوْبَيْ زُورٍ". (ق)', 'അസ്മാഅ്(റ): ഒരു സത്രീ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, എനിക്കൊരു സഹകളത്രമുണ്ട്. അതിനാൽ എന്റെ ഭർത്താവ് എനിക്ക് നൽകുന്നതല്ലാത്ത വല്ല വസ്തുകൊണ്ടും, ഭർത്താവിൽ നിന്ന് ഞാൻ വയർ നിറച്ചാൽ എന്റെ മേൽ വല്ല കുറ്റവുമുണ്ടോ? അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "നൽകപ്പെടാത്തത് കൊണ്ട് വയർ നിറക്കുന്നവൻ രണ്ട് കള്ളവസ്ത്രങ്ങൾ ധരിച്ചവനെപ്പോലെയാണ്." (ബു,മു)', 'أَسْمَاءَ', 'അസ്മാഅ്(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 114, 114, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=82 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 233, 'عَنْ عُرْوَةَ رَضِيَ اللهُ عَنْهَا قَالَ: قَالَتْ عَائِشَةُ رَضِيَ اللهُ عَنْهَا: يَا ابْنَ أُخْتِي، كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَا يُفَضِّلُ بَعْضَنَا عَلَى بَعْضٍ فِي الْقَسْمِ، مِنْ مُكْثِهِ عِنْدَنَا، وَكَانَ قَلَّ يَوْمٌ إِلَّا وَهُوَ يَطُوفُ عَلَيْنَا جَمِيعًا، فَيَدْنُو مِنْ كُلِّ امْرَأَةٍ مِنْ غَيْرِ مَسِيسٍ حَتَّى يَبْلُغَ إِلَى الَّتِي هُوَ يَوْمُهَا فَيَبِيتَ عِنْدَهَا، وَلَقَدْ قَالَتْ سَوْدَةُ بِنْتُ زَمْعَةَ، حِينَ أَسَنَّتْ وَفَرِقَتْ أَنْ يُفَارِقَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: يَا رَسُولَ اللهِ، يَوْمِي لِعَائِشَةَ. فَقَبِلَ ذَلِكَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْهَا، قَالَتْ: نَقُولُ: فِي ذَلِكَ أَنْزَلَ اللهُ تَعَالَى وَفِي أَشْبَاهِهَا: {وَإِنِ امْرَأَةٌ خَافَتْ مِنْ بَعْلِهَا نُشُوزًا} [النساء: ١٢٨] (ق,د)', 'ഉർവ്വ(റ): ആഇശ(റ) പറഞ്ഞു: എന്റെ സഹോദരീ പുത്രാ, ഞങ്ങളുടെ അടുത്ത് തങ്ങുന്നതിൽ റസൂൽ(സ) ഞങ്ങളിൽ ചിലർക്ക് ചിലരേക്കാൾ ശ്രേഷ്ഠത, (ദിവസം) ഓഹരിവെക്കുന്നതിൽ കൽപിക്കാറില്ല. ഞങ്ങൾ എല്ലാവരുടെയും അടുക്കൽ അവിടന്ന് ചുറ്റാത്ത ദിവസങ്ങൾ വളരെ കുറവായിരുന്നു. അങ്ങനെ അവിടന്ന് എല്ലാ ഭാര്യമാരുടെയും അടുത്ത് ചെന്ന് അവരോട് ബന്ധപ്പെടാതെ, ആ ദിനം ആരുടേതാണോ അവരുടെ അടുക്കൽ രാത്രിയിൽ എത്തിച്ചേരുമായിരുന്നു. വാർദ്ധക്യമെത്തുകയും തിരുമേനി(സ) തന്നെ വേർപിരിയുമെന്ന് ഭയക്കുകയും ചെയ്തപ്പോൾ സൗദ ബിൻതു സംഅ(റ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ ദൂതരേ, എന്റെ ദിവസം ആഇശക്കാണ്. അത് മഹതിയിൽ നിന്ന് തിരുമേനി(സ) സ്വീകരിച്ചു. ആഇശ(റ) പറഞ്ഞു: അതിലും അത് പോലുള്ളവയിലുമാണ് അല്ലാഹു ''ഏതെങ്കിലും സ്ത്രീ തന്റെ ഭർത്താവിൽ നിന്നും പിണക്കം ഭയന്നാൽ'' (നിസാഅ്: 128) എന്ന സൂക്തം അവതരിച്ചതെന്ന് ഞങ്ങൾ പറയുമായിരുന്നു. (ബു,മു,ദ)', 'عُرْوَةَ', 'ഉർവ്വ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], 'النساء: ١٢٨', null, 114, 115, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=82 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 234, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَسْتَأْذِنُنَا إِذَا كَانَ فِي يَوْمِ الْمَرْأَةِ مِنَّا، بَعْدَمَا نَزَلَتْ: {تُرْجِي مَنْ تَشَاءُ مِنْهُنَّ وَتُؤْوِي إِلَيْكَ مَنْ تَشَاءُ} [الأحزاب:٥١] قَالَتْ مَعَاذَةُ: فَقُلْتُ لَهَا: مَا كُنْتِ تَقُولِينَ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ قَالَتْ: كُنْتُ أَقُولُ: إِنْ كَانَ ذَلِكَ إِلَيَّ لَمْ أُوثِرْ أَحَدًا عَلَى نَفْسِي. (ق,د,ن)', 'ആഇശ(റ): ''അവരിൽ നിന്ന് താങ്കൾ ഇഷ്ടപ്പെടുന്നവരെ (അവരുടെ ഊഴം) താങ്കൾക്ക് മാറ്റി നിർത്താം. താങ്കൾ ഉദ്ദേശിക്കുന്ന ആരെയും താങ്കൾക്ക് സ്വീകരിക്കുകയും ചെയ്യാം.'' (അഹ്സാബ്: 51) എന്ന സൂക്തം ഇറങ്ങിയതിന് ശേഷം റസൂൽ(സ) ഞങ്ങളിൽ ഒരു ഭാര്യയുടെ ദിവസം ഞങ്ങളോട് സമ്മതം ചോദിക്കാറുണ്ടായിരുന്നു. മുആദത്(റ) പറഞ്ഞു: അപ്പോൾ ഞാൻ മഹതിയോട് പറഞ്ഞു: താങ്കൾ റസൂൽ(സ)യോട് പറയാറില്ലായിരുന്നോ? മഹതി പറഞ്ഞു: ഞാൻ പറയുമായിരുന്നു: അതെന്നോടായിരുന്നുവെങ്കിൽ ഞാൻ ഒരാളെയും (എന്നേക്കാൾ) മുൻഗണന നൽകുമായിരുന്നില്ല. (ബു,മു,ദ,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], 'الأحزاب:٥١', null, 115, 115, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=82 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 235, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَعَثَ إِلَى النِّسَاءِ – تَعْنِي فِي مَرَضِهِ – فَاجْتَمَعْنَ، فَقَالَ: "إِنِّي لَا أَسْتَطِيعُ أَنْ أَدُورَ بَيْنَكُنَّ، فَإِنْ رَأَيْتُنَّ أَنْ تَأْذَنَّ لِي فَأَكُونَ عِنْدَ عَائِشَةَ فَعَلْتُنَّ". فَأَذِنَّ لَهُ. (د)', 'ആഇശ(റ): റസൂൽ(സ) ഭാര്യമാരിലേക്ക് (ആളെ) അയച്ചു - അവിടത്തെ രോഗകാലത്തന്നാണ് മഹതി ഉദ്ദേശിക്കുന്നത് - അങ്ങിനെ അവർ ഒരുമിച്ചുകൂടി. അവിടന്നരുളി: "നിശ്ചയം എനിക്ക് നിങ്ങൾക്കിടയിൽ കറങ്ങിവരാൻ കഴിയുന്നില്ല. ഞാൻ ആഇശ(റ)യുടെ കൂടെ താമസിക്കുന്നത് നിങ്ങൾക്ക് സമ്മതമാണെങ്കിൽ നിങ്ങളങ്ങനെ ചെയ്യുക." അപ്പോൾ അവർ അവിടത്തേക്ക് സമ്മതം നൽകി." (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 115, 115, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=82 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 236, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا أَرَادَ سَفَرًا أَقْرَعَ بَيْنَ نِسَائِهِ، فَأَيَّتُهُنَّ خَرَجَ سَهْمُهَا خَرَجَ بِهَا مَعَهُ، وَكَانَ يَقْسِمُ لِكُلِّ امْرَأَةٍ مِنْهُنَّ يَوْمَهَا وَلَيْلَتَهَا، غَيْرَ أَنَّ سَوْدَةَ بِنْتَ زَمْعَةَ وَهَبَتْ يَوْمَهَا لِعَائِشَةَ. (خ,د,جه)', 'ആഇശ(റ): റസൂൽ(സ) യാത്ര പോകാൻ ഉദ്ദേശിച്ചാൽ തന്റെ ഭാര്യമാർക്കിടയിൽ നറുക്കിടുമായിരുന്നു. ആർക്കാണോ നറുക്ക് വീഴുന്നത് അവരെയും കൂടെക്കൂട്ടി അവിടന്ന് പുറപ്പെടുമായിരുന്നു. അവിടന്ന് എല്ലാ ഭാര്യമാർക്കും അവരുടെ രാത്രിയും പകലും ഊഴം നൽകാറുണ്ടായിരുന്നു. പക്ഷേ, സൗദതു ബിൻതു സംഅ(റ) തന്റെ ദിനം ആഇശ(റ)ക്ക് നൽകിയിരുന്നു. (ബു,ദ,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ','د','جه']::text[], array['ബു','ദ','ജ']::text[], null, null, 115, 115, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=82 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 237, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا خَرَجَ أَقْرَعَ بَيْنَ نِسَائِهِ، فَطَارَتِ الْقُرْعَةُ لِعَائِشَةَ وَحَفْصَةَ، وَكَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا كَانَ بِاللَّيْلِ سَارَ مَعَ عَائِشَةَ يَتَحَدَّثُ. فَقَالَتْ حَفْصَةُ: أَلَا تَرْكَبِينَ اللَّيْلَةَ بَعِيرِي وَأَرْكَبُ بَعِيرَكِ تَنْظُرِينَ وَأَنْظُرُ فَقَالَتْ: بَلَى، فَرَكِبَتْ، فَجَاءَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَى جَمَلِ عَائِشَةَ وَعَلَيْهِ حَفْصَةُ، فَسَلَّمَ عَلَيْهَا ثُمَّ سَارَ حَتَّى نَزَلُوا وَافْتَقَدَتْهُ عَائِشَةُ. فَلَمَّا نَزَلُوا جَعَلَتْ رِجْلَيْهَا بَيْنَ الْإِذْخِرِ وَتَقُولُ: يَا رَبِّ سَلِّطْ عَلَيَّ عَقْرَبًا أَوْ حَيَّةً تَلْدَغُنِي، وَلَا أَسْتَطِيعُ أَنْ أَقُولَ لَهُ شَيْئًا. (ق)', 'ആഇശ(റ): നബി(സ) യാത്ര പുറപ്പെട്ടാൽ തന്റെ ഭാര്യമാർക്കിടയിൽ നറുക്കിടുമായിരുന്നു. അങ്ങനെ നറുക്ക് ആഇശ(റ)ക്കും ഹഫ്സ(റ)ക്കും വീണു. നബി(സ) രാത്രിയായാൽ ആഇശയുടെ കൂടെ സംസാരിച്ച് നടക്കുമായിരുന്നു. അപ്പോൾ ഹഫ്സ(റ) പറഞ്ഞു: ഈ രാത്രിയിൽ നീ എന്റെ ഒട്ടകത്തിലും ഞാൻ നിന്റെ ഒട്ടകത്തിലും സവാരി ചെയ്യാം. (എന്താണ് സംഭവിക്കുന്നതെന്ന്) നമുക്ക് നോക്കുകയും ചെയ്യാം. അപ്പോൾ ആഇശ(റ) പറഞ്ഞു: അതെ. അങ്ങനെ അവർ വാഹനം കയറി. അപ്പോൾ തിരുമേനി(സ) ആഇശ(റ)യുടെ ഒട്ടകത്തിന്റെ അടുത്ത് വന്നു. അതിന്റെ മുകളിലാണെങ്കിൽ ഹഫ്സ(റ)യുമാണ്. അവിടന്ന് മഹതിക്ക് സലാം ചൊല്ലി ഒട്ടകപ്പുറത്ത് കയറി മുന്നോട്ട് പോയി. ഉദ്ദിശ്ട സ്ഥലത്ത് എത്തിയപ്പോൾ അവർ ഇറങ്ങി. ആഇശ(റ)ക്ക് നബി(സ)യെ തിരഞ്ഞുനോക്കി. അവർ ഇറങ്ങിയപ്പോൾ മഹതി ഇദ്ഖിറി(ഒരു തരം ചെടി)ലേക്ക് തന്റെ രണ്ടുകാലുകളും തിരിച്ച് വെച്ചു. എന്നിട്ട് പറഞ്ഞു: എന്റെ രക്ഷിതാവേ, എന്റെ കാലിൽ തേളോ പാമ്പോ കടിക്കട്ടെ. എനിക്ക് അവിടത്തോട് ഒന്നും പറയാൻകഴിയില്ല. (ബു,മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 115, 116, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=82 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 238, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَجَدَ عَلَى صَفِيَّةَ بِنْتِ حُيَيٍّ فِي شَيْءٍ، فَقَالَتْ صَفِيَّةُ: يَا عَائِشَةُ، هَلْ لَكِ أَنْ تُرْضِي رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِّي، وَلَكِ يَوْمِي؟ قَالَتْ: نَعَمْ. فَأَخَذَتْ خِمَارًا لَهَا مَصْبُوغًا بِزَعْفَرَانٍ، فَرَشَّتْهُ بِالْمَاءِ لِيَفُوحَ رِيحُهُ، ثُمَّ قَعَدَتْ إِلَى جَنْبِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَا عَائِشَةُ، إِلَيْكِ عَنِّي، إِنَّهُ لَيْسَ يَوْمَكِ". فَقَالَتْ: ذَلِكَ فَضْلُ اللهِ يُؤْتِيهِ مَنْ يَشَاءُ. فَأَخْبَرَتْهُ بِالْأَمْرِ، فَرَضِيَ عَنْهَا. [ز: فِي سنده مَجْهُولٌ] (جه)', 'ആഇശ(റ): റസൂൽ(സ) സ്വഫിയ്യ ബിൻത് ഹുയയ്യിനോട് ഒരു കാര്യത്തിൽ ദേഷ്യത്തിലായി. അപ്പോൾ സ്വഫിയ്യ(റ) പറഞ്ഞു: ആഇശാ, നിനക്ക് റസൂൽ(സ)യെ എന്നിൽ പ്രീതിപ്പെടുത്താനാകുമോ? നിനക്കെന്റെ ദിവസം തരാം. അവർ (ആഇശ(റ)) പറഞ്ഞു: അതെ. അപ്പോൾ മഹതി തന്റെ കുങ്കുമത്തിൽ മുക്കിയ ഒരു തട്ടമെടുത്തു. എന്നിട്ടതിൽ വെള്ളം കുടഞ്ഞു. അതിന്റെ വാസന പരന്നു. പിന്നീട് മഹതി റസൂൽ(സ)യുടെ ഒരു ഭാഗത്തിരുന്നു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഓ ആഇശ(റ) നീ എന്നിൽ നിന്ന് മാറിനിൽക്കൂ. നിശ്ചയം ഇത് നിന്റെ ദിനമല്ല." അപ്പോൾ മഹതി പറഞ്ഞു: അത് അല്ലാഹുവിന്റെ ഔദാര്യമാണ്. അവനുദ്ദേശിച്ചവർക്ക് അത് നൽകും. എന്നിട്ട് മഹതി കാര്യം പറഞ്ഞു: അപ്പോൾ അവിടന്ന് അവരെ (സ്വഫിയ്യ(റ)) തൃപ്തിപ്പെട്ടു. (പരമ്പരയിൽ അറിയപ്പെടാത്ത നിവേദകനുണ്ട്.) (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: فِي سنده مَجْهُولٌ', null, 116, 116, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=82 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 239, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا أَنَّهَا قَالَتْ: نَزَلَتْ هَذِهِ الْآيَةُ: {وَالصُّلْحُ خَيْرٌ} [النساء: ١٢٨] فِي رَجُلٍ كَانَتْ تَحْتَهُ امْرَأَةٌ قَدْ طَالَتْ صُحْبَتُهَا، وَوَلَدَتْ مِنْهُ أَوْلَادًا، فَأَرَادَ أَنْ يَسْتَبْدِلَ بِهَا، فَرَاضَتْهُ عَلَى أَنْ تُقِيمَ عِنْدَهُ وَلَا يَقْسِمَ لَهَا. (جه)', 'ആഇശ(റ): ഒരുത്തന്റെ വിഷയത്തിലാണ് ഇപ്രകാരം സൂക്തമിറങ്ങിയത്: ''ഒത്തുതീർക്കലാണ് നന്മ'' (നിസാഅ്: 128) അയാൾക്ക് കീഴിൽ ഒരു സ്ത്രീയുണ്ടായിരുന്നു. അവളുമായി കൂറെ കാലം സഹവസിച്ചു. അവനിൽ നിന്നവൾ കുട്ടികളെ പ്രസവിച്ചു. അങ്ങനെ അയാൾ അവളെ ഒഴിവാക്കി വേറെ സ്ത്രീയെ വിവാഹം കഴിക്കാൻ ഉദ്ദേശിച്ചു. അപ്പോൾ അവൾ തനിക്ക് ഊഴം ഇല്ലാതെ തന്നെ അയാളുടെ കൂടെക്കഴിയാൻ ഇഷ്ടപ്പെട്ടു. (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'النساء: ١٢٨', null, 116, 116, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=82 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 240, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: مَا رَأَيْتُ امْرَأَةً أَحَبَّ إِلَيَّ أَنْ أَكُونَ فِي مِسْلَاخِهَا مِنْ سَوْدَةَ بِنْتِ زَمْعَةَ، مِنِ امْرَأَةٍ فِيهَا حِدَّةٌ، قَالَتْ: فَلَمَّا كَبِرَتْ جَعَلَتْ يَوْمَهَا مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِعَائِشَةَ، قَالَتْ: يَا رَسُولَ اللهِ قَدْ جَعَلْتُ يَوْمِي مِنْكَ لِعَائِشَةَ، فَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقْسِمُ لِعَائِشَةَ يَوْمَيْنِ، يَوْمَهَا وَيَوْمَ سَوْدَةَ. (م)', 'ആഇശ(റ): നല്ല ശരീരശേഷിയും ബുദ്ധിയുമുള്ള സ്ത്രീകളിൽ വെച്ച് സൗദതുബിൻതു സംഅ(റ)യേക്കാൾ, എനിക്ക് പാർപ്പിടത്തിൽ കിടക്കാൻ ഏറ്റവും ഇഷ്ടപ്പെട്ട മറ്റൊരു സ്ത്രീയെയും ഞാൻ കണ്ടിട്ടില്ല. നിവേദക പറയുന്നു: അവർ (സൗദ) പ്രായമായപ്പോൾ തിരുമേനി(സ) തന്റെകൂടെ കഴിയേണ്ട ദിവസം അവർ ആഇശ(റ)ക്ക് നൽകി. അവർ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, ഞാൻ എന്റെ ദിവസം ആഇശക്ക് നൽകിയിട്ടുണ്ട്. അങ്ങനെ റസൂൽ(സ) ആഇശക്ക് രണ്ടുദിവസങ്ങൾ ഊഴം നൽകാറുണ്ടായിരുന്നു. അവരുടെ ദിനവും സൗദയുടെ ദിനവും. (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 117, 117, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 241, 'عَنْ عَطَاءٍ رَضِيَ اللهُ عَنْهُ قَالَ: حَضَرْنَا مَعَ ابْنِ عَبَّاسٍ جَنَازَةَ مَيْمُونَةَ زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِسَرِفَ، فَقَالَ ابْنُ عَبَّاسٍ: هَذِهِ زَوْجُ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَإِذَا رَفَعْتُمْ نَعْشَهَا فَلَا تُزَعْزِعُوا وَلَا تُزَلْزِلُوا وَارْفُقُوا، فَإِنَّهُ كَانَ عِنْدَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تِسْعٌ، فَكَانَ يَقْسِمُ لِثَمَانٍ وَلَا يَقْسِمُ لِوَاحِدَةٍ. قَالَ عَطَاءٌ: الَّتِي لَا يَقْسِمُ لَهَا صَفِيَّةُ بِنْتُ حُيَيِّ بْنِ أَخْطَبَ. (م)', 'അത്വാഅ്(റ): സരിഫയിൽ വെച്ച് ഞങ്ങൾ ഇബ്നുഅബ്ബാസ്(റ)വിന്റെ കൂടെ, നബി(സ)യുടെ പത്നി മൈമൂന(റ)യുടെ ജനാസയിൽ പങ്കെടുത്തു. അപ്പോൾ ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: ഇത് നബി(സ)യുടെ ഭാര്യയാണ്. അവരുടെ മൃതശരീരം ഉയർത്തുമ്പോൾ നിങ്ങൾ ധൃതികൂട്ടുകയോ ഇളക്കുകയോ ചെയ്യാതെ സൗമ്യമായി പെരുമാറുക. നിശ്ചയം തിരുമേനി(സ)ക്ക് ഒമ്പത് ഭാര്യമാരുണ്ടായിരുന്നു. അവിടന്ന് എട്ട്പേർക്ക് ഊഴം വീതിക്കുകയും ഒരാൾക്ക് നൽകാതിരിക്കുകയും ചെയ്യുമായിരുന്നു. അത്വാഅ്: അവിടന്ന് ഊഴം നൽകാതിരുന്നത് സ്വഫിയ്യതുബിൻത് ഹുയയ്യിനിബ്നി അഖ്തബ്(റ)ക്ക് ആയിരുന്നു. (മു)', 'عَطَاءٍ', 'അത്വാഅ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 117, 117, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=84 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 242, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ لِلثَّيِّبِ ثَلَاثًا وَلِلْبِكْرِ سَبْعًا". (ق,د,ت,جه)', 'അനസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം കന്യകക്ക് (അവളെ വിവാഹം കഴിച്ചാൽ) ഏഴും വിധവക്ക് (അവളെ വിവാഹം കഴിച്ചാൽ) മൂന്നും ദിവസങ്ങളാണ് (ആദ്യം തുടർച്ചയായി കൂടെ കഴിയേണ്ടത്.)" (ബു,മു,ദ,തു,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 117, 117, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=85 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 243, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَمَّا تَزَوَّجَ أُمَّ سَلَمَةَ أَقَامَ عِنْدَهَا ثَلَاثًا، وَقَالَ: "لَيْسَ بِكِ عَلَى أَهْلِكِ هَوَانٌ، إِنْ شِئْتِ سَبَّعْتُ لَكِ، وَإِنْ سَبَّعْتُ لَكِ سَبَّعْتُ لِنِسَائِي". (م,د,جه)', 'ഉമ്മുസലമ(റ): റസൂൽ(സ) ഉമ്മുസലമയെ വിവാഹം ചെയ്തപ്പോൾ അവിടന്ന് മൂന്ന് ദിവസം മഹതിയുടെ കൂടെ കഴിഞ്ഞു. എന്നിട്ട് അവിടന്ന് പറഞ്ഞു: "അത് നിന്റെ ഭർത്താവിന് മോശമുള്ളക കാര്യമില്ല. നീ ആഗ്രഹിക്കുന്നുവെങ്കിൽ ഞാൻ ഏഴ് ദിവസം നിന്റെ കൂടെക്കഴിയാം. നിന്റെ കൂടെ ഏഴ് ദിവസം കഴിച്ചുകൂട്ടിയാൽ എന്റെ (മറ്റു) ഭാര്യമാർക്കും ഞാൻ ഏഴ് ദിവസമാക്കും." (മു,ദ,ജ)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 117, 118, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=85 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 244, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: وَلَوْ شِئْتُ أَنْ أَقُولَ قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَلَكِنْ قَالَ: السُّنَّةُ إِذَا تَزَوَّجَ الْبِكْرَ أَقَامَ عِنْدَهَا سَبْعًا وَإِذَا تَزَوَّجَ الثَّيِّبَ أَقَامَ عِنْدَهَا ثَلَاثًا. (خ)', 'അനസ്(റ): നബി(സ) പറഞ്ഞു എന്ന് വേണമെങ്കിൽ ഞാൻ പറയും, പക്ഷേ, അദ്ദേഹം പറഞ്ഞു: പ്രവാചകചര്യ, അവിടന്ന് കന്യകയെ വിവാഹം കഴിച്ചാൽ അവളുടെയടുക്കൽ ഏഴ്ദിവസം തങ്ങലും വിധവയെ വിവാഹം കഴിച്ചാൽ അവളുടെ അടുക്കൽ മൂന്ന് ദിവസം തങ്ങലുമാണ്. (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 118, 118, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=85 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 245, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا أَخَذَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَفِيَّةَ أَقَامَ عِنْدَهَا ثَلَاثًا، وَكَانَتْ ثَيِّبًا. (د)', 'അനസുബ്നു മാലിക്(റ): സ്വഫിയ്യ(റ)യെ റസൂൽ(സ) കല്യാണം കഴിച്ചപ്പോൾ മൂന്ന് ദിവസം അവരുടെ കൂടെ കൂടി. മഹതി വിധവയായിരുന്നു. (ദ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 118, 118, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=85 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 246, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَوْ أَمَرْتُ أَحَدًا أَنْ يَسْجُدَ لِأَحَدٍ لَأَمَرْتُ الْمَرْأَةَ أَنْ تَسْجُدَ لِزَوْجِهَا، وَلَوْ أَنَّ رَجُلًا أَمَرَ امْرَأَتَهُ أَنْ تَنْقُلَ مِنْ جَبَلٍ أَحْمَرَ إِلَى جَبَلٍ أَسْوَدَ، وَمِنْ جَبَلٍ أَسْوَدَ إِلَى جَبَلٍ أَحْمَرَ، لَكَانَ نَوْلُهَا أَنْ تَفْعَلَ". [ز: فِي سَنَدِهِ ضَعِيفٌ، لَكِنْ لَهُ شَوَاهِدُ] (ت,جه)', 'ആഇശ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഞാൻ ആരോടെങ്കിലും ആർക്കെങ്കിലും സാഷ്ടാംഗം ചെയ്യാൻ കൽപ്പിച്ചിരുന്നെങ്കിൽ ഭാര്യയോട് തന്റെ ഭർത്താവിന് സാഷ്ടാംഗം ചെയ്യാൻ തീർച്ചയായും ഞാൻ കൽപ്പിക്കുമായിരുന്നു. ഒരു പുരുഷൻ (ഭർത്താവ്) ഒരു സ്ത്രീയോട് (ഭാര്യയോട്) ഒരു ചുവന്ന മലയിൽ നിന്നും ഒരു കറുത്ത മലയിലേക്കും കറുത്ത മലയിൽ നിന്നും ചുവന്ന മലയിലേക്കും നീങ്ങാൻ കൽപ്പിച്ചാൽ അപ്രകാരം ചെയ്യൽ അവളുടെ ബാധ്യതയാകുമായിരുന്നു." (ഈ ഹദീസിന്റെ പരമ്പരയിൽ ഭംഗമുള്ളവനുണ്ടെങ്കിലും ഹദീസിന് ശാഹിദ് ഉണ്ട്.) (തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], 'ز: فِي سَنَدِهِ ضَعِيفٌ، لَكِنْ لَهُ شَوَاهِدُ', null, 118, 118, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 247, 'عَنْ عَبْدِ اللهِ بْنِ أَبِي أَوْفَى رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا قَدِمَ مُعَاذٌ مِنَ الشَّامِ سَجَدَ لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، قَالَ: "مَا هَذَا يَا مُعَاذُ". قَالَ: أَتَيْتُ الشَّامَ، فَوَافَقْتُهُمْ يَسْجُدُونَ لِأَسَاقِفَتِهِمْ وَبَطَارِقَتِهِمْ، فَوَدِدْتُ فِي نَفْسِي أَنْ نَفْعَلَ ذَلِكَ بِكَ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "فَلَا تَفْعَلُوا، فَإِنِّي لَوْ كُنْتُ آمِرًا أَحَدًا أَنْ يَسْجُدَ لِغَيْرِ اللهِ لَأَمَرْتُ الْمَرْأَةَ أَنْ تَسْجُدَ لِزَوْجِهَا. وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ، لَا تُؤَدِّي الْمَرْأَةُ حَقَّ رَبِّهَا حَتَّى تُؤَدِّيَ حَقَّ زَوْجِهَا، وَلَوْ سَأَلَهَا نَفْسَهَا وَهِيَ عَلَى قَتَبٍ لَمْ تَمْنَعْهُ". (جه)', 'അബ്ദുല്ലാഹിബ്നു അബീഔഫാ(റ): മുആദ്(റ) ശാമിൽ നിന്നും വന്നപ്പോൾ നബി(സ)ക്ക് സാഷ്ടാംഗം ചെയ്തു. അവിടന്ന് പറഞ്ഞു: "മുആദേ, എന്താണിത്." അദ്ദേഹം പറഞ്ഞു: ഞാൻ ശാമിൽ പോയി. അപ്പോൾ അവർ തങ്ങളുടെ കൃസ്തീയ സഭാധ്യക്ഷൻമാർക്കും റോമൻ സേനാനായകൻമാർക്കും സാഷ്ടാംഗം ചെയ്യുന്നത് ഞാൻ കണ്ടു. അപ്പോൾ ഞാൻ എന്റെ മനസ്സിൽ കൊതിച്ചു, അങ്ങേക്ക് ഞങ്ങളും അപ്രകാരം ചെയ്യണമെന്ന്. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "എന്നാൽ നിങ്ങളത് ചെയ്യരുത്. കാരണം ഞാൻ അല്ലാഹുവല്ലാത്ത മറ്റാർക്കെങ്കിലും സാഷ്ടാംഗം ചെയ്യാൻ കൽപിക്കുമായിരുന്നുവെങ്കിൽ സ്ത്രീയോട് തന്റെ ഭർത്താവിന് സാഷ്ടാംഗം ചെയ്യാൻ കൽപിക്കുമായിരുന്നു. മുഹമ്മദിന്റെ ശരീരം ആരുടെ കയ്യിലാണോ അവൻ തന്നെ സത്യം! സ്ത്രീ തന്റെ ഭാർത്താവിനോടുള്ള ബാധ്യത വീട്ടുന്നത് വരെ, തന്റെ രക്ഷിതാവിനോടുള്ള കടമ തീർക്കുകയില്ല. അവൾ ഒട്ടകക്കട്ടിലിലായിരിക്കെ അവൻ അവളോട് തന്റെ ശരീരം ചോദിച്ചാൽ അവളവനെ തടയരുത്." (ജ)', 'عَبْدِ اللهِ بْنِ أَبِي أَوْفَى', 'അബ്ദുല്ലാഹിബ്നു അബീഔഫാ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 118, 119, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 248, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "أَيُّمَا امْرَأَةٍ مَاتَتْ وَزَوْجُهَا عَنْهَا رَاضٍ دَخَلَتِ الْجَنَّةَ". (ت,جه)', 'ഉമ്മുസലമ(റ): ഞാൻ റസൂൽ(സ) പറയുന്നത് കേട്ടു: "ഏത് സ്ത്രീയും, തന്റെ ഭർത്താവ് അവളോട് സംതൃപ്തനായിരിക്കെ, (അവൾ) മരണപ്പെട്ടാൽ അവൾ സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കുന്നതാണ്." (തു,ജ)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 119, 119, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 249, 'عَنْ قَيْسِ بْنِ سَعْدٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَيْتُ الْحِيرَةَ فَرَأَيْتُهُمْ يَسْجُدُونَ لِمَرْزُبَانٍ لَهُمْ، فَقُلْتُ: رَسُولُ اللهِ أَحَقُّ أَنْ يُسْجَدَ لَهُ، قَالَ: فَأَتَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: إِنِّي أَتَيْتُ الْحِيرَةَ فَرَأَيْتُهُمْ يَسْجُدُونَ لِمَرْزُبَانٍ لَهُمْ، فَأَنْتَ يَا رَسُولَ اللهِ أَحَقُّ أَنْ نَسْجُدَ لَكَ. قَالَ: "أَرَأَيْتَ لَوْ مَرَرْتَ بِقَبْرِي أَكُنْتَ تَسْجُدُ لَهُ". قَالَ: قُلْتُ: لَا، قَالَ: "فَلَا تَفْعَلُوا، لَوْ كُنْتُ آمِرًا أَحَدًا أَنْ يَسْجُدَ لِأَحَدٍ لَأَمَرْتُ النِّسَاءَ أَنْ يَسْجُدْنَ لِأَزْوَاجِهِنَّ، لِمَا جَعَلَ اللهُ لَهُمْ عَلَيْهِنَّ مِنَ الْحَقِّ". (د)', 'ഖൈസുബ്നു സഅ്ദ്(റ): ഞാൻ ഹീറയിൽ ചെന്നു. അപ്പോൾ അവർ അവരുടെ പേർഷ്യൻ ഗവർണ്ണർക്ക് സാഷ്ടാംഗം ചെയ്യുന്നത് ഞാൻ കണ്ടു. അപ്പോൾ ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതനാണ് സാഷ്ടാംഗം ചെയ്യപ്പെടാൻ ഏറ്റവും അർഹൻ. അദ്ദേഹം പറയുന്നു: അങ്ങനെ ഞാൻ നബി(സ)യുടെ അടുത്ത് ചെന്ന് പറഞ്ഞു: നിശ്ചയം ഞാൻ ഹീറയിൽ ചെന്നു. അപ്പോൾ അവർ അവരുടെ പേർഷ്യൻ ഗവർണർക്ക് സാഷ്ടാംഗം ചെയ്യുന്നത് ഞാൻ കണ്ടു. അല്ലാഹുവിന്റെ റസൂലേ, ഞങ്ങൾ സാഷ്ടാംഗം ചെയ്യാൻ അങ്ങാണ് കൂടുതൽ ബന്ധപ്പെട്ടവർ. അവിടന്നരുളി: "താങ്കൾ എന്റെ ഖബ്റിന്റെ അരികിലൂടെ നടക്കുമ്പോൾ അതിന് സുജൂദ് ചെയ്യുമോ എന്ന് പറഞ്ഞുതരൂ." ഞാൻ പറഞ്ഞു: ഇല്ല. അവിടന്ന് പറഞ്ഞു: "എങ്കിൽ നിങ്ങളപ്രകാരം ചെയ്യരുത്. ഞാൻ ആരോടെങ്കിലും വല്ലവനും സുജൂദ് ചെയ്യാൻ കൽപ്പിക്കുമായിരുന്നുവെങ്കിൽ സ്ത്രീകളോട് തങ്ങളുടെ ഭർത്താക്കൻമാർക്ക് സുജൂദ് ചെയ്യാൻ കൽപിക്കുമായിരുന്നു. അല്ലാഹു ഭർത്താക്കൻമാർക്ക് ഭാര്യമാരുടെ മേലിൽ വെച്ച ബാധ്യതകൾ കാരണത്താലാണത്. (ദ)', 'قَيْسِ بْنِ سَعْدٍ', 'ഖൈസുബ്നു സഅ്ദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 119, 119, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 250, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا دَعَا الرَّجُلُ امْرَأَتَهُ إِلَى فِرَاشِهِ فَأَبَتْ فَلَمْ تَأْتِهِ، فَبَاتَ غَضْبَانَ عَلَيْهَا، لَعَنَتْهَا الْمَلَائِكَةُ حَتَّى تُصْبِحَ". (ق,د)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "പുരുഷൻ തന്റെ പത്നിയെ വിരിപ്പിലേക്ക് വിളിക്കുകയും അവൾ വിസമ്മതിച്ച് വരാതിരിക്കുകയും അവൻ അവളോട് ദേഷ്യമുള്ളവനായി ആ രാത്രി കഴിച്ച് കൂട്ടുകയും ചെയ്താൽ, നേരം പുലരുവോളം മലക്കുകൾ അവളെ ശപിച്ച് കൊണ്ടിരിക്കും." (ബു,മു,ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 119, 119, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 251, 'عَنْ طَلْقِ بْنِ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا الرَّجُلُ دَعَا زَوْجَتَهُ لِحَاجَتِهِ فَلْتَأْتِهِ وَإِنْ كَانَتْ عَلَى التَّنُّورِ". حَسَنٌ. (ت)', 'ത്വൽഖുബ്നു അലി(റ): റസൂൽ(സ) പറഞ്ഞു: "പുരുഷൻ തന്റെ പത്നിയെ തന്റെ ആവശ്യത്തിനായി വിളിച്ചാൽ അവൾ അവന്റെയടുക്കൽ പോയിക്കൊള്ളട്ടെ, അവൾ അടുപ്പിനടുത്താണെങ്കിലും." (തു)', 'طَلْقِ بْنِ عَلِيٍّ', 'ത്വൽഖുബ്നു അലി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 119, 119, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 252, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَحِلُّ لِلْمَرْأَةِ أَنْ تَصُومَ وَزَوْجُهَا شَاهِدٌ إِلَّا بِإِذْنِهِ وَلَا تَأْذَنَ فِي بَيْتِهِ إِلَّا بِإِذْنِهِ، وَمَا أَنْفَقَتْ مِنْ نَفَقَةٍ مِنْ غَيْرِ أَمْرِهِ فَإِنَّهُ يُؤَدَّى إِلَيْهِ شَطْرُهُ". (خ,ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "തന്റെ ഭർത്താവുണ്ടായിരിക്കെ അവന്റെ സമ്മതം കൂടാതെ ഒരു സ്ത്രീ നോമ്പെടുക്കൽ അനുവദനീയമല്ല. അവന്റെ സമ്മതം കൂടാതെ അവൾ ആ വീട്ടിൽ (മറ്റുള്ളവർക്ക്) സമ്മതം നൽകരുത്. അവന്റെ കൽപനയല്ലാതെ അവൾ വല്ല ചെലവും ചെലവഴിച്ചാൽ അതിന്റെ പകുതി അവന്ന് തിരിച്ച് കൊടുക്കണം." (ബു,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','ت','جه']::text[], array['ബു','തു','ജ']::text[], null, null, 119, 120, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 253, 'عَنْ أُسَامَةَ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "قُمْتُ عَلَى بَابِ الْجَنَّةِ فَكَانَ عَامَّةُ مَنْ دَخَلَهَا الْمَسَاكِينُ وَأَصْحَابُ الْجَدِّ مَحْبُوسُونَ، غَيْرَ أَنَّ أَصْحَابَ النَّارِ قَدْ أُمِرَ بِهِمْ إِلَى النَّارِ. وَقُمْتُ عَلَى بَابِ النَّارِ فَإِذَا عَامَّةُ مَنْ دَخَلَهَا النِّسَاءُ". (ق)', 'ഉസാമ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഞാൻ സ്വർഗ്ഗവാതിൽക്കൽ നിന്നു. അപ്പോൾ അതിൽ കടക്കുന്ന മിക്കവരും മിസ്കീൻ(പാവപ്പെട്ടവർ) ആണ്. സമ്പത്തുള്ളവർ ചോദ്യം ചെയ്യപ്പെടുന്നവരുമാണ്. പക്ഷേ, നരകത്തിന്റെയാളുകൾ നരകത്തിലേക്ക് കൽപ്പിക്കപ്പെട്ടിരിക്കുന്നു. ഞാൻ നരക കവാടത്തിൽ നിന്നു. അപ്പോൾ അതിൽ കടക്കുന്ന മിക്കവരും സ്ത്രീകളാണ്." (ബു,മു)', 'أُسَامَةَ', 'ഉസാമ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 120, 120, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 254, 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَتِ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ امْرَأَةٌ مَعَهَا صَبِيَّانِ لَهَا، قَدْ حَمَلَتْ أَحَدَهُمَا وَهِيَ تَقُودُ الْآخَرَ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "حَامِلَاتٌ وَالِدَاتٌ، رَحِيمَاتٌ. لَوْلَا مَا يَأْتِينَ إِلَى أَزْوَاجِهِنَّ دَخَلَ مُصَلِّيَاتُهُنَّ الْجَنَّةَ". [ز: سنده منقطع] (جه)', 'അബൂഉമാമ(റ): നബി(സ)യുടെ അടുത്ത് തന്റെ രണ്ടുകുട്ടികളുമായി ഒരു സ്ത്രീ വന്നു. അവരിലൊരാളെ അവൾ ചുമക്കുകയും മറ്റവളെ നയിക്കുകയും ചെയ്യുന്നു. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "ഗർഭിണികളായ സ്ത്രീകൾ, (പിന്നീട്) പ്രസവിക്കുന്നവർ, (കുട്ടികളോട്) കാരുണ്യം കാണിക്കുന്നവർ. അവർ തങ്ങളുടെ ഭർത്താക്കൻമാരെ വെറുപ്പിച്ചിട്ടില്ലെങ്കിൽ അവരിൽ നിന്ന് നിസ്കരിക്കുന്നവർ സ്വർഗ്ഗത്തിൽ കടക്കുന്നതാണ്." (പരമ്പരയിൽ ഒരു മുൻഖതിഅ് ഉണ്ട്.) (ജ)', 'أَبِي أُمَامَةَ', 'അബൂഉമാമ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: سنده منقطع', null, 120, 120, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=87 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 255, 'عَنْ مُعَاذِ بْنِ جَبَلٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تُؤْذِي امْرَأَةٌ زَوْجَهَا إِلَّا قَالَتْ زَوْجَتُهُ مِنَ الْحُورِ الْعِينِ: لَا تُؤْذِيهِ، قَاتَلَكِ اللهُ، فَإِنَّمَا هُوَ عِنْدَكِ دَخِيلٌ، أَوْشَكَ أَنْ يُفَارِقَكِ إِلَيْنَا". (ت,جه)', 'മുആദുബ്നു ജബൽ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരു സ്ത്രീയും തന്റെ ഭർത്താവിനെ ബുദ്ധിമുട്ടിക്കുകയില്ല, ഹൂറുൽഈനുകളിൽ നിന്നുള്ള അവന്റെ സഖി ഇപ്രകാം പറഞ്ഞിട്ടല്ലാതെ: അദ്ദേഹത്തെ നീ ബുദ്ധിമുട്ടിക്കരുത്. അല്ലാഹു നിന്നെ നശിപ്പിക്കട്ടെ. നിശ്ചയം അദ്ദേഹം നിന്റെയടുക്കൽ യാത്രികനായ ഒരു അതിഥി മാത്രമാണ്. ഉടൻ നിന്നെ വിട്ട്പിരിഞ്ഞ് ഞങ്ങളുടെ അടുത്തേക്ക് വരുന്നതാണ്." (തു,ജ)', 'مُعَاذِ بْنِ جَبَلٍ', 'മുആദുബ്നു ജബൽ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 120, 120, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=87 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 256, 'عَنْ مُعَاوِيَةَ بْنِ حَيْدَةَ الْقُشَيْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا سَأَلَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: مَا حَقُّ الْمَرْأَةِ عَلَى الزَّوْجِ؟ قَالَ: "أَنْ يُطْعِمَهَا إِذَا طَعِمَ، وَأَنْ يَكْسُوَهَا إِذَا اكْتَسَى، وَلَا يَضْرِبِ الْوَجْهَ، وَلَا يُقَبِّحْ، وَلَا يَهْجُرْ إِلَّا فِي الْبَيْتِ". (د,جه)', 'മുആവിയതുബ്നു ഹൈദതിൽ ഖുശൈരി(റ): ഒരാൾ നബി(സ)യോട് ചോദിച്ചു: ഭർത്താവ് ഭാര്യക്ക് ചെയ്യേണ്ട ബാധ്യത എന്താണ്? അവിടന്ന് പറഞ്ഞു: "അവൻ ഭക്ഷിക്കുമ്പോൾ അവളെയും ഭക്ഷിപ്പിക്കുക, അവൻ വസ്ത്രം ധരിക്കുമ്പോൾ അവളെയും ധരിപ്പിക്കുക. മുഖത്തടിക്കരുത്, മോശപ്പെടുത്തരുത്. വീട്ടിൽ വെച്ചല്ലാതെ അവളെ കിടപ്പറയിൽനിന്ന് മാറ്റിനിർത്തുകയും ചെയ്യരുത്." (ദ,ജ)', 'مُعَاوِيَةَ بْنِ حَيْدَةَ الْقُشَيْرِيِّ', 'മുആവിയതുബ്നു ഹൈദതിൽ ഖുശൈരി(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 120, 121, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=88 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 257, 'عَنْ عَمْرِو بْنِ الْأَحْوَصِ رَضِيَ اللهُ عَنْهُ: أَنَّهُ شَهِدَ حَجَّةَ الْوَدَاعِ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَحَمِدَ اللهَ وَأَثْنَى عَلَيْهِ، وَذَكَّرَ وَوَعَظَ، فَقَالَ: "أَلَا وَاسْتَوْصُوا بِالنِّسَاءِ خَيْرًا، فَإِنَّمَا هُنَّ عَوَانٌ عِنْدَكُمْ، لَيْسَ تَمْلِكُونَ مِنْهُنَّ شَيْئًا غَيْرَ ذَلِكَ، إِلَّا أَنْ يَأْتِينَ بِفَاحِشَةٍ مُبَيِّنَةٍ، فَإِنْ فَعَلْنَ فَاهْجُرُوهُنَّ فِي الْمَضَاجِعِ وَاضْرِبُوهُنَّ ضَرْبًا غَيْرَ مُبَرِّحٍ، فَإِنْ أَطَعْنَكُمْ فَلَا تَبْغُوا عَلَيْهِنَّ سَبِيلًا. أَلَا إِنَّ لَكُمْ عَلَى نِسَائِكُمْ حَقًّا، وَلِنِسَائِكُمْ عَلَيْكُمْ حَقًّا: فَأَمَّا حَقُّكُمْ عَلَى نِسَائِكُمْ فَلَا يُوطِئْنَ فُرُشَكُمْ مَنْ تَكْرَهُونَ، وَلَا يَأْذَنَّ فِي بُيُوتِكُمْ لِمَنْ تَكْرَهُونَ. أَلَا وَحَقُّهُنَّ عَلَيْكُمْ أَنْ تُحْسِنُوا إِلَيْهِنَّ فِي كِسْوَتِهِنَّ وَطَعَامِهِنَّ". حَسَنٌ صَحِيحٌ. (د,ت,ن,جه)', 'അംറുബ്നു അഹ്വസ്(റ): അദ്ദേഹം റസൂൽ(സ)യുടെ കൂടെ വിടവാങ്ങൽ ഹജ്ജിൽ സാക്ഷ്യംവഹിച്ചു. അവിടന്ന് അല്ലാഹുവിനെ സ്തുതിക്കുകയും പുകഴ്ത്തുകയും ചെയ്തു. അവിടന്ന് ഓർമ്മിപ്പിക്കുകയും ഉപദേശിക്കുകയും ചെയ്തു. എന്നിട്ട് പറഞ്ഞു: "അറിയുക, സ്ത്രീകളോട് നന്മചെയ്യണമെന്ന ഉപദേശം നിങ്ങൾ സ്വീകരിക്കുക. അവർ നിങ്ങളുടെ അടുത്ത് ഒരു വിവാഹിത മാത്രമാണ്. അവരിൽ നിന്ന് അതല്ലാത്തതൊന്നിനും നിങ്ങൾ അവകാശികളാകുന്നില്ല. അവൾ വ്യക്തമായ തിന്മചെയ്താലൊഴികെ. അവർ അങ്ങനെ ചെയ്താൽ നിങ്ങൾ അവരെ കിടപ്പറയിൽ നിന്ന് ഒഴിവാക്കുക, ശക്തിയായി വേദനിപ്പിക്കാത്ത അടി അടിക്കുക. അവർ നിങ്ങളെ അനുസരിച്ചാൽ ഒരു വിധത്തിലും അവരോട് അതിക്രമം കാണിക്കരുത്. അറിയുക, നിങ്ങളോട് നിങ്ങളുടെ ഭാര്യമാർക്കും (അവർ നിങ്ങൾക്ക് ചെയ്ത് തരേണ്ടതായ) കടമകളുണ്ട്. അവരോട് നിങ്ങൾക്കും (നിങ്ങൾ അവർക്ക് ചെയ്ത് കൊടുക്കേണ്ടതായ) ബാധ്യതകളുണ്ട്. അവർക്ക് നിങ്ങളോടുള്ള ബാധ്യത, നിങ്ങൾ വെറുക്കുന്നവരോട് നിങ്ങളുടെ വിരിപ്പിൽ അവൾ ശയിക്കാതിരിക്കലും, നിങ്ങൾ വെറുക്കുന്നവർക്ക് നിങ്ങളുടെ വീടുകളിൽ (കയറാൻ) സമ്മതം നൽകാതിരിക്കലുമാണ്. അറിയുക, നിങ്ങൾക്ക് അവരോടുള്ള ബാധ്യത നിങ്ങൾ അവർക്ക് ഭക്ഷണവും വസ്ത്രവും നൽകലാണ്." (ദ,തു,ന,ജ)', 'عَمْرِو بْنِ الْأَحْوَصِ', 'അംറുബ്നു അഹ്വസ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 121, 121, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=88 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 258, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَكْمَلُ الْمُؤْمِنِينَ إِيمَانًا أَحْسَنُهُمْ خُلُقًا، وَخِيَارُكُمْ خِيَارُكُمْ لِنِسَائِهِمْ خُلُقًا". حَسَنٌ صَحِيحٌ. (د,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "തങ്ങളുടെ ഭാര്യമാരോട് ഏറ്റവും നന്നായി പെരുമാറുന്നവരാണ് നിങ്ങളിൽ ഉത്തമരും, സൽസ്വഭാവക്കാരും, പരിപൂർണ്ണ വിശ്വാസികളും." (ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 121, 121, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=88 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 259, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا أَنَّهَا زَفَّتِ امْرَأَةً إِلَى رَجُلٍ مِنَ الْأَنْصَارِ، فَقَالَ نَبِيُّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَا عَائِشَةُ، مَا كَانَ مَعَكُمْ لَهْوٌ؟ فَإِنَّ الْأَنْصَارَ يُعْجِبُهُمُ اللَّهْوُ". (خ)', 'ആഇശ(റ): മഹതി ഒരു സ്ത്രീയെ അൻസാരികളിൽ പെട്ട ഒരാളുടെ അടുത്തേക്ക് ആനയിച്ചു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഓ ആഇശ, നിങ്ങളുടെ കൂടെ നേരംപോക്ക് കളികളൊന്നുമില്ലേ, അൻസാരികൾക്ക് അത് ഇഷ്ടമാണ്." (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 121, 121, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=88 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 260, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ كَانَ يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ فَلَا يُؤْذِي جَارَهُ، وَاسْتَوْصُوا بِالنِّسَاءِ خَيْرًا، فَإِنَّهُنَّ خُلِقْنَ مِنْ ضِلَعٍ، وَإِنَّ أَعْوَجَ شَيْءٍ فِي الضِّلَعِ أَعْلَاهُ، فَإِنْ ذَهَبْتَ تُقِيمُهُ كَسَرْتَهُ، وَإِنْ تَرَكْتَهُ لَمْ يَزَلْ أَعْوَجَ، فَاسْتَوْصُوا بِالنِّسَاءِ خَيْرًا". (ق,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും അല്ലാഹുവിലും അന്ത്യദിനത്തിലും വിശ്വസിക്കുന്നുവെങ്കിൽ അവൻ തന്റെ അയൽവാസിയെ ബുദ്ധിമുട്ടിക്കാതിരിക്കട്ടെ. നിങ്ങൾ ഭാര്യമാരോട് നല്ലരീതിയിൽ പെരുമാറുക. കാരണം അവർ ഒരു വാരിയെല്ലിൽ നിന്ന് സൃഷ്ടിക്കപ്പെട്ടു, വാരിയെല്ലുകളിൽ നിന്ന് ഏറ്റവും വളഞ്ഞത് ഏറ്റവും മുകളിലുള്ളതാണ്. നീ അത് നിവർത്താൻ ശ്രമിച്ചാൽ അത് നീ പൊട്ടിക്കും. അതിനെ അങ്ങനെത്തന്നെ വെച്ചാൽ അത് വളഞ്ഞ് തന്നെയിരിക്കും. അതിനാൽ നിങ്ങൾ സ്ത്രീകളോട് നല്ലരീതിയിൽ അനുവർത്തിക്കുക." (ബു,മു,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 121, 122, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=89 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 261, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "خَيْرُكُمْ خَيْرُكُمْ لِأَهْلِهِ، وَأَنَا خَيْرُكُمْ لِأَهْلِي". [ز: في سنده راو مختلف فيه، وللحديث رواية عن عائشة رضي الله عنها] (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിൽ ഏറ്റവും നല്ലവൻ, തന്റെ വീട്ടുകാരോട് നല്ല(രീതിയിൽ പെരുമാറുന്ന)വനാണ്. നിങ്ങളിൽ വെച്ച് തന്റെ വീട്ടുകാരോട് ഏറ്റവും നല്ല നിലയിൽ പെരുമാറുന്നവൻ ഞാനാണ്." (പരമ്പരയിൽ വിശ്വാസത്തൽ അഭിപ്രായവ്യത്യാസമുള്ള ഒരു നിവേദകനുണ്ട്. ഈ ഹദീസ് ആഇശ(റ)വും ഉദ്ദരിച്ചിട്ടുണ്ട്.) (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده راو مختلف فيه، وللحديث رواية عن عائشة رضي الله عنها', null, 122, 122, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=89 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 262, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: سَابَقَنِي النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَسَبَقْتُهُ. (جه)', 'ആഇശ(റ): നബി(സ) എന്നോട് മത്സരിച്ചു, ഞാൻ അവിടത്തെ മുൻകടന്നു. (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 122, 122, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=89 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 263, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: لَمَّا قَدِمَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْمَدِينَةَ، وَهُوَ عَرُوسٌ بِصَفِيَّةَ بِنْتِ حُيَيٍّ، جِئْنَ نِسَاءُ الْأَنْصَارِ فَأَخْبَرْنَ عَنْهَا، قَالَتْ: فَتَنَكَّرْتُ وَتَنَقَّبْتُ فَذَهَبْتُ، فَنَظَرَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَى عَيْنِي فَعَرَفَنِي، قَالَتْ: فَالْتَفَتَ، فَأَسْرَعْتُ الْمَشْيَ، فَأَدْرَكَنِي فَاحْتَضَنَنِي، فَقَالَ: "كَيْفَ رَأَيْتِ". قَالَتْ: قُلْتُ: أَرْسِلْ، يَهُودِيَّةٌ وَسْطَ يَهُودِيَّاتٍ. [ز: في إسناده ضعيف] (جه)', 'ആഇശ(റ): സ്വഫിയ്യ ബിൻത് ഹുയയ്യിന്റെ പുതുമാരനായിരിക്കെ റസൂൽ(സ) മദീനയിൽ വന്നപ്പോൾ അൻസാരി സ്ത്രീകൾ വന്ന്, സ്വഫിയ്യ(റ)യെ കുറിച്ച് പറഞ്ഞുകൊടുത്തു. മഹതി പറയുന്നു: അപ്പോൾ എന്റെ നിറം മാറി, ഞാനെന്റെ മുഖം മറച്ചു. പിന്നെ എഴുന്നേറ്റ് പോയി. റസൂൽ(സ) എന്റെ കണ്ണുകളിലേക്ക് നോക്കി. അപ്പോൾ എന്നെ തിരിച്ചറിഞ്ഞു. മഹതി പറയുന്നു: ഞാൻ മുഖം തിരിച്ച് പെട്ടെന്ന് നടന്നകന്നു. പക്ഷേ, തിരുമേനി(സ) എന്നെ പിടിച്ചു. അവിടന്നെന്നെ (അവിടത്തെ തൃക്കരങ്ങൾ കൊണ്ട്) കെട്ടിപ്പിടിച്ചു. എന്നിട്ട് അവിടന്ന് പറഞ്ഞു: "നീ എന്താണ് കണ്ടത്. (നിന്റെ അഭിപ്രായമെന്താണ്?)" മഹതി പറയുന്നു: ഞാൻ പറഞ്ഞു: അവളെ വിട്ടേക്കൂ. ജൂതസ്ത്രീകളിൽ പെട്ട ഒരു ജൂതയാണവൾ. (ഈ ഹദീസിന്റെ പരമ്പരയിൽ ഭംഗമുള്ള നിവേദകനുണ്ട്.) (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 122, 122, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=89 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 264, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: مَا عَلِمْتُ حَتَّى دَخَلَتْ عَلَيَّ زَيْنَبُ بِغَيْرِ إِذْنٍ، وَهِيَ غَضْبَى، ثُمَّ قَالَتْ: يَا رَسُولَ اللهِ، أَحَسْبُكَ إِذَا قَلَبَتْ بُنَيَّةُ أَبِي بَكْرٍ ذُرَيْعَتَيْهَا، ثُمَّ أَقْبَلَتْ عَلَيَّ فَأَعْرَضْتُ عَنْهَا، حَتَّى قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "دُونَكِ، فَانْتَصِرِي". فَأَقْبَلْتُ عَلَيْهَا، حَتَّى رَأَيْتُهَا وَقَدْ يَبِسَ رِيقُهَا فِي فِيهَا، مَا تَرُدُّ عَلَيَّ شَيْئًا، فَرَأَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَتَهَلَّلُ وَجْهُهُ. [ز: في سنده مدلس عنعنه] (جه)', 'ആഇശ(റ): സമ്മതമില്ലാതെ സൈനബ്(റ) എന്റെയടുത്ത് കടന്നുവരുന്നത് വരെ ഞാനറിഞ്ഞില്ലായിരുന്നു. അവർ ദേഷ്യത്തിലായിരുന്നു. എന്നിട്ട് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അബൂബക്കറിന്റെ ചെറിയ പെൺകുട്ടി തന്റെ ചെറിയ കരങ്ങൾ താങ്കൾക്കായി കൂട്ടിപ്പിടിച്ചാൽ താങ്കൾക്കത് മാത്രം മതിയോ? എന്നിട്ട് അവർ തന്റെ നേർക്ക് തിരിഞ്ഞു. പക്ഷേ, ഞാനെന്റെ മുഖം അവരിൽ നിന്ന് മാറ്റിക്കളഞ്ഞു. അങ്ങനെ നബി(സ) പറഞ്ഞു: "നീ പ്രതിരോധിച്ചുകൊൾക (അവളോട് നീയും സംസാരിക്കൂ, എന്നിട്ട് സ്വയം രക്ഷ നേടൂ)." അപ്പോൾ ഞാൻ അവരിലേക്ക് തിരിഞ്ഞു. അപ്പോൾ മറുത്തൊന്നും പറയാൻ കഴിയാത്തവിധം അവരുടെ വായയിലെ ഉമിനീർ വറ്റിയതായി ഞാൻ കണ്ടു. ഉടനെ ഞാൻ റസൂൽ(സ)യെ നോക്കി. അവിടത്തെ മുഖം സന്തോഷത്താൽ പ്രസന്നമാകുന്നുണ്ടായിരുന്നു. (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده مدلس عنعنه', null, 122, 123, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=89 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 265, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كُنْتُ أَلْعَبُ بِالْبَنَاتِ وَأَنَا عِنْدَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَكَانَ يُسَرِّبُ إِلَيَّ صَوَاحِبَاتِي يُلَاعِبْنَنِي. [ز: في إسناده ضعيف. وقال السندي: أصل الحديث ثابت بلا ريب] (جه)', 'ആഇശ(റ): റസൂൽ(സ)യുടെ അടുക്കലായിരിക്കെ ഞാൻ പെൺകുട്ടികളുമൊത്ത് കളിക്കാറുണ്ടായിരുന്നു. എന്നോട് കൂടെക്കളിക്കുന്ന എന്റെ കൂട്ടുകാരികളെ അവിടന്ന് എന്റെയടുത്തേക്ക് അയക്കാറുണ്ടായിരുന്നു. (ഈ ഹദീസിന്റെ പരമ്പരയിൽ ഭംഗമുള്ള ഒരാളുണ്ട്. സിൻദി(റ) പറയുന്നു: ഈ ഹദീസിന്റെ മുരട് ഉറച്ചതാണെന്നതിൽ ഒരു സംശയവുമില്ല.) (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف. وقال السندي: أصل الحديث ثابت بلا ريب', null, 123, 123, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=89 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 266, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: جَلَسَ إِحْدَى عَشْرَةَ امْرَأَةً، فَتَعَاهَدْنَ وَتَعَاقَدْنَ أَنْ لَا يَكْتُمْنَ مِنْ أَخْبَارِ أَزْوَاجِهِنَّ شَيْئًا، قَالَتِ الْأُولَى: زَوْجِي لَحْمُ جَمَلٍ غَثٌّ عَلَى رَأْسِ جَبَلٍ، لَا سَهْلٍ فَيُرْتَقَى، وَلَا سَمِينٍ فَيُنْتَقَلُ. قَالَتِ الثَّانِيَةُ: زَوْجِي لَا أَبُثُّ خَبَرَهُ إِنِّي أَخَافُ أَنْ لَا أَذَرَهُ إِنْ أَذْكُرْهُ أَذْكُرْ عُجَرَهُ وَبُجَرَهُ. قَالَتِ الثَّالِثَةُ: زَوْجِي الْعَشَنَّقُ إِنْ أَنْطِقْ أُطَلَّقْ، وَإِنْ أَسْكُتْ أُعَلَّقْ. قَالَتِ الرَّابِعَةُ: زَوْجِي كَلَيْلِ تِهَامَةَ، لَا حَرٌّ وَلَا قُرٌّ، وَلَا مَخَافَةَ وَلَا سَآمَةَ. قَالَتِ الْخَامِسَةُ: زَوْجِي إِنْ دَخَلَ فَهِدَ، وَإِنْ خَرَجَ أَسِدَ، وَلَا يَسْأَلُ عَمَّا عَهِدَ، قَالَتِ السَّادِسَةُ: زَوْجِي إِنْ أَكَلَ لَفَّ، وَإِنْ شَرِبَ اشْتَفَّ، وَإِنِ اضْطَجَعَ الْتَفَّ، وَلَا يُولِجُ الْكَفَّ، لِيَعْلَمَ الْبَثَّ، قَالَتِ السَّابِعَةُ: زَوْجِي غَيَايَاءُ أَوْ عَيَايَاءُ طَبَاقَاءُ، كُلُّ دَاءٍ لَهُ دَاءٌ، شَجَّكِ أَوْ فَلَّكِ، أَوْ جَمَعَ كُلًّا لَكِ، قَالَتِ الثَّامِنَةُ: زَوْجِي الْمَسُّ مَسُّ أَرْنَبٍ، وَالرِّيحُ رِيحُ زَرْنَبٍ. قَالَتِ التَّاسِعَةُ: زَوْجِي رَفِيعُ الْعِمَادِ، طَوِيلُ النِّجَادِ، عَظِيمُ الرَّمَادِ، قَرِيبُ الْبَيْتِ مِنَ النَّادِ. قَالَتِ الْعَاشِرَةُ: زَوْجِي مَالِكٌ، وَمَا مَالِكٌ، مَالِكٌ خَيْرٌ مِنْ ذَلِكِ، لَهُ إِبِلٌ كَثِيرَاتُ الْمَبَارِكِ، قَلِيلَاتُ الْمَسَارِحِ، وَإِذَا سَمِعْنَ صَوْتَ الْمِزْهَرِ، أَيْقَنَّ أَنَّهُنَّ هَوَالِكُ. قَالَتِ الْحَادِيَةَ عَشْرَةَ: زَوْجِي أَبُو زَرْعٍ وَمَا أَبُو زَرْعٍ، أَنَاسَ مِنْ حُلِيٍّ أُذُنَيَّ، وَمَلَأَ مِنْ شَحْمٍ عَضُدَيَّ، وَبَجَّحَنِي فَبَجِحَتْ إِلَيَّ نَفْسِي وَجَدَنِي فِي أَهْلِ غُنَيْمَةٍ بِشِقٍّ، فَجَعَلَنِي فِي أَهْلِ صَهِيلٍ وَأَطِيطٍ وَدَائِسٍ وَمُنَقٍّ، فَعِنْدَهُ أَقُولُ فَلَا أُقَبَّحُ، وَأَرْقُدُ فَأَتَصَبَّحُ، وَأَشْرَبُ فَأَتَقَنَّحُ. أُمُّ أَبِي زَرْعٍ، فَمَا أُمُّ أَبِي زَرْعٍ عُكُومُهَا رَدَاحٌ، وَبَيْتُهَا فَسَاحٌ. ابْنُ أَبِي زَرْعٍ، فَمَا ابْنُ أَبِي زَرْعٍ، مَضْجَعُهُ كَمَسَلِّ شَطْبَةٍ، وَيُشْبِعُهُ ذِرَاعُ الْجَفْرَةِ. بِنْتُ أَبِي زَرْعٍ فَمَا بِنْتُ أَبِي زَرْعٍ طَوْعُ أَبِيهَا وَطَوْعُ أُمِّهَا، وَمِلْءُ كِسَائِهَا، وَغَيْظُ جَارَتِهَا. جَارِيَةُ أَبِي زَرْعٍ فَمَا جَارِيَةُ أَبِي زَرْعٍ، لَا تَبُثُّ حَدِيثَنَا تَبْثِيثًا، وَلَا تُنَقِّثُ مِيرَتَنَا تَنْقِيثًا، وَلَا تَمْلَأُ بَيْتَنَا تَعْشِيشًا. قَالَتْ: خَرَجَ أَبُو زَرْعٍ وَالْأَوْطَابُ تُمْخَضُ، فَلَقِيَ امْرَأَةً مَعَهَا وَلَدَانِ لَهَا كَالْفَهْدَيْنِ، يَلْعَبَانِ مِنْ تَحْتِ خَصْرِهَا بِرُمَّانَتَيْنِ، فَطَلَّقَنِي وَنَكَحَهَا، فَنَكَحْتُ بَعْدَهُ رَجُلًا سَرِيًّا، رَكِبَ شَرِيًّا، وَأَخَذَ خَطِّيًّا، وَأَرَاحَ عَلَيَّ نَعَمًا ثَرِيًّا، وَأَعْطَانِي مِنْ كُلِّ رَائِحَةٍ زَوْجًا، وَقَالَ: كُلِي أُمَّ زَرْعٍ وَمِيرِي أَهْلَكِ. قَالَتْ: فَلَوْ جَمَعْتُ كُلَّ شَيْءٍ أَعْطَانِيهِ مَا بَلَغَ أَصْغَرَ آنِيَةِ أَبِي زَرْعٍ. قَالَتْ عَائِشَةُ رَضِيَ اللهُ عَنْهَا: قَالَ لِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "كُنْتُ لَكِ كَأَبِي زَرْعٍ لِأُمِّ زَرْعٍ". (ق)', 'ആഇശ(റ): പതിനൊന്ന് സ്ത്രീകൾ ഇരുന്നു. തങ്ങളുടെ ഭർത്താക്കൻമാരുടെ വിവരങ്ങളിൽ നിന്ന് ഒന്നും മറച്ചുവെക്കില്ലെന്ന് അവർ പരസ്പരം കരാർ ചെയ്തു. ഒന്നാമത്തവൾ പറഞ്ഞു: മലമുകളിലിരിക്കുന്ന ഒരു മെലിഞ്ഞ ഒട്ടകത്തിന്റെ ഇറച്ചിയാണ് എന്റെ ഭർത്താവ്. അങ്ങോട്ട് കയറിപ്പോകാനുള്ള മാർഗ്ഗം സുഗമമല്ല. എടുത്തു കൊണ്ട് വരാൻ മാത്രം കൊഴുത്തതുമല്ല. രണ്ടാമത്തവൾ: എന്റെ ഭർത്താവിനെക്കുറിച്ച് ഞാനൊന്നും പറയുന്നില്ല. പറയാൻ പുറപ്പെട്ടാൽ മുഴുവൻ പറഞ്ഞേക്കുമോ എന്ന് ഞാൻ ഭയപ്പെടുന്നു. പറയുന്ന പക്ഷം അദ്ദേഹത്തിന്റെ ഒരു വാർത്തയും ഞാൻ പുറത്ത് പറയാതിരിക്കില്ല. മൂന്നാമത്തവൾ പറഞ്ഞു: എന്റെ ഭർത്താവ് അവസരവാദിയാണ്. ഞാൻ (അയാളെക്കുറിച്ച് വല്ലതും) പറഞ്ഞാൽ എന്നെ ത്വലാഖ് ചൊല്ലും. മൗനിയായാൽ എന്നെ കെട്ടിയിടുകയോ വിട്ടയക്കുകയോ ചെയ്യാതെ ബുദ്ധിമുട്ടിക്കും. നാലാമത്തവൾ പറഞ്ഞു: തിഹാമയിലെ രാത്രി പോലെയാണ് എന്റെ ഭർത്താവ്. ചൂടുമില്ല, തണുപ്പുമില്ല, മുഷിപ്പോ ഭയമോ വേണ്ട. അഞ്ചാമത്തവൾ: എന്റെ ഭർത്താവ് (വീട്ടിൽ) കടക്കുമ്പോൾ പുള്ളിപ്പുലി പോലെയാകും. (വീട്ടിൽ നിന്ന്) പുറത്തുപോകുമ്പോൾ സിംഹത്തെ പോലെയും. അദ്ദേഹം കണ്ടെത്തിയ ഒന്നിനെക്കുറിച്ചും ചോദിക്കുകയുമില്ല. ആറാമത്തവൾ പറഞ്ഞു: എന്റെ ഭർത്താവ് (വല്ലതും) കഴിക്കുകയാണെങ്കിൽ എല്ലാം പൂർത്തിയാക്കി ഭക്ഷിക്കും. കുടിക്കുകയാണെങ്കിലോ, മുഴുവൻ കുടിച്ച് തീർക്കുകയും ചെയ്യും. കിടക്കുമ്പോൾ ആകെ മൂടിപ്പുതക്കും. (ഭാര്യയുടെ ആവശ്യം) അറിയാൻ (അവൾക്ക് നേരെ) കരം നീട്ടുകയുമില്ല. ഏഴാമത്തവൾ: എന്റെ ഭർത്താവ് തനി വിഡ്ഢിയാണ്, അല്ലെങ്കിൽ, പൂർണ്ണവിധത്തിൽ സംഭോഗം ചെയ്യാൻ കഴിയാത്തവനാണ്. സകല രോഗങ്ങളും അയാളിൽ സമ്മേളിച്ചിട്ടുണ്ട്. ചിലപ്പോൾ തലക്ക് മുറിവേൽപ്പിക്കും. അല്ലെങ്കിൽ എല്ല് പിളർത്തും. ചിലപ്പോൾ രണ്ടും കൂടിയാകും. എട്ടാമത്തവൾ പറഞ്ഞു: എന്റെ ഭർത്താവിനെ സ്പർശിക്കുമ്പോൾ മുയലിനെപ്പോലെയാണ്. മണമാണെങ്കിൽ കുങ്കുമത്തിന്റെ നറുമണവുമാണ്. ഒമ്പതാമത്തവൾ പറഞ്ഞു: എന്റെ ഭർത്താവ് പൊക്കമുള്ളവനാണ്, നന്നായി ഉദാരത ചെയ്യുന്നവനാണ്, കൂടുതലായി ആതിഥ്യമരുളുന്നവനുമാണ്, അദ്ദേഹത്തിന് തന്റെ വീട് ഒരു ആലോചനാ കേന്ദ്രമാണ്. പത്താമത്തവൾ പറഞ്ഞു: എന്റെ ഭർത്താവ് മാലികാണ്. മാലിക് ആരെന്നോ? അദ്ദേഹം നിങ്ങൾ കരുതുന്നതിനേക്കാൾ നല്ല മാലികാണ്. വിശ്രമിക്കാനും ദാഹമകറ്റാനും വേണ്ടി ധാരാളം സ്ഥലങ്ങളിലെത്തിച്ചേരുന്ന, മേച്ചിൽ സ്ഥലങ്ങളിൽ കുറച്ച് നേരം മാത്രം തങ്ങുന്ന ധാരാളം ഒട്ടകങ്ങൾ അദ്ദേഹത്തിനുണ്ട്. വാദ്യമേളം അവ കേൾക്കുന്ന പക്ഷം ഞങ്ങൾ നശിച്ചുപോയെന്ന് അവ ഉറപ്പിക്കും. പതിനൊന്നാമത്തവൾ പറഞ്ഞു: എന്റെ ഭർത്താവ് അബൂ സർഅ് ആണ്. അബൂസർഅ് ആരെന്നോ? ആഭരണങ്ങൾ കൊണ്ട് എന്റെ ഇരുചെവികളും അദ്ദേഹം കനത്തതാക്കി. എന്റെ രണ്ടുതോളുകളും അദ്ദേഹം കൊഴുപ്പിച്ചു. അയാളെന്നെ ആഹ്ലാദിപ്പിക്കുന്നു. എനിക്ക് സന്തോഷമായി. ''ശഖ്'' എന്ന മലഞ്ചെരുവിൽ ഒരു ചെറിയ ആട്ടിൻകൂട്ടത്തിലാണ് അദ്ദേഹം എന്നെ കണ്ടത്. അങ്ങനെ കുതിരകളും ഒട്ടകങ്ങളുമുള്ള ധാന്യങ്ങൾ മെതിക്കാനും ചേറാനും (സൗകര്യങ്ങൾ) ഉള്ള ഒരു വലിയ കർഷകകുടുംബത്തിലാക്കി. ഞാനയാളോട് സംസാരിച്ചാൽ അയാളെന്നെ മോശപ്പെടുത്തുകയില്ല. ഞാൻ ഉറങ്ങുകയും നേരം വെളുക്കുകയും ചെയ്യുന്നു. ഞാൻ ദാഹം തീരുവോളം വെള്ളം കുടിക്കുന്നു. അബൂസർഇന്റെ ഉമ്മ! ആരാണ് അബൂസർഇന്റെ ഉമ്മ: ധാരാളം ചരക്കുകളിടുന്ന അവരുടെ പാത്രങ്ങൾ നിറഞ്ഞതായിരിക്കും. വീടോ, വളരെ വിശാലമായാതും. അബൂസർഇന്റെ മകൻ: ആരാണ് അബൂസർഇന്റെ മകൻ? പായയുടെ ഒരു ഇഴയോളം സ്ഥലം മതി അവന് കിടക്കാൻ. ഒരു കുഞ്ഞാടിന്റെ കൈക്കുറക് തിന്നാൽ അവന് വയറ് നിറയും. അബൂസർഇന്റെ പുത്രി: ആരാണ് അബൂസർഇന്റെ പുത്രി! തന്റെ പിതാവിനോടും മാതാവിനോടും അവൾക്ക് നല്ല അനുസരണയാണ്. അവൾ ധരിക്കുന്ന വസ്ത്രം അവളുടെ (അവളുടെ ശരീരത്തിന്റെ മാതളത്വവും, വ്യക്തിത്വത്തിന്റെ പൂർണ്ണതയും കാരണം) ശരീരം നിറയെ ഉണ്ടാകും. അവളുടെ അയൽക്കാരികളെ അവൾ അസൂയ ജനിപ്പിക്കുന്നു. അബൂസർഇന്റെ പരിചാരിക: ആരാണ് അബൂസർഇന്റെ പരിചാരിക? ഞങ്ങൾക്കിടയിലെ സംഭാഷണങ്ങൾ അവർ പാടിപ്പറയാറില്ല. ഞങ്ങളുടെ ഭക്ഷണം സൂത്രത്തിൽ അകത്താക്കുകയുമില്ല. ഞങ്ങളുടെ വീട്ടിൽ ചപ്പുചവറുകൾ അവൾ നിറക്കുകയില്ല. അവൾ പറയുന്നു: കറന്നുവെച്ച പാൽ പാത്രത്തിൽ കിടന്ന് തൈരായിക്കൊണ്ടിരിക്കവെ, അബൂസർഅ് (വീട്ടിൽ നിന്ന്) പുറത്തുപോയി. അപ്പോൾ തന്റെ കൂടെ, പുലികളെപ്പോലുള്ള രണ്ട് കുട്ടികളുമായി ഒരു സ്ത്രീയെ അയാൾ കണ്ടുമുട്ടി. രണ്ട് ഉറുമാൻ പഴവുമായി അവരിരുവരും അവളുടെ അരക്കെട്ടിനുചുറ്റും കളിച്ചുകൊണ്ടിരിക്കുകയാണ്. അപ്പോൾ അയാൾ എന്നെ ത്വലാഖ് ചൊല്ലി അവളെ വിവാഹം ചെയ്തു. അയാൾക്ക് ശേഷം ഞാനൊരു ഉത്കൃഷ്ട പുരുഷനെ വിവാഹം കഴിച്ചു. അയാൾ (ആയുധവുമായി) കുതിരപ്പുറത്ത് സവാരിചെയ്ത് (മടങ്ങിവരുമ്പോൾ) ധാരാളം വിഭവങ്ങൾ കൊണ്ടുവരും. മതിയാകുവോളം സാധനങ്ങൾ അയാൾ എനിക്ക് തരും. വൈകുന്നേരം വിശ്രമിക്കുന്ന എല്ലാ മൃഗങ്ങളിൽ നിന്നും ഓരോ ജോഡി എനിക്ക് അയാൾ തന്നു. എന്നിട്ട് പറഞ്ഞു: ഉമ്മുസർഏ, നീ ഭക്ഷിക്കുക, നിന്റെ ആളുകളെ നീ ഭക്ഷിപ്പിക്കുക. അവൾ പറയുന്നു: അയാൾ എനിക്ക് തന്ന എല്ലാ വസ്തുക്കളും ഞാൻ ഒരുമിച്ചുകൂട്ടിയാൽ അബൂസർഇന്റെ ഏറ്റവും ചെറിയ പാത്രംപോലും നിറയുകയില്ല. ആഇശ(റ) പറഞ്ഞു: എന്നോട് റസൂൽ(സ) പറഞ്ഞു: "അബൂസർഅ് ഉമ്മുസർഇനോട് എപ്രകാരമാണോ അപ്രകാരമാണ് നിന്നോട് ഞാൻ." (ബു,മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 123, 125, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=89 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 267, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مِنَ الْغَيْرَةِ مَا يُحِبُّ اللهُ، وَمِنْهَا مَا يَكْرَهُ اللهُ. فَأَمَّا مَا يُحِبُّ فَالْغَيْرَةُ فِي الرِّيبَةِ، وَأَمَّا مَا يَكْرَهُ فَالْغَيْرَةُ فِي غَيْرِ رِيبَةٍ". (د,ن,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു ഇഷ്ടപ്പെടുന്ന ദേഷ്യവുമുണ്ട്, വെറുക്കുന്ന ദേഷ്യവുമുണ്ട്. സംശയം കാരണത്താലുണ്ടാകുന്ന ദേഷ്യത്തെയാണ് അല്ലാഹു ഇഷ്ടപ്പെടുന്നത്. സംശയം കാരണമല്ലാതെയുള്ള ദേഷ്യത്തെയാണ് അല്ലാഹു വെറുക്കുന്നത്." (ദ,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 125, 125, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=90 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 268, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: مَا غِرْتُ عَلَى امْرَأَةٍ قَطُّ مَا غِرْتُ عَلَى خَدِيجَةَ، مِمَّا رَأَيْتُ مِنْ ذِكْرِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَهَا، وَلَقَدْ أَمَرَهُ رَبُّهُ أَنْ يُبَشِّرَهَا بِبَيْتٍ فِي الْجَنَّةِ مِنْ قَصَبٍ. (ق,ت,جه)', 'ആഇശ(റ): ഖദീജ(റ)യോട് ദേഷ്യം വെച്ച പോലെ ഞാൻ ആരോടും ദേഷ്യം വെച്ചിട്ടില്ല. കാരണം റസൂൽ(സ) അവരെക്കുറിച്ച് കൂടുതൽ സംസാരിക്കാറുണ്ടായിരുന്നു. സ്വർഗ്ഗത്തിൽ അവർക്ക് സ്വർണ്ണത്താലുള്ള ഒരു വീടുണ്ടെന്ന് അവരെ സന്തോഷവാർത്തയറിയിക്കാൻ റസൂൽ(സ)യോട് തന്റെ റബ്ബ് കൽപ്പിച്ചിട്ടുണ്ടായിരുന്നു. (ബു,മു,തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 125, 125, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=90 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 269, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللهَ يَغَارُ، وَالْمُؤْمِنُ يَغَارُ، وَغَيْرَةُ اللهِ أَنْ يَأْتِيَ الْمُؤْمِنُ مَا حَرَّمَ عَلَيْهِ". (ق,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു ദേഷ്യം വെക്കും, സത്യവിശ്വാസിയും ദേഷ്യം വെക്കും. അല്ലാഹുവിന്റെ ദേഷ്യം സത്യവിശ്വാസി തനിക്ക് നിഷിദ്ധമാക്കപ്പെട്ടത് ചെയ്യുന്നതിലാണ്." (ബു,മു,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 125, 125, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=90 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 270, 'عَنْ أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ رَضِيَ اللهُ عَنْهُمَا قَالَتْ: تَزَوَّجَنِي الزُّبَيْرُ وَمَا لَهُ فِي الْأَرْضِ مِنْ مَالٍ وَلَا مَمْلُوكٍ، وَلَا شَيْءٍ، غَيْرَ نَاضِحٍ، وَغَيْرَ فَرَسِهِ، فَكُنْتُ أَعْلِفُ فَرَسَهُ وَأَسْتَقِي الْمَاءَ وَأَخْرِزُ غَرْبَهُ وَأَعْجِنُ، وَلَمْ أَكُنْ أُحْسِنُ أَخْبِزُ، وَكَانَ يَخْبِزُ جَارَاتٌ لِي مِنَ الْأَنْصَارِ، وَكُنَّ نِسْوَةَ صِدْقٍ، وَكُنْتُ أَنْقُلُ النَّوَى مِنْ أَرْضِ الزُّبَيْرِ الَّتِي أَقْطَعَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى رَأْسِي وَهِيَ مِنِّي عَلَى ثُلُثَيْ فَرْسَخٍ، فَجِئْتُ يَوْمًا وَالنَّوَى عَلَى رَأْسِي، فَلَقِيتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَمَعَهُ نَفَرٌ مِنَ الْأَنْصَارِ فَدَعَانِي ثُمَّ قَالَ: إِخْ، إِخْ، لِيَحْمِلَنِي خَلْفَهُ فَاسْتَحْيَيْتُ أَنْ أَسِيرَ مَعَ الرِّجَالِ، وَذَكَرْتُ الزُّبَيْرَ وَغَيْرَتَهُ، وَكَانَ أَغْيَرَ النَّاسِ، فَعَرَفَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنِّي قَدِ اسْتَحْيَيْتُ، فَمَضَى، فَجِئْتُ الزُّبَيْرَ فَقُلْتُ: لَقِيَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَعَلَى رَأْسِي النَّوَى وَمَعَهُ نَفَرٌ مِنْ أَصْحَابِهِ، فَأَنَاخَ لِأَرْكَبَ فَاسْتَحْيَيْتُ مِنْهُ، وَعَرَفْتُ غَيْرَتَكَ. فَقَالَ: وَاللهِ لَحَمْلُكِ النَّوَى كَانَ أَشَدَّ عَلَيَّ مِنْ رُكُوبِكِ مَعَهُ. قَالَتْ: حَتَّى أَرْسَلَ إِلَيَّ أَبُو بَكْرٍ بَعْدَ ذَلِكَ بِخَادِمٍ تَكْفِينِي سِيَاسَةَ الْفَرَسِ، فَكَأَنَّمَا أَعْتَقَنِي. (ق)', 'അസ്മാഅ് ബിൻത് അബീബക്കർ(റ): സുബൈർ(റ) എന്നെ വിവാഹം കഴിക്കുമ്പോൾ അദ്ദേഹത്തിന് ഭൂമിയിൽ ധനമോ അടിമയോ ഒന്നുമുണ്ടായിരുന്നില്ല. ഒരു കുതിരയും കൃഷിക്ക് വെള്ളം വലിക്കാൻ ഉപയോഗിക്കുന്ന ഒരു ഒട്ടകവും മാത്രമാണുണ്ടായിരുന്നത്. ഞാൻ അദ്ദേഹത്തിന്റെ കുതിരക്ക് പുല്ല് പറിച്ച് കൊടുക്കുകയും വെള്ളം കൊടുക്കുകയും തോൽപ്പാത്രം തുന്നുകയും മാവ് കുഴച്ച് പാകപ്പെടുത്തുകയും ചെയ്യുമായിരുന്നു. എനിക്ക് റൊട്ടി ചുടാൻ പരിചയമുണ്ടായിരുന്നില്ല. ചില അൻസാരി അയൽവാസിനികളാണ് റൊട്ടി ചുട്ടു തന്നിരുന്നത്. അവർ വളരെ സത്യസന്ധരായിരുന്നു. തിരുമേനി(സ) സുബൈർ(റ)വിന് പതിച്ചുകൊടുത്ത രണ്ട് മൈൽ ദൂരത്തുള്ള ഭൂമിയിൽ നിന്ന് ഈത്തപ്പഴക്കുരു ഞാൻ ചുമന്ന് കൊണ്ട് വരുമായിരുന്നു. ഒരു ദിവസം ഈത്തപ്പഴക്കുരു ചുമന്നുപോരുമ്പോൾ ഞാൻ റസൂൽ(സ)യെ കണ്ടു. കൂടെ ഒരു സംഘം അൻസാരികളുമുണ്ടായിരുന്നു. "ഇഖ്, ഇഖ്" എന്ന് പറഞ്ഞ് തന്റെ ഒട്ടകത്തെ മുട്ടുകുത്തിച്ച് റസൂൽ(സ) എന്നോട് തന്റെ പിറകിൽ കയറാൻ പറഞ്ഞു. പുരുഷൻമാരോടൊന്നിച്ച് യാത്ര ചെയ്യാൻ എനിക്ക് ലജ്ജ തോന്നി. സുബൈർ(റ)വിന്റെ രോഷം ഞാനോർത്തു. അദ്ദേഹം വലിയ ദേഷ്യക്കാരനായിരുന്നു. എനിക്ക് ലജ്ജയുണ്ടെന്ന് മനസ്സിലാക്കിയ റസൂൽ(സ) മുന്നോട്ട് പോയി. ശേഷം ഞാൻ സുബൈർ(റ)വിനെ കണ്ടുമുട്ടിയപ്പോൾ സംഭവമെല്ലാം പറഞ്ഞുകൊടുത്തു. ഞാൻ പറഞ്ഞു: തലയിൽ ഈത്തപ്പഴക്കുരു ഏറ്റിനടക്കുമ്പോൾ എന്നെ റസൂൽ(സ) കണ്ടുമുട്ടി. തിരുമേനി(സ)യോടൊപ്പം കുറച്ച് അനുചരരുമുണ്ടായിരുന്നു. എനിക്ക് കയറാൻ വേണ്ടി തിരുമേനി(സ) തന്റെ ഒട്ടകത്തെ മുട്ടുകുത്തിച്ചു, പക്ഷേ, എനിക്ക് ലജ്ജ തോന്നി. അങ്ങയുടെ അഭിമാന രോഷവും ഞാനോർത്തു. സുബൈർ(റ) പറഞ്ഞു: നീ ഈത്തപ്പഴക്കുരു ചുമന്നുവെന്നതാണ് റസൂൽ(സ)യോടൊപ്പം നീ വാഹനത്തിൽ കയറുന്നതിനേക്കാൾ എനിക്ക് അസഹ്യം. മഹതി പറഞ്ഞു: അതിനുശേഷം അബൂബക്കർ(റ) കുതിരയെ പരിപാലിക്കാൻ പറ്റുന്ന ഒരു ഭൃത്യനെ എനിക്ക് അയച്ചുതന്നു. അപ്പോൾ അടിമത്വ വിമുക്തയായ പോലെ എനിക്ക് തോന്നി. (ബു,മു)', 'أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ', 'അസ്മാഅ് ബിൻത് അബീബക്കർ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 125, 126, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=90 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 271, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ لِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنِّي لَأَعْلَمُ إِذَا كُنْتِ عَنِّي رَاضِيَةً، وَإِذَا كُنْتِ عَلَيَّ غَضْبَى". قَالَتْ: فَقُلْتُ: مِنْ أَيْنَ تَعْرِفُ ذَلِكَ؟ فَقَالَ: "أَمَّا إِذَا كُنْتِ عَنِّي رَاضِيَةً فَإِنَّكِ تَقُولِينَ لَا وَرَبِّ مُحَمَّدٍ، وَإِذَا كُنْتِ عَلَيَّ غَضْبَى قُلْتِ لَا وَرَبِّ إِبْرَاهِيمَ". قَالَتْ: قُلْتُ: أَجَلْ وَاللهِ يَا رَسُولَ اللهِ مَا أَهْجُرُ إِلَّا اسْمَكَ. (ق)', 'ആഇശ(റ): തിരുമേനി(സ) എന്നോട് ഇപ്രകാരം പറഞ്ഞു: "നിനക്ക് എന്നെക്കുറിച്ച് സംതൃപ്തിയുള്ള സമയവും ദേഷ്യമുള്ള സമയവും എനിക്ക് മനസ്സിലാക്കാൻ കഴിയാറുണ്ട്." ഞാൻ ചോദിച്ചു: എങ്ങനെയാണ് അങ്ങ് അത് മനസ്സിലാക്കുന്നത്? തിരുമേനി(സ) പറഞ്ഞു: "നിനക്ക് എന്നെക്കുറിച്ച് സംതൃപ്തിയാണുള്ളതെങ്കിൽ അല്ല, മുഹമ്മദിന്റെ നാഥനെക്കൊണ്ട് സത്യം, എന്നാണ് നീ പറയുക. എന്നോട് കോപിച്ചിരിക്കുകയാണെങ്കിൽ, ''അല്ല, ഇബ്റാഹീമിന്റെ നാഥനെക്കൊണ്ട് സത്യം എന്നാണ് നീ പറയാറുള്ളത്." ഞാൻ പറഞ്ഞു: അല്ലാഹു തന്നെ സത്യം, അങ്ങ് പറഞ്ഞതെത്ര ശരി. അങ്ങയുടെ നാമം മാത്രമേ ഞാനുപേക്ഷിക്കാറുള്ളൂ. (അങ്ങയോടുള്ള പ്രേമം എന്റെ മനസ്സിൽ അപ്പോഴുമുണ്ടാകും.) (ബു,മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 126, 126, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=90 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 272, 'عَنْ عَبْدِ اللهِ بْنِ زَمْعَةَ رَضِيَ اللهُ عَنْهُ قَالَ: خَطَبَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ ذَكَرَ النِّسَاءَ فَوَعَظَهُمْ فِيهِنَّ، ثُمَّ قَالَ: "إِلَامَ يَجْلِدُ أَحَدُكُمُ امْرَأَتَهُ جَلْدَ الْأَمَةِ؟ وَلَعَلَّهُ أَنْ يُضَاجِعَهَا مِنْ آخِرِ يَوْمِهِ". (ق,ت,جه)', 'അബ്ദുല്ലാഹിബ്നു സംഅ(റ): നബി(സ) പ്രസംഗിക്കുകയും സ്ത്രീകളെക്കുറിച്ച് പറയുകയും ചെയ്തു. ശേഷം സ്ത്രീകളുടെ വിഷയത്തിൽ അനുചരരെ ഉപദേശിച്ചു: "ഏതു വരെയാണ് അടിമസ്ത്രീകളെ അടിക്കും പോലെ നിങ്ങളിലൊരുത്തൻ തന്റെ ഭാര്യയെ അടിക്കുക. ഒരു പക്ഷേ, ആ ദിവസം തന്നെ അവൻ തന്റെ ഭാര്യയോടൊപ്പം കിടപ്പറ പങ്കിടുകയും ചെയ്തേക്കാം." (ബു,മു,തു,ജ)', 'عَبْدِ اللهِ بْنِ زَمْعَةَ', 'അബ്ദുല്ലാഹിബ്നു സംഅ(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 126, 126, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=91 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 273, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: مَا ضَرَبَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَادِمًا لَهُ، وَلَا امْرَأَةً، وَلَا ضَرَبَ بِيَدِهِ شَيْئًا. (م,جه)', 'ആഇശ(റ): റസൂൽ(സ) തന്റെ ഭാര്യമാരെയോ സേവകരെയോ അടിച്ചിട്ടില്ല. തന്റെ കൈ കൊണ്ട് അവിടന്ന് ഒന്നിനെയും അടിച്ചിട്ടില്ല. (മു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 126, 127, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=91 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 274, 'عَنْ إِيَاسِ بْنِ عَبْدِ اللهِ بْنِ أَبِي ذُبَابٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَضْرِبُنَّ إِمَاءَ اللهِ". فَجَاءَ عُمَرُ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللهِ، قَدْ ذَئِرَ النِّسَاءُ عَلَى أَزْوَاجِهِنَّ، فَأَمَرَ بِضَرْبِهِنَّ. فَضُرِبْنَ، فَطَافَ بِآلِ مُحَمَّدٍ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ طَائِفُ نِسَاءٍ كَثِيرٍ، فَلَمَّا أَصْبَحَ قَالَ: "لَقَدْ طَافَ اللَّيْلَةَ بِآلِ مُحَمَّدٍ سَبْعُونَ امْرَأَةً، كُلُّ امْرَأَةٍ تَشْتَكِي زَوْجَهَا، فَلَا تَجِدُونَ أُولَئِكَ خِيَارَكُمْ". (د,جه)', 'ഇയാസുബ്നു അബ്ദില്ല(റ): നബി(സ) പറഞ്ഞു:"അല്ലാഹുവിന്റെ അടിമസ്ത്രീകളെ നിങ്ങൾ അടിക്കരുത്." ശേഷം ഉമർ(റ) നബി(സ)യുടെ അടുത്ത് വന്നു പറഞ്ഞു: റസൂലേ, സ്ത്രീകൾ തങ്ങളുടെ ഭർത്താക്കളുടെ മേൽ കൂടുതൽ ധൈര്യം കാണിക്കുന്നു. അതിനാൽ അവരെ അടിക്കാൻ കൽപിക്കുക. അങ്ങനെ സ്ത്രീകൾ അടിക്കപ്പെട്ടു. അങ്ങനെ നബി(സ)യുടെ വീടുകൾക്ക് സമീപം ധാരാളം സ്ത്രീകൾ തടിച്ചുകൂടി. നേരം പുലർന്നപ്പോൾ നബി(സ) പറഞ്ഞു: "മുഹമ്മദിന്റെ വീടുകൾക്ക് പരിസരത്ത് ഇന്നലെ രാത്രി എഴുപതോളം സ്ത്രീകൾ ഒത്തുകൂടി, എല്ലാവരും തങ്ങളുടെ ഭർത്താക്കൻമാരെക്കുറിച്ചാണ് പരാതിപ്പെടുന്നത്. നിശ്ചയം നിങ്ങളിലുത്തമർ അപ്രകാരം ചെയ്യുകയില്ല." (ദ,ജ)', 'إِيَاسِ بْنِ عَبْدِ اللهِ بْنِ أَبِي ذُبَابٍ', 'ഇയാസുബ്നു അബ്ദില്ല(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 127, 127, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=91 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 275, 'عَنِ الْأَشْعَثِ بْنِ قَيْسٍ رَضِيَ اللهُ عَنْهُ قَالَ: ضِفْتُ عُمَرَ لَيْلَةً، فَلَمَّا كَانَ فِي جَوْفِ اللَّيْلِ قَامَ إِلَى امْرَأَتِهِ يَضْرِبُهَا، فَحَجَزْتُ بَيْنَهُمَا، فَلَمَّا أَوَى إِلَى فِرَاشِهِ قَالَ لِي: يَا أَشْعَثُ، احْفَظْ عَنِّي شَيْئًا سَمِعْتُهُ عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يُسْأَلُ الرَّجُلُ فِيمَ يَضْرِبُ امْرَأَتَهُ. وَلَا تَنَمْ إِلَّا عَلَى وِتْرٍ" وَنَسِيتُ الثَّالِثَةَ. (د,جه)', 'അശ്അസുബ്നു ഖൈസ്(റ): ഒരു രാത്രി ഞാൻ ഉമർ(റ)വിന്റെയുടുത്ത് അതിഥിയായി ചെന്നു. അർദ്ധരാത്രിയായപ്പോൾ ഉമർ(റ) എഴുന്നേറ്റ് തന്റെ ഭാര്യയെ അടിക്കാൻ തുടങ്ങി. ഞാൻ രണ്ടുപേർക്കുമിടയിൽ തടസ്സം നിന്നു. ശേഷം ഉമർ(റ) തന്റെ കിടപ്പറയിലേക്കെത്തിയപ്പോൾ എന്നോട് പറഞ്ഞു: അശ്അസേ, ഞാൻ റസൂൽ(സ)യിൽ നിന്ന് കേട്ട ഒരുകാര്യം നീ മനഃപാഠമാക്കുക. "തന്റെ ഭാര്യയെ എന്തിനാണ് അടിച്ചതെന്ന് ഒരാളോടും ചോദിക്കപ്പെടുകയില്ല. വിത്റ് നിസ്കരിക്കണമെന്ന ഉദ്ദേശത്തോടെയല്ലാതെ നീ ഉറങ്ങരുത്." മൂന്നാമത്തെ കാര്യം ഞാൻ മറന്നുപോയി. (ദ,ജ)', 'الْأَشْعَثِ بْنِ قَيْسٍ', 'അശ്അസുബ്നു ഖൈസ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 127, 127, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=91 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 276, 'عَنْ أَبِي حُرَّةَ الرَّقَاشِيِّ، عَنْ عَمِّهِ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "فَإِنْ خِفْتُمْ نُشُوزَهُنَّ فَاهْجُرُوهُنَّ فِي الْمَضَاجِعِ". (د)', 'തന്റെ പിതൃവ്യനിൽ നിന്ന് അബൂഹുർറതുർറഖാഷീ(റ): നബി(സ) പറഞ്ഞു: "അവർ (ഭാര്യമാർ) പിണങ്ങുമോ എന്ന് നിങ്ങൾ ഭയപ്പെട്ടാൽ കിടപ്പറകളിൽ നിന്ന് നിങ്ങളവരെ അകറ്റുക." (ദ)', 'أَبِي حُرَّةَ الرَّقَاشِيِّ، عَنْ عَمِّهِ', 'തന്റെ പിതൃവ്യനിൽ നിന്ന് അബൂഹുർറതുർറഖാഷീ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 127, 127, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=91 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 277, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُعَلِّمُنَا الِاسْتِخَارَةَ فِي الْأُمُورِ كُلِّهَا كَمَا يُعَلِّمُنَا السُّورَةَ مِنَ الْقُرْآنِ، يَقُولُ: "إِذَا هَمَّ أَحَدُكُمْ بِالْأَمْرِ فَلْيَرْكَعْ رَكْعَتَيْنِ مِنْ غَيْرِ الْفَرِيضَةِ، ثُمَّ يَقُولُ: اللَّهُمَّ إِنِّي أَسْتَخِيرُكَ بِعِلْمِكَ، وَأَسْتَعِينُكَ بِقُدْرَتِكَ، وَأَسْأَلُكَ مِنْ فَضْلِكَ الْعَظِيمِ، فَإِنَّكَ تَقْدِرُ وَلَا أَقْدِرُ، وَتَعْلَمُ وَلَا أَعْلَمُ، وَأَنْتَ عَلَّامُ الْغُيُوبِ. اللَّهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الْأَمْرَ خَيْرٌ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي – أَوْ قَالَ: فِي عَاجِلِ أَمْرِي وَآجِلِهِ – فَاقْدُرْهُ لِي وَيَسِّرْهُ لِي، ثُمَّ بَارِكْ لِي فِيهِ. وَإِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الْأَمْرَ شَرٌّ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي – أَوْ قَالَ: فِي عَاجِلِ أَمْرِي وَآجِلِهِ – فَاصْرِفْهُ عَنِّي وَاصْرِفْنِي عَنْهُ، وَاقْدُرْ لِيَ الْخَيْرَ حَيْثُ كَانَ، ثُمَّ أَرْضِنِي بِهِ. قَالَ: وَيُسَمِّي حَاجَتَهُ". (ن)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): ഖുർആനിലെ അധ്യായങ്ങളെ പഠിപ്പിച്ചുതരും പോലെത്തന്നെ സർവ്വ കാര്യങ്ങളിലും നന്മയെ തേടേണ്ട രൂപത്തെയും റസൂൽ(സ) ഞങ്ങൾക്ക് പഠിപ്പിച്ച് തരാറുണ്ടായിരുന്നു. അവിടന്ന് ഇപ്രകാരം പറയും: "നിങ്ങളിൽ ആരെങ്കിലും വല്ല കാര്യവുമുദ്ദേശിച്ചാൽ രണ്ട് റക്അത് സുന്നത് നമസ്കരിക്കുകയും ഇപ്രകാരം പറയുകയും ചെയ്യണം: അല്ലാഹുവേ നിന്റെ അറിവ് കൊണ്ട് ഞാൻ നിന്നോട് നന്മ തേടുന്നു. നിന്റെ കഴിവ് കൊണ്ട് നിന്നോട് സഹായം ചോദിക്കുന്നു. നിന്റെ മഹത്തായ ഔദാര്യത്തെ ഞാൻ ചോദിക്കുന്നു. നിശ്ചയം നിനക്കാണ് സർവ്വം സാധിക്കുക, എനിക്ക് ഒന്നിനും കഴിവില്ല. നിയാണ് സർവ്വമറിയുന്നവൻ, എനിക്കൊന്നും അറിയില്ല. നീയാണ് സർവ്വ രഹസ്യങ്ങളുമറിയുന്നവൻ. അല്ലാഹുവേ, എന്റെ ദീനിലും ജീവിതത്തിലും അന്ത്യത്തിലും - അല്ലെങ്കിൽ അവിടന്ന് ഇപ്രകാരമാണ് പറഞ്ഞത്: എന്റെ ഐഹിക ജീവിതത്തിലും പാരത്രിക ജീവിതത്തിലും - ഈ കാര്യം നന്മയാണെന്നാണ് നിന്റെ അറിവിലുള്ളതെങ്കിൽ അതിനെ നീ എനിക്ക് കണക്കാക്കുകയും എളുപ്പമാക്കിത്തരികയും ശേഷം അതിൽ അനുഗ്രഹം ചെയ്തുതരികയും ചെയ്യേണമേ. എന്റെ ദീനിലും ജീവിതത്തിലും അന്ത്യത്തിലും - അല്ലെങ്കിൽ എന്റെ ഐഹിക ജീവിതത്തിലും പാരത്രിക ജീവിതത്തിലും - ഈ കാര്യം തിന്മയാണെന്നാണ് നിന്റെ അറിവിലുള്ളതെങ്കിൽ അതിനെ എന്നിൽ നിന്നും എന്നെ അതിൽ നിന്നും നീ അകറ്റേണമേ. നന്മ എവിടെയാണെങ്കിലും എനിക്ക് നീ അത് നൽകുകയും ശേഷം എന്നെ അതിൽ തൃപ്തനാക്കുകയും ചെയ്യുക. നബി(സ) പറഞ്ഞു: "ശേഷമവൻ തന്റെ ആവശ്യം പറയുക." (ന)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 127, 128, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=92 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 278, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ امْرَأَةً جَاءَتْ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَسْلَمَتْ، فَتَزَوَّجَهَا رَجُلٌ، قَالَ: فَجَاءَ زَوْجُهَا الْأَوَّلُ فَقَالَ: يَا رَسُولَ اللهِ، إِنِّي قَدْ كُنْتُ أَسْلَمْتُ مَعَهَا، وَعَلِمَتْ بِإِسْلَامِي. قَالَ: فَانْتَزَعَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ زَوْجِهَا الْآخَرِ، وَرَدَّهَا إِلَى زَوْجِهَا الْأَوَّلِ. (د,ت,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ഒരു സ്ത്രീ നബി(സ)യുടെ അടുത്ത് വന്ന് മുസ്ലിമാവുകയും അവളെ ഒരാൾ വിവാഹം കഴിക്കുകയും ചെയ്തു. ശേഷം അവളുടെ ആദ്യത്തെ ഭർത്താവ് വന്ന് പറഞ്ഞു: റസൂലേ, ഞാൻ അവളോടൊപ്പം മുസ്ലിമായിട്ടുണ്ടായിരുന്നു. ഞാൻ മുസ്ലിമായ വിവരം അവൾ അറിഞ്ഞിട്ടുമുണ്ടായിരുന്നു. അങ്ങനെ റസൂൽ(സ) ആ സ്ത്രീയെ രണ്ടാമത്തെ ഭർത്താവിൽ നിന്ന് വേർപ്പെടുത്തുകയും ആദ്യത്തെ ഭർത്താവിന് തിരിച്ചു നൽകുകയും ചെയ്തു. (ദ,തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 128, 128, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=93 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 279, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَدَّ ابْنَتَهُ عَلَى أَبِي الْعَاصِ بْنِ الرَّبِيعِ– بَعْدَ سَنَتَيْنِ-بِنِكَاحِهَا الْأَوَّلِ. (د,ت,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) ആദ്യത്തെ വിവാഹമടിസ്ഥാനമാക്കി തന്റെ മകളെ രണ്ട് വർഷങ്ങൾക്ക് ശേഷം അബുൽആസുബ്നു റബീഅ്(റ)വിന് തിരിച്ചു നൽകി. (ദ,തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 128, 128, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=93 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 280, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَدَّ ابْنَتَهُ زَيْنَبَ عَلَى أَبِي الْعَاصِي بْنِ الرَّبِيعِ بِمَهْرٍ جَدِيدٍ، وَنِكَاحٍ جَدِيدٍ. (ت,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പുതിയ വിവാഹത്തിലൂടെയും മഹ്റിലൂടെയും തന്റെ മകൾ സൈനബ്(റ)യെ അബുൽആസുബ്നു റബീഅ്(റ)വിന് തിരിച്ചു നൽകി. (തു,ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 128, 128, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=93 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 281, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: رَدَّ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ابْنَتَهُ زَيْنَبَ عَلَى أَبِي الْعَاصِي بْنِ الرَّبِيعِ، بَعْدَ سِتِّ سِنِينَ، بِالنِّكَاحِ الْأَوَّلِ، وَلَمْ يُحْدِثْ نِكَاحًا. (د,ت,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ആദ്യത്തെ വിവാഹത്തെ അടിസ്ഥാനമാക്കി റസൂൽ(സ) തന്റെ മകൾ സൈനബ്(റ)യെ ആറു വർഷങ്ങൾക്ക് ശേഷം അബുൽആസ്ബ്നു റബീഅ്(റ)വിന് മടക്കിക്കൊടുത്തു. നബി(സ) പുതിയതായി വിവാഹം കഴിപ്പിച്ചില്ല. (ദ,തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 128, 129, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=93 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 282, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَجُلًا جَاءَ مُسْلِمًا عَلَى عَهْدِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ جَاءَتِ امْرَأَتُهُ مُسْلِمَةً. فَقَالَ: يَا رَسُولَ اللهِ، إِنَّهَا كَانَتْ أَسْلَمَتْ مَعِي، فَرُدَّهَا عَلَيَّ. فَرَدَّهَا عَلَيْهِ. صَحِيحٌ. (د,ت)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ)യുടെ കാലത്ത് ഒരാൾ മുസ്ലിമായി വന്നു. ശേഷം അദ്ദേഹത്തിന്റെ ഭാര്യയും മുസ്ലിമായി വന്നു. അന്നേരം അദ്ദേഹം പറഞ്ഞു: റസൂലേ, അവളും എന്റെ കൂടെ മുസ്ലിമായിട്ടുണ്ടായിരുന്നു. അത്കൊണ്ട് അവളെ എനിക്ക് തിരിച്ചു നൽകിയാലും. അങ്ങനെ നബി(സ) അവളെ അദ്ദേഹത്തിന് തിരിച്ചു നൽകി. (ദ,തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 129, 129, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=93 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 283, 'عَنْ عَبْدِ الْحَمِيدِ بْنِ سَلَمَةَ الْأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُ عَنْ أَبِيهِ عَنْ جَدِّهِ: أَنَّهُ أَسْلَمَ وَأَبَتِ امْرَأَتُهُ أَنْ تُسْلِمَ، فَجَاءَ ابْنٌ لَهُمَا صَغِيرٌ لَمْ يَبْلُغِ الْحُلُمَ، فَأَجْلَسَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْأَبَ هَا هُنَا وَالْأُمَّ هَا هُنَا، ثُمَّ خَيَّرَهُ فَقَالَ: "اللَّهُمَّ اهْدِهِ". فَذَهَبَ إِلَى أَبِيهِ. (ن)', 'അബ്ദുൽഹമീദുബ്നു സലമതുൽ അൻസാരി(റ) തന്റെ പിതാവിൽ നിന്നും അവർ തന്റെ പിതാമഹനിൽ നിന്നും നിവേദനം ചെയ്യുന്നു: അവർ മുസ്ലിമാവുകയും തന്റെ ഭാര്യ മുസ്ലിമാകാൻ വിസമ്മതിക്കുകയും ചെയ്തു. അങ്ങനെ അവരുടെ പ്രായപൂർത്തിയാകാത്ത ഒരു കുട്ടി നബി(സ)യുടെ അടുത്ത് വന്നു. നബി(സ) പിതാവിനെ ഒരു ഭാഗത്തും മാതാവിനെ മറ്റൊരു ഭാഗത്തും ഇരുത്തി. ശേഷം മകനോട് ഇഷ്ടാനുസരണം ചെയ്യാൻ ആവശ്യപ്പെട്ടു. എന്നിട്ട് പറഞ്ഞു: "അല്ലാഹുവേ, നീയവന് നേർമാർഗ്ഗം കാണിക്കണേ." അപ്പോൾ മകൻ പിതാവിന്റെയടുത്തേക്ക് പോയി. (ന)', 'عَبْدِ الْحَمِيدِ بْنِ سَلَمَةَ الْأَنْصَارِيِّ', 'അബ്ദുൽഹമീദുബ്നു സലമതുൽ അൻസാരി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 129, 129, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=94 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 284, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ فَقَالَ: إِنَّ امْرَأَةً جَاءَتْ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: فِدَاكَ أَبِي وَأُمِّي، إِنَّ زَوْجِي يُرِيدُ أَنْ يَذْهَبَ بِابْنِي، وَقَدْ نَفَعَنِي وَسَقَانِي مِنْ بِئْرِ أَبِي عِنَبَةَ. فَجَاءَ زَوْجُهَا وَقَالَ: مَنْ يُخَاصِمُنِي فِي ابْنِي؟ فَقَالَ: يَا غُلَامُ، هَذَا أَبُوكَ وَهَذِهِ أُمُّكَ، فَخُذْ بِيَدِ أَيِّهِمَا شِئْتَ". فَأَخَذَ بِيَدِ أُمِّهِ، فَانْطَلَقَتْ بِهِ. (ن)', 'അബൂഹുറൈറ(റ): ഒരു സ്ത്രീ റസൂൽ(സ)യുടെ അടുത്ത് വന്ന് പറഞ്ഞു: എന്റെ മാതാപിതാക്കൾ അങ്ങേക്ക് ദണ്ഡമാണ്. എന്റെ ഭർത്താവ് എന്റെ മകനെ കൂട്ടിക്കൊണ്ടു പോകണമെന്നാഗ്രഹിക്കുന്നു. അവൻ അബൂഇനബയുടെ കിണറ്റിൽ നിന്ന് എനിക്ക് വെള്ളം കോരിത്തരാറുണ്ട്. ധാരാളം ഉപകാരങ്ങൾ ചെയ്തുതരാറുണ്ട്. ശേഷം ആ സ്ത്രീയുടെ ഭർത്താവ് വന്ന് പറഞ്ഞു: ആരാണ് എന്റെ മകന്റെ കാര്യത്തിൽ എന്നോട് തർക്കിക്കുന്നത്? അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "കുട്ടീ, ഇത് നിന്റെ പിതാവാണ്, ഇത് നിന്റെ മാതാവും. അവരിൽ നിനക്ക് ഇഷ്ടമുള്ളവരുടെ കൈ നീ പിടിക്കുക." അപ്പോൾ കുട്ടി തന്റെ ഉമ്മയുടെ കൈ പിടിക്കുകയും ഉമ്മയോടൊപ്പം പോവുകയും ചെയ്തു. (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 129, 129, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=94 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 285, 'عَنْ رَافِعِ بْنِ سِنَانٍ رَضِيَ اللهُ عَنْهُ أَنَّهُ أَسْلَمَ، وَأَبَتِ امْرَأَتُهُ أَنْ تُسْلِمَ، فَأَتَتِ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَتْ: ابْنَتِي وَهِيَ فَطِيمٌ، أَوْ شِبْهُهُ، وَقَالَ رَافِعٌ: ابْنَتِي، قَالَ لَهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اقْعُدْ نَاحِيَةً". وَقَالَ لَهَا: "اقْعُدِي نَاحِيَةً". قَالَ: وَأَقْعَدَ الصَّبِيَّةَ بَيْنَهُمَا، ثُمَّ قَالَ: "ادْعُوَاهَا". فَمَالَتِ الصَّبِيَّةُ إِلَى أُمِّهَا، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اللَّهُمَّ اهْدِهَا". فَمَالَتِ الصَّبِيَّةُ إِلَى أَبِيهَا، فَأَخَذَهَا. (د,ن)', 'റാഫിഉബ്നു സിനാൻ(റ): അദ്ദേഹം മുസ്ലിമാവുകയും തന്റെ ഭാര്യ മുസ്ലിമാകാൻ വിസമ്മതിക്കുകയും ചെയ്തു. അവൾ നബി(സ)യുടെ അടുത്ത് ചെന്ന് പറഞ്ഞു: അത് എന്റെ മകളാണ്. അവൾ മുലകുടി നിർത്തിയവളാണ്. അല്ലെങ്കിൽ നിർത്തിയതു പോലെയാണ്. റാഫിഅ്(റ) പറഞ്ഞു: അവൾ എന്റെ മകളാണ്. അപ്പോൾ റസൂൽ(സ) അദ്ദേഹത്തോട് പറഞ്ഞു: "നീയൊരു ഭാഗത്ത് ഇരിക്കുക." ഭാര്യയോട് പറഞ്ഞു: "നീ മറ്റൊരു ഭാഗത്ത് ഇരിക്കുക." ശേഷം മകളെ അവർക്കിടയിൽ നിർത്തി. എന്നിട്ട് പറഞ്ഞു: "നിങ്ങൾ രണ്ടു പേരും അവളെ വിളിക്കുക." അപ്പോൾ മകൾ തന്റെ ഉമ്മയുടെ ഭാഗത്തേക്ക് തിരിഞ്ഞു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അല്ലാഹുവേ, അവളെ നേർമാർഗ്ഗത്തിലാക്കുക." അപ്പോൾ മകൾ തന്റെ പിതാവിന്റെ ഭാഗത്തേക്ക് തിരിഞ്ഞു. അങ്ങനെ പിതാവ് അവളെ പിടിച്ചു. (ദ,ന)', 'رَافِعِ بْنِ سِنَانٍ', 'റാഫിഉബ്നു സിനാൻ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 129, 130, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=94 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 286, 'عَنْ فَيْرُوزَ الدَّيْلَمِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَدِمْتُ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَعِنْدِي أُخْتَانِ تَزَوَّجْتُهُمَا فِي الْجَاهِلِيَّةِ، فَقَالَ: "إِذَا رَجَعْتَ فَطَلِّقْ إِحْدَاهُمَا". وفي رواية قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: يَا رَسُولَ اللهِ، إِنِّي أَسْلَمْتُ وَتَحْتِي أُخْتَانِ؟ قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِي: "طَلِّقْ أَيَّتَهُمَا شِئْتَ". (جه)', 'ഫൈറൂസുദ്ദൈലമീ(റ): ജാഹിലിയ്യാ കാലത്ത് വിവാഹം ചെയ്ത രണ്ട് സഹോദരിമാരോടൊപ്പം ഞാൻ റസൂൽ(സ)യുടെ അടുത്ത് ചെന്നു. റസൂൽ(സ) പറഞ്ഞു: "നീ മടങ്ങിച്ചെന്നാൽ അവരിലൊരാളെ വിവാഹമോചനം ചെയ്യുക." മറ്റൊരു നിവേദനം: ഞാൻ നബി(സ)യുടെ അടുത്ത് ചെന്നു പറഞ്ഞു: റസൂലേ, രണ്ട് സഹോദരിമാർ ഭാര്യമാരായുണ്ടായിരിക്കെയാണ് ഞാൻ മുസ്ലിമായത്. റസൂൽ(സ) പറഞ്ഞു: "അവരിൽ നീയുദ്ദേശിച്ചവളെ വിവാഹമോചനം നടത്തുക." (ജ)', 'فَيْرُوزَ الدَّيْلَمِيِّ', 'ഫൈറൂസുദ്ദൈലമീ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 130, 130, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=95 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=2 and h.hadith_no=286), 1, 'وَفِي رِوَايَةٍ قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: يَا رَسُولَ اللهِ، إِنِّي أَسْلَمْتُ وَتَحْتِي أُخْتَانِ؟ قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِي: "طَلِّقْ أَيَّتَهُمَا شِئْتَ". (جه)', 'മറ്റൊരു നിവേദനം: ഞാൻ നബി(സ)യുടെ അടുത്ത് ചെന്നു പറഞ്ഞു: റസൂലേ, രണ്ട് സഹോദരിമാർ ഭാര്യമാരായുണ്ടായിരിക്കെയാണ് ഞാൻ മുസ്ലിമായത്. റസൂൽ(സ) പറഞ്ഞു: "അവരിൽ നീയുദ്ദേശിച്ചവളെ വിവാഹമോചനം നടത്തുക." (ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 287, 'عَنْ قَيْسِ بْنِ الْحَارِثِ رَضِيَ اللهُ عَنْهُ قَالَ: أَسْلَمْتُ وَعِنْدِي ثَمَانُ نِسْوَةٍ، فَأَتَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ ذَلِكَ لَهُ، فَقَالَ: "اخْتَرْ مِنْهُنَّ أَرْبَعًا". (د,ت,جه)', 'ഖൈസുബ്നുൽ ഹാരിസ്(റ): എട്ട് ഭാര്യമാരുണ്ടായിരിക്കെയാണ് ഞാൻ മുസ്ലിമായത്. അങ്ങനെ നബി(സ)യുടെ അടുത്ത് ചെന്ന് ഞാൻ ആ വിവരം പറഞ്ഞു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അവരിൽ നിന്ന് നാലു പേരെ നീ തെരഞ്ഞെടുക്കുക." (ദ,തു,ജ)', 'قَيْسِ بْنِ الْحَارِثِ', 'ഖൈസുബ്നുൽ ഹാരിസ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 130, 130, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=96 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 288, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَسْلَمَ غَيْلَانُ بْنُ سَلَمَةَ وَتَحْتَهُ عَشْرُ نِسْوَةٍ، فَقَالَ: لَهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "خُذْ مِنْهُنَّ أَرْبَعًا". (ت,جه)', 'ഇബ്നുഉമർ(റ): പത്ത് ഭാര്യമാരുണ്ടായിരിക്കെയാണ് ഗൈലാനുബ്നു സലമ(റ) മുസ്ലിമായത്. നബി(സ) അദ്ദേഹത്തോട് പറഞ്ഞു: "അവരിൽ നിന്ന് നാലു പേരെ നീ തെരഞ്ഞെടുക്കുക." (തു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 130, 130, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=96 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 289, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَأَى امْرَأَةً، فَأَتَى امْرَأَتَهُ زَيْنَبَ وَهِيَ تَمْعَسُ مَنِيئَةً لَهَا، فَقَضَى حَاجَتَهُ ثُمَّ خَرَجَ إِلَى أَصْحَابِهِ، فَقَالَ: "إِنَّ الْمَرْأَةَ تُقْبِلُ فِي صُورَةِ شَيْطَانٍ، وَتُدْبِرُ فِي صُورَةِ شَيْطَانٍ. فَإِذَا أَبْصَرَ أَحَدُكُمْ امْرَأَةً فَلْيَأْتِ أَهْلَهُ، فَإِنَّ ذَلِكَ يَرُدُّ مَا فِي نَفْسِهِ". (م)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ) ഒരിക്കൽ ഒരു സ്ത്രീയെ കണ്ടു. ഉടനെ അവിടന്ന് തന്റെ ഭാര്യ സൈനബ(റ)യുടെ അടുത്ത് ചെന്നു. അന്നേരം മഹതി ഊറയിലിട്ട തോൽ ഉരക്കുകയായിരുന്നു. റസൂൽ(സ) തന്റെ ആവശ്യം നിർവ്വഹിക്കുകയും തന്റെ അനുചരരുടെ അടുത്ത ചെല്ലുകയും ചെയ്തു. എന്നിട്ട് പറഞ്ഞു: "നിശ്ചയം സ്ത്രീ വരുന്നതും പോകുന്നതും ഒരു പിശാചിന്റെ രൂപത്തിലാണ്. അത് കൊണ്ട് നിങ്ങളാരെങ്കിലും വല്ല സ്ത്രീയെയും കണ്ടാൽ ഉടനെ തന്റെ ഭാര്യയെ സമീപിച്ചു കൊള്ളട്ടെ. നിശ്ചയം അത് അവന്റെ മാനസികാസ്വാസ്ഥ്യം ഇല്ലാതെയാക്കുന്നതാണ്. (മു)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 131, 131, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=97 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 290, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَأَى امْرَأَةً، فَدَخَلَ عَلَى زَيْنَبَ فَقَضَى حَاجَتَهُ وَخَرَجَ، وَقَالَ: "إِنَّ الْمَرْأَةَ إِذَا أَقْبَلَتْ أَقْبَلَتْ فِي صُورَةِ شَيْطَانٍ، فَإِذَا رَأَى أَحَدُكُمْ امْرَأَةً فَأَعْجَبَتْهُ فَلْيَأْتِ أَهْلَهُ، فَإِنَّ مَعَهَا مِثْلَ الَّذِي مَعَهَا". حَسَنٌ. (م,د,ت)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): നബി(സ) ഒരു സ്ത്രീയെ കണ്ടു. അപ്പോൾ നബി(സ) സൈനബ്(റ)യുടെ അടുത്ത് ചെല്ലുകയും തന്റെ ആവശ്യം നിർവ്വഹിക്കുകയും പുറത്തു വരികയും ചെയ്തു. എന്നിട്ട് പറഞ്ഞു: "സ്ത്രീ വരുന്നത് ഒരു പിശാചിന്റെ രൂപത്തിലാണ്. അതിനാൽ നിങ്ങളിലാരെങ്കിലും ഒരു സ്ത്രീയെ കാണുകയും അവൾ തന്റെ മനസ്സിളക്കുകയും ചെയ്താൽ അവൻ തന്റെ ഭാര്യയുടെ അടുത്ത് ചെന്നു കൊള്ളുക. ഭാര്യയുടെയടുത്തും ആ അന്യ സ്ത്രീയുടെ അടുത്തുള്ളതെല്ലാം ഉണ്ട്." (മു,ദ,തു)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 131, 131, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=97 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 291, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا يَفْرَكْ مُؤْمِنٌ مُؤْمِنَةً، إِنْ كَرِهَ مِنْهَا خُلُقًا رَضِيَ مِنْهَا آخَرَ". أَوْ قَالَ: "غَيْرَهُ". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരു സത്യവിശ്വാസിയും ഒരു സത്യവിശ്വാസിനിയെ ദേഷ്യം പിടിപ്പിക്കരുത്. അവൻ അവളുടെ ഒരു സ്വഭാവത്തെ വെറുത്താലും മറ്റൊരു സ്വഭാവത്തെ അവൻ തൃപ്തിപ്പെടും." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 131, 131, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=98 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 292, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَوْلَا بَنُو إِسْرَائِيلَ لَمْ يَخْبُثِ الطَّعَامُ وَلَمْ يَخْنَزِ اللَّحْمُ، وَلَوْلَا حَوَّاءُ لَمْ تَخُنْ أُنْثَى زَوْجَهَا الدَّهْرَ". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ബനൂഇസ്റാഈൽ ഇല്ലായിരുന്നെങ്കിൽ ഭക്ഷണം നശിക്കുകയോ ദുർഗന്ധം വമിക്കുന്നതാവുകയോ ചെയ്യുമായിരുന്നില്ല. ഹവ്വാ(റ) ഉണ്ടായിരുന്നില്ലെങ്കിൽ ഒരു സ്ത്രീയും ഒരു കാലത്തും തന്റെ ഭർത്താവിനെ വഞ്ചിക്കുമായിരുന്നില്ല." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 131, 132, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=99 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 293, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي غَزَاةٍ، فَلَمَّا أَقْبَلْنَا تَعَجَّلْتُ عَلَى بَعِيرٍ لِي قَطُوفٍ، فَلَحِقَنِي رَاكِبٌ خَلْفِي فَنَخَسَ بَعِيرِي بِعَنَزَةٍ كَانَتْ مَعَهُ، فَانْطَلَقَ بَعِيرِي كَأَجْوَدِ مَا أَنْتَ رَاءٍ مِنَ الْإِبِلِ، فَالْتَفَتُّ فَإِذَا أَنَا بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَقَالَ: "مَا يُعْجِلُكَ يَا جَابِرُ". قُلْتُ: يَا رَسُولَ اللَّهِ إِنِّي حَدِيثُ عَهْدٍ بِعُرْسٍ، فَقَالَ: "أَبِكْرًا تَزَوَّجْتَهَا أَمْ ثَيِّبًا". قَالَ: قُلْتُ بَلْ ثَيِّبًا، قَالَ: "فَهَلَّا جَارِيَةً تُلَاعِبُهَا وَتُلَاعِبُكَ". قَالَ: فَلَمَّا قَدِمْنَا الْمَدِينَةَ، ذَهَبْنَا لِنَدْخُلَ فَقَالَ: "أَمْهِلُوا حَتَّى نَدْخُلَ لَيْلًا – أَيْ عِشَاءً – كَيْ تَمْتَشِطَ الشَّعِثَةُ، وَتَسْتَحِدَّ الْمُغِيبَةُ". قَالَ: وَقَالَ: إِذَا قَدِمْتَ فَالْكَيْسَ الْكَيْسَ". (م)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ)യോടൊപ്പം ഞങ്ങൾ ഒരു യുദ്ധസംഘത്തിലായിരുന്നു. ഞങ്ങൾ മടങ്ങുന്ന വഴിക്ക് എന്റെ വേഗതയില്ലാത്ത ഒരു ഒട്ടകത്തിന്റെ പുറത്ത് ഞാൻ വേഗം പുറപ്പെട്ടു. അപ്പോൾ എന്റെ പിൻവശത്തു നിന്ന് ഒരു യാത്രികൻ എന്നോടൊപ്പമെത്തുകയും തന്റെയടുത്തുള്ള വടി കൊണ്ട് എന്റെ ഒട്ടകത്തെ കുത്തുകയും ചെയ്തു. അന്നേരം ഏറ്റവും മുന്തിയ ഒട്ടകങ്ങൾ സഞ്ചരിക്കും പോലെ എന്റെ ഒട്ടകം സഞ്ചരിച്ചു. ഞാൻ തിരിഞ്ഞുനോക്കിയപ്പോൾ റസൂൽ(സ)യുടെ അടുത്തായിരുന്നു. റസൂൽ(സ) പറഞ്ഞു: "നീയെന്താണ് ധൃതിയിൽ പോകുന്നത്?" ഞാൻ പറഞ്ഞു: റസൂലേ, ഞാൻ ഈയടുത്താണ് വിവാഹം കഴിച്ചത്. റസൂൽ(സ) പറഞ്ഞു: "കന്യകയെയാണോ, വിധവയെയാണോ നീ വിവാഹം കഴിച്ചത്?" ഞാൻ പറഞ്ഞു: വിധവയെ. റസൂൽ(സ) പറഞ്ഞു: "ഒരു കന്യകയെ വിവാഹം ചെയ്തുകൂടായിരുന്നോ. എങ്കിൽ നിനക്കവളെയും അവൾക്ക് നിന്നെയും കളിപ്പിക്കാമായിരുന്നു." ശേഷം മദീനയിലെത്തിയപ്പോൾ വീടുകളിലേക്ക് പ്രവേശിക്കാനൊരുങ്ങി. അന്നേരം റസൂൽ(സ) പറഞ്ഞു: "അൽപം കാത്തുനിൽക്കുക, നമുക്ക് രാത്രിയിൽ പ്രവേശിക്കാം. അങ്ങനെയെങ്കിൽ മുടി ജടകുത്തിയ സ്ത്രീകൾക്ക് അത് വാർന്നൊതുക്കാം, ഗുഹ്യഭാഗങ്ങളിലെ രോമങ്ങൾ നീക്കം ചെയ്യാം." ശേഷം റസൂൽ(സ) പറഞ്ഞു: "വീട്ടിലെത്തിയാൽ നിങ്ങൾ ബുദ്ധിപൂർവ്വം പ്രവർത്തിക്കുക." (മു)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 132, 132, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=100 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 294, 'عَنْ جَابِرِ بْنِ عَبْدِاللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا أَطَالَ أَحَدُكُمُ الْغَيْبَةَ فَلَا يَطْرُقْ أَهْلَهُ لَيْلًا". (خ)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ) പറഞ്ഞു: "കൂടുതൽ സമയം അകന്നു നിന്നതിന് ശേഷം നിങ്ങളിൽ ആരും രാത്രി സമയത്ത് തന്റെ ഭാര്യയുടെ അടുത്തേക്ക് കടന്ന് ചെല്ലരുത്." (ബു)', 'جَابِرِ بْنِ عَبْدِاللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 132, 132, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=100 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 295, 'عَنْ أَبِي رُهْمٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مِنْ أَفْضَلِ الشَّفَاعَةِ أَنْ يُشَفَّعَ بَيْنَ الِاثْنَيْنِ فِي النِّكَاحِ". [ز: مرسل] (جه)', 'അബൂറുഹ്മ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഏറ്റവും ഉത്തമമായ ശിപാർശ രണ്ട് പേരോട് വിവാഹബന്ധത്തിലേർപ്പെടാൻ ശിപാർശ ചെയ്യലാണ്." (ജ)', 'أَبِي رُهْمٍ', 'അബൂറുഹ്മ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: مرسل', null, 132, 132, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=101 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 296, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: عَثَرَ أُسَامَةُ بِعَتَبَةِ الْبَابِ فَشُجَّ فِي وَجْهِهِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَمِيطِي عَنْهُ الْأَذَى". فَتَقَذَّرْتُهُ، فَجَعَلَ يَمُصُّ عَنْهُ الدَّمَ وَيَمُجُّهُ عَنْ وَجْهِهِ، ثُمَّ قَالَ: "لَوْ كَانَ أُسَامَةُ جَارِيَةً لَحَلَّيْتُهُ وَكَسَوْتُهُ حَتَّى أُنَفِّقَهُ". [ز: مختلف في اتصال سنده] (جه)', 'ആഇശ(റ): വീട്ടുപടിക്കൽ ഉസാമ(റ) വഴുതിവീഴുകയും തന്റെ മുഖം പൊട്ടുകയും ചെയ്തു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അവന്റെ ശരീരത്തിൽ നിന്ന് ചെളി നീക്കിക്കൊടുക്കുക". എനിക്ക് അറപ്പു തോന്നി. പക്ഷേ, റസൂൽ(സ) ഉസാമ(റ)ന്റെ മുഖത്തുനിന്ന് ചോര നക്കിയെടുത്ത് തുപ്പാൻ തുടങ്ങി. ശേഷം പറഞ്ഞു: "ഉസാമ ഒരു പെൺകുട്ടിയായിരുന്നെങ്കിൽ പുരുഷന്മാരെ ആകർഷിക്കുംവിധം ഞാനവനെ ആഭരണവും വസ്ത്രവും അണിയിക്കുമായിരുന്നു." (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: مختلف في اتصال سنده', null, 133, 133, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=101 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 297, 'عَنْ مِخْمَرِ بْنِ مُعَاوِيَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا شُؤْمَ، وَقَدْ يَكُونُ الْيُمْنُ فِي ثَلَاثَةٍ: فِي الْمَرْأَةِ وَالْفَرَسِ وَالدَّارِ". (جه)', 'മിഖ്മറുബ്നു മുആവിയ(റ): റസൂൽ(സ) ഇപ്രകാരം പറയുന്നത് ഞാൻ കേട്ടു: "മൂന്ന് കാര്യങ്ങൾ അപലക്ഷണമല്ല ചിലപ്പോൾ ശുഭലക്ഷണമാണ്: സ്ത്രീ, കുതിര, വീട് എന്നിവയാണവ." (ജ)', 'مِخْمَرِ بْنِ مُعَاوِيَةَ', 'മിഖ്മറുബ്നു മുആവിയ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 133, 133, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=102 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 298, 'عَنْ سَهْلِ بْنِ سَعْدٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنْ كَانَ فَفِي الْفَرَسِ وَالْمَرْأَةِ وَالْمَسْكَنِ" يَعْنِي الشُّؤْمَ. (م,جه)', 'സഹ്ലുബ്നു സഅ്ദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "അത് (അപലക്ഷണം) ഉണ്ടാവുകയാണെങ്കിൽ, കുതിര, സ്ത്രീ, പാർപ്പിടം എന്നിവയിൽ മാത്രമാണുണ്ടാവുക." (മു,ജ)', 'سَهْلِ بْنِ سَعْدٍ', 'സഹ്ലുബ്നു സഅ്ദ്(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 133, 133, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=102 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 299, 'عَنْ زَيْنَبَ بِنْتِ أَبِي سَلَمَة، عَنْ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهُمْ أَنَّهَا كَانَتْ تَعُدُّ هَؤُلَاءِ الثَّلَاثَةَ، وَتَزِيدُ مَعَهُنَّ السَّيْفَ. (م,جه)', 'ഉമ്മുസലമ(റ)യിൽ നിന്ന് സൈനബ് ബിൻതു അബീസലമ(റ): അവർ മേൽപ്പറഞ്ഞ മൂന്ന് കാര്യങ്ങളെ എണ്ണുകയും അവയോടൊപ്പം വാളും ഉൾപ്പെടുത്തുമായിരുന്നു. (മു,ജ)', 'زَيْنَبَ بِنْتِ أَبِي سَلَمَة، عَنْ أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 133, 133, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=102 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 300, 'عَنْ أُسَامَةَ بْنِ زَيْدٍ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا تَرَكْتُ بَعْدِي فِتْنَةً أَضَرَّ عَلَى الرِّجَالِ مِنَ النِّسَاءِ". (خ)', 'ഉസാമതുബ്നു സൈദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "സ്ത്രീകൾ കാരണത്താൽ ഉണ്ടാകുന്ന ഫിത്നയുടെ അത്ര കഠിനമായ ഒരു ഫിത്നയും എന്റെ ശേഷം ഞാൻ പുരുഷൻമാർക്ക് ഉപേക്ഷിച്ചിട്ടില്ല." (ബു)', 'أُسَامَةَ بْنِ زَيْدٍ', 'ഉസാമതുബ്നു സൈദ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 133, 133, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=102 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 301, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا يَحِلُّ لِامْرَأَةٍ تُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ أَنْ تُسَافِرَ سَفَرًا، يَكُونُ ثَلَاثَةَ أَيَّامٍ فَصَاعِدًا، إِلَّا وَمَعَهَا أَبُوهَا أَوْ أَخُوهَا أَوْ زَوْجُهَا أَوِ ابْنُهَا أَوْ ذُو مَحْرَمٍ مِنْهَا". حَسَنٌ صَحِيحٌ. (ق,ت)', 'അബൂസഈദിൽ ഖുദ്രി(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിലും അന്ത്യനാളിലും വിശ്വസിക്കുന്ന ഒരു സ്ത്രീയും, തന്റെ പിതാവിന്റെയോ സഹോദരന്റെയോ ഭർത്താവിന്റെയോ മകന്റെയോ വിവാഹബന്ധം നിഷിദ്ധമായ ഏതെങ്കിലും ഒരാളുടെയോ കൂടെയല്ലാതെ മൂന്നോ അതിലധികമോ ദിവസം വഴിദൂരമുള്ള യാത്ര ചെയ്യുന്നത് അനുവദനീയമല്ല." (ബു,മു,തു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 133, 134, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=103 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 302, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تُسَافِرُ امْرَأَةٌ مَسِيرَةَ يَوْمٍ وَلَيْلَةٍ إِلَّا وَمَعَهَا ذُو مَحْرَمٍ". حَسَنٌ صَحِيحٌ. (ق,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "വിവാഹബന്ധം നിഷിദ്ധമായ ഒരാളോട് കൂടെയല്ലാതെ ഒരു സ്ത്രീയും ഒരു രാപകൽ സമയം വഴിദൂരമുള്ള യാത്ര ചെയ്യരുത്." (ബു,മു,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 134, 134, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=103 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 303, 'عَنْ مَيْمُونَةَ بِنْتِ سَعْدٍ رَضِيَ اللَّهُ عَنْهَا – وَكَانَتْ خَادِمًا لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ – قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَثَلُ الرَّافِلَةِ فِي الزِّينَةِ فِي غَيْرِ أَهْلِهَا كَمَثَلِ ظُلْمَةِ يَوْمِ الْقِيَامَةِ، لَا نُورَ لَهَا". (ت)', 'മൈമൂനതു ബിൻതു സഅ്ദ്(റ): അവർ നബി(സ)യുടെ സേവകയായിരുന്നു. റസൂൽ(സ) പറഞ്ഞു: "തന്റെ ഭർത്താവിനു വേണ്ടിയല്ലാതെ മോടി കൂട്ടി നടക്കുന്ന സ്ത്രീ അന്ത്യനാളിലെ ഇരുട്ട് പോലെയാണ്, അതിന് പ്രകാശം ഉണ്ടാവുകയില്ല." (തു)', 'مَيْمُونَةَ بِنْتِ سَعْدٍ', 'മൈമൂനതു ബിൻതു സഅ്ദ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 134, 134, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=104 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 304, 'عَنْ جَرِيرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَأَلْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ نَظْرَةِ الْفَجْأَةِ، فَقَالَ: "اصْرِفْ بَصَرَكَ". (م,د,ت)', 'ജരീർ(റ): പെട്ടെന്ന് നോക്കിപ്പോകുന്നതിനെക്കുറിച്ച് ഞാൻ റസൂൽ(സ)യോട് ചോദിച്ചു: റസൂൽ(സ) പറഞ്ഞു: "നീ നിന്റെ കാഴ്ചയെ തിരിക്കുക." (മു,ദ,തു)', 'جَرِيرٍ', 'ജരീർ(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 134, 134, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=105 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 305, 'عَنْ بُرَيْدَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِعَلِيٍّ: "يَا عَلِيُّ، لَا تُتْبِعِ النَّظْرَةَ النَّظْرَةَ، فَإِنَّ لَكَ الْأُولَى، وَلَيْسَتْ لَكَ الْآخِرَةُ". (د,ت)', 'ബുറൈദ(റ): അലി(റ)വിനോട് റസൂൽ(സ) പറഞ്ഞു: "അലിയേ, ആദ്യത്തെ നോട്ടത്തിന് ശേഷം വീണ്ടും നീ നോക്കരുത്. ഒന്നാമത്തെ നോട്ടത്തിൽ നിനക്ക് പ്രശ്നമില്ല. പക്ഷേ, ശേഷമുള്ള നോട്ടങ്ങൾ നിനക്ക് അനുവദനീയമല്ല." (ദ,തു)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 134, 134, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=105 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 306, 'عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تُبَاشِرُ الْمَرْأَةُ الْمَرْأَةَ لِتَنْعَتَهَا لِزَوْجِهَا كَأَنَّمَا يَنْظُرُ إِلَيْهَا". (خ,د,ت)', 'ഇബ്നുമസ്ഊദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "മറ്റൊരു സ്ത്രീയെ വർണ്ണിച്ച് തന്റെ ഭർത്താവിന് പറഞ്ഞ് കൊടുക്കാൻ വേണ്ടി ഒരു സ്ത്രീയും മറ്റൊരുത്തിയോട് ഇടപഴകരുത്. അങ്ങനെയവൾ പറഞ്ഞ് കൊടുക്കുമ്പോൾ അവൻ അവളിലേക്ക് നോക്കുന്നത് പോലെയായിരിക്കും." (ബു,ദ,തു)', 'ابْنِ مَسْعُودٍ', 'ഇബ്നുമസ്ഊദ്(റ)', null, null, array['خ','د','ت']::text[], array['ബു','ദ','തു']::text[], null, null, 134, 134, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=105 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 307, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَأَى امْرَأَةً فَدَخَلَ عَلَى زَيْنَبَ بِنْتِ جَحْشٍ، فَقَضَى حَاجَتَهُ مِنْهَا، ثُمَّ خَرَجَ إِلَى أَصْحَابِهِ فَقَالَ لَهُمْ: "إِنَّ الْمَرْأَةَ تُقْبِلُ فِي صُورَةِ شَيْطَانٍ، فَمَنْ وَجَدَ مِنْ ذَلِكَ شَيْئًا فَلْيَأْتِ أَهْلَهُ، فَإِنَّهُ يُضْمِرُ مَا فِي نَفْسِهِ". (م,د,ت)', 'ജാബിർ(റ): നബി(സ) ഒരു സ്ത്രീയെ കണ്ടു. ഉടൻ തന്നെ അവിടന്ന് സൈനബ് ബിൻതു ജഹ്ശ്(റ)വിന്റെ അടുത്ത് വരികയും തന്റെ ആവശ്യം നിർവ്വഹിക്കുകയും ചെയ്തു. ശേഷം തന്റെ അനുചരരുടെ അടുത്ത് പോയിപ്പറഞ്ഞു: "സ്ത്രീ വരുന്നത് ഒരു പിശാചിന്റെ രൂപത്തിലാണ്. അതുകാരണത്താൽ ആരുടെയെങ്കിലും മനസ്സിന് വല്ല ഇളക്കവും സംഭവിച്ചാൽ തന്റെ ഭാര്യയെ സമീപിച്ചുകൊള്ളുക. കാരണം അത് അവന്റെ മനസ്സിലുള്ളതിനെ ഇല്ലാതാക്കും." (മു,ദ,തു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 134, 135, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=105 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 308, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: مَا رَأَيْتُ شَيْئًا أَشْبَهَ بِاللَّمَمِ مِمَّا قَالَ: أَبُو هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللَّهَ كَتَبَ عَلَى ابْنِ آدَمَ حَظَّهُ مِنَ الزِّنَا، أَدْرَكَ ذَلِكَ لَا مَحَالَةَ، فَزِنَا الْعَيْنَيْنِ النَّظَرُ، وَزِنَا اللِّسَانِ الْمَنْطِقُ، وَالنَّفْسُ تَمَنَّى وَتَشْتَهِي، وَالْفَرْجُ يُصَدِّقُ ذَلِكَ وَيُكَذِّبُهُ". (ق,د)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ)യിൽനിന്ന് അബൂഹുറൈറ(റ) ഉദ്ദരിച്ച ഒരു കാര്യത്തേക്കാൾ ചെറുദോശങ്ങളെ വിശദീകരിക്കുന്ന ഒന്നും തന്നെ ഞാൻ കണ്ടിട്ടില്ല. റസൂൽ(സ) പറഞ്ഞു: "വ്യഭിചാരത്തിൽ നിന്ന് ഓരോ മനുഷ്യനുമുള്ള വിഹിതം അല്ലാഹു കണക്കാക്കിയിട്ടുണ്ട്. അവനത് ചെയ്യുക തന്നെ ചെയ്യും. ഇരു കണ്ണുകളുടെയും വ്യഭിചാരം നോട്ടമാണ്. നാവിന്റെ വ്യഭിചാരം സംസാരമാണ്. ശരീരം ആഗ്രഹിക്കുകയും കൊതിക്കുകയും ചെയ്യും. ലിംഗം അതെല്ലാം വാസ്തവമാക്കുകയും, അവാസ്തമാക്കുകയും ചെയ്യും." (ബു,മു,ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 135, 135, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=105 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 309, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لِكُلِّ ابْنِ آدَمَ حَظُّهُ مِنَ الزِّنَا" بِهَذِهِ الْقِصَّةِ، قَالَ: "وَالْيَدَانِ تَزْنِيَانِ فَزِنَاهُمَا الْبَطْشُ، وَالرِّجْلَانِ تَزْنِيَانِ فَزِنَاهُمَا الْمَشْيُ، وَالْفَمُ يَزْنِي فَزِنَاهُ الْقُبَلُ". (م,د)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "എല്ലാ മനുഷ്യനും വ്യഭിചാരത്തിൽ തന്റെ വിഹിതമുണ്ട്" ശേഷം അവിടന്ന് ബാക്കി ചരിത്രം പറഞ്ഞു. അവിടന്ന് പറഞ്ഞു: "ഇരു കരങ്ങളും വ്യഭിചരിക്കും. അവയുടെ വ്യഭിചാരം പിടിക്കലാണ്. ഇരു കാലുകളും വ്യഭിചരിക്കും. അവയുടെ വ്യഭിചാരം നടത്തമാണ്. വായ വ്യഭിചരിക്കും. അതിന്റെ വ്യഭിചാരം ചുംബനമാണ്." (മു,ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 135, 135, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=105 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 310, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِهَذِهِ الْقِصَّةِ، قَالَ: "وَالْأُذُنُ زِنَاهَا الِاسْتِمَاعُ". (د)', 'അബൂഹുറൈറ(റ): മേൽപ്പറഞ്ഞ കാര്യത്തിന്റെ ശേഷം നബി(സ) പറഞ്ഞു: "ചെവിയുടെ വ്യഭിചാരം ശ്രദ്ധിച്ച് കേൾക്കലാണ്." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 135, 135, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=105 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 311, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللَّهُ عَنْهُ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِيَّاكُمْ وَالدُّخُولَ عَلَى النِّسَاءِ". فَقَالَ رَجُلٌ مِنَ الْأَنْصَارِ: يَا رَسُولَ اللَّهِ أَفَرَأَيْتَ الْحَمْوَ؟ قَالَ: "الْحَمْوُ الْمَوْتُ". (خ)', 'ഉഖ്ബതുബ്നു ആമിർ(റ): റസൂൽ(സ) പറഞ്ഞു: "സ്ത്രീകളുടെ അടുത്ത് പ്രവേശിക്കുന്നതിനെ നിങ്ങൾ സൂക്ഷിക്കുക". അൻസാരിയായ ഒരാൾ ചോദിച്ചു: റസൂലേ, ഇളയച്ചനെക്കുറിച്ച് നിങ്ങളുടെ അഭിപ്രായമെന്ത്? റസൂൽ(സ) പറഞ്ഞു: "ഇളയച്ചനെന്നാൽ മരണതുല്യമാണ്". (ബു)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബതുബ്നു ആമിർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 135, 135, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=105 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 312, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَلِجُوا عَلَى الْمُغِيبَاتِ، فَإِنَّ الشَّيْطَانَ يَجْرِي مِنْ أَحَدِكُمْ مَجْرَى الدَّمِ". قُلْنَا: وَمِنْكَ؟ قَالَ: "وَمِنِّي، وَلَكِنَّ اللَّهَ أَعَانَنِي عَلَيْهِ، فَأَسْلَمَ". (ت)', 'ജാബിർ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഭർത്താവ് വീട്ടിലില്ലാത്ത സ്ത്രീയുടെ അടുത്തേക്ക് നിങ്ങൾ പ്രവേശിക്കരുത്. നിശ്ചയം നിങ്ങളുടെ ശരീരത്തിൽ രക്തം സഞ്ചരിക്കുന്നിടത്തെല്ലാം പിശാച് സഞ്ചരിക്കും". ഞങ്ങൾ ചോദിച്ചു: അങ്ങയുടെ ശരീരത്തിലും അപ്രകാരമാണോ? അവിടന്ന് പറഞ്ഞു: "എന്റെ ശരീരത്തിലും അപ്രകാരമാണ്. പക്ഷേ, എന്റെ പിശാചിനു മേൽ അല്ലാഹു എന്നെ സഹായിക്കുകയും അവൻ മുസ്ലിമാവുകയും ചെയ്തിരിക്കുന്നു." (തു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 135, 136, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=105 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 313, 'عَنْ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْمَرْأَةُ عَوْرَةٌ، فَإِذَا خَرَجَتِ اسْتَشْرَفَهَا الشَّيْطَانُ". حَسَنٌ. (ت)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "സ്ത്രീ മറക്കപ്പെടേണ്ടവളാണ്. അവൾ പുറത്ത് വന്നാൽ പിശാച് അവളെ എത്തിനോക്കും." (തു)', 'عَبْدِ اللَّهِ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 136, 136, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=105 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 314, 'عَنْ زَيْنَبَ بِنْتِ أُمِّ سَلَمَةَ عَنْ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهُمْ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلَ عَلَيْهَا، فَسَمِعَ مُخَنَّثًا وَهُوَ يَقُولُ لِعَبْدِ اللَّهِ بْنِ أَبِي أُمَيَّةَ: إِنْ يَفْتَحِ اللَّهُ الطَّائِفَ غَدًا دَلَلْتُكَ عَلَى امْرَأَةٍ: تُقْبِلُ بِأَرْبَعٍ وَتُدْبِرُ بِثَمَانٍ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَخْرِجُوهُ مِنْ بُيُوتِكُمْ". (ق,د,جه)', 'ഉമ്മുസലമ(റ)യിൽ നിന്ന് സൈനബ് ബിൻതു ഉമ്മുസലമ(റ): മഹതിയുടെ അടുത്ത് നബി(സ) വന്നു. അപ്പോൾ സ്ത്രൈണ രൂപമുള്ള (രൂപത്തിലും സ്വഭാവത്തിലും) ഒരു പുരുഷൻ അബ്ദുല്ലാഹിബ്നു അബീഉമയ്യ(റ)വിനോട് ഇപ്രകാരം പറയുന്നത് കേട്ടു: നാളെ അല്ലാഹു ത്വാഇഫ് കീഴ്പ്പെടുത്തിത്തന്നാൽ ഒരു സ്ത്രീയെക്കുറിച്ച് ഞാൻ നിനക്ക് പറഞ്ഞ് തരാം. അവളുടെ വയറിന്റെ മുൻഭാഗത്ത് നാലും പിൻഭാഗത്ത് എട്ടും മടക്കുകളുണ്ടാകും (തടിച്ചവളാണ്). അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അവനെ നിങ്ങളുടെ വീട്ടിൽ നിന്ന് പുറത്താക്കുക." (ബു,മു,ദ,ജ)', 'زَيْنَبَ بِنْتِ أُمِّ سَلَمَةَ عَنْ أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['ق','د','جه']::text[], array['ബു','മു','ദ','ജ']::text[], null, null, 136, 136, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=106 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 315, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَعَنَ الْمَرْأَةَ تَتَشَبَّهُ بِالرِّجَالِ، وَالرَّجُلَ يَتَشَبَّهُ بِالنِّسَاءِ. (خ,د,ت,جه)', 'അബൂഹുറൈറ(റ): പുരുഷന്മാരുടെ കോലം കെട്ടുന്ന സ്ത്രീകയേയും സ്ത്രീയുടെ കോലം കെട്ടുന്ന പുരുഷനെയും റസൂൽ(സ) ശപിച്ചു. (ബു,ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','د','ت','جه']::text[], array['ബു','ദ','തു','ജ']::text[], null, null, 136, 136, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=106 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 316, 'عَنِ ابْنِ عَبَّاسٍ أَنَّ النَّبِيَّ صَلَّى اللَّهُمَ عَلَيْهِ وَسَلَّمَ لَعَنَ الْمُتَشَبِّهِينَ مِنَ الرِّجَالِ بِالنِّسَاءِ وَلَعَنَ الْمُتَشَبِّهَاتِ مِنَ النِّسَاءِ بِالرِّجَالِ (خ,د,ت,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): പുരുഷന്മാരിൽ നിന്ന് സ്ത്രീകളുടെ കോലം കെട്ടുന്നവരെയും സ്ത്രീകളിൽ നിന്ന് പുരുഷന്മാരുടെ കോലം കെട്ടുന്നവരെയും റസൂൽ(സ) ശപിച്ചിരിക്കുന്നു. (ബു,ദ,തു,ജ)', null, 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ','د','ت','جه']::text[], array['ബു','ദ','തു','ജ']::text[], null, null, 136, 136, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=106 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 317, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ لَعَنَ الْوَاصِلَةَ وَالْمُسْتَوْصِلَةَ، وَالْوَاشِمَةَ وَالْمُسْتَوْشِمَةَ. (م,جه)', 'ഇബ്നു ഉമർ(റ): മുടിചേർത്ത് കൊടുക്കുന്നവളെയും ചേർത്ത് വെച്ചുകൊടുക്കപ്പെടുന്നവളെയും കൊത്തിവെക്കുന്നവളെയും കൊത്തിവെച്ച് കൊടുക്കപ്പെടുന്നവളെയും നബി(സ) ശപിച്ചിരിക്കുന്നു. (മു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നു ഉമർ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 136, 136, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=107 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 318, 'عَنْ أَسْمَاءَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: جَاءَتِ امْرَأَةٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: إِنَّ ابْنَتِي عُرَيِّسٌ، وَقَدْ أَصَابَتْهَا الْحَصْبَةُ، فَتَمَرَّقَ شَعْرُهَا، فَأَصِلُ لَهَا فِيهِ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَعَنَ اللَّهُ الْوَاصِلَةَ وَالْمُسْتَوْصِلَةَ". (ق,ن,جه)', 'അസ്മാഅ്(റ): ഒരു സ്ത്രീ നബി(സ)യുടെ അടുത്തുവന്ന് പറഞ്ഞു: എന്റെ മകൾ പുതുനാരിയാണ്, പനി ബാധിച്ചതിനാൽ അവളുടെ മുടികൊഴിഞ്ഞു പോയിരിക്കുന്നു. ഞാനവൾക്ക് മുടിചേർത്തു കൊടുക്കട്ടെയോ? റസൂൽ(സ) പറഞ്ഞു: "മുടിചേർത്ത് കൊടുക്കുന്നവളെയും മുടിചേർത്ത് കൊടുക്കപ്പെടുന്നവളെയും അല്ലാഹു ശപിച്ചിരിക്കുന്നു." (ബു,മു,ന,ജ)', 'أَسْمَاءَ', 'അസ്മാഅ്(റ)', null, null, array['ق','ن','جه']::text[], array['ബു','മു','ന','ജ']::text[], null, null, 136, 137, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=107 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 319, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَعَنَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْوَاشِمَاتِ وَالْمُسْتَوْشِمَاتِ، وَالْمُتَنَمِّصَاتِ، وَالْمُتَفَلِّجَاتِ لِلْحُسْنِ، الْمُغَيِّرَاتِ لِخَلْقِ اللَّهِ. فَبَلَغَ ذَلِكَ امْرَأَةً مِنْ بَنِي أَسَدٍ يُقَالُ لَهَا: أُمُّ يَعْقُوبَ، فَجَاءَتْ إِلَيْهِ فَقَالَتْ: بَلَغَنِي عَنْكَ أَنَّكَ قُلْتَ كَيْتَ وَكَيْتَ؟ قَالَ: وَمَا لِي لَا أَلْعَنُ مَنْ لَعَنَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَهُوَ فِي كِتَابِ اللَّهِ؟ قَالَتْ: إِنِّي لَأَقْرَأُ مَا بَيْنَ لَوْحَيْهِ فَمَا وَجَدْتُهُ. قَالَ: إِنْ كُنْتِ قَرَأْتِهِ فَقَدْ وَجَدْتِهِ. أَمَا قَرَأْتِ: {وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا} [الحشر: ٧] قَالَتْ: بَلَى. قَالَ: فَإِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ نَهَى عَنْهُ. قَالَتْ: فَإِنِّي لَأَظُنُّ أَهْلَكَ يَفْعَلُونَ. قَالَ: اذْهَبِي فَانْظُرِي. فَذَهَبَتْ فَنَظَرَتْ فَلَمْ تَرَ مِنْ حَاجَتِهَا شَيْئًا، قَالَتْ: مَا رَأَيْتُ شَيْئًا. قَالَ عَبْدُ اللَّهِ: لَوْ كَانَتْ كَمَا تَقُولِينَ مَا جَامَعَتْنَا. (جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): കൊത്തിവെക്കുന്ന സ്ത്രീകളെയും, കൊത്തിവെച്ച് കൊടുക്കപ്പെടുന്ന സ്ത്രീകളെയും, മുടിപറിച്ച് നീക്കുന്ന സ്ത്രീകളെയും, ഭംഗിക്കുവേണ്ടി പല്ലുകൾക്കിടയിൽ വിടവുണ്ടാക്കുന്ന സ്ത്രീകളെയും, അല്ലാഹുവിന്റെ സൃഷ്ടികൾക്ക് തടസ്സങ്ങൾ സൃഷ്ടിക്കുന്ന സ്ത്രീകളെയും റസൂൽ(സ) ശപിച്ചിരിക്കുന്നു. അബ്ദുല്ല(റ) ഈ ഹദീസ് പറഞ്ഞ വിവരം ഉമ്മുയഅ്ഖൂബ് എന്ന് പേരുള്ള ബനൂഅസദ് ഗോത്രത്തലെ ഒരു സ്ത്രീ അറിയുകയും അബ്ദുല്ല(റ)വിന്റെ അടുത്ത് വന്ന് ഇപ്രകാരം പറയുകയും ചെയ്തു: അങ്ങ് ഇപ്രകാരമെല്ലാം പറഞ്ഞുവെന്ന് ഞാനറിഞ്ഞല്ലോ? അബ്ദുല്ല പറഞ്ഞു: റസൂൽ(സ) ശപിച്ചവരെ ഞാൻ ശപിക്കാതിരിക്കുകയോ, അത് അല്ലാഹുവിന്റെ ഗ്രന്ഥത്തിലുള്ളത് തന്നെയല്ലേ? അവൾ പറഞ്ഞു: രണ്ട് ചട്ടകൾക്കിടയിലുള്ള ആ ഗ്രന്ഥം ഓതിയിട്ടും ഈ കാര്യം ഞാൻ കണ്ടിട്ടില്ലല്ലോ? അബ്ദുല്ല(റ) പറഞ്ഞു: നീ അത് പാരായണം ചെയ്തിട്ടുണ്ടെങ്കിൽ നീ അത് കണ്ടിട്ടുമുണ്ട്. ''റസൂൽ(സ) നിങ്ങളിലേക്ക് കൊണ്ടുവന്നതിനെ നിങ്ങൾ സ്വീകരിക്കുകയും അവിടന്ന് നിരോധിച്ചതിനെ വെടിയുകയും ചെയ്യുക.'' എന്ന് നീ പാരായണം ചെയ്തിട്ടില്ലേ. അവൾ പറഞ്ഞു: അതെ. അബ്ദുല്ല(റ) പറഞ്ഞു: എങ്കിൽ ഈ കാര്യങ്ങളെയെല്ലാം റസൂൽ(സ) നിരോധിച്ചിരിക്കുന്നു. അവൾ പറഞ്ഞു: അങ്ങയുടെ ഭാര്യയും അപ്രകാരം ചെയ്യുന്നുണ്ടെന്നാണ് എന്റെ തോന്നൽ. അബ്ദുല്ല(റ) പറഞ്ഞു: എങ്കിൽ നീ പോയിനോക്കുക. അങ്ങനെ ആ സ്ത്രീ പോയി നോക്കി. പക്ഷേ, താൻ ലക്ഷ്യം വെച്ചതൊന്നും അവൾ കണ്ടില്ല. അവൾ തിരിച്ച് വന്ന് പറഞ്ഞു: ഞാൻ ഒന്നും കണ്ടിട്ടില്ല. അബ്ദുല്ല(റ) പറഞ്ഞു: എന്റെ ഭാര്യ നീ പറയും പോലെയാണെങ്കിൽ അവൾ എന്റെകൂടെ ഉണ്ടാകുമായിരുന്നില്ല. (ജ)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'الحشر: ٧', null, 137, 137, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=107 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 320, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخْبَرَتْهُ أَنَّ النِّكَاحَ كَانَ فِي الْجَاهِلِيَّةِ عَلَى أَرْبَعَةِ أَنْحَاءٍ: فَكَانَ مِنْهَا نِكَاحُ النَّاسِ الْيَوْمَ يَخْطُبُ الرَّجُلُ إِلَى الرَّجُلِ وَلِيَّتَهُ، فَيُصْدِقُهَا ثُمَّ يَنْكِحُهَا. وَنِكَاحٌ آخَرُ: كَانَ الرَّجُلُ يَقُولُ لِامْرَأَتِهِ إِذَا طَهُرَتْ مِنْ طَمْثِهَا: أَرْسِلِي إِلَى فُلَانٍ فَاسْتَبْضِعِي مِنْهُ، وَيَعْتَزِلُهَا زَوْجُهَا، وَلَا يَمَسُّهَا أَبَدًا حَتَّى يَتَبَيَّنَ حَمْلُهَا مِنْ ذَلِكَ الرَّجُلِ الَّذِي تَسْتَبْضِعُ مِنْهُ، فَإِذَا تَبَيَّنَ حَمْلُهَا أَصَابَهَا زَوْجُهَا إِنْ أَحَبَّ، وَإِنَّمَا يَفْعَلُ ذَلِكَ رَغْبَةً فِي نَجَابَةِ الْوَلَدِ، فَكَانَ هَذَا النِّكَاحُ يُسَمَّى نِكَاحَ الِاسْتِبْضَاعِ. وَنِكَاحٌ آخَرُ: يَجْتَمِعُ الرَّهْطُ دُونَ الْعَشَرَةِ، فَيَدْخُلُونَ عَلَى الْمَرْأَةِ كُلُّهُمْ يُصِيبُهَا، فَإِذَا حَمَلَتْ وَوَضَعَتْ وَمَرَّ لَيَالٍ بَعْدَ أَنْ تَضَعَ حَمْلَهَا أَرْسَلَتْ إِلَيْهِمْ، فَلَمْ يَسْتَطِعْ رَجُلٌ مِنْهُمْ أَنْ يَمْتَنِعَ، حَتَّى يَجْتَمِعُوا عِنْدَهَا، فَتَقُولُ لَهُمْ: قَدْ عَرَفْتُمُ الَّذِي كَانَ مِنْ أَمْرِكُمْ، وَقَدْ وَلَدْتُ، وَهُوَ ابْنُكَ يَا فُلَانُ، فَتُسَمِّي مَنْ أَحَبَّتْ مِنْهُمْ بِاسْمِهِ، فَيَلْحَقُ بِهِ وَلَدُهَا. وَنِكَاحٌ رَابِعٌ: يَجْتَمِعُ النَّاسُ الْكَثِيرُ فَيَدْخُلُونَ عَلَى الْمَرْأَةِ لَا تَمْتَنِعُ مِمَّنْ جَاءَهَا، وَهُنَّ الْبَغَايَا، كُنَّ يَنْصِبْنَ عَلَى أَبْوَابِهِنَّ رَايَاتٍ يَكُنَّ عَلَمًا لِمَنْ أَرَادَهُنَّ دَخَلَ عَلَيْهِنَّ، فَإِذَا حَمَلَتْ فَوَضَعَتْ حَمْلَهَا جُمِعُوا لَهَا، وَدَعَوْا لَهُمُ الْقَافَةَ، ثُمَّ أَلْحَقُوا وَلَدَهَا بِالَّذِي يَرَوْنَ، فَالْتَاطَهُ وَدُعِيَ ابْنَهُ، لَا يَمْتَنِعُ مِنْ ذَلِكَ فَلَمَّا بَعَثَ اللَّهُ مُحَمَّدًا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ هَدَمَ نِكَاحَ أَهْلِ الْجَاهِلِيَّةِ كُلَّهُ، إِلَّا نِكَاحَ أَهْلِ الْإِسْلَامِ الْيَوْمَ. (خ,د)', 'ആഇശ(റ): നബി(സ)യുടെ പത്നിയായ മഹതി നിവേദകനോട് പറഞ്ഞു: ജാഹിലിയ്യാ കാലത്തെ വിവാഹങ്ങൾ നാല് തരത്തിലായിരുന്നു: അതിൽ ഒന്ന് ജനങ്ങൾ ഇന്ന് ചെയ്യുന്നത് പോലെയുള്ള വിവാഹമായിരുന്നു. ഒരാൾ മറ്റൊരാളോട് അവന്റെ സംരക്ഷണത്തിലുള്ള സ്ത്രീയെക്കുറിച്ച് വിവാഹാഭ്യർത്ഥന നടത്തും. ശേഷം മഹ്റ് നൽകുകയും വിവാഹം കഴിക്കുകയും ചെയ്യും. മറ്റൊരു രൂപം: തന്റെ ഭാര്യ ആർത്തവത്തിൽ നിന്ന് ശുദ്ധിയായാൽ ഭർത്താവ് ഭാര്യയോട് പറയും: നീ ഇന്ന വ്യക്തിയുടെ അടുത്ത് പോയി അവനോട് നീയുമായി ബന്ധപ്പെടാൻ ആവശ്യപ്പെടുക. ശേഷം ബന്ധപ്പെട്ട ആ വ്യക്തിയിൽ നിന്ന് അവൾക്ക് ഗർഭമുണ്ടായി എന്ന് വ്യക്തമാകും വരെ ഭർത്താവ് അവളെ വെടിഞ്ഞ് നിൽക്കും. ഗർഭമുണ്ടെന്ന് വ്യക്തമായാൽ തനിക്കിഷ്ടമുണ്ടെങ്കിൽ ഭർത്താവ് അവളെ മടക്കിയെടുക്കും. ജനിക്കുന്ന കുട്ടി തന്റേടമുള്ളവനാകണമെന്ന ഉദ്ദേശത്തോടെയാണ് ഇപ്രകാരം ചെയ്യുന്നത്. ഇത്തരത്തിലുള്ള വിവാഹങ്ങൾ ഇസ്തിബ്ളാഅ് (ബന്ധപ്പെടാൻ ആവശ്യപ്പെടൽ) വിവാഹം എന്നാണ് അറിയപ്പെട്ടിരുന്നത്. മറ്റൊരു രൂപം: പത്തിനു താഴെ ആളുകൾ ഒരുമിച്ച് കൂടുകയും അവർ സംഘമായി ഒരു സ്ത്രീയുടെ അടുത്ത് ചെന്ന് എല്ലാവരും അവളുമായി ബന്ധപ്പെടുകയും ചെയ്യും. ഗർഭം ധരിക്കുകയും പ്രസവിക്കുകയും അതിന് ശേഷം അൽപദിവസം കഴിയുകയും ചെയ്താൽ അവൾ അവരുടെ അടുത്തേക്ക് ആളെ പറഞ്ഞയക്കും. അവരിൽ ഒരാൾക്കും താൻ വരില്ലെന്ന് പറയാൻ സാധിക്കില്ല. അങ്ങനെ അവരെല്ലാവരും അവളുടെ അടുത്ത് ഒത്തുകൂടിയാൽ അവൾ പറയും: മുമ്പ് നിങ്ങളുടെ ഭാഗത്ത് നിന്ന് ഉണ്ടായ കാര്യങ്ങളെല്ലാം നിങ്ങൾക്കറിയാം. ഞാൻ പ്രസവിച്ചിരിക്കുന്നു. ശേഷം അവർക്കിടയിൽ നിന്ന് തനിക്കിഷ്ടപ്പെട്ട ഒരാളുടെ പേര് വിളിച്ച് അവൾ പറയും: ഇത് നിന്റെ മകനാണ്. ആ വ്യക്തി ആ കുട്ടിയെ തന്നോട് ചേർക്കുകയും ചെയ്യും. നാലാമത്തെ രൂപം: ധാരാളം ജനങ്ങൾ ഒരുമിച്ചുകൂടുകയും എല്ലാവരും കൂടി ആരെയും സ്വീകരിക്കുന്ന ഒരു സ്ത്രീയുടെ അടുത്ത് ചെല്ലുകയും ചെയ്യും. അത്തരക്കാരികൾ അഭിസാരികകളായിരിക്കും. ഇഷ്ടമുള്ളവർക്ക് കയറിവരുന്നതിന് അടയാളമെന്നോണം അവർ തങ്ങളുടെ കവാടത്തിൽ കൊടി നാട്ടിയിട്ടുണ്ടാകും. ശേഷം ഗർഭം ധരിക്കുകയും പ്രസവിക്കുകയും ചെയ്താൽ അവരെല്ലാവരും അവളുടെയടുത്ത് ഒരുമിച്ചുകൂടുകയും ലക്ഷണം നോക്കുന്നയാളെ വരുത്തുകയും ചെയ്യും. അങ്ങനെ തീരുമാനിക്കപ്പെടുന്ന വ്യക്തിയോട് ആ കുട്ടിയെ ചേർക്കുകയും ആ വ്യക്തി അക്കാര്യം നിഷേധിക്കാതെ കുട്ടിയെ എടുക്കുകയും ശേഷം അവന്റെ മകനായി ആ കുട്ടി അറിയപ്പെടുകയും ചെയ്യും. മുഹമ്മദ് നബി(സ)യെ അല്ലാഹു അയച്ചപ്പോൾ ഇന്നത്തെ ഇസ്ലാമിക കാലത്ത് നില നിൽക്കുന്ന വിവാഹ സമ്പ്രദായമല്ലാത്ത, ജാഹിലിയ്യാ കാലത്തെ മുഴുവൻ വിവാഹ സമ്പ്രദായങ്ങളെയും അല്ലാഹു പൊളിച്ച് കളഞ്ഞു. (ബു,ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 137, 138, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=108 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 321, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ عِنْدَهَا، وَإِنَّهَا سَمِعَتْ صَوْتَ رَجُلٍ يَسْتَأْذِنُ فِي بَيْتِ حَفْصَةَ، قَالَتْ عَائِشَةُ: فَقُلْتُ: يَا رَسُولَ اللَّهِ، هَذَا رَجُلٌ يَسْتَأْذِنُ فِي بَيْتِكَ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أُرَاهُ فُلَانًا" لِعَمِّ حَفْصَةَ مِنَ الرَّضَاعَةِ، فَقَالَتْ عَائِشَةُ: [قلت]: يَا رَسُولَ اللَّهِ لَوْ كَانَ فُلَانٌ حَيًّا – لِعَمِّهَا مِنَ الرَّضَاعَةِ – دَخَلَ عَلَيَّ؟ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "نَعَمْ، إِنَّ الرَّضَاعَةَ تُحَرِّمُ مَا تُحَرِّمُ الْوِلَادَةُ". (ق)', 'ആഇശ(റ): ഒരിക്കൽ റസൂൽ(സ) മഹതിയുടെ അടുക്കലായിരുന്നപ്പോൾ ഹഫ്സ(റ)യുടെ വീട്ടിൽ പ്രവേശിക്കുവാൻ ഒരാൾ സമ്മതം ചേദിക്കുന്നത് അവർ കേട്ടു. മഹതി പറയുന്നു: അന്നേരം ഞാൻ പറഞ്ഞു: റസൂലേ, ഒരാളിതാ അങ്ങയുടെ (ഭാര്യയായ ഹഫ്സ(റ) താമസിക്കുന്ന) വീട്ടിൽ പ്രവേശിക്കാൻ അനുവാദം ചോദിക്കുന്നു. റസൂൽ(സ) പറഞ്ഞു: "അത് ഹഫ്സ(റ)യുടെ മുലകുടിബന്ധം മുഖേനയുള്ള പിതൃവ്യനായ ഇന്ന ആളാണെന്ന് ഞാൻ വിചാരിക്കുന്നു." ഞാൻ ചോദച്ചു: റസൂലേ, മുലകുടിബന്ധം മുഖേന അവളുടെ (ആഇശ(റ)യുടെ) പിതൃവ്യനായ വ്യക്തി ജീവിച്ചിരിപ്പുണ്ടെങ്കിൽ അദ്ദേഹത്തിന് എന്റെയടുത്ത് വരാൻ പറ്റുമോ? റസൂൽ(സ) പറഞ്ഞു: "അതെ, നിശ്ചയം മുലകുടിബന്ധം കുടുംബബന്ധം നിഷിദ്ധമാക്കുന്ന കാര്യങ്ങളെ എല്ലാം നിഷിദ്ധമാക്കും." (ബു,മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], 'قلت', null, 139, 139, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=109 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 322, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ أُمَّ حَبِيبَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: يَا رَسُولَ اللَّهِ، هَلْ لَكَ فِي أُخْتِي؟ قَالَ: "فَأَفْعَلُ مَاذَا". قَالَتْ: فَتَنْكِحُهَا، قَالَ: "أُخْتَكِ". قَالَتْ: نَعَمْ، قَالَ: "أَوَتُحِبِّينَ ذَلِكَ". قَالَتْ: لَسْتُ بِمُخْلِيَةٍ بِكَ، وَأَحَبُّ مَنْ شَرِكَنِي فِي خَيْرٍ أُخْتِي. قَالَ: "فَإِنَّهَا لَا تَحِلُّ لِي". قَالَتْ: فَوَاللَّهِ لَقَدْ أُخْبِرْتُ أَنَّكَ تَخْطُبُ دُرَّةَ – أَوْ ذُرَّةَ – بِنْتَ أَبِي سَلَمَةَ؟ قَالَ: "بِنْتَ أُمِّ سَلَمَةَ". قَالَتْ: نَعَمْ، قَالَ: "أَمَا وَاللَّهِ لَوْ لَمْ تَكُنْ رَبِيبَتِي فِي حِجْرِي مَا حَلَّتْ لِي، إِنَّهَا ابْنَةُ أَخِي مِنَ الرَّضَاعَةِ، أَرْضَعَتْنِي وَأَبَاهَا ثُوَيْبَةُ، فَلَا تَعْرِضْنَ عَلَيَّ بَنَاتِكُنَّ وَلَا أَخَوَاتِكُنَّ". (ق,د,ن,جه)', 'ഉമ്മുസലമ(റ): ഉമ്മുഹബീബ(റ) റസൂൽ(സ)യോട് പറഞ്ഞു: റസൂലേ, എന്റെ സഹോദരിയെ അങ്ങേക്ക് ആവശ്യമുണ്ടോ? റസൂൽ(സ) ചോദിച്ചു: "ഞാൻ എന്ത് ചെയ്യണമെന്നാണ് നീ പറയുന്നത്." മഹതി പറഞ്ഞു: അങ്ങ് അവളെ വിവാഹം കഴിക്കണം. റസൂൽ(സ) ചോദിച്ചു: "നിന്റെ സഹോദരിയെയോ?" മഹതി പറഞ്ഞു: അതെ. നബി(സ) ചോദിച്ചു: "നീ അത് ഇഷ്ടപ്പെടുന്നുണ്ടോ?" മഹതി പറഞ്ഞു: ഞാൻ അങ്ങയെ വിട്ട് കൊടുക്കുകയില്ല, പക്ഷേ, ഒരു നന്മയിൽ എന്നോട് പങ്കാളിയാകുന്നത് എന്റെ സഹോദരി തന്നെയാകുന്നതാണ് ഞാൻ ഇഷ്ടപ്പെടുന്നത്. നബി(സ) പറഞ്ഞു: "അവൾ എനിക്ക് അനുവദനീയമല്ല." മഹതി പറഞ്ഞു: ദുർറതുബിൻത് അബീസലമ(റ)യെ നിങ്ങൾ വിവാഹാലോചന നടത്തുന്നുവെന്ന് ഞാനറിഞ്ഞല്ലോ? നബി(സ) പറഞ്ഞു: "ഉമ്മുസലമ(റ)യുടെ മകളെയോ?" മഹതി പറഞ്ഞു: അതെ. നബി(സ) പറഞ്ഞു: "അവൾ എന്റെ സംരക്ഷണത്തിലുള്ള വളർത്തുപുത്രിയല്ലെങ്കിൽ തന്നെ എനിക്ക് അനുവദനീയമാവുകയില്ല. കാരണം അവൾ മുലകുടിബന്ധത്തിലുള്ള എന്റെ സഹോദരപുത്രിയാണ്. സുവൈബ എന്ന സ്ത്രീ എനിക്കും അവളുടെ പിതാവിനും മുലകുടിപ്പിച്ചിട്ടുണ്ട്. അതിനാൽ നിങ്ങളുടെ പെൺകുട്ടികളെയും സഹോദരിമാരെയും നിങ്ങൾ എന്നോട് വിവാഹാലോചന നടത്തരുത്." (ബു,മു,ദ,ന,ജ)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 139, 139, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=109 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 323, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قُلْتُ يَا رَسُولَ اللَّهِ، مَا لَكَ تَنَوَّقُ فِي قُرَيْشٍ وَتَدَعُنَا؟ قَالَ: "وَعِنْدَكُمْ شَيْءٌ". قُلْتُ: نَعَمْ، بِنْتُ حَمْزَةَ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّهَا لَا تَحِلُّ لِي، إِنَّهَا ابْنَةُ أَخِي مِنَ الرَّضَاعَةِ". (م,ن)', 'അലി(റ): ഞാൻ ചോദിച്ചു: റസൂലേ, അങ്ങ് ഖുറൈശികളെ തെരഞ്ഞെടുക്കുന്നുവെങ്കിലും (വിവാഹകാര്യത്തിൽ), ഞങ്ങളെ ഒഴിവാക്കുന്നു. റസൂൽ(സ) ചോദിച്ചു: "നിങ്ങളോടൊപ്പം (എനിക്ക് യോജിച്ച) വല്ലവരുമുണ്ടോ?" ഞാൻ പറഞ്ഞു: അതെ, ഹംസ(റ)വിന്റെ മകൾ. റസൂൽ(സ) പറഞ്ഞു: "അവൾ എനിക്ക് അനുവദനീയമല്ല, കാരണം മുലകുടിബന്ധത്തിലുള്ള എന്റെ സഹോദരപുത്രിയാണവൾ." (മു,ന)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 139, 140, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=109 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 324, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: جَاءَ عَمِّي مِنَ الرَّضَاعَةِ يَسْتَأْذِنُ عَلَيَّ، فَأَبَيْتُ أَنْ آذَنَ لَهُ حَتَّى أَسْتَأْمِرَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا جَاءَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قُلْتُ: إِنَّ عَمِّي مِنَ الرَّضَاعَةِ اسْتَأْذَنَ عَلَيَّ فَأَبَيْتُ أَنْ آذَنَ لَهُ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "فَلْيَلِجْ عَلَيْكِ عَمُّكِ". قُلْتُ: إِنَّمَا أَرْضَعَتْنِي الْمَرْأَةُ وَلَمْ يُرْضِعْنِي الرَّجُلُ؟ قَالَ: "إِنَّهُ عَمُّكِ، فَلْيَلِجْ عَلَيْكِ". (ق,ت,جه)', 'ആഇശ(റ): മുലകുടിബന്ധത്തിൽ നിന്നുള്ള എന്റെ പിതൃവ്യൻ എന്റെ അടുത്ത് വരാൻ സമ്മതം ചോദിച്ചു. പക്ഷേ, റസൂൽ(സ)യോട് ചർച്ചചെയ്യും വരെ ഞാൻ അനുവാദം നൽകിയില്ല. ശേഷം റസൂൽ(സ) വന്നപ്പോൾ ഞാൻ പറഞ്ഞു: മുലകുടിബന്ധത്തിൽ നിന്നുള്ള എന്റെ പിതൃവ്യൻ എന്റെയടുത്ത് വരാൻ സമ്മതം ചോദിച്ചെങ്കിലും ഞാൻ അനുവാദം നൽകിയില്ല. റസൂൽ(സ) പറഞ്ഞു: "നിന്റെ പിതൃവ്യന് നിന്റെയടുത്ത് പ്രവേശിക്കാം." ഞാൻ പറഞ്ഞു: സ്ത്രീയാണ് എനിക്ക് മുലതന്നത്, പുരുഷനല്ല. റസൂൽ(സ) പറഞ്ഞു: "അദ്ദേഹം നിന്റെ എളാപ്പ തന്നെയാണ്, അതുകൊണ്ട് അദ്ദേഹത്തിന് നിന്റെയടുത്ത് പ്രവേശിക്കാം." (ബു,മു,തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 140, 140, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=109 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 325, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: دَخَلَ عَلَيَّ أَفْلَحُ بْنُ أَبِي الْقُعَيْسِ، فَاسْتَتَرْتُ مِنْهُ، قَالَ: تَسْتَتِرِينَ مِنِّي وَأَنَا عَمُّكِ؟ قَالَتْ: قُلْتُ: مِنْ أَيْنَ؟ قَالَ: أَرْضَعَتْكِ امْرَأَةُ أَخِي. قَالَتْ: إِنَّمَا أَرْضَعَتْنِي الْمَرْأَةُ وَلَمْ يُرْضِعْنِي الرَّجُلُ. فَدَخَلَ عَلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَحَدَّثْتُهُ فَقَالَ: "إِنَّهُ عَمُّكِ، فَلْيَلِجْ عَلَيْكِ". (ق,د)', 'ആഇശ(റ): എന്റെയടുത്ത് അഫ്ലഹുബ്നു അബിൽ ഉഖൈസ്(റ) വന്നു. അന്നേരം ഞാൻ അദ്ദേഹത്തിൽ നിന്ന് മറഞ്ഞുനിന്നു. അദ്ദേഹം ചോദിച്ചു: നീ എന്നിൽ നിന്ന് മറഞ്ഞുനിൽക്കുകയാണോ, ഞാൻ നിന്റെ പിതൃവ്യനാണല്ലോ? ഞാൻ ചോദിച്ചു: എങ്ങനെ? അദ്ദേഹം പറഞ്ഞു: എന്റെ സഹോദരന്റെ ഭാര്യ നിനക്ക് മുലതന്നിട്ടുണ്ട്. ഞാൻ പറഞ്ഞു: എനിക്ക് മുലതന്നത് സ്ത്രീയാണ്. പുരുഷനല്ല. അപ്പോൾ റസൂൽ(സ) എന്റെയടുത്ത് വന്നു. ഞാൻ അവിടത്തോട് വിവരം പറഞ്ഞു. അന്നേരം പറഞ്ഞു: "നിശ്ചയമദ്ദേഹം നിന്റെ പിതൃവ്യനാണ്, അതുകൊണ്ട് അദ്ദേഹത്തിന് നിന്റെ അടുത്ത് പ്രവേശിക്കാം." (ബു,മു,ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 140, 140, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=109 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 326, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّهُ سُئِلَ عَنْ رَجُلٍ لَهُ جَارِيَتَانِ، أَرْضَعَتْ إِحْدَاهُمَا جَارِيَةً وَالْأُخْرَى غُلَامًا، أَيَحِلُّ لِلْغُلَامِ أَنْ يَتَزَوَّجَ بِالْجَارِيَةِ؟ فَقَالَ: لَا. اللِّقَاحُ وَاحِدٌ. (ت)', 'ഇബ്നുഅബ്ബാസ്(റ): രണ്ട് അടിമസ്ത്രീക്കുള്ള ഒരാളെക്കുറിച്ച് അവരോട് ചോദിക്കപ്പെട്ടു. അവരിലൊരുത്തി ഒരു പെൺകുട്ടിക്കും മറ്റൊരുത്തി ഒരു ആൺകുട്ടിക്കും മുലകൊടുത്തു. എങ്കിൽ ആ ആൺകുട്ടിക്ക് ആ പെൺകുട്ടിയെ വിവാഹം കഴിക്കാമോ? ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: ഇല്ല. കാരണം ഇന്ദ്രിയം ഒന്ന് തന്നെയാണ്. (രണ്ട് അടിമ സത്രീകളും ഒരാൾക്ക് അവകാശപ്പെട്ടതാണ്.) (തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 140, 140, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=109 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 327, 'عَنْ عُقْبَةَ بْنِ الْحَارِثِ رَضِيَ اللَّهُ عَنْهُ قَالَ: تَزَوَّجْتُ امْرَأَةً، فَجَاءَتْنَا امْرَأَةٌ سَوْدَاءُ فَقَالَتْ: إِنِّي قَدْ أَرْضَعْتُكُمَا. فَأَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: تَزَوَّجْتُ فُلَانَةَ بِنْتَ فُلَانٍ، فَجَاءَتْنَا امْرَأَةٌ سَوْدَاءُ فَقَالَتْ: إِنِّي قَدْ أَرْضَعْتُكُمَا، وَهِيَ كَاذِبَةٌ. قَالَ: فَأَعْرَضَ عَنِّي. قَالَ: فَأَتَيْتُهُ مِنْ قِبَلِ وَجْهِهِ فَأَعْرَضَ عَنِّي بِوَجْهِهِ، فَقُلْتُ: إِنَّهَا كَاذِبَةٌ. قَالَ: "وَكَيْفَ بِهَا، وَقَدْ زَعَمَتْ أَنَّهَا قَدْ أَرْضَعَتْكُمَا؟ دَعْهَا عَنْكَ". حَسَنٌ صَحِيحٌ. (خ,د,ت,ن,جه)', 'ഉഖ്ബതുബ്നു ഹാരിസ്(റ): ഞാനൊരു സ്ത്രീയെ വിവാഹം ചെയ്തു. അപ്പോൾ ഒരു കറുത്ത സ്ത്രീ വന്ന് കൊണ്ട് പറഞ്ഞു: ഞാൻ നിങ്ങൾ രണ്ടുപേർക്കും മുല തന്നിട്ടുണ്ട്. അപ്പോൾ ഞാൻ നബി(സ)യുടെ അടുത്ത് ചെന്ന് പറഞ്ഞു: ഞാൻ ഇന്ന സ്ത്രീയെ വിവാഹം ചെയ്തു. ശേഷം കറുത്ത ഒരു സ്ത്രീ വന്നുകാണ്ട് പറഞ്ഞു: ഞാൻ നിങ്ങൾക്കിരുവർക്കും മുലതന്നിട്ടുണ്ട്. അവൾ കളവ് പറഞ്ഞതാണ്. അപ്പോൾ റസൂൽ(സ) എന്നിൽ നിന്ന് തിരിഞ്ഞുകളഞ്ഞു. അപ്പോൾ ഞാൻ അവിടത്തെ മുൻഭാഗത്തുകൂടി ചെന്നു. അപ്പോഴും എന്നിൽ നിന്ന് തിരിഞ്ഞുകളഞ്ഞു. അപ്പോഴും ഞാൻ പറഞ്ഞു: അവൾ കളവ് പറഞ്ഞതാണ്. നബി(സ) പറഞ്ഞു: "അപ്പോൾ അവൾ പറഞ്ഞതോ? നിങ്ങൾക്കിരുവർക്കും മുലതന്നിട്ടുണ്ടെന്ന് അവൾ പറഞ്ഞുവല്ലോ? നീയവളെ(ഭാര്യയെ) ഉപേക്ഷിക്കുക." (ബു,ദ,തു,ന,ജ)', 'عُقْبَةَ بْنِ الْحَارِثِ', 'ഉഖ്ബതുബ്നു ഹാരിസ്(റ)', null, null, array['خ','د','ت','ن','جه']::text[], array['ബു','ദ','തു','ന','ജ']::text[], null, null, 140, 141, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=110 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 328, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ فِيمَا أَنْزَلَ اللَّهُ عَزَّ وَجَلَّ وَقَالَ – وَفِي رِوَايَةٍ: فِيمَا أُنْزِلَ مِنَ الْقُرْآنِ: – {عَشْرُ رَضَعَاتٍ مَعْلُومَاتٍ يُحَرِّمْنَ}. ثُمَّ نُسِخْنَ: {بِخَمْسٍ مَعْلُومَاتٍ}. فَتُوُفِّيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهِيَ مِمَّا يُقْرَأُ مِنَ الْقُرْآنِ. (م,ت,ن,جه)', 'ആഇശ(റ): ''വ്യക്തമായ പത്ത് മുലകുടികൾ വിവാഹബന്ധം നിഷിദ്ധമാക്കും'' എന്ന സൂക്തം ഖുർആനിലുണ്ടായിരുന്നു. അല്ലെങ്കിൽ അല്ലാഹുവിന്റെ ഗ്രന്ഥത്തിലുണ്ടായിരുന്നു. ശേഷം ''വ്യക്തമായ അഞ്ച് കുടികൾ'' എന്ന വാക്യം കൊണ്ട് അത് തിരുത്തപ്പെട്ടു. ശേഷം ''വ്യക്തമായ അഞ്ച് കുടികൾ'' എന്ന് ഖുർആനിലുള്ള അവസ്ഥയിലാണ് റസൂൽ(സ) വഫാത്തായത് (മു,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','ت','ن','جه']::text[], array['മു','തു','ന','ജ']::text[], null, null, 141, 141, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=111 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=2 and h.hadith_no=328), 1, 'وَفِي رِوَايَةٍ: فِيمَا أُنْزِلَ مِنَ الْقُرْآنِ: – {عَشْرُ رَضَعَاتٍ مَعْلُومَاتٍ يُحَرِّمْنَ}. ثُمَّ نُسِخْنَ: {بِخَمْسٍ مَعْلُومَاتٍ}. فَتُوُفِّيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهِيَ مِمَّا يُقْرَأُ مِنَ الْقُرْآنِ. (م,ت,ن,جه)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 329, 'عَنْ أُمِّ الْفَضْلِ رَضِيَ اللَّهُ عَنْهَا: أَنَّ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سُئِلَ عَنِ الرَّضَاعِ؟ فَقَالَ: "لَا تُحَرِّمُ الْإِمْلَاجَةُ وَلَا الْإِمْلَاجَتَانِ". وَفِي رِوَايَةٍ: "الْمَصَّةُ وَالْمَصَّتَانِ". (ن)', 'ഉമ്മുൽഫള്ല്(റ): മുലകുടിബന്ധത്തെക്കുറിച്ച് നബി(സ)യോട് ചോദിക്കപ്പെട്ടു. തിരുമേനി(സ) പറഞ്ഞു: "ഒരു പ്രാവശ്യമോ രണ്ടുപ്രാവശ്യമോ മുലകുടിക്കുന്നത് വിവാഹബന്ധത്തെ നിഷിദ്ധമാക്കുകയില്ല." മറ്റൊരു നിവേദനം: "ഒന്നോ രണ്ടോ ഊമ്പൽ." (ന)', 'أُمِّ الْفَضْلِ', 'ഉമ്മുൽഫള്ല്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 141, 141, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=111 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=2 and h.hadith_no=329), 1, 'وَفِي رِوَايَةٍ: "الْمَصَّةُ وَالْمَصَّتَانِ". (ن)', 'മറ്റൊരു നിവേദനം: "ഒന്നോ രണ്ടോ ഊമ്പൽ." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 330, 'عَنْ قَتَادَةَ قَالَ: كَتَبْنَا إِلَى إِبْرَاهِيمَ بْنِ يَزِيدَ النَّخَعِيِّ نَسْأَلُهُ عَنِ الرَّضَاعِ؟ فَكَتَبَ: أَنَّ شُرَيْحًا حَدَّثَنَا: أَنَّ عَلِيًّا وَابْنَ مَسْعُودٍ كَانَا يَقُولَانِ: يُحَرِّمُ مِنَ الرَّضَاعِ قَلِيلُهُ وَكَثِيرُهُ. وَكَانَ فِي كِتَابِهِ: أَنَّ أَبَا الشَّعْثَاءِ الْمُحَارِبِيَّ حَدَّثَنَا: أَنَّ عَائِشَةَ حَدَّثَتْهُ: أَنَّ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ: "لَا تُحَرِّمُ الْخَطْفَةُ وَالْخَطْفَتَانِ". (ن)', 'ഖതാദ(റ): മുലകുടിബന്ധത്തെക്കുറിച്ച് ചോദിച്ചുകൊണ്ട് ഞങ്ങൾ ഇബ്റാഹീമുബ്നു യസീദുന്നഖഇൗ(റ)വിലേക്ക് സന്ദേശമയച്ചു. അപ്പോൾ അദ്ദേഹം ഇപ്രകാരം മറുപടി അയച്ചു: ശുറൈഹ്(റ) ഞങ്ങൾക്കിപ്രകാരം പറഞ്ഞുതന്നു: അലി(റ)വും ഇബ്നുമസ്ഊദ്(റ)വും ഇപ്രകാരം പറയാറുണ്ടായിരുന്നു. ''മുലകുടിബന്ധം എത്ര കുറവാണെങ്കിലും കൂടുതലാണെങ്കിലും അത് കാരണം വിവാഹബന്ധം നിഷിദ്ധമാകും.'' അദ്ദേഹത്തിന്റെ കത്തിൽ ഇതുകൂടിയുണ്ടായിരുന്നു: അബുശ്ശഅ്സാഉൽ മഹാരിബി(റ)വിനോട് ആഇശ(റ) പറഞ്ഞു: നബി(സ) ഇപ്രകാരം പറയാറുണ്ടായിരുന്നു: "ഒരു മുറുക്കോ രണ്ട് മുറുക്കോ മുലകുടിക്കുന്നത് വിവാഹബന്ധത്തെ നിഷിദ്ധമാക്കുകയില്ല." (ന)', 'قَتَادَةَ قَالَ', 'ഖതാദ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 141, 141, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=111 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 331, 'عَنْ عَائِشَةَ وَأُمِّ سَلَمَةَرَضِيَ اللَّهُ عَنْهُمَا: أَنَّ أَبَا حُذَيْفَةَ بْنَ عُتْبَةَ كَانَ تَبَنَّى سَالِمًا، وَأَنْكَحَهُ ابْنَةَ أَخِيهِ هِنْدَ بِنْتَ الْوَلِيدِ بْنِ عُتْبَةَ، وَهُوَ مَوْلًى لِامْرَأَةٍ مِنَ الْأَنْصَارِ، كَمَا تَبَنَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ زَيْدًا، وَكَانَ مَنْ تَبَنَّى رَجُلًا فِي الْجَاهِلِيَّةِ دَعَاهُ النَّاسُ إِلَيْهِ وَوُرِّثَ مِيرَاثَهُ، حَتَّى أَنْزَلَ اللَّهُ سُبْحَانَهُ وَتَعَالَى فِي ذَلِكَ: {ادْعُوهُمْ لِآبَائِهِمْ} إِلَى قَوْلِهِ: {فَإِخْوَانُكُمْ فِي الدِّينِ وَمَوَالِيكُمْ} [الأحزاب: ٥] فَرُدُّوا إِلَى آبَائِهِمْ، فَمَنْ لَمْ يُعْلَمْ لَهُ أَبٌ كَانَ مَوْلًى وَأَخًا فِي الدِّينِ، فَجَاءَتْ سَهْلَةُ بِنْتُ سُهَيْلِ بْنِ عَمْرٍو، وَهِيَ امْرَأَةُ أَبِي حُذَيْفَةَ، فَقَالَتْ: يَا رَسُولَ اللَّهِ، إِنَّا كُنَّا نَرَى سَالِمًا وَلَدًا، وَكَانَ يَأْوِي مَعِي وَمَعَ أَبِي حُذَيْفَةَ فِي بَيْتٍ وَاحِدٍ، وَيَرَانِي فُضْلًا، وَقَدْ أَنْزَلَ اللَّهُ عَزَّ وَجَلَّ فِيهِمْ مَا قَدْ عَلِمْتَ، فَكَيْفَ تَرَى فِيهِ؟ فَقَالَ لَهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَرْضِعِيهِ". فَأَرْضَعَتْهُ خَمْسَ رَضَعَاتٍ، فَكَانَ بِمَنْزِلَةِ وَلَدِهَا مِنَ الرَّضَاعَةِ، فَبِذَلِكَ كَانَتْ عَائِشَةُ رَضِيَ اللَّهُ عَنْهَا تَأْمُرُ بَنَاتِ أَخَوَاتِهَا وَبَنَاتِ إِخْوَتِهَا أَنْ يُرْضِعْنَ مَنْ أَحَبَّتْ عَائِشَةُ أَنْ يَرَاهَا وَيَدْخُلَ عَلَيْهَا – وَإِنْ كَانَ كَبِيرًا – خَمْسَ رَضَعَاتٍ، ثُمَّ يَدْخُلُ عَلَيْهَا، وَأَبَتْ أُمُّ سَلَمَةَ وَسَائِرُ أَزْوَاجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُدْخِلْنَ عَلَيْهِنَّ بِتِلْكَ الرَّضَاعَةِ أَحَدًا مِنَ النَّاسِ حَتَّى يَرْضَعَ فِي الْمَهْدِ، وَقُلْنَ لِعَائِشَةَ: وَاللَّهِ مَا نَدْرِي، لَعَلَّهَا كَانَتْ رُخْصَةً مِنَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِسَالِمٍ دُونَ النَّاسِ. (ق,د,ن,جه)', 'ആഇശ(റ), ഉമ്മുസലമ(റ): അബൂഹുദൈഫതുബ്നു ഉത്ബ(റ) സാലിം(റ)വിനെ ദത്തെടുക്കുകയും തന്റെ സഹോദര പുത്രി ഹിന്ദുബിൻത് വലീദ്ബിൻ ഉത്ബ(റ)യെ അദ്ദേഹത്തിന് വിവാഹം കഴിച്ചുകൊടുക്കുകയും ചെയ്തു. സാലിം(റ) മുമ്പ് ഒരു അൻസാരിസ്ത്രീയുടെ അടിമയായിരുന്നു. റസൂൽ(സ) സൈദ്(റ)വിനെ ദത്തെടുത്തത് പോലെയായിരുന്നു ഈ സംഭവം. ജാഹിലിയ്യാ കാലത്ത് ഒരാളെ ദത്തെടുത്താൽ അയാളെ ആ ദത്തെടുത്തവന്റെ കുടുംബമായി ഗണിക്കുകയും ദത്തുപുത്രന് അനന്തരാവകാശം ലഭിക്കുകയും ചെയ്യാറുണ്ടായിരുന്നു. അവസാനം ''അവരെ യഥാർത്ഥ പിതാക്കളോട് ചേർത്ത് വിളിക്കുക.'' എന്ന് തുടങ്ങുന്ന സൂക്തം അവതരിച്ചു. അതോടെ അവരെയെല്ലാം സ്വന്തം പിതാക്കളോട് ചേർത്തുവിളിക്കാൻ തുടങ്ങി. പിതാവ് ആരെന്ന് അറിയപ്പെടാത്തവർ സേവകരും ദീനിലെ സഹോദരൻമാരുമായി പരിഗണിക്കപ്പെട്ടു. അങ്ങനെയിരിക്കെ അബൂഹുദൈഫ(റ)വിന്റെ ഭാര്യയായ സഹ്ലതുബിൻത് സുഹൈലുബ്നു അംറ്(റ) വന്ന് റസൂൽ(സ)യോട് പറഞ്ഞു: റസൂലേ, സ്വന്തം പുത്രനായിട്ടാണ് സാലിം(റ)വിനെ ഞങ്ങൾ പരിഗണിച്ചിരുന്നത്. എന്നോടും അബൂഹുദൈഫ(റ)വിനോടുമൊപ്പം ഒരേ വീട്ടിലാണ് അവർ താമസിച്ചിരുന്നത്. സാധാരണവസ്ത്രം ധരിച്ചിരിക്കെത്തന്നെ എന്നെ അവർ കാണാറുണ്ടായിരുന്നു. ഇപ്പോഴിതാ അങ്ങ് അറിഞ്ഞ പോലെ അല്ലാഹു ഈ വിധി അവതരിപ്പിച്ചിരിക്കുന്നു. അതിനാൽ ഈ വിഷയത്തിൽ അങ്ങയുടെ തീരുമാനമെന്താണ്? നബി(സ) മഹതിയോട് പറഞ്ഞു: "നീ സാലിം(റ)വിന് മുലയൂട്ടുക." അങ്ങനെ സഹ്ല(റ) സാലിം(റ)വിനെ അഞ്ച് പ്രാവശ്യം മുലയൂട്ടി. അതിനുശേഷം സഹ്ല(റ)യുടെ മുലകുടിബന്ധത്തിലെ മകനായിട്ടാണ് സാലിം(റ) പരിഗണിക്കപ്പെട്ടത്. ഇക്കാരണത്താൽ തന്നെ, തനിക്ക് കാണണമെന്നോ തന്റെയടുത്ത് വരണമെന്നോ ആഗ്രഹിക്കുന്നവർക്ക് - അവർ വലിയവരാണെങ്കിലും ശരി - അഞ്ചുപ്രാവശ്യം മുലയൂട്ടാൻ ആഇശ(റ) തന്റെ സഹോദരൻമാരുടെയും സഹോദരിമാരുടെയും പുത്രിമാരോട് കൽപിക്കാറുണ്ടായിരുന്നു. അതിനുശേഷമാണ് അത്തരക്കാർ മഹതിയുടെ അടുത്ത് വന്നിരുന്നത്. പക്ഷേ, ഉമ്മുസലമ(റ)വും റസൂൽ(സ)യുടെ മറ്റുഭാര്യമാരും, ചെറുപ്പത്തിൽ തന്നെ മുലകുടിക്കാതെയുള്ള, ഇത്തരം മുലകുടിബന്ധം മുഖേന തങ്ങളുടെ അടുത്തേക്ക് ആരെയെങ്കിലും പ്രവേശിപ്പിക്കുന്നത് തടയുമായിരുന്നു. അവർ ആഇശ(റ)യോട് ഇപ്രകാരം പറഞ്ഞു: അല്ലാഹുവാണ് സത്യം, നമുക്കറിയില്ല, ഒരുപക്ഷേ, റസൂൽ(സ) സാലിം(റ)വിന് മാത്രം നൽകിയ ഒരു ഇളവായിരിക്കുമത്. (ബു,മു,ദ,ന,ജ)', 'عَائِشَةَ وَأُمِّ سَلَمَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], 'الأحزاب: ٥', null, 142, 142, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=111 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 332, 'عَنْ أُمِّ الْفَضْلِ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: دَخَلَ أَعْرَابِيٌّ عَلَى نَبِيِّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ فِي بَيْتِي، فَقَالَ: يَا نَبِيَّ اللَّهِ، إِنِّي كَانَتْ لِي امْرَأَةٌ فَتَزَوَّجْتُ عَلَيْهَا أُخْرَى، فَزَعَمَتِ امْرَأَتِي الْأُولَى أَنَّهَا أَرْضَعَتِ امْرَأَتِي الْحُدْثَى رَضْعَةً أَوْ رَضْعَتَيْنِ؟ فَقَالَ: نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تُحَرِّمُ الْإِمْلَاجَةُ وَالْإِمْلَاجَتَانِ". (م)', 'ഉമ്മുൽ ഫള്ല്(റ): റസൂൽ(സ) എന്റെ വീട്ടിലായിരിക്കെ ഒരു അഅ്റാബി വന്ന് കൊണ്ട് പറഞ്ഞു: നബിയേ, എനിക്കൊരു ഭാര്യയുണ്ടായിരുന്നു, ഞാൻ മറ്റൊരുത്തിയെക്കൂടി വിവാഹം ചെയ്തു. പക്ഷേ, എന്റെ പുതിയ ഭാര്യയെ പഴയ ഭാര്യ ഒന്നോ രണ്ടോ പ്രാവശ്യം മുലയൂട്ടിയിട്ടുണ്ടെന്ന് പഴയ ഭാര്യ വാദിക്കുന്നു. നബി(സ) പറഞ്ഞു: "ഒരു പ്രാവശ്യമോ രണ്ടുപ്രാവശ്യമോ മുലയൂട്ടിയത് വിവാഹ ബന്ധത്തെ നിഷിദ്ധമാക്കുകയില്ല." (മു)', 'أُمِّ الْفَضْلِ', 'ഉമ്മുൽ ഫള്ല്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 142, 143, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=111 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 333, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَنَّهَا قَالَتْ: كَانَ فِيمَا أَنْزَلَ اللَّهُ مِنَ الْقُرْآنِ ثُمَّ سَقَطَ: لَا يُحَرِّمُ إِلَّا عَشْرُ رَضَعَاتٍ. أَوْ: خَمْسٌ مَعْلُومَاتٌ. (جه)', 'ആഇശ(റ): ഖുർആനിൽ ''പത്ത് മുലകുടികളല്ലാതെ വിവാഹബന്ധത്തെ നിഷിദ്ധമാക്കുകയില്ല.'' അല്ലെങ്കിൽ ''അറിയപ്പെട്ട അഞ്ച് മുലകുടികൾ'' എന്നുണ്ടായിരുന്നു. ശേഷമത് ഒഴിവാക്കപ്പെട്ടു (നസ്ഖ് ചെയ്യപ്പെട്ടു). (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 143, 143, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=111 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 334, 'عَنْ حَجَّاجٍ الْأَسْلَمِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ سَأَلَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، مَا يُذْهِبُ عَنِّي مَذَمَّةَ الرَّضَاعِ؟ فَقَالَ: "غُرَّةٌ: عَبْدٌ، أَوْ أَمَةٌ". حَسَنٌ صَحِيحٌ. (د,ت,ن)', 'ഹജ്ജാജുൽ അസ്ലമി(റ): അവർ നബി(സ)യോട് ചോദിച്ചു: റസൂലേ, മുലകുടി ബന്ധത്താൽ എനിക്ക് നിർബന്ധമാകുന്ന ബാധ്യതകളെ എങ്ങനെയാണ് ഇല്ലാതാക്കുക? നബി(സ) പറഞ്ഞു: "അടിമയെയോ അടിമസ്ത്രീയെയോ നൽകിക്കൊണ്ട് (മുലതന്നതിന് പകരം ഇവരെ മുലതന്നവൾക്ക് നൽകിക്കൊണ്ട്.)" (ദ,തു,ന)', 'حَجَّاجٍ الْأَسْلَمِيِّ', 'ഹജ്ജാജുൽ അസ്ലമി(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 143, 143, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=112 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 335, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلَ عَلَيْهَا وَعِنْدَهَا رَجُلٌ، فَشَقَّ ذَلِكَ عَلَيْهِ وَتَغَيَّرَ وَجْهُهُ، قَالَتْ: يَا رَسُولَ اللَّهِ، إِنَّهُ أَخِي مِنَ الرَّضَاعَةِ. فَقَالَ: "انْظُرْنَ مَنْ إِخْوَانُكُنَّ، فَإِنَّمَا الرَّضَاعَةُ مِنَ الْمَجَاعَةِ". (ق,د,ن)', 'ആഇശ(റ): ഒരിക്കൽ റസൂൽ(സ) വന്നപ്പോൾ എന്റെയടുത്ത് ഒരു മനുഷ്യൻ ഇരിക്കുന്നുണ്ടായിരുന്നു. ഇത് അവിടത്തേക്ക് പ്രയാസമായിത്തോന്നുകയും അവിടത്തെ മുഖത്ത് ഞാൻ കോപത്തിന്റെ ലക്ഷണങ്ങൽ കാണുകയും ചെയ്തു. ഞാൻ പറഞ്ഞു: റസൂലേ, ഇദ്ദേഹം മുലകുടിബന്ധം മുഖേനയുള്ള എന്റെ സഹോദരനാണ്. റസൂൽ(സ) പറഞ്ഞു: "മുലകുടിബന്ധം മുഖേനയുള്ള സഹോദരൻമാരെ നിങ്ങൾ ശരിക്കും മനസ്സിലാക്കണം. കാരണം, വിശപ്പടക്കുന്നതിനുള്ള ആഹാരമായി പാൽകുടിക്കുന്നത് മാത്രമാണ് മുലകുടി." (ബു,മു,ദ,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 143, 143, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=113 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 336, 'عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: لَا رِضَاعَ إِلَّا مَا شَدَّ الْعَظْمَ، وَأَنْبَتَ اللَّحْمَ. وفي رواية: أَنْشَزَ الْعَظْمَ. فَقَالَ أَبُو مُوسَرَضِيَ اللَّهُ عَنْهُ: لَا تَسْأَلُونَا وَهَذَا الْحَبْرُ فِيكُمْ. (د)', 'ഇബ്നുമസ്ഊദ്(റ): എല്ലുകൾക്ക് ശക്തിനൽകുകയും മാംസത്തെ മുളപ്പിക്കുകയും ചെയ്യുന്ന വിധത്തിലുള്ളതല്ലാത്ത മുലകുടി പരിഗണിക്കപ്പെടുകയില്ല. അബൂമൂസ(റ) പറഞ്ഞു: ഈ പണ്ഡിതൻ നിങ്ങളിലുണ്ടായിരിക്കെ നമ്മോട് കൂടുതൽ കാര്യങ്ങൾ ചോദിക്കരുത്. (ദ)', 'ابْنِ مَسْعُودٍ', 'ഇബ്നുമസ്ഊദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 143, 144, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=113 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=2 and h.hadith_no=336), 1, 'وَفِي رِوَايَةٍ: أَنْشَزَ الْعَظْمَ. فَقَالَ أَبُو مُوسَرَضِيَ اللَّهُ عَنْهُ: لَا تَسْأَلُونَا وَهَذَا الْحَبْرُ فِيكُمْ. (د)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 337, 'عَنْ زَيْنَبَ بِنْتِ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ أُمَّهَا أُمَّ سَلَمَةَ زَوْجَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَتْ تَقُولُ: أَبَى سَائِرُ أَزْوَاجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُدْخِلْنَ عَلَيْهِنَّ أَحَدًا بِتِلْكَ الرَّضَاعَةِ، وَقُلْنَ لِعَائِشَةَ: وَاللَّهِ مَا نَرَى هَذَا إِلَّا رُخْصَةً أَرْخَصَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِسَالِمٍ خَاصَّةً، فَمَا هُوَ بِدَاخِلٍ عَلَيْنَا أَحَدٌ بِهَذِهِ الرَّضَاعَةِ وَلَا رَائِينَا. (م)', 'സൈനബ് ബിൻത് ഉമ്മിസലമ(റ): നബി(സ)യുടെ പത്നിയും തന്റെ ഉമ്മയുമായ ഉമ്മുസലമ(റ) ഇപ്രകാരം പറയാറുണ്ടായിരുന്നു: ഇത്തരം മുലകുടിബന്ധം (മുലകുടിക്കാലം കഴിഞ്ഞ ശേഷമുണ്ടാക്കുന്ന മുലകുടിബന്ധം) മുഖേന തങ്ങളുടെ അടുത്ത് ആരെയെങ്കിലും പ്രവേശിപ്പിക്കുന്നതിനെ ആഇശ(റ) അല്ലാത്ത എല്ലാ പ്രവാചക പത്നിമാരും വിലക്കുമായിരുന്നു. അവരെല്ലാവരും ആഇശ(റ)യോട് പറഞ്ഞു: അല്ലാഹുവാണ് സത്യം, റസൂൽ(സ) സാലിം(റ)വിന് മാത്രം നൽകിയ ഒരു ഇളവായിട്ടാണ് ഞങ്ങൾ അതിനെ കാണുന്നത്. ഇത്തരം മുലകുടിബന്ധം മുഖേന ഒരാളും ഞങ്ങളുടെ അടുത്ത് വരാനോ ഞങ്ങളെ കാണാനോ പാടില്ല. (മു)', 'زَيْنَبَ بِنْتِ أُمِّ سَلَمَةَ', 'സൈനബ് ബിൻത് ഉമ്മിസലമ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 144, 144, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=113 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 338, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: جَاءَتْ سَهْلَةُ بِنْتُ سُهَيْلٍ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: إِنِّي أَرَى فِي وَجْهِ أَبِي حُذَيْفَةَ مِنْ دُخُولِ سَالِمٍ عَلَيَّ، قَالَ: فَأَرْضِعِيهِ". قَالَتْ: وَكَيْفَ أُرْضِعُهُ وَهُوَ رَجُلٌ كَبِيرٌ؟ فَقَالَ: "أَلَسْتُ أَعْلَمُ أَنَّهُ رَجُلٌ كَبِيرٌ". ثُمَّ جَاءَتْ بَعْدُ فَقَالَتْ: وَالَّذِي بَعَثَكَ بِالْحَقِّ نَبِيًّا، مَا رَأَيْتُ فِي وَجْهِ أَبِي حُذَيْفَةَ بَعْدُ شَيْئًا أَكْرَهُ.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=2 and h.hadith_no=338), 1, 'وَفِي رِوَايَةٍ قَالَتْ: أَمَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ امْرَأَةَ أَبِي حُذَيْفَةَ أَنْ تُرْضِعَ سَالِمًا مَوْلَى أَبِي حُذَيْفَةَ حَتَّى تَذْهَبَ غَيْرَةُ أَبِي حُذَيْفَةَ، فَأَرْضَعَتْهُ وَهُوَ رَجُلٌ، فَكَانَتْ رُخْصَةً لِسَالِمٍ.', 'മറ്റൊരു നിവേദനം: മഹതി പറഞ്ഞു: അബൂഹുദൈഫ(റ)വിന്റെ മൗലയായ സാലിം(റ)വിന് മുലപ്പാൽ നൽകാൻ അബൂഹുദൈഫ(റ)വിന്റെ ഭാര്യയോട് റസൂൽ(സ) കൽപ്പിച്ചു. അബൂഹുദൈഫ(റ)വിന്റെ മനോവിഷമം അകറ്റാനായിരുന്നു അപ്രകാരം ചെയ്തത്. അങ്ങനെ സാലിം(റ) പ്രായപൂർത്തിയായവനായിരിക്കെത്തന്നെ അവർ അദ്ദേഹത്തിന് മുലപ്പാൽ നൽകി. ഇത് സാലിം(റ)വിനുള്ള ഇളവായിരുന്നു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=2 and h.hadith_no=338), 2, 'وَفِي رِوَايَةٍ: قَالَتْ: جَاءَتْ سَهْلَةُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللَّهِ، إِنَّ سَالِمًا يَدْخُلُ عَلَيْنَا وَقَدْ عَقَلَ مَا يَعْقِلُ الرِّجَالُ، وَعَلِمَ مَا يَعْلَمُ الرِّجَالُ؟ قَالَ: "أَرْضِعِيهِ تَحْرُمِي عَلَيْهِ بِذَلِكَ".', 'മറ്റൊരു നിവേദനം: സഹ്ല(റ) റസൂൽ(സ)യുടെ അടുത്ത് വന്ന് പറഞ്ഞു: റസൂലേ, സ്ത്രീപുരുഷൻമാർ തമ്മിലുള്ള ബന്ധങ്ങളെല്ലാം മനസ്സിലാക്കിയ ശേഷവും (ബുദ്ധിയും തന്റേടവും എത്തിയ ശേഷവും) സാലിം(റ) ഞങ്ങളുടെയടുത്ത് വന്ന് പോകുന്നു? തിരുമേനി(സ) പറഞ്ഞു: "നീ അദ്ദേഹത്തിന് മുലയൂട്ടുക, എങ്കിൽ നീ അവന് നിഷിദ്ധമാകും. (കാണൽ അനുവദനീയമാകും.)"');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=2 and h.hadith_no=338), 3, 'وَفِي رِوَايَةٍ: أَنَّ سَالِمًا مَوْلَى أَبِي حُذَيْفَةَ كَانَ مَعَ أَبِي حُذَيْفَةَ وَأَهْلِهِ فِي بَيْتِهِمْ، فَأَتَتْ بِنْتُ سُهَيْلٍ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: إِنَّ سَالِمًا قَدْ بَلَغَ مَا يَبْلُغُ الرِّجَالُ وَعَقَلَ مَا عَقَلُوهُ، وَإِنَّهُ يَدْخُلُ عَلَيْنَا، وَإِنِّي أَظُنُّ فِي نَفْسِ أَبِي حُذَيْفَةَ مِنْ ذَلِكَ شَيْئًا. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَرْضِعِيهِ تَحْرُمِي عَلَيْهِ". فَأَرْضَعْتُهُ فَذَهَبَ الَّذِي فِي نَفْسِ أَبِي حُذَيْفَةَ، فَرَجَعَتْ إِلَيْهِ فَقَلْتُ: إِنِّي قَدْ أَرْضَعْتُهُ، فَذَهَبَ الَّذِي فِي نَفْسِ أَبِي حُذَيْفَةَ. (ن)', 'മറ്റൊരു നിവേദനം: അബൂഹുദൈഫ(റ)വിന്റെ മൗലയായ സാലിം(റ) അബൂഹുദൈഫ(റ)വിന്റെയും തന്റെ കുടുംബത്തിന്റെയും കൂടെ അവരുടെ വീട്ടിലാണ് താമസിച്ചിരുന്നത്. അങ്ങനെയിരിക്കെ (അബൂഹുദൈഫ(റ)വിന്റെ ഭാര്യ) സഹ്ല ബിൻത് സുഹൈൽ(റ) നബി(സ)യുടെ അടുത്ത് വന്ന് പറഞ്ഞു: സാലിം(റ)വിന് പ്രായപൂർത്തിയാവുകയും സ്ത്രീപുരുഷ ബന്ധങ്ങൾ മനസ്സിലാകുന്ന നില എത്തുകയും ചെയ്തിട്ടുണ്ട്. ഇപ്പോഴും അദ്ദേഹം ഞങ്ങളുടെ അടുത്ത് വന്നുപോകുന്നു. ഇക്കാരണത്താൽ അബൂഹുദൈഫ(റ)വിന്റെ മനസ്സിൽ എന്തോ വിഷമമുണ്ടെന്ന് എനിക്ക് തോന്നുന്നു. തിരുമേനി(സ) പറഞ്ഞു: "നീയവന് മുലപ്പാൽ നൽകുക, എങ്കിൽ നീയവന് നിഷിദ്ധമാകും (കാണൽ അനുവദനീയമാകും)." അങ്ങനെ ഞാൻ സാലിം(റ)വിന് മുലപ്പാൽ നൽകുകയും തന്നിമിത്തം അബൂഹുദൈഫ(റ)വിന്റെ മനോവിഷമം ഇല്ലാതാകുകയും ചെയ്തു. ശേഷം ഞാൻ റസൂൽ(സ)യുടെ അടുത്ത് മടങ്ങിവന്ന് കൊണ്ട് പറഞ്ഞു: ഞാൻ സാലിം(റ)വിന് മുലപ്പാൽ നൽകുകയും അത് കാരണത്താൽ അബൂഹുദൈഫ(റ)വിന്റെ മനോവിഷമം ഇല്ലാതാകുകുയം ചെയ്തിട്ടുണ്ട്. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 339, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: جَاءَتْ سَهْلَةُ بِنْتُ سُهَيْلٍ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللَّهِ، إِنِّي أَرَى فِي وَجْهِ أَبِي حُذَيْفَةَ الْكَرَاهِيَةَ مِنْ دُخُولِ سَالِمٍ عَلَيَّ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَرْضِعِيهِ". قَالَتْ: كَيْفَ أُرْضِعُهُ وَهُوَ رَجُلٌ كَبِيرٌ؟ فَتَبَسَّمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَالَ: "قَدْ عَلِمْتُ أَنَّهُ رَجُلٌ كَبِيرٌ". فَفَعَلَتْ، فَأَتَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: مَا رَأَيْتُ فِي وَجْهِ أَبِي حُذَيْفَةَ شَيْئًا أَكْرَهُهُ بَعْدُ. وَكَانَ شَهِدَ بَدْرًا. (م,ن,جه)', 'ആഇശ(റ): സഹ്ലതു ബിൻതു സുഹൈൽ(റ) നബി(സ)യുടെ അടുത്ത് വന്ന് പറഞ്ഞു: റസൂലേ, സാലിം(റ) എന്റെയടുത്ത് വന്നുപോകുന്ന വിഷയത്തിൽ അബൂഹുദൈഫ(റ)വിന് എന്തോ മനോവിഷമം ഉള്ളതായി എനിക്ക് തോന്നുന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നീ സാലിം(റ)വിന് മുലപ്പാൽ നൽകുക." സഹ്ല(റ) ചോദിച്ചു: ഞാൻ എങ്ങനെയാണ് അദ്ദേഹത്തിന് മുലപ്പാൽ നൽകുക, അദ്ദേഹം വലിയ മനുഷ്യനല്ലേ? അന്നേരം പുഞ്ചിരിച്ചുകൊണ്ട് തിരുമേനി(സ) പറഞ്ഞു: "അദ്ദേഹം വലിയ മനുഷ്യനാണെന്ന് എനിക്കുമറിയാം." അങ്ങനെ അവർ സാലിം(റ)വിന് മുലകൊടുത്തു. ശേഷം മഹതി നബി(സ)യുടെ അടുത്ത് വന്ന് പറഞ്ഞു: അതിനുശേഷം അബൂഹുദൈഫ(റ)വിന്റെ മുഖത്ത് ദേഷ്യത്തിന്റെ ഒരു ലക്ഷണവും ഞാൻ കണ്ടിട്ടില്ല. അബൂഹുദൈഫ(റ) ബദ്ർ യുദ്ധത്തിൽ പങ്കെടുത്ത വ്യക്തിയായിരുന്നു. (മു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','ن','جه']::text[], array['മു','ന','ജ']::text[], null, null, 145, 145, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=113 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 340, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: لَقَدْ نَزَلَتْ آيَةُ الرَّجْمِ، وَرَضَاعَةُ الْكَبِيرِ عَشْرًا. وَلَقَدْ كَانَ فِي صَحِيفَةٍ تَحْتَ سَرِيرِي، فَلَمَّا مَاتَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَتَشَاغَلْنَا بِمَوْتِهِ دَخَلَ دَاجِنٌ فَأَكَلَهَا. (د,ت,ن,جه)', 'ആഇശ(റ): വലിയവർക്ക് പത്ത്പ്രാവശ്യം മുലകൊടുക്കുന്നതിനെക്കുറിച്ചും (വിവാഹം കഴിച്ചതിനുശേഷം വ്യഭിചരിച്ചവനെ) കല്ലെറിഞ്ഞുകൊല്ലുന്നതിനെക്കുറിച്ചുമുള്ള സൂക്തം അവതരിച്ചിരുന്നു. എന്റെ കട്ടിലിനു ചുവട്ടിലുള്ള ഒരു ഏടിൽ അവ എഴുതപ്പെട്ടിട്ടുണ്ടായിരുന്നു. റസൂൽ(സ) വഫാത്താകുകയും അവിടത്തെ വിയോഗസംബന്ധമായ വിഷയങ്ങളിൽ ഞങ്ങൾ മുഴുകുകയും ചെയ്തപ്പോൾ ഒരു വളർത്തുമൃഗം ഉള്ളിൽ വന്നുകൊണ്ട് ആ ഏട് ഭക്ഷിച്ചു. (ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 145, 145, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=113 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 341, 'عَنْ زَيْنَبَ بِنْتِ أَبِي سَلَمَةَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ أَزْوَاجَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كُلَّهُنَّ خَالَفْنَ عَائِشَةَ، وَأَبَيْنَ أَنْ يَدْخُلَ عَلَيْهِنَّ أَحَدٌ بِمِثْلِ رَضَاعَةِ سَالِمٍ مَوْلَى أَبِي حُذَيْفَةَ، وَقُلْنَ: وَمَا يُدْرِينَا؟ لَعَلَّ ذَلِكَ كَانَتْ رُخْصَةً لِسَالِمٍ وَحْدَهُ. (م,ن,جه)', 'സൈനബ് ബിൻത് അബൂസലമ(റ): അബൂഹുദൈഫ(റ)വിന്റെ അടിമയായ സാലിം(റ)വിന്റെ മുലകുടിബന്ധം (പ്രായപൂർത്തിയായ ശേഷം ഉണ്ടാക്കുന്ന മുലകുടിബന്ധം) പോലുള്ള മുലകുടിബന്ധം മുഖേന തങ്ങളുടെ അടുത്ത് ആരെങ്കിലും വരുന്നതിനെ ആഇശ(റ) അല്ലാത്ത നബി(സ)യുടെ പത്നിമാർ വിലക്കുകയും ആ വിഷയത്തിൽ അവരെല്ലാം ആഇശ(റ)വിനോട് എതിരാവുകയും ചെയ്തിരുന്നു. അവർ ഇപ്രകാരം പറയാറുമുണ്ടായിരുന്നു: നമുക്കറിയില്ല. ഒരു പക്ഷേ, അത് സാലിം(റ)വിന് മാത്രമുള്ള ഒരു ഇളവാകാം. (മു,ന,ജ)', 'زَيْنَبَ بِنْتِ أَبِي سَلَمَةَ', 'സൈനബ് ബിൻത് അബൂസലമ(റ)', null, null, array['م','ن','جه']::text[], array['മു','ന','ജ']::text[], null, null, 146, 146, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=114 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 342, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا يُحَرِّمُ مِنَ الرَّضَاعَةِ إِلَّا مَا فَتَقَ الْأَمْعَاءَ فِي الثَّدْيِ، وَكَانَ قَبْلَ الْفِطَامِ". حَسَنٌ صَحِيحٌ. (ت)', 'ഉമ്മുസലമ(റ): റസൂൽ(സ) പറഞ്ഞു: "മുലകുടി നിർത്തുന്നതിന് മുമ്പ്, വയറ്റിൽ എല്ലാ ഭാഗത്തും എത്തുന്ന വിധത്തിൽ കുടിച്ച മുലകുടിയല്ലാതെ വിവാഹബന്ധത്തെ നിഷിദ്ധമാക്കുകയില്ല. (തു)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 146, 146, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=114 where b.volume_id=3 and b.book_no=2 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
